protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Sygnet Uzdrowienia','Otrzymujesz 82...172 pkt. żywotności. W czasie używania tej umiejętności wartość twojego pancerza zmniejsza się o 40 pkt.','Otrzymujesz 82...172 pkt. żywotności. W czasie używania tej umiejętności twój pancerz zmniejsza się o 40.'],
2=>['Sygnet Wskrzeszenia','Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 100% punktów żywotności i 25% punktów energii. Ten sygnet odnawia się tylko, gdy podniesie się twoje morale.','Wskrzesza wybranego członka drużyny (100% żywotności, 25% energii). Ten sygnet odnowi się tylko po tym, jak otrzymasz premię "zwiększone morale".'],
3=>['Sygnet Przechwycenia','Wybierz umiejętność, spośród tych, które posiada martwy boss twojej profesji leżący w pobliżu. Sygnet Przechwycenia zostanie na stałe zamieniony na tą umiejętność. Jeśli była to umiejętność elitarna, to za każdy swój poziom otrzymujesz 250 PD.','Wybierz umiejętność, spośród tych które posiada martwy boss twojej profesji leżący w pobliżu. Sygnet Przechwycenia zostanie na stałe zamieniony na tą umiejętność. Jeśli była to umiejętność elitarna, to za każdy swój poziom otrzymujesz po 250 PD.'],
5=>['Blokada Mocy','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność ta oraz wszystkie umiejętności tego atrybutu zostają zablokowane na 1...12 sek., a użycie umiejętności zostaje przerwane.','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność ta oraz wszystkie umiejętności tego atrybutu zostają zablokowane (1...12 sek.), a użycie umiejętności zostaje przerwane.'],
6=>['Mantra Ziemi','Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od ziemi, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','(30...90 sek.) Obrażenia od ziemi, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od ziemi, dostajesz 2 pkt. energii.'],
7=>['Mantra Płomienia','Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od ognia, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','(30...90 sek.) Obrażenia od ognia, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od ognia, dostajesz 2 pkt. energii.'],
8=>['Mantra Mrozu','Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od zimna, obrażenia są zmniejszone o 26...50% i zyskujesz 2 punkty energii.','(30...90 sek.) Obrażenia od zimna, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od zimna, dostajesz 2 pkt. energii.'],
9=>['Mantra Błyskawicy','Przez 30...90 sek., za każdym razem, kiedy otrzymujesz obrażenia od błyskawic, obrażenia zostają zmniejszone o 26...50% i zyskujesz 2 punkty energii.','(30...90 sek.) Obrażenia od błyskawic, jakie otrzymujesz, zmniejszane są o 26...50%. Kiedy otrzymujesz obrażenia od błyskawic, dostajesz 2 pkt. energii.'],
10=>['Łamacz Klątw','Przez 5...80 sek., następnym razem, gdy jesteś celem klątwy, klątwa ta nie zadziała, a rzucający ją otrzymuje 10...46 pkt. obrażeń.','(5...80 sek.) Następna klątwa rzucana na ciebie nie dochodzi do skutku, a rzucający ją otrzymuje 10...46 pkt. obrażeń.'],
11=>['Zniekształcenie','Przez 1...5 sek., masz 75% szans na zablokowanie ataków. Za każdym razem, kiedy zablokujesz w ten sposób atak, tracisz 2 pkt. energii albo Zniekształcenie przestanie działać.','(1...5 sek.) Masz 75% szans na blokowanie. Koszt blokowania: tracisz 2 pkt. energii lub Zniekształcenie przestaje działać.'],
13=>['Mantra Odzyskiwania','Przez 5...20 sek., rzucane przez ciebie czary odnawiają się o 33% szybciej.','(5...20 sek.) Twoje czary odnawiają się o 33% szybciej.'],
14=>['Mantra Wytrwałości','Przez 5...25 sek. twoje klątwy z Magii Iluzji trwają o 10...40% dłużej.','(5...25 sek.) Klątwy Magii Iluzji jakie rzucasz trwają o 10...40% dłużej.'],
15=>['Mantra Inskrypcji','Przez 5...25 sek. twoje sygnety, które z powodzeniem aktywujesz przyjąwszy tę postawę, odnawiają się o 10...40% szybciej.','(5...25 sek.) Twoje sygnety, które z powodzeniem aktywujesz przyjąwszy tę postawę, odnawiają się o 10...40% szybciej.'],
16=>['Mantra Koncentracji','Przez 1...38 sek., następnym razem, gdy twoje czynności byłyby przerwane, nie są one przerywane.','(1...38 sek.) Następnym razem, gdy twoje czynności byłyby przerwane, nie są one przerywane.'],
17=>['Mantra Zdecydowania','Przez 30...90 sek., twoje czynności nie mogą być przerwane, ale za każdym razem, gdy byłyby przerwane, tracisz 10...4 pkt. energii albo Mantra Zdecydowania przestanie działać.','(30...90 sek.) Chroni cię przed przerwaniami. Koszt ochrony: utrata 10...4 pkt. energii lub koniec Mantry Zdecydowania.'],
18=>['Mantra Sygnetów','Przez 10...40 sek., otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.','(10...40 sek.) Otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.'],
19=>['Kruchość','Przez 8...20 sek., wybrany cel i sąsiadujący przeciwnicy otrzymują 5...20 pkt. obrażeń za każdym razem, kiedy zaczynają cierpieć lub zdrowieć z przypadłości.','Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci otrzymują 5...20 obrażeń za każdym razem gdy tracą lub otrzymują jakąś przypadłość.'],
21=>['Inspirujące Zaklęcie','Z wybranego przeciwnika zdejmujesz jedno zaklęcie i otrzymujesz 3...15 pkt. energii. Na 20 sekund Inspirujące Zaklęcie zostaje zastąpione zdjętym zaklęciem.','Z wybranego przeciwnika usuwa zaklęcie. Efekty usunięcia: otrzymujesz 3...15 pkt. energii; ten czar zamieniany jest na to zaklęcie (20 sek.).'],
22=>['Inspirująca Klątwa','Z wybranego sojusznika zdejmujesz jedną klątwę i otrzymujesz 4...10 pkt. energii. Na 20 sekund Inspirująca Klątwa zostaje zastąpiona zdjętą klątwą.','Z wybranego sojusznika usuwa jedną klątwę. Efekty usunięcia: otrzymujesz 4...10 pkt. energii; ten czar zamieniany jest na tę klątwę (20 sek.).'],
23=>['Uderzenie Mocy','Jeśli wybrany przeciwnik rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel otrzymuje 30...120 pkt. obrażeń.','Przerywa użycie czaru lub pieśni. Skutek przerwania: zadaje 30...120 pkt. obrażeń.'],
24=>['Wyciek Mocy','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel traci 3...17 pkt. energii.','Przerywa użycie czaru lub pieśni. Skutek przerwania: powoduje utratę 3...17 pkt. energii.'],
25=>['Wyssanie Mocy','Jeśli wybrany przeciwnik rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a ty otrzymujesz 1...31 pkt. energii.','Przerywa czar lub zaśpiew. Efekt przerwania: otrzymujesz 1...31 pkt. energii.'],
26=>['Empatia','Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje, ten przeciwnik otrzymuje 10...55 pkt. obrażeń, a sam zadaje 1...15 obrażeń mniej.','(5...15 sek.) Wybrany przeciwnik otrzymuje 10...55 pkt. obrażeń za każdym razem, kiedy atakuje, i zadaje 1...15 pkt. obrażeń mniej każdym swoim atakiem.'],
27=>['Rozbicie Urojeń','Zdejmij jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa zostanie usunięta, to ten przeciwnik odniesie 15...75 pkt. obrażeń, wszyscy wrogowie w jego bezpośrednim sąsiedztwie odniosą 75% tych obrażeń.','Zdejmuje jedną klątwę mesmera z wyznaczonego przeciwnika. Skutek zdjęcia: 15...75 pkt. obrażeń dla celu i 75% tych obrażeń dla wszystkich sąsiednich przeciwników.'],
28=>['Wypalanie','Przez 10 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, ten przeciwnik otrzymuje 35...140 pkt. obrażeń.','(10 sek.) Wybrany przeciwnik otrzymuje 35...140 pkt. obrażeń, za każdym razem, kiedy rzuca czar.'],
29=>['Zaciemnienie','Przez 2...8 sek., wszystkie umiejętności wybranego dotkniętego przeciwnika zostają wyłączone, a twoje umiejętności zostają wyłączone na 5 sek.','(2...8 sek.) Wyłącza umiejętności. Twoje umiejętności są wyłączone (5 sek.).'],
30=>['Dywersja','Przez 6 sek., następnym razem, gdy wybrany przeciwnik użyje umiejętności, ta umiejętność odnawia się o 10...56 sek. dłużej.','(6 sek.) Następna umiejętność wybranego przeciwnika będzie się odnawiała o +10...56 sek. dłużej.'],
31=>['Przyzwanie Widziadła','Przez 4...18 sek., wybrany przeciwnik odczuwa -5 degeneracji żywotności.','(4...18 sek.) Powoduje degenerację żywotności -5.'],
32=>['Iluzja Słabości','Tracisz 50...240 pkt. żywotności. Iluzja Słabości przestanie działać jeżeli obrażenia spowodują spadek pkt. żywotności poniżej 25% wartości maksymalnej. Gdy Iluzja Słabości przestanie działać, otrzymujesz 50...240 pkt. żywotności.','Utrata 50...240 pkt. żywotności. Efekt końcowy: otrzymujesz 50...240 pkt. żywotności. Koniec, jeżeli obrażenia sprowadzą twoją żywotność poniżej 25% jej maksymalnej wartości.'],
33=>['Iluzoryczna Broń','Przez 30 sekund, twoje ataki wręcz nie trafiają ani nie chybiają. Zamiast tego Iluzoryczna Broń zadajee 20...60 pkt. obrażeń twoim celom przy każdym ataku wręcz. Otrzymujesz +5 do pancerza za każdą umiejętność magii iluzji, jaką masz na wyposażeniu.','(30 sek.) Zadaje 20...60 pkt. obrażeń przeciwnikom zamiast innych obrażeń lub efektów z ataków wręcz. Otrzymujesz +5 do pancerza za każdą umiejętność magii iluzji na wyposażeniu. Twoje ataki wręcz nie trafiają ani nie chybiają.'],
34=>['Życzliwe Oblicze','Przez 4...10 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony atakiem wręcz, wszyscy przeciwnicy bezpośrednio przy nim stracą całą adrenalinę i 3 punkty energii.','(4...10 sek.) Wszyscy przeciwnicy w kontakcie tracą adrenalinę i 3 pkt. energii, za każdym razem, kiedy atak wręcz trafi wybranego sojusznika.'],
35=>['Ignorancja','Przez 8...20 sek. wybrany przeciwnik nie może używać sygnetów.','(8...20 sek.) Wybrany przeciwnik nie może używać sygnetów.'],
36=>['Magiczna Zagadka','Przez 5...15 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim rzucają czary dwa razy dłużej niż normalnie. Kiedy ta klątwa się skończy, otrzymujesz 1...7 energii.','Klątwa działa także na przeciwników bezpośrednio przy celu (5...15 sek.). Podwaja czas rzucania czarów. Efekt końcowy: otrzymujesz 1...7 energii.'],
37=>['Iluzja Pośpiechu','Przez 5...11 sek., nie jesteś już okulawiony i poruszasz się o 33% szybciej. Gdy Iluzja Pośpiechu przestanie działać, zostajesz okulawiony na 3 sek.','(5...11 sek.) Poruszasz się o 33% szybciej. Efekt początkowy: usuwa przypadłość okulawienia. Efekt końcowy: zostajesz okulawiony (3 sek.).'],
38=>['Czerpanie Mocy','Przez 8...56 sek., za każdym razem, kiedy rzucasz czar, zyskujesz 1 punkt energii za każdego przeciwnika w okolicy.','(8...56 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 pkt. energii za każdego przeciwnika w okolicy.'],
39=>['Udar Energetyczny','Wybrany przeciwnik traci 1...10 pkt. energii. Za każdy stracony punkt energii, ten przeciwnik odnosi 7 pkt. obrażeń, a wszyscy przeciwnicy znajdujący się w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Powoduje utratę 1...10 pkt. energii. Za każdy punkt straconej energii wybrany przeciwnik otrzymuje 7 pkt. obrażeń, a przeciwnicy w pobliżu otrzymują 75% tych obrażeń.'],
40=>['Eteryczna Uczta','Wybrany przeciwnik traci 3 punkty energii. Zyskujesz 20...65 pkt. życia za każdy stracony przez przeciwnika punkt energii.','Powoduje utratę 3 pkt. energii. Za każdy punkt straconej energii otrzymujesz 20...65 pkt. żywotności.'],
41=>['Władca Eteru','Tracisz całą energię. Przez 5...10 sek., wybrany przeciwnik cierpi na -1...3 degeneracji energii, a ty otrzymujesz +1...3 regeneracji energii.','Tracisz całą energię. Wybrany przeciwnik posiada degenerację energii -1...3, a ty posiadasz regenerację energii +1...3 (5...10 sek.).'],
42=>['Wypalanie Energii','Wybrany przeciwnik traci 1...10 pkt. energii i otrzymuje 9 pkt. obrażeń za każdy stracony punkt energii.','Powoduje utratę 1...10 pkt. energii. Za każdy punkt straconej energii zadaje 9 pkt. obrażeń.'],
43=>['Niezgrabność','Przez 4 sek. wybrany przeciwnik i przeciwnicy w bezpośredniej odległości znajdują się pod wpływem klątwy Niezgrabność. Kiedy następnym razem każdy z nich spróbuje zaatakować, atak zostanie przerwany, a przeciwnik otrzyma 10...80 pkt. obrażeń.','(4 sek.) Klątwa działa także na przeciwników w bezpośredniej odległości. Przerywa następny atak wybranego przeciwnika. Efekt przerwania: zadaje 10...80 pkt. obrażeń.'],
44=>['Widmowy Ból','Przez 10 sek., wybrany przeciwnik cierpi -1...4 degeneracji żywotności. Gdy Widmowy Ból przestanie działać, ten przeciwnik otrzymuje Głęboką Ranę, obniżając maksymalną żywotność przeciwnika o 20% na 5...20 sek.','(10 sek.) Powoduje degenerację żywotności -1...4. Efekt końcowy: wywołuje przypadłość głęboka rana (5...20 sek.).'],
45=>['Eteryczne Brzemię','Przez 6...12 sek., wybrany przeciwnik porusza się 50% wolniej. Gdy Eteryczne Brzemię przestanie działać, otrzymujesz 10...18 pkt. energii.','(6...12 sek.) Wybrany przeciwnik porusza się o 50% wolniej. Efekt końcowy: otrzymujesz 10...18 pkt. energii.'],
46=>['Wina','Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony we wroga, czar zawodzi, a ty wykradasz przeciwnikowi do 5...14 pkt. energii.','(6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 5...14 pkt. energii. Bez efektu, chyba że jeden z twoich sojuszników jest celem czaru tego przeciwnika.'],
47=>['Niezdarność','Przez 4 sek., następnym razem, kiedy wybrany przeciwnik lub jakikolwiek wróg w sąsiedztwie zaatakuje, otrzyma 30...135 pkt. obrażeń i zostanie oślepiony na 10 sek.','(4 sek.) Klątwa działa także na wrogów bezpośrednio przy celu. Zadaje 30...135 pkt. obrażeń. Powoduje oślepienie (10 sekund). Bez efektu, jeśli wróg pod działaniem tej klątwy nie zaatakuje.'],
48=>['Duch Porażki','Przez 30 sek., wybrany przeciwnik ma 25% szans na nieudany atak. Zyskujesz 1...3 pkt. energii za każdym razem, kiedy ten przeciwnik nie trafi.','(30 sek.) Wybrany przeciwnik ma 25% szans na nietrafianie. Ty otrzymujesz 1...3 pkt. energii, za każdym razem, kiedy ten przeciwnik nie trafia.'],
49=>['Spustoszenie Umysłu','Przez 5...40 sek., za każdym razem gdy wybrany przeciwnik jest celem dowolnej z twoich umiejętności mesmera (oprócz klątw), traci on 1 pkt. energii i otrzymuje 5...25 pkt. obrażeń za każdy stracony punkt energii. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.','(5...40 sek.) Powoduje utratę 1 pkt. energii, za każdym razem gdy przeciwnik jest celem twoich umiejętności mesmera (oprócz klątw). Zadaje 5...25 obrażeń za każdy stracony punkt energii. Jeśli energia wroga spadnie do 0, otrzymuje on 15...100 pkt. obrażeń, a Spustoszenie Umysłu dobiega końca.'],
50=>['Zmartwienie Marnotrawcy','Po 3 sek. wybrany przeciwnik odniesie 20...100 pkt. obrażeń, a wszyscy sąsiadujący z nim wrogowie odniosą 75% tych obrażeń. Jeśli wybrany przeciwnik zdoła użyć umiejętności, Zmartwienie Marnotrawcy przestanie działać i nie zadaje obrażeń.','(3 sek.). Efekt końcowy: zadaje 20...100 pkt. obrażeń przeciwnikowi i 75% tych obrażeń sąsiadującym z nim wrogom. Nie ma efektu i kończy się wcześniej, jeżeli wybrany przeciwnik używa umiejętności.'],
51=>['Wstyd','Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony w swojego sojusznika, czar zawodzi, a ty wykradasz przeciwnikowi do 5...14 pkt. energii.','(6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 5...14 pkt. energii. Bez efektu, chyba że celem czaru tego przeciwnika jest jeden z jego sojuszników.'],
52=>['Panika','Przez 1...10 sek., wybrany przeciwnik i wszyscy wrogowie w jego pobliżu znajdują sie pod działaniem Paniki. Kiedy spanikowany przeciwnik użyje umiejętności, akcje wszystkich pobliskich wrogów zostają przerwane.','Klątwa działa także na wrogów w pobliżu celu (1...10 sek.). Przerywa akcje wszystkich pobliskich wrogów, za każdym razem, gdy przeciwnik z klątwą uaktywni jakąś umiejętność.'],
53=>['Migrena','Przez 5...20 sek., wybrany przeciwnik cierpi na -1...8 degeneracji pkt. żywotności oraz uaktywnia umiejętności 100% dłużej.','(5...20 sek.) Powoduje degenerację żywotności -1...8 i dwukrotnie wydłuża czas aktywacji umiejętności.'],
54=>['Okulawiające Katusze','Przez 5...20 sek., cel porusza się i atakuje 50% wolniej, otrzymuje też -1...8 do regeneracji zdrowia.','(5...20 sek.) Cel porusza się i atakuje 50% wolniej, otrzymuje też -1...8 do regeneracji zdrowia.'],
55=>['Gorączkowe Sny','Przez 10...25 sek., za każdym razem, kiedy wybrany przeciwnik zaczyna cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczynają cierpieć na tą samą przypadłość. Jeśli przeciwnik cierpi na dwie lub więcej przypadłości, zostaje on ponadto oszołomiony na 1...3 sek.','(10...25 sek.) Przeciwnicy w okolicy otrzymują wszystkie nowe przypadłości, które dostaje wybrany przeciwnik. Wywołuje przypadłość oszołomienie (1...3 sek.), jeżeli wybrany przeciwnik cierpi na dwie lub więcej przypadłości.'],
56=>['Kojące Wizje','Przez 8...20 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim nie zdobywają adrenaliny.','Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci nie mogą otrzymywać adrenaliny.'],
57=>['Krzyk Frustracji','Jeżeli wybrany przeciwnik używa umiejętności, czynności tego przeciwnika i wszystkich wrogów w okolicy zostają przerwane. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń, a pobliscy wrogowie otrzymują 75% tych obrażeń.','Jeżeli wybrany przeciwnik używa umiejętności, czynności tego przeciwnika i wszystkich wrogów w okolicy zostają przerwane. Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń, a pobliscy wrogowie otrzymują 75% tych obrażeń.'],
58=>['Sygnet Północy','Ty i wybrany dotknięty przeciwnik ślepniecie na 15 sekund.','(15 sek.) Wywołuje przypadłość oślepienie. Zostajesz oślepiony (15 sek.).'],
59=>['Sygnet Zmęczenia','Wybrany przeciwnik i wszyscy pobliscy wrogowie tracą 3...8 energii i zostają Osłabieni na 1...12 sek.','Działa także na przeciwników w pobliżu celu. Powoduje utratę 3...8 energii oraz Osłabienie (1...12 sek).'],
61=>['Sygnet Pijawki','Przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, otrzymujesz 3...15 pkt. energii.','Przerywa czynność. Efekt przerwania: jeżeli czynnością było rzucanie czaru, otrzymujesz 3...15 pkt. energii.'],
62=>['Sygnet Pokory','Elitarna umiejętność wybranego przeciwnika zostaje wyłączona na 1...16 sek. Wszystkie twoje umiejętności nie należące do mesmera będą niedostępne przez 4 sek.','Wyłącza umiejętność elitarną (1...16 sek.). Wyłącza twoje umiejętności nie należące do mesmera (4 sek.).'],
63=>['Sygnet Klucza','Wszystkie twoje sygnety poza Sygnetem Klucza zostają odnowione. Przez 20 sek., następne 0...6 razy kiedy użyjesz sygnetu działającego na wroga, wszyscy wrogowie sąsiadujący z twoim celem otrzymają 15...60 pkt. obrażeń i przerwą wykonywanie akcji.','(20 sek.) Twoje kolejne (0...6) sygnety przerywają wykonywanie akcji przeciwników sąsiadujących z twoim celem i zadają im 15...60 pkt. obrażeń. Efekt początkowy: odnawia wszystkie twoje pozostałe sygnety.'],
65=>['Magiczna Mimikra','Na 20 sek. Magiczna Mimikra staje się elitarną umiejętnością nie związaną z przemianą, należącą do wybranego sojusznika innego niż ty.','Ta umiejętność zamieniana jest na umiejętność elitarną sojusznika (20 sek.). Na cel nie można wybrać siebie. Bez efektu, jeśli umiejętność elitarna związana jest z przemianą formy.'],
66=>['Duchowe Okowy','Przez 5...20 sek., wybrany przeciwnik traci 5 pkt. energii za każdym razem, kiedy ten przeciwnik atakuje.','(5...20 sek.) Wybrany przeciwnik traci 5 punkty energii, za każdym razem, kiedy zaatakuje.'],
67=>['Rozbicie Klątwy','Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta, to każdy przeciwnik w pobliżu sojusznika otrzyma 30...120 pkt. obrażeń.','Z wybranego sojusznika usuwa jedną klątwę. Efekt usunięcia: zadaje po 30...120 pkt. obrażeń przeciwnikom w pobliżu tego sojusznika.'],
68=>['Wyssanie Zaklęcia','Z wybranego przeciwnika usuwasz jedno zaklęcie. Jeżeli zaklęcie zostało usunięte, otrzymujesz 8...17 pkt. energii i 40...120 pkt. żywotności.','Z wybranego przeciwnika usuwa zaklęcie. Efekt usunięcia: otrzymujesz 8...17 pkt. energii i 40...120 pkt. żywotności.'],
69=>['Rozbicie Zaklęcia','Z wybranego przeciwnika usuwasz jedno zaklęcie. Jeśli zaklęcie zostanie usunięte, to ten przeciwnik otrzymuje 14...100 pkt. obrażeń.','Z wybranego przeciwnika usuwa zaklęcie. Efekt usunięcia: zadaje 14...100 pkt. obrażeń.'],
72=>['Odporność na Żywioły','Przez 30...90 sek., zyskujesz +40 pkt. pancerza przeciw obrażeniom od żywiołów, ale tracisz 24...12 pkt. pancerza przeciw obrażeniom fizycznym.','(30...90 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom od żywiołów. Przeciwko obrażeniom fizycznym posiadasz -24...12 pkt. pancerza.'],
73=>['Fizyczna Odporność','Przez 30...90 sek., zyskujesz +40 pkt. pancerza przeciw obrażeniom fizycznym, ale tracisz 24...12 pkt. pancerza przeciw obrażeniom od żywiołów.','(30...90 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom fizycznym. Przeciwko obrażeniom od żywiołów posiadasz -24...12 pkt. pancerza.'],
74=>['Echo','W ciągu 30 sek. Echo zostaje zastąpione następną umiejętnością jakiej użyjesz. Echo zachowuje się jak ta umiejętność przez 30 sek.','(30 sek.) Echo zamienia się w następną umiejętność, której użyjesz (30 sek.).'],
75=>['Magiczne Echo','Jeżeli rzucisz czar w przeciągu następnych 20 sek., Magiczne Echo zostanie zastąpione przez ten czar na 20 sek. Magiczne Echo przestanie działać przedwcześnie, jeżeli użyjesz umiejętności innej niż czar.','(20 sek.) Magiczne Echo zamienia się w następny czar, którego użyjesz (20 sek.). To zaklęcie przestanie działać, jeśli użyjesz umiejętność, która nie jest czarem.'],
76=>['Urojone Brzemię','Przez 8...20 sek., wybrany przeciwnik porusza się 50% wolniej.','(8...20 sek.) Cel porusza się 50% wolniej.'],
77=>['Burza Chaosu','Tworzy Burzę Chaosu w miejscu, w którym znajduje się wybrany przeciwnik. Burza trwa 10 sek. Przeciwnicy bezpośrednio przy tym miejscu co sekundę otrzymują 5...25 pkt. obrażeń i tracą 0...2 energii.','W każdej sekundzie zadaje 5...25 pkt. obrażeń i powoduje utratę 0...2 energii (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu pobytu celu.'],
78=>['Epidemia','Przenieś wszystkie przypadłości, wraz z ich pozostałymi czasami działania, z wybranego przeciwnika na wszystkich przeciwników bezpośrednio przy z nim.','Przypadłości wybranego przeciwnika przenoszą się na przeciwników bezpośrednio przy nim.'],
79=>['Wyssanie Energii','Wybrany przeciwnik traci 2...9 pkt. energii. Zyskujesz 3 punkty energii za każdy punkt energii stracony przez przeciwnika.','Powoduje utratę 2...9 pkt. energii. Otrzymujesz 3 punkty energii za każdy punkt straconej energii.'],
80=>['Pobranie Energii','Wybrany przeciwnik traci 4...7 pkt. energii. Zyskujesz 2 punkty energii za każdy stracony przez przeciwnika punkt energii.','Powoduje utratę 4...7 pkt. energii. Otrzymujesz 2 punkty energii za każdy punkt straconej energii.'],
81=>['Magiczne Złodziejstwo','Na 5...35 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Magiczne Złodziejstwo zostaje zastąpione tym czarem.','(5...35 sek.) Wyłącza jeden losowy czar. Ta umiejętność staje się tym czarem.'],
82=>['Mantra Przypomnienia','Przez 20 sek., nic nie zyskujesz. Gdy Mantra Przypomnienia przestanie działać, otrzymujesz 10...25 pkt. energii.','(20 sek.) Efekt końcowy: otrzymujesz 10...25 pkt. energii.'],
83=>['Ożywienie Kościanej Poczwary','Wykorzystaj najbliższe zwłoki by ożywić Kościaną Poczwarę na 1...17 poziomie.','Tworzy kościaną poczwarę na poziomie 1...17. Zużywa świeże ciało.'],
84=>['Ożywienie Kościanego Biesa','Wykorzystaj najbliższe zwłoki, by ożywić Kościanego Biesa na 1...17 poziomie. Kościane biesy potrafią atakować z odległości.','Tworzy kościanego biesa na poziomie 1...17, który potrafi atakować na odległość. Zużywa świeże ciało.'],
85=>['Ożywienie Kościanych Sługusów','Wykorzystaj najbliższe zwłoki, by ożywić dwóch Kościanych Sługusów na 0...12 poziomie.','Tworzy dwóch kościanych sługusów na poziomie 0...12. Zużywa świeże ciało.'],
86=>['Równowaga Grentha','Jeżeli wybrany przeciwnik ma więcej pkt. żywotności niż ty, otrzymujesz połowę tej różnicy (aż do maksymalnego poziomu pkt. żywotności), a ten przeciwnik traci taką samą ilość. Jeżeli ten przeciwnik ma mniej pkt. żywotności niż ty, tracisz połowę tej różnicy, a ten przeciwnik otrzymuje taką samą ilość.','Otrzymujesz punkty żywotności w liczbie równej połowie różnicy pomiędzy żywotnością twoją, a przeciwnika, z kolei przeciwnik traci tę liczbę punktów żywotności. Jeżeli ten przeciwnik posiada mniej żywotności niż ty, to tracisz punkty żywotności w liczbie równej połowie tej różnicy, z kolei przeciwnik otrzymuje tę liczbę punktów żywotności.'],
87=>['Spojrzenie Veraty','Jeżeli wybrany wrogi wskrzeszony truposz ma pana, jego więź z panem zostaje zerwana, tworząc go wrogim wobec wszelkich stworzeń. Jeżeli nie miał pana, ty stajesz się jego panem i leczysz go, przywracając mu 60...80 żywotności. (50% szans na niepowodzenie, gdy wartość Magii Śmierci wynosi 4 lub mniej).','Powoduje, że wybrany nieumarły sługa staje się bezpańskim. Jeżeli już jest bezpański, to ty stajesz się jego panem i leczysz go, przywracając mu 60...80 żywotności. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
88=>['Aura Veraty','Wszystkie wrogie wskrzeszone sługi w okolicy stają się twoimi sługami. Aura Veraty przestanie działać po 120...300 sek. Gdy Aura Veraty przestanie działać, tracisz władzę nad wszystkimi truposzami. (50% szans na niepowodzenie, gdy Magia Śmierci wynosi 4 lub mniej.)','(120...300 sek.) Zostajesz panem wszystkich wrogo nastawionych nieumarłych sług w okolicy. Efekt końcowy: twoi nieumarli słudzy stają się bezpańscy. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
89=>['Trupi Chłód','Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od zimna. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, zdajesz dodatkowe 5...50 pkt. obrażeń od cienia.','Zadaje 5...50 pkt. obrażeń od zimna. Zadaje 5...50 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma powyżej 50% żywotności.'],
90=>['Ofiara Veraty','Przez 5...10 sek. twoje wskrzeszone sługi posiadają regenerację żywotności +10. Wszystkie przypadłości zostają z nich przeniesione na ciebie. Ten czar odnawia się natychmiastowo, jeżeli czar zadziałał, a ty dowodzisz 3 lub mniej sługami.','(5...10 sek.) Zaprzyjaźnieni nieumarli słudzy w liczbie 10 otrzymują regenerację żywotności +10. Natychmiast się odnawia, jeżeli władasz 3 lub mniej sługami. Przenosi wszystkie przypadłości z tych sług na ciebie.'],
91=>['Studnia Mocy','Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Mocy. Przez 10...30 sek. sojusznicy w zasięgu Studni Mocy otrzymują regenerację żywotności +1...6 i regenerację energii +2.','(10...30 sek.). Sojusznicy w tej studni mają regenerację żywotności +1...6 i regenerację energii +2. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
92=>['Studnia Krwi','Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Krwi. Przez 8...20 sek. sojusznicy w tym obszarze otrzymują +1...6 regeneracji żywotności.','(8...20 sek.). Sojusznicy w tej studni mają regenerację żywotności +1...6. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
93=>['Studnia Cierpienia','Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Cierpienia. Przez 10...30 sek. przeciwnicy w tym obszarze otrzymują -1...6 degeneracji żywotności.','(10...30 sek.). Przeciwnicy w tej studni mają degenerację żywotności -1...6. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
94=>['Studnia Profanacji','Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by utworzyć Studnię Profanacji. Przez 8...20 sek. przeciwnicy w tym obszarze tracą wszystkie zaklęcia i nie mogą być celem kolejnych zaklęć. (50% szans na niepowodzenie, gdy wartość Magii Śmierci wynosi 4 lub mniej).','(8...20 sek.). Przeciwnicy w tej studni tracą wszystkie zaklęcia i nie mogą być celem kolejnych zaklęć. Zużywa świeże ciało lub poświęca 66% zdrowia. 50% szans na niepowodzenie, chyba że wartość Magii Śmierci wynosi 5 lub więcej.'],
95=>['Eksplozja Zgnilizny','Zwłoki znajdujące się najbliżej twojego celu eksplodują, tworząc falę uderzeniową, która zadaje 24...120 pkt. obrażeń pobliskim wrogom.','Rozrywa ciało, zadając przeciwnikom w jego pobliżu po 24...120 pkt. obrażeń. Zużywa świeże ciało.'],
96=>['Uczta Duszy','Wykorzystaj najbliższe zwłoki by uzyskać 50...280 pkt. żywotności.','Otrzymujesz 50...280 pkt. żywotności. Zużywa świeże ciało.'],
97=>['Martwicze Przemieszczenie','Wykorzystaj przypadkowe zwłoki lub poświęć 30...20% zdrowia, aby przenieść się do wskazanego wroga. Na 6 sek. popadasz w chorobę, a wszyscy pobliscy wrogowie zostają zatruci na 5...20 sek.','Wykorzystaj przypadkowe zwłoki lub poświęć 30...20% zdrowia, aby przenieść się do wskazanego wroga. Na 6 sek. popadasz w chorobę, a wszyscy pobliscy wrogowie zostają zatruci na 5...20 sek.'],
98=>['Pożarcie Zwłok','Wykorzystaj przypadkowe zwłoki. Przenosisz się w miejsce tych zwłok i zyskujesz 25...100 pkt. żywotności oraz 5...20 pkt. energii.','Przenosisz się do wybranego ciała. Otrzymujesz 25...100 pkt. żywotności i 5...20 pkt. energii. Zużywa świeże ciało.'],
99=>['Pasożytnicza Więź','Przez 20 sek., wybrany przeciwnik cierpi -1 degeneracji żywotności. Rzucający ten czar otrzymuje 30...120 pkt. Żywotności gdy Pasożytnicza Więź przestanie działać.','(20 sek.) Powoduje degenerację żywotności -1. Efekt końcowy: odzyskujesz 30...120 pkt. żywotności.'],
100=>['Ciernie Duszy','Przez 30 sek. wybrany przeciwnik otrzymuje 15...30 pkt. obrażeń za każdym razem, gdy jest na niego rzucane zaklęcie lub klątwa.','(30 sek.) Zadaje 15...30 pkt. obrażeń, kiedy wybrany przeciwnik otrzymuje klątwę lub zaklęcie.'],
101=>['Ciernie','Przez 30 sek., wybrany przeciwnik otrzymuje 4...16 dodatkowych obrażeń gdy otrzymuje fizyczne obrażenia.','(30 sek.) Wybrany przeciwnik otrzymuje 4...16 pkt. obrażeń, za każdym razem, kiedy otrzymuje obrażenia fizyczne.'],
102=>['Uderzenie Cienia','Wybrany przeciwnik otrzymuje 12...48 pkt. obrażeń od cienia. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, wykradasz mu 12...48 pkt. żywotności.','Zadaje 12...48 pkt. obrażeń. Wykrada do 12...48 pkt. żywotności, jeżeli ten przeciwnik miał powyżej 50% żywotności.'],
103=>['Cena Porażki','Przez 30 sek., wybrany przeciwnik ma 25% szansy na nieudany atak i otrzymuje 1...46 pkt. obrażeń za każdym razem, kiedy spudłuje w walce.','(30 sek.) 25% szans na nietrafianie. Wybrany przeciwnik otrzymuje 1...46 pkt. obrażeń, za każdym razem, kiedy nie trafi.'],
104=>['Zabójczy Wybuch','Przez 30 sek., jeżeli wybrany sojusznik zginie, wszyscy przeciwnicy bezpośrednio przy nim otrzymają 26...100 pkt. obrażeń i zostaną zatruci na 15 sek.','(30 sek.) Jeżeli wybrany sojusznik umrze, umiejętność zadaje 26...100 pkt. obrażeń przeciwnikom bezpośrednio przy nim i wywołuje u nich przypadłość zatrucie (15 sek.).'],
105=>['Śmiercionośny Rój','Śmiercionośny Rój wylatuje powoli i zadaje 30...90 pkt. obrażeń od zimna maksymalnie trzem przeciwnikom w okolicy.','Śmiercionośny Rój przemieszcza się powoli i zadaje 30...90 pkt. obrażeń od zimna. Dodatkowo trafia dwóch przeciwników w okolicy.'],
106=>['Gnijące Ciało','Wybrany cielesny przeciwnik zaczyna chorować na 10...25 sek., powoli tracąc punkty żywotności.','Wywołuje przypadłość choroba (10...25 sek.).'],
107=>['Zjadliwa Choroba','Jeżeli wybrany przeciwnik cierpi na jakąś przypadłość, to otrzymuje dodatkowo na 3...15 sek. chorobę, zatrucie i osłabienie.','Wywołuje przypadłości choroba, zatrucie oraz osłabienie (3...15 sek.). Bez efektu, chyba że ten przeciwnik już cierpi na przypadłość.'],
108=>['Cierpienie','Przez 6...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -0...3.','Klątwa działa także na przeciwników w pobliżu celu (6...30 sek.). Ci przeciwnicy posiadają degenerację żywotności -0...3.'],
109=>['Wyssanie Życia','Przez 12...24 sek. wybrany przeciwnik posiada degenerację żywotności -1...3, a ty posiadasz regenerację żywotności +1...3.','(12...24 sek.) Wybrany przeciwnik posiada degenerację żywotności -1...3. Ty posiadasz regenerację żywotności +1...3.'],
110=>['Bluźniercza Uczta','Wykradasz do 10...65 pkt. żywotności od maksymalnie 1...4 przeciwników w okolicy.','Wykrada 10...65 pkt. żywotności od 1...4 przeciwników w twojej okolicy.'],
111=>['Przebudzenie Krwi','Przez 20...44 sek., zyskujesz premię +2 do Magii Krwi i +2 do Klątw, ale za każdym razem, kiedy poświęcasz punkty żywotności, poświęcasz 50% więcej niż normalnie.','(20...44 sek.) Otrzymujesz +2 pkt. do Magii Krwi i Klątw. Poświęcasz o 50% więcej żywotności niż normalnie.'],
112=>['Zbezczeszczenie Zaklęć','Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują po 6...60 pkt. obrażeń od cienia oraz po 4...20 pkt. obrażeń od cienia za każde zaklęcie, które mają na sobie.','Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 6...60 pkt. obrażeń. Zadaje 4...20 pkt. dodatkowych obrażeń za każde zaklęcie, pod którego są działaniem.'],
113=>['Skażone Ciało','Przez 20...44 sek. pobliscy sojusznicy są odporni na choroby, a każdy, kto ich zaatakuje będzie chory przez 3...15 sek.','(20...44 sek.) Przeciwnicy, którzy trafią sojuszników w okolicy atakiem wręcz, zachorują (3...15 sek.); sojusznik staje się niewrażliwy na chorobę.'],
114=>['Aura Licza','Wszystkie ciała w zasięgu słuchu zostają zużyte, a ty wskrzeszasz kościaną poczwarę na poziomie 1...17, plus dodatkową poczwarę na każde ciało zużyte w ten sposób. Przez 5...45 sek. twój atrybut Magia Śmierci jest zwiększony o +1.','Wykorzystuje wszystkie ciała w zasięgu słuchu. Wskrzesza kościaną poczwarę na poziomie 1...17, plus dodatkową poczwarę na każde zużyte ciało. Otrzymujesz +1 pkt. do Magii Śmierci (5...45 sek.).'],
115=>['Krwawa Odnowa','Przez 7 sek., otrzymujesz regenerację żywotności równą +3...6. Gdy Krwawa Odnowa przestanie działać, otrzymujesz 40...190 pkt. żywotności.','(7 sek.) Posiadasz regenerację żywotności +3...6. Efekt końcowy: otrzymujesz 40...190 pkt. żywotności.'],
116=>['Mroczna Aura','Przez 30 sek., za każdym razem, kiedy wybrany sojusznik poświęca punkty żywotności, Mroczna Aura zadaje 5...50 pkt. obrażeń od cienia przeciwnikom bezpośrednio przy nim, a ty tracisz 5...20 pkt. żywotności.','(30 sek.) Zadaje 5...50 pkt. obrażeń przeciwnikom bezpośrednio przy wybranym sojuszniku, za każdym razem, kiedy poświęca on żywotność. Koszt obrażeń: tracisz 5...20 pkt. żywotności.'],
117=>['Osłabienie','Wybrany przeciwnik cierpi na osłabienie przez 10...30 sek.','Wywołuje przypadłość osłabienie (10...30 sek.).'],
118=>['Osłabiająca Krew','Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu cierpią na osłabienie przez 5...20 sek.','Osłabia (5...20 sek.) wybranego przeciwnika i wszystkich przeciwników w pobliżu.'],
119=>['Krew to Potęga','Przez 10 sek. wybrany sojusznik inny niż ty posiada regenerację energii +3...6.','(10 sek.) Regeneracja energii +3...6. Na cel nie można wybrać siebie.'],
120=>['Krew Władcy','Wszyscy twoi nieumarli sojusznicy otrzymują 30...116 pkt. żywotności. Poświęcasz dodatkowe 2% maksymalnych punktów żywotności za każdego sługusa uleczonego w ten sposób.','Dodaje po 30...116 pkt. żywotności twoim nieumarłym sługom. Koszt uleczenia: +2% poświęcanej żywotności na uzdrowionego sługę.'],
121=>['Mściwy Duch','Przez 10...25 sek., za każdym razem, kiedy wybrany przeciwnik atakuje lub używa umiejętności, Mściwy Duch zadaje jemu i jego sojusznikom bezpośrednio przy nim 15...45 pkt. obrażeń od cienia.','(10...25 sek.) Wybranemu przeciwnikowi i przeciwnikom w bezpośredniej odległości zadaje 15...45 pkt. obrażeń, za każdym razem, kiedy ten przeciwnik atakuje lub używa umiejętności.'],
122=>['Szkodliwa Interwencja','Przez 5...20 sek. wybrany przeciwnik otrzymuje o 20% mniej pkt. żywotności. Jeżeli wybrany przeciwnik zginie przeklęty Szkodliwą Interwencją, zostaje przywołana bezpańska kościana poczwara na poziomie 1...17.','(5...20 sek.) Wybrany przeciwnik otrzymuje o 20% mniej pkt. żywotności. Jeżeli ten przeciwnik umrze, będąc pod działaniem tej klątwy, zostanie przyzwana bezpańska kościana poczwara na poziomie 1...17.'],
123=>['Podstępny Pasożyt','Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik trafi podczas ataku, wykradasz mu do 15...45 pkt. żywotności.','(5...15 sek.) Wykrada 15...45 pkt. żywotności, za każdym razem, kiedy trafi atak wybranego przeciwnika.'],
124=>['Przejmujące Dreszcze','Przez 10...40 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia od zimna podczas używania umiejętności, ten przeciwnik zostaje rozproszony, a ty tracisz 8...3 pkt. energii albo Przejmujące Dreszcze przestają działać.','(10...40 sek.) Obrażenia od zimna przerywają umiejętności wybranego przeciwnika. Koszt przerwania: tracisz 8...3 pkt. energii lub Przejmujące Dreszcze przestają działać.'],
125=>['Więdnięcie','Przez 5...35 sek., wybrany przeciwnik posiada degenerację żywotności -2...4 oraz degeneracji energii -1. Jeżeli energia wybranego przeciwnika dojdzie do 0, otrzyma on 15...75 pkt. obrażeń, a Więdnięcie przestanie działać.','(5...35 sek.) Powoduje degenerację żywotności -2...4 i degenerację energii -1. Zadaje 15...75 pkt. obrażeń, jeżeli energia wybranego przeciwnika spadnie do 0. Przestanie działać, jeśli energia tego przeciwnika spadnie do 0.'],
126=>['Przelanie Życia','Przez 6...12 sek. wybrany przeciwnik i przeciwnicy bezpośrednio przy nim posiadają degenerację żywotności -3...8, z kolei ty posiadasz regenerację żywotności o tej samej wartości.','Klątwa działa także na przeciwników bezpośrednio przy celu (6...12 sek.). Powoduje degenerację żywotności -3...8. Posiadasz regenerację żywotności +3...8.'],
127=>['Piętno Przewrotu','Przez 6 sek., następnym razem, kiedy wybrany przeciwnik rzuca czar wymierzony w swojego sojusznika, czar zawodzi, a ty wykradasz przeciwnikowi do 10...92 pkt. żywotności.','(6 sek.) Następny czar wybranego przeciwnika nie zadziała, a ty wykradasz 10...92 pkt. żywotności. Bez efektu, chyba że celem czaru tego przeciwnika jest jeden z jego sojuszników.'],
128=>['Wyssanie Duszy','Przez 10 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, wykradasz mu do 16...80 pkt. żywotności.','(10 sek.) Wykrada 16...80 pkt. żywotności, za każdym razem, kiedy wybrany przeciwnik rzuca czar.'],
129=>['Splugawienie Ciała','Przez 5...35 sek. wybrany przeciwnik otrzymuje jedynie dwie trzecie punktów żywotności podczas leczenia.','(5...35 sek.) Zmniejsza o 33% liczbę punktów żywotności jakie otrzymuje wybrany przeciwnik. Działa tylko na umiejętności zawierające w opisie słowo "otrzymuje".'],
130=>['Demoniczne Ciało','Przez 30...60 sek., za każdym razem kiedy używasz umiejętności, której celem będzie jakiś przeciwnik, zadajesz 5...20 pkt. obrażeń od cienia wszystkim sąsiadującym z tobą wrogom.','(30...60 sek.) Kiedy używasz umiejętności na przeciwniku, zadajesz 5...20 pkt. obrażeń od cienia wszystkim sąsiadującym z tobą wrogom.'],
131=>['Kolczasty Sygnet','Na 3...15 sek. powodujesz krwawienie u wybranego przeciwnika i wszystkich przeciwników bezpośrednio przy nim.','Cel i przeciwnicy w bezpośrednim sąsiedztwie cierpią z powodu krwawienia (3...15 sek.).'],
132=>['Sygnet Plagi','Przenosisz wszystkie przypadłości, wraz z ich pozostałymi czasami działania ( 100...200%), z siebie na wybranego przeciwnika. (50% szans na niepowodzenie, gdy wartość gdy wartość atrybutu Klątwy wynosi 4 lub mniej.)','Przenosi wszystkie przypadłości, wraz z ich pozostałymi czasami działania ( 100...200%), z ciebie na wybranego przeciwnika. 50% szans na niepowodzenie, chyba że wartość Klątw wynosi 5 lub więcej.'],
133=>['Mroczny Pakt','Wybranemu przeciwnikowi zadaje 20...60 pkt. obrażeń od cienia.','Zadaje 20...60 pkt. obrażeń.'],
134=>['Rozkaz Bólu','Przez 5 sek., za każdym razem, kiedy członek drużyny trafi przeciwnika i zada mu obrażenia fizyczne, ten członek drużyny zada dodatkowo 3...16 pkt. obrażeń.','Zaklina wszystkich członków drużyny (5 sek.). 3...16 pkt. dodatkowych obrażeń, za każdym razem, kiedy zadają oni fizyczne obrażenia.'],
135=>['Lękliwość','Przez 4...18 sek., wybrany przeciwnik atakuje 50% wolniej oraz cierpi -1...3 degeneracji żywotności.','(4...18 sek.) Wybrany przeciwnik atakuje o 50% wolniej i posiada degenerację żywotności -1...3.'],
136=>['Cień Strachu','Wybrany przeciwnik i wszyscy przeciwnicy znajdujący się bezpośrednio przy nim atakują 50% wolniej przez następne 5...30 sek.','Klątwa działa także na przeciwników bezpośrednio przy celu (5...30 sek.). Atakują oni o 50% wolniej.'],
137=>['Stężenie Pośmiertne','Przez 8...20 sek., wybrany przeciwnik nie może blokować.','(8...20 sek.) Wybrany przeciwnik nie może blokować.'],
138=>['Mroczne Więzy','Przez 30...60 sek., za każdym razem, kiedy otrzymujesz obrażenia, najbliższy sługus otrzymuje zamiast ciebie 75% tych obrażeń.','(30...60 sek.) Przenosi 75% obrażeń z ciebie na twojego najbliższego sługę.'],
139=>['Przenoszenie Przypadłości','Przez 15...60 sek., za każdym razem, kiedy otrzymujesz nową przypadłość, najbliższy sługa otrzymuje tę przypadłość zamiast ciebie.','(15...60 sek.) Za każdym razem, kiedy otrzymujesz przypadłość, zostaje ona przeniesiona na twojego najbliższego nieumarłego sługę.'],
140=>['Niemoc','Przez 5...35 sek., wybrany przeciwnik posiada degenerację energii -1, zaś ty posiadasz degeneracją żywotności -1. Jeżeli energia wybranego przeciwnika dojdzie do 0, otrzyma on 5...50 pkt. obrażeń, a Niemoc przestanie działać.','(5...35 sek.) Powoduje degenerację energii -1. Zadaje 5...50 pkt. obrażeń, jeżeli energia wybranego przeciwnika spadnie do 0. Posiadasz degenerację żywotności -1. Przestanie działać, jeśli energia tego przeciwnika spadnie do 0.'],
141=>['Rozerwanie Zaklęć','Z wybranego przeciwnika usuwasz zaklęcia w liczbie 5...9. Za każde usunięte zaklęcie mnicha, tracisz 55...25 pkt. żywotności.','Z wybranego przeciwnika usuwa zaklęcia w liczbie 5...9. Koszt usunięcia: za każde zdjęte zaklęcie mnicha tracisz 55...25 pkt. żywotności.'],
142=>['Przewlekła Klątwa','Przez 6...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -1...4 i w trakcie leczenia otrzymują o 25% mniej żywotności.','(6...30 sek.) Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -1...4 i w trakcie leczenia otrzymują o 25% mniej żywotności.'],
143=>['Zdarcie Zaklęcia','Z wybranego przeciwnika zdejmujesz zaklęcia w liczbie 0...2. Jeżeli zaklęcie zostało zdjęte, wykradasz 5...65 pkt. żywotności.','Z wybranego przeciwnika zdejmuje zaklęcia w liczbie 0...2. Efekt usunięcia: wykradasz 5...65 pkt. żywotności.'],
144=>['Odmrożenie','Zostajesz zatruty na 10 sekund. Przeciwnicy w okolicy twojego celu otrzymują po 10...44 pkt. obrażeń od zimna i tracą zaklęcia w liczbie 1...2.','Przeciwnikom w okolicy twojego celu zadaje po 10...44 pkt. obrażeń od zimna; zdejmuje z tych przeciwników zaklęcia w liczbie 1...2. Zostajesz zatruty (10 sek.).'],
145=>['Sygnet Agonii','Krwawisz przez 25 sek. Wszyscy przeciwnicy w pobliżu otrzymują 10...70 pkt. obrażeń.','Przeciwnikom w pobliżu ciebie zadaje po 10...70 pkt. obrażeń. Krwawisz (25 sek.).'],
146=>['Ofiara z Krwi','Otrzymujesz 8...20 pkt. energii.','Otrzymujesz 8...20 pkt. energii.'],
147=>['Mroczna Furia','Przez 5 sek., za każdym razem, kiedy dowolny członek drużyny trafi przeciwnika, otrzyma jedną dawkę adrenaliny. (50% szans na niepowodzenie, gdy wartość Magii Krwi wynosi 4 lub mniej.)','Zaklina członków drużyny (5 sek.). Ci członkowie drużyny otrzymują dawkę adrenaliny, za każdym razem, kiedy ich atak trafi. 50% szans na niepowodzenie, chyba że wartość Magii Krwi wynosi 5 lub więcej.'],
148=>['Rozkaz Wampira','Przez 5 sek., za każdym razem, kiedy niebędący pod wpływem innych zaklęć nekromanty członek drużyny trafi przeciwnika i zada mu obrażenia fizyczne, ten członek drużyny wykrada 3...16 pkt. żywotności.','Zaklina wszystkich członków drużyny (5 sek.). Ci członkowie drużyny, każdym atakiem zadającym obrażenia fizyczne, wykradają po 3...16 pkt. żywotności. Nie działa na członków drużyny znajdujących się pod działaniem innego zaklęcia nekromanty.'],
149=>['Przesyłanie Plagi','Przenosisz 1...3 przypadłości, wraz z pozostałym czasem działania, z siebie na wybranego przeciwnika i wszystkich przeciwników w bezpośredniej odległości.','Przenosisz 1...3 przypadłości, wraz z pozostałym czasem działania, z siebie na wybranego przeciwnika i wszystkich przeciwników w bezpośredniej odległości.'],
150=>['Piętno Bólu','Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia fizyczne, Piętno Bólu zadaje przeciwnikom bezpośrednio przy nim po 10...40 pkt. obrażeń od cienia.','(30 sek.) Przeciwnikom bezpośrednio przy wybranym przeciwniku zadaje po 10...40 pkt. obrażeń, za każdym razem, kiedy otrzymuje on obrażenia fizyczne.'],
151=>['Uczta Zepsucia','Wybrany przeciwnik i wszyscy przeciwnicy znajdujący się bezpośrednio przy nim otrzymują 16...80 pkt. obrażeń od cienia. Wykradasz do 8...40 pkt. żywotności od każdego zranionego przeciwnika, który jest pod wpływem klątwy.','Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 16...80 pkt. obrażeń. Każdemu przeciwnikowi pod działaniem klątwy wykradasz 8...40 pkt. żywotności.'],
152=>['Posmak Śmierci','Wykradnij do 100...400 pkt. żywotności od wybranego sojuszniczego wskrzeszonego truposza.','Sojuszniczemu nieumarłemu słudze wykrada 100...400 pkt. żywotności.'],
153=>['Wampiryczne Spojrzenie','Wykradasz do 18...60 pkt. żywotności od wybranego przeciwnika.','Wykrada 18...60 pkt. żywotności.'],
154=>['Dotyk Plagi','Na wybranego przeciwnika przenosisz przypadłości w liczbie 1...3, pod których działaniem się znajdujesz, wraz z ich pozostałym czasem działania.','Przenosi 1...3 przypadłości z ciebie na wybranego przeciwnika.'],
155=>['Podły Dotyk','Dotknij wybranego przeciwnika by zadać 20...65 pkt. obrażeń.','Zadaje 20...65 pkt. obrażeń.'],
156=>['Wampiryczny Dotyk','Dotknij wybranego przeciwnika by wykraść mu do 29...74 pkt. żywotności.','Wykrada 29...74 pkt. żywotności.'],
157=>['Rytuał Krwi','Przez 8...14 sek. wybrany dotknięty sojusznik posiada regenerację energii +3. Rytuał Krwi nie może być użyty na rzucającym ten czar.','(8...14 sek.) Regeneracja energii +3. Na cel nie można wybrać siebie.'],
158=>['Dotyk Agonii','Wybrany dotknięty przeciwnik otrzymuje 20...58 pkt. obrażeń od cienia.','Zadaje 20...58 pkt. obrażeń.'],
159=>['Osłabienie Zbroi','Wybrany przeciwnik i przeciwnicy bezpośrednio przy twoim celu na 5...20 sek. otrzymują pękniętą zbroję.','Działa także na przeciwników w bezpośredniej odległości. Wywołuje przypadłość pęknięta zbroja (5...20 sek.).'],
160=>['Szybkość Wiatru','Przez 5...13 sek., wybrany sojusznik porusza się 33% szybciej.','(5...13 sek.) Wybrany sojusznik porusza się o 33% szybciej.'],
162=>['Podmuch','Powala wybranego przeciwnika na 2 sek. Ten czar powoduje wyczerpanie. (50% szans na niepowodzenie, gdy wartość Magii Powietrza wynosi 4 lub mniej.)','Powoduje powalenie. Powoduje u ciebie wyczerpanie. 50% szans na niepowodzenie, chyba że wartość Magii Powietrza wynosi 5 lub więcej.'],
163=>['Trąba Powietrzna','Wszyscy przeciwnicy w bezpośrednim sąsiedztwie otrzymują po 15...75 pkt. obrażeń od zimna. Atakujący przeciwnicy trafieni przez Tornado zostają powaleni. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia pobliskich wrogów, zamiast będących w bezpośrednim sąsiedztwie.','Trafia przeciwników w bezpośrednim sąsiedztwie. Zadaje 15...75 pkt. obrażeń od zimna. Powoduje powalenie atakujących przeciwników. Trafia pobliskich zamiast bezpośrednio sąsiadujących podczas Przemagicznienia.'],
164=>['Zestrojenie z Żywiołami','Przez 25...60 sek. osiągasz dostrojenie do żywiołów powietrza, ognia, wody oraz ziemi i zyskujesz +1...2 pkt. do tych atrybutów. Zyskujesz 1 pkt. energii oraz 50% podstawowego kosztu energii umiejętności za każdym razem, gdy używasz czarów związanych z tymi żywiołami.','(25...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1...2 pkt. Zyskujesz 1 pkt. energii oraz 50% podstawowego kosztu energii używanej umiejętności związanych z magią powietrza, ognia, wody i ziemi.'],
165=>['Zbroja Ziemi','Przez 30 sek., otrzymujesz +24...60 pkt. pancerza, ale poruszasz się 50...14% wolniej.','(30 sek.) Posiadasz +24...60 pkt. pancerza. Poruszasz się o 50...14% wolniej.'],
166=>['Kinetyczny Pancerz','Przez 12 sek. masz +20...80 pkt. pancerza. Za każdym razem, kiedy rzucasz czar, Kinetyczny Pancerz zostaje odnowiony na 12 sek.','(12 sek.) Masz +20...80 pkt. pancerza. Premiowe odnowienie: rzuć czar.'],
167=>['Erupcja','Wywołaj Erupcję w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...40 pkt. obrażeń od ziemi oraz zostają oślepieni na 10 sek.','W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Wywołuje przypadłość oślepienie (10 sek.).'],
168=>['Magnetyczna Aura','Przez 1...8 sek., blokujesz następny atak przeciwko sobie i zadajesz 10...50 obrażeń atakującemu przeciwnikowi. Podczas Przemagicznienia wszyscy członkowie drużyny w zasięgu słuchu zostają wzmocnieni aurą.','(1...8 sek.) Zablokuj następny atak i odbij 10...50 obrażeń do napastnika. Podczas Przemagicznienia wzmocnij aurą wszystkich członków drużyny w zasięgu słuchu.'],
169=>['Zestrojenie z Ziemią','Przez 36...60 sek. postać jest dostrojona do ziemi. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ziemi, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','(36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ziemi, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
170=>['Trzęsienie Ziemi','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Trzęsienie Ziemi. Wszyscy przeciwnicy w pobliżu tego miejsca zostają powaleni i otrzymują po 26...100 pkt. obrażeń od ziemi. Ten czar powoduje wyczerpanie.','Zadaje 26...100 pkt. obrażeń od ziemi. Trafia także przeciwników w pobliżu celu. Powoduje powalenie. Powoduje u ciebie wyczerpanie.'],
171=>['Ukamienowanie','Wyślij ogromny kamień, który, jeżeli trafi, zada wybranemu przeciwnikowi 45...105 pkt. obrażeń od ziemi. Jeśli Ukamienowanie trafi przeciwnika cierpiącego na osłabienie, to zostanie on powalony.','Pocisk: zadaje 45...105 pkt. obrażeń od ziemi. Powoduje powalenie, jeżeli wybrany przeciwnik jest osłabiony.'],
172=>['Kamienne Sztylety','Wyślij dwa Kamienne Sztylety. Każdy z Kamiennych Sztyletów zadaje 8...33 pkt. obrażeń od ziemi, jeżeli trafi wybranego przeciwnika. Będąc pod wpływem Przemagicznienia, każdy pocisk powoduje Krwawienie przez 1...5 sek.','Dwa pociski: każdy zadaje 8...33 pkt. obrażeń od ziemi. Podczas Przemagicznienia powoduje krwawienie przez 1...5 sek.'],
173=>['Grząska Ziemia','Przez 5...20 sek., wszyscy przeciwnicy w pobliżu poruszają się o 50% wolniej.','Klątwa działa na przeciwników w pobliżu ciebie (5...20 sek.). Ci przeciwnicy poruszają się o 50% wolniej.'],
174=>['Wstrząs Wtórny','Wszyscy przeciwnicy w pobliżu otrzymują 15...85 pkt. obrażeń od ziemi. Wszyscy powaleni przeciwnicy otrzymują 15...85 pkt. dodatkowych obrażeń od ziemi.','Zadaje 15...85 obrażeń od ziemi pobliskim wrogom. Zadaje 15...85 więcej obrażeń od ziemi powalonym wrogom.'],
175=>['Ochrona przed Żywiołami','W miejscu, w którym przebywasz tworzysz Ochronę przed Żywiołami. Przez 8...20 sek. nie będący duchami sojusznicy w tej okolicy posiadają +24 punkty pancerza przeciwko obrażeniom od żywiołów.','(8...20 sek.) Sojusznicy w granicach tej ochrony posiadają +24 pkt. pancerza przeciwko obrażeniom od żywiołów. Nie działa na duchy.'],
176=>['Ochrona przed Ciosami','Tworzysz Ochronę przed Ciosami w miejscu, w którym przebywasz. Przez 5...20 sek. nie będący duchami sojusznicy na tym obszarze mają 50% szans na blokowanie ciosów wręcz.','(5...20 sek.) Sojusznicy w granicach tej ochrony posiadają 50% szans na blokowanie ataków wręcz. Nie działa na sojusznicze duchy.'],
177=>['Ochrona przed Przeciwnikami','Tworzysz Ochronę przed Przeciwnikami w miejscu, w którym przebywasz. Przez 8...20 sek. wszyscy nie będący duchami przeciwnicy w okolicy poruszają się o 50% wolniej.','(8...20 sek.) Przeciwnicy w granicach tej ochrony poruszają się o 50% wolniej.'],
178=>['Eteryczny Cud','Tracisz wszystkie zaklęcia. Przez 8...20 sek. posiadasz regenerację energii +6. Gdy Eteryczny Cud przestanie działać, tracisz 3 pkt. żywotności za każdy posiadany pkt. energii. Ten czar powoduje wyczerpanie.','(8...20 sek.) Posiadasz regenerację energii +6. Efekt końcowy: za każdy punkt posiadanej energii tracisz 3 pkt. żywotności. Tracisz wszystkie zaklęcia. Powoduje u ciebie wyczerpanie.'],
179=>['Zapalające Więzy','Po 3 sek., wybrany przeciwnik i przeciwnicy bezpośrednio przy nim otrzymują po 20...80 pkt. obrażeń od ognia oraz zostają podpaleni na 1...3 sek. Jeśli cel zginie, aktywuje się wcześniej.','(3 sek.) Efekt końcowy: przeciwnikom w pobliżu twojego celu zadaje 20...80 pkt. obrażeń od ognia i wywołuje przypadłość płonięcie (1...3 sek.). Uruchamia się też po śmierci przeciwnika.'],
180=>['Aura Odnowy','Przez 60 sek., za każdym razem, kiedy rzucisz czar, otrzymasz 0...1 pkt. energii i punkty żywotności w liczbie równej 200...500% energetycznego kosztu czaru.','(60 sek.) Za każdym razem, kiedy rzucisz czar, otrzymasz 0...1 pkt. energii i punkty żywotności w liczbie równej 200...500% energetycznego kosztu czaru.'],
181=>['Eteryczna Odnowa','Przez 5...20 sek., za każdym razem, kiedy rzucasz czar, otrzymujesz 1...4 pkt. energii i 5...20 pkt. żywotności za każde zaklęcie, które masz na sobie.','(5...20 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1...4 pkt. energii i 5...20 pkt. żywotności, za każde zaklęcie, które masz na sobie.'],
182=>['Przyzwanie Ognia','Przez 60 sek., jeżeli posiadasz ognistą broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od ognia.','(60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od ognia. Bez efektu, jeśli twoja broń nie zadaje obrażeń od ognia.'],
183=>['Piekło','Przeciwnicy w kontakcie otrzymują 30...135 pkt. obrażeń od ognia.','Przeciwnikom bezpośrednio przy tobie zadaje po 30...135 pkt. obrażeń od ognia.'],
184=>['Zestrojenie z Ogniem','Przez 36...60 sek. postać jest dostrojona do ognia. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ognia, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','(36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Ognia, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
185=>['Wypalanie Umysłu','Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 15...60 pkt. obrażeń od ognia oraz zostaje podpalony na 1...10 sek. Ten czar powoduje wyczerpanie.','Zadaje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej energii niż wybrany przeciwnik, zadaje 15...60 pkt. dodatkowych obrażeń od ognia i wywołuje przypadłość płonięcie (1...10 sek.). Powoduje u ciebie wyczerpanie.'],
186=>['Kula Ognia','Wysyłasz kulę ognia, która uderza w cel i pobliskich przeciwników, zadając każdemu 7...112 pkt. obrażeń od ognia.','Pocisk: zadaje celowi i pobliskim przeciwnikom po 7...112 pkt. obrażeń od ognia.'],
187=>['Meteoryt','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują 7...112 pkt. obrażeń od ognia i zostają powaleni. Ten czar powoduje wyczerpanie.','Zadaje 7...112 pkt. obrażeń od ognia i powala. Trafia także przeciwników bezpośrednio przy wybranym przeciwniku. Powoduje u ciebie wyczerpanie.'],
188=>['Ognisty Wybuch','Przeciwnicy w pobliżu otrzymują 15...120 pkt. obrażeń od ognia.','Wszystkim przeciwnikom w pobliżu ciebie zadaje po 15...120 pkt. obrażeń od ognia.'],
189=>['Inwokacja Rodgorta','Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują 15...120 obrażeń od ognia oraz zostają podpaleni na 1...3 sek.','Zadaje 15...120 pkt. obrażeń od ognia. Działa także na przeciwników w pobliżu twojego celu. Wywołuje przypadłość płonięcie (1...3 sek.).'],
190=>['Piętno Rodgorta','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim znajdują się pod działaniem klątwy Piętna Rodgorta. Przez 10...35 sek., za każdym razem, kiedy jeden z tych przeciwników otrzymuje obrażenia od ognia, zostaje podpalony na 1...4 sek.','Klątwa działa także na przeciwników w pobliżu twojego celu (10...35 sek.). Wywołuje przypadłość płonięcie (1...4 sek.), kiedy ci przeciwnicy otrzymują obrażenia od ognia.'],
191=>['Samospalenie','Wybrany przeciwnik otrzymuje 20...75 obrażeń od ognia oraz zostaje podpalony na 1...3 sek.','Zadaje 20...75 pkt. obrażeń od ognia. Wywołuje przypadłość płonięcie (1...3 sek.).'],
192=>['Deszcz Meteorytów','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Deszcz Meteorytów. Przez 9 sek., co 3 sek. wszyscy przeciwnicy w tej okolicy otrzymują 7...112 pkt. obrażeń od ognia i zostają powaleni. Ten czar powoduje wyczerpanie.','Co 3 sek. zadaje 7...112 pkt. obrażeń od ognia i powala (9 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu. Powoduje u ciebie wyczerpanie.'],
193=>['Feniks','Ognisty Feniks pojawia się obok ciebie i leci w kierunku celu, wybuchając trafia w cel. Wybuch rani cel oraz pobliskich przeciwników za 10...60 pkt. obrażeń od ognia. Podczas Przemagicznienia, sojusznicy znajdujący się w zasięgu wybuchu zostają uzdrowieni o 20...80 pkt. żywotności.','Pocisk: wybranemu przeciwnikowi i pobliskim przeciwnikom zadaje po 10...60 pkt. obrażeń od ognia. Uzdrawia sojuszników o 20...80, jeśli jesteś pod wpływem Przemagicznienia.'],
194=>['Flara','Wystrzel Flarę, która po trafieniu zadaje wybranemu przeciwnikowi 20...65 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, Flara trafia również pobliskich wrogów.','Pocisk: zadaje 20...65 pkt. obrażeń od ognia. Podczas Przemagicznienia trafia pobliskich.'],
195=>['Krynica Lawy','Przez 5 sek. przeciwnicy znajdujący się bezpośrednio w miejscu, w którym ten czar został rzucony otrzymują w każdej sekundzie 5...50 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia pobliskich wrogów, zamiast tych będących w bezpośrednim sąsiedztwie.','Zadaje 5...50 pkt. obrażeń od ognia na sek. (przez 5 sek.). Trafia wrogów w pobliżu twojego początkowego położenia. Podczas Przemagicznienia zasięg zwiększony do pobliskich przeciwników.'],
196=>['Palący Żar','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Palący Żar. Przez 5 sek., przeciwnicy w tej okolicy otrzymują w każdej sekundzie po 10...40 pkt. obrażeń od ognia. Gdy Palący Żar przestanie działać, przeciwnicy w okolicy zostaną podpaleni na 3 sek.','W każdej sekundzie zadaje 10...40 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Efekt końcowy: wywołuje przypadłość płonięcie (3 sek.).'],
197=>['Deszcz Ognia','Wywołaj Deszcz Ognia w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 10 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 5...35 pkt. obrażeń od ognia.','W każdej sekundzie zadaje 5...35 pkt. obrażeń od ognia (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
198=>['Glif Mocy Żywiołów','Przez 25 sek. twoje atrybuty związane z żywiołami zostają zwiększone o 2 dla następnych czarów w liczbie 10.','(25 sek.) Dla następnych czarów w liczbie 10 zwiększa twoje atrybuty związane z żywiołami o +2.'],
199=>['Glif Energii','Twoje kolejne zaklęcia 1...3 nie wywołują limitu aktywacyjnego i kosztują 10...25 mniej energii. Twoje atrybuty związane z żywiołami są zwiększane o 1...2.','Twoje kolejne zaklęcia 1...3 nie wywołują limitu aktywacyjnego i kosztują 10...25 mniej energii. Premia 1...2 do wszystkich atrybutów związanych z żywiołami.'],
200=>['Glif Mniejszej Energii','Przez następne 15 sek. twoje następne czary w liczbie 2 kosztują o 10...18 pkt. energii mniej.','(15 sek.) Twoje następne czary w liczbie 2 kosztują o 10...18 pkt. energii mniej.'],
201=>['Glif Koncentracji','Przez 15 sek. twoje następne czary w liczbie 1 nie mogą być przerwane i ignorują efekt oszołomienia.','(15 sek.) Twoje następne czary w liczbie 1 nie mogą zostać przerwane i nie działa na nie przypadłość oszołomienie.'],
202=>['Glif Ofiary','Przez 15 sek., twój następny czar zostaje rzucony natychmiast, ale odnawia się 30 sek. dłużej. Kończy się przedwcześnie, jeśli użyjesz umiejętności nie będącej czarem.','(15 sek.) Twój następny czar zostaje rzucony natychmiast, ale odnawia się 30 sek. dłużej. Kończy się, jeśli użyjesz umiejętności nie będącej czarem.'],
203=>['Glif Odnowy','Przez 15 sek. twój następny czar odnawia się natychmiast.','(15 sek.) Twój następny czar natychmiast się odnawia.'],
204=>['Rdza','Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 10...85 pkt. obrażeń od zimna. Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim potrzebują 2 razy więcej czasu na użycie sygnetów. Jeśli jesteś pod wpływem Przemagicznienia, przeciwnicy trafieni Rdzą nie mogą skorzystać ze swoich sygnetów przez 1...10 sek.','Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 10...85 pkt. obrażeń od zimna. Nakłada klątwę na cel i przeciwników bezpośrednio przy nim (na 5...20 sek.). Podwaja czas aktywacji sygnetów. Przerywa i uniemożliwia wykorzystanie sygnetów na 1...10 sek., jeśli jesteś pod wpływem Przemagicznienia.'],
205=>['Fala Błyskawic','Po 3 sek., wybrany przeciwnik zostaje powalony i otrzymuje 14...100 pkt. obrażeń od błyskawic.','(3 sek.) Efekt końcowy: zadaje 14...100 pkt. obrażeń od piorunów i powala.'],
206=>['Zbroja Mrozu','Przez 10...34 sek., przeciwko obrażeniom fizycznym posiadasz +40 pkt. pancerza. Zbroja Mrozu przestanie działać, jeżeli użyjesz Magii Ognia.','(10...34 sek.) Posiadasz +40 pkt. pancerza przeciwko obrażeniom fizycznym. Przestanie działać, jeśli użyjesz Magii Ognia.'],
207=>['Przyzwanie Mrozu','Przez 60 sek., jeżeli posiadasz zadającą obrażenia od zimna broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od zimna.','(60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od zimna. Bez efektu, jeśli twoja broń nie zadaje obrażeń od zimna.'],
208=>['Zestrojenie z Wodą','Przez 36...60 sek. postać jest dostrojona do wody. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Wody, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','(36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Wody, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
209=>['Zamrożenie Umysłu','Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...60 pkt. obrażeń od zimna oraz porusza się o 90% wolniej przez 1...5 sek. Ten czar powoduje wyczerpanie.','Zadaje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii niż wybrany przeciwnik, to umiejętność zadaje 10...60 pkt. dodatkowych obrażeń od zimna i o 90% spowalnia ruch (1...5 sek.). Powoduje u ciebie wyczerpanie.'],
210=>['Lodowe Więzienie','Przez 8...20 sek., nogi wybranego przeciwnika zostają uwięzione w lodzie, powodując jego spowolnienie o 66%. Działanie czaru skończy się, gdy cel otrzyma obrażenia od ognia.','(8...20 sek.) Wybrany przeciwnik porusza się o 66% wolniej. Przestanie działać, jeśli ten przeciwnik otrzyma obrażenia od ognia.'],
211=>['Lodowe Kolce','Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim otrzymują 20...80 pkt. obrażeń od zimna oraz przez 2...6 sek. poruszają się o 66% wolniej.','Klątwa działa także na przeciwników bezpośrednio przy celu (2...6 sek.). Ci przeciwnicy poruszają się o 66% wolniej. Efekt początkowy: zadaje 20...80 pkt. obrażeń od zimna.'],
212=>['Mroźny Wybuch','Wszyscy przeciwnicy w pobliżu otrzymują 10...85 obrażeń od zimna oraz poruszają się o 66% wolniej przez 3...8 sek.','Nakłada klątwę na przeciwników w pobliżu ciebie. Ci przeciwnicy poruszają się o 66% wolniej (3...8 sek.). Efekt początkowy: przeciwnikom w pobliżu ciebie zadaje po 10...85 pkt. obrażeń od zimna.'],
213=>['Lodowa Burza','Wyrzuć lodowy odłamek, który zadaje wybranemu przeciwnikowi 10...85 obrażeń od zimna oraz spowalnia go o 66% na 2...6 sek.','Pocisk: zadaje 10...85 pkt. obrażeń od zimna. Wybrany przeciwnik porusza się o 66% wolniej (2...6 sek.).'],
214=>['Lodowa Włócznia','Wystrzeliwujesz Lodową Włócznię, która, jeżeli trafi, zadaje wybranemu przeciwnikowi 10...60 pkt. obrażeń od zimna. Będąc pod wpływem Przemagicznienia, otrzymujesz premię +1...4 do regeneracji żywotności przez 5 sek.','Pocisk: zadaje 10...60 pkt. obrażeń od zimna. Bonus +1...4 do regeneracji żywotności przez 5 sek. podczas Przemagicznienia.'],
215=>['Wir','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Wir. Przez 10 sek. przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...25 pkt. obrażeń od zimna. Wir przerywa rzucane czary, gdy trafia w przeciwnika. Ten czar powoduje wyczerpanie.','W każdej sekundzie zadaje 10...25 pkt. obrażeń od zimna i przerywa czary (10 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu. Powoduje u ciebie wyczerpanie.'],
216=>['Żelazna Mgła','Na 8...15 sek. twój pancerz zwiększa się o +15. Twoje zaklęcia Magii Powietrza kierowane przeciwko wrogowi aktywują się i odnawiają 33% szybciej, ale otrzymujesz 2 pkt. przemagicznienia.','(8...15 sek.) Twój pancerz zwiększa się o +15. Twoje zaklęcia Magii Powietrza kierowane przeciwko wrogowi aktywują się i odnawiają 33% szybciej, ale otrzymujesz 2 pkt. przemagicznienia.'],
217=>['Krystaliczna Fala','Przeciwnicy bezpośrednio przy tobie otrzymują 10...70 pkt. obrażeń, ale zostają wyleczeni z wszelkich przypadłości. Każda usunięta przypadłość zadaje 5...15 pkt. obrażeń.','Przeciwnikom bezpośrednio przy tobie zadaje po 10...70 pkt. obrażeń. Ci przeciwnicy tracą wszystkie przypadłości i otrzymują 5...15 pkt. obrażeń za każdą usuniętą przypadłość.'],
218=>['Obsydianowe Ciało','Przez 8...20 sek., otrzymujesz +20 pkt. pancerza i nie możesz być celem czarów przeciwnika, ale nie możesz atakować i otrzymujesz -2 do degeneracji energii.','(8...20 sek.) Otrzymujesz +20 do pancerza i nie możesz być celem czarów przeciwnika. Nie możesz atakować i otrzymujesz -2 do degeneracji energii.'],
219=>['Obsydianowy Płomień','Wybranemu przeciwnikowi zadajesz 22...112 pkt. obrażeń. Ten czar ignoruje pancerz, ale powoduje wyczerpanie.','Zadaje 22...112 pkt. obrażeń. Powoduje u ciebie wyczerpanie.'],
220=>['Oślepiający Błysk','Wybrany przeciwnik zostaje oślepiony na 3...8 sek.','Wywołuje przypadłość oślepienie (3...8 sek.).'],
221=>['Przyzwanie Błyskawicy','Przez 60 sek., jeżeli posiadasz zadającą obrażenia od błyskawic broń, twoje ataki zadają dodatkowe 5...20 pkt. obrażeń od błyskawic.','(60 sek.) Twoje ataki zadają +5...20 pkt. obrażeń od błyskawic. Bez efektu, jeśli twoja broń nie zadaje obrażeń od błyskawic.'],
222=>['Uderzenie Błyskawicą','Wybranemu przeciwnikowi zadajesz 10...60 pkt. obrażeń od elektryczności. To zaklęcie ma 25% penetrację pancerza. Jeśli jesteś pod wpływem Przemagicznienia, ten przeciwnik zostanie przeklęty Uderzeniem Pioruna przez 3 sek. Gdy klątwa dobiega końca, cel zostaje raz jeszcze trafiony przez piorun za 20...40 pkt. obrażeń od elektryczności.','Zadaje 10...60 pkt. obrażeń od elektryczności. 25% penetracji pancerza. Klątwa na 3 sek. podczas Przemagicznienia. Efekt końcowy: zadaje 20...40 pkt. obrażeń od elektryczności.'],
223=>['Wyładowanie Łańcuchowe','Wybrany przeciwnik i maksymalnie dwóch innych przeciwników w jego pobliżu otrzymuje 10...85 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicia pancerza oraz powoduje wyczerpanie, jeśli nie znajdujesz się pod wpływem zaklęcia.','Zadaje 10...85 pkt. obrażeń od błyskawic. Trafia także dwóch przeciwników w pobliżu twojego celu. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie, jeśli nie znajdujesz się pod wpływem zaklęcia.'],
224=>['Osłabiający Ładunek','Wybrany przeciwnik otrzymuje 25...50 pkt. obrażeń od błyskawic oraz zostaje osłabiony na 5...20 sek. Ten czar posiada 25% przebicie pancerza.','Zadaje 25...50 pkt. obrażeń od błyskawic. Wywołuje przypadłość osłabienie (5...20 sek.). 25% przebicie pancerza.'],
225=>['Zestrojenie z Powietrzem','Przez 36...60 sek. postać jest dostrojona do powietrza. Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Powietrza, otrzymasz 1 pkt. energii plus 30% pkt. energetycznego kosztu tej umiejętności.','(36...60 sek.) Za każdym razem, kiedy użyjesz umiejętności związanej z Magią Powietrza, otrzymasz 1 pkt. energii plus 30% pkt. zużytej energii.'],
226=>['Wstrząs Mózgu','Wybrany przeciwnik otrzymuje 10...50 pkt. obrażeń od błyskawic. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...50 pkt. obrażeń od błyskawic oraz zostaje powalony. Ten czar posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Zadaje 10...50 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic i powala, jeżeli masz więcej energii niż ten przeciwnik. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
227=>['Migoczące Piętno','Przez 10 sek., wskazany wróg otrzymuje co sekundę 5...25 pkt. obrażeń. Klątwa ta kończy się, kiedy użyjesz innej umiejętności na tym celu.','(10 sek.) Co sekundę zadaje 5...25 pkt. obrażeń. Przestaje działać, jeśli użyjesz umiejętności, której celem jest ten przeciwnik.'],
228=>['Grzmot','W miejscu, w którym znajduje się wybrany przeciwnik, wywołuje potężne uderzenie pioruna, zadające 10...50 pkt. obrażeń. Cel i wszyscy sąsiadujący z nim przeciwnicy mają pękniętą zbroję i zostają osłabieni na 5...20 sek. Ten czar ma 25% przebicia pancerza.','Zadaje 10...50 pkt. obrażeń. Trafia też pobliskich wrogów. Wywołuje pęknięcie zbroi i osłabienie (na 5...20 sek.). 25% przebicia pancerza.'],
229=>['Piorun Kulisty','Wystrzeliwujesz Błyskawicę Kulistą, która po trafieniu zadaje wybranemu przeciwnikowi 10...100 pkt. obrażeń od elektryczności. To zaklęcie ma 25% penetrację pancerza.','Pocisk: zadaje 10...100 pkt. obrażeń od elektryczności. 25% penetracji pancerza.'],
230=>['Oszczep Błyskawicy','Wystrzeliwuje Oszczep Błyskawicy, który po trafieniu zadaje 15...50 obrażeń od elektryczności. Oszczep Błyskawicy przerywa ataki przeciwników. To zaklęcie ma 25% penetracji pancerza i trafia wszystkich przeciwników między tobą a celem.','Pocisk: zadaje 15...50 pkt. obrażeń od elektryczności. Przerywa, jeśli twój cel wykonywał atak. 25% penetracji pancerza. Trafia wszystkich przeciwników między tobą a celem.'],
231=>['Wstrząs','Wybrany dotknięty przeciwnik zostaje powalony i otrzymuje 10...60 pkt. obrażeń od błyskawic. Ta umiejętność posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Zadaje 10...60 pkt. obrażeń od błyskawic. Powoduje powalenie. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
232=>['Elektryzujący Dotyk','Dotknięty cel i będący w bezpośrednim sąsiedztwie przeciwnicy zostają uderzeni piorunem za 10...60 pkt. obrażeń od elektryczności, zostają oślepieni na 1...4 sek. i dostają przypadłość pękniętej zbroi na 1...10 sek. To zaklęcie ma 25% penetrację pancerza.','Zadaje 10...60 pkt. obrażeń od elektryczności. Trafia również wrogów stojących w bezpośrednim sąsiedztwie celu. Powoduje oślepienie (1...4 sek.) i pękniętą zbroję (1...10) u wszystkich trafionych przeciwników. 25% penetracji pancerza.'],
233=>['Wirująca Aura','Przez 3...7 sek. wzmacnia cię Wirująca Aura i otrzymujesz +1...6 regeneracji żywotności oraz masz 50% szansy na zablokowanie pocisków. Podczas Przemagicznienia rzucenie tego zaklęcia spowoduje, że wszyscy członkowie drużyny w zasięgu słuchu zostają wzmocnieni aurą.','(3...7 sek.) Daje +1...6 regeneracji żywotności oraz 50% szansy na zablokowanie pocisków. Podczas Przemagicznienia wzmacnia wszystkich członków drużyny w zasięgu słuchu.'],
234=>['Przenikliwy Chłód','Wywołaj Przenikliwy Chłód w miejscu, gdzie znajduje się wybrany przeciwnik. Wszyscy przeciwnicy w okolicy otrzymują 10...85 pkt. obrażeń od zimna oraz przez 10 sek. poruszają się o 66% wolniej.','Klątwa działa także na przeciwników w okolicy twojego celu (10 sek.). Ci przeciwnicy poruszają się o 66% wolniej. Efekt początkowy: zadaje 10...85 pkt. obrażeń od zimna.'],
235=>['Nieostry Wzrok','Przez 4...10 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim są pod działaniem klątwy Nieostry Wzrok. Pod wpływem klątwy, ci przeciwnicy mają 50% szans na nietrafianie, kiedy atakują.','Klątwa działa także na przeciwników bezpośrednio przy celu (4...10 sek.). Ci przeciwnicy posiadają 50% szans na nietrafianie.'],
236=>['Mglisty Kształt','Przez 10...45 sek., nie możesz otrzymać, ani zadać obrażeń podczas ataku.','(10...45 sek.) Nie otrzymujesz obrażeń z ataków. Twoje ataki nie zadają obrażeń.'],
237=>['Wodny Trójząb','Wyślij szybko poruszający się Wodny Trójząb, który przy trafieniu zadaje wybranemu przeciwnikowi 10...90 pkt. obrażeń od zimna. Jeśli atak trafi poruszającego się przeciwnika, przeciwnik ten zostaje powalony.','Szybki pocisk: zadaje 10...90 pkt. obrażeń od zimna; powala poruszających się przeciwników.'],
238=>['Mglista Zbroja','Przez 8...20 sek., zyskujesz +10...40 pkt. pancerza oraz poruszasz się o 33% szybciej.','(8...20 sek.) Posiadasz +10...40 pkt. pancerza i poruszasz się o 33% szybciej.'],
239=>['Ochrona przed Krzywdą','W miejscu, w którym przebywasz, tworzysz Ochronę przed Krzywdą. Przez 5...15 sek. nie będący duchami sojusznicy w tej okolicy otrzymują po 12...24 pkt. pancerza przeciwko obrażeniom od ognia i po 1...3 pkt. pancerza przeciwko innym obrażeniom.','(5...15 sek.) Sojusznicy w granicach tej ochrony posiadają +12...24 pkt. pancerza przeciwko obrażeniom od ognia i +1...3 pkt. pancerza przeciwko innym obrażeniom. Nie działa na duchy.'],
240=>['Pogrom','Atak zadaje 10...55 pkt. świętych obrażeń. Jeśli cel atakuje, otrzymuje dodatkowe 10...35 pkt. świętych obrażeń.','Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...35 pkt. dodatkowych świętych obrażeń, jeżeli cel atakuje.'],
241=>['Życiodajna Więź','Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia pochodzące od ataków, połowa tych obrażeń zostanie przekierowana na ciebie. Obrażenia, które otrzymasz w ten sposób zostaną zmniejszone o 3...30 pkt.','Połowa obrażeń jakie otrzymuje wybrany sojusznik z ataków jest przenoszona na ciebie. Przenoszone obrażenia zmniejszane są o 3...30. Na cel nie można wybrać siebie.'],
242=>['Duch Baltazara','Podczas gdy utrzymujesz to zaklęcie, kiedy wybrany sojusznik otrzyma obrażenia, zwiększy się jego adrenalina i energia. (Ilość otrzymywanej adrenaliny jest wprost proporcjonalna do wartości atrybutu Modlitwy Ofensywne.)','Wybrany sojusznik dostaje adrenalinę i 1 pkt. energii, kiedy otrzymuje obrażenia.'],
243=>['Siła Honoru','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje w walce wręcz 5...25 pkt. dodatkowych obrażeń.','W walce wręcz wybrany sojusznik zadaje 5...25 pkt. dodatkowych obrażeń.'],
244=>['Dostrojenie do Życia','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje o 30% mniej obrażeń w walce, ale podczas leczenia otrzymuje o 14...50% pkt. żywotności więcej.','Wybrany sojusznik otrzymuje podczas uzdrawiania o 14...50% więcej żywotności. Ten sojusznik zadaje swoimi atakami o 30% mniej obrażeń.'],
245=>['Ochronny Duch','Przez 5...23 sek. wybrany sojusznik na skutek pojedynczego ataku lub czaru nie może stracić więcej niż 10% maksymalnej żywotności.','(5...23 sek.) Otrzymywane obrażenia zmniejszane są do 10% maksymalnej żywotności wybranego sojusznika.'],
246=>['Boska Interwencja','Przez 10 sek., kiedy następnym razem wybrany sojusznik ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 26...240 pkt. żywotności.','(10 sek.) Neguje następne śmiertelne obrażenia, jakie miałby otrzymać wybrany sojusznik. Efekt zanegowania: dodaje 26...240 pkt. żywotności.'],
247=>['Symbol Gniewu','Tworzysz Symbol Gniewu w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek. sąsiadujący wrogowie odnoszą co sekundę 10...40 pkt. świętych obrażeń.','W każdej sekundzie (przez 5 sek.) zadaje 10...40 pkt. obrażeń od zimna. Trafia przeciwników sąsiadujących z początkowej lokalizacji wybranego wroga.'],
248=>['Pomsta','Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia pochodzące z ataków, czar zadaje atakującemu 33% tych obrażeń (maksymalnie 5...20 pkt. obrażeń).','Przekazuje źródłu 33% obrażeń z każdego ataku (maksymalnie 5...20).'],
249=>['Święty Gniew','Przez 10...30 sek., w kolejnych (1...10) sytuacjach kiedy wskazany sojusznik otrzymuje obrażenia od ataku, czar ten odbija 66% tych obrażeń z powrotem na ich źródło (maksymalnie 5...50 pkt. obrażeń).','(10...30 sek.) Odbija 66% obrażeń z każdego ataku (maksymalnie 5...50) z powrotem na ich źródło. Kończy się po 1...10-krotnym zadaniu obrażeń. Na cel nie można wybrać siebie.'],
250=>['Więź Esencji','Podczas gdy utrzymujesz to zaklęcie, kiedy wybrany sojusznik otrzyma obrażenia fizyczne lub obrażenia od żywiołów, twoja energia zwiększy się o 1.','Otrzymujesz 1 pkt. energii, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia fizyczne lub obrażenia od żywiołów.'],
251=>['Zgubne Leczenie','Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik będzie uzdrawiany, uzdrawiający otrzyma 15...80 pkt. świętych obrażeń.','(30 sek.) Za każdym razem, kiedy wybrany przeciwnik będzie uzdrawiany, uzdrawiający otrzyma 15...80 pkt. świętych obrażeń.'],
252=>['Wygnanie','Wybrany przeciwnik otrzymuje 20...65 świętych obrażeń.','Zadaje 20...65 pkt. świętych obrażeń. Przyzwanym stworzeniom zadaje podwójne obrażenia.'],
253=>['Zgubna Ofiara','Przez 8...20 sek., za każdym razem, kiedy wybrany przeciwnik i przeciwnicy bezpośrednio przy nim poświecą punkty żywotności, stracą podwójną ich liczbę.','Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Podwaja poświęcaną żywotność.'],
254=>['Życiodajny Duch','Przez 30 sek., za każdym razem, kiedy wybrany sojusznik atakuje lub rzuca czar, otrzymuje 5...20 pkt. żywotności.','(30 sek.) Dodaje 5...20 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik atakuje lub rzuca czar.'],
255=>['Czujny Duch','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik posiada regenerację żywotności +2. Kiedy Czujny Duch przestanie działać, osoba, na którą działał otrzyma 30...180 pkt. żywotności.','Regeneracja żywotności +2. Efekt końcowy: dodaje 30...180 pkt. żywotności.'],
256=>['Błogosławiona Aura','Podczas gdy utrzymujesz to zaklęcie, zaklęcia mnicha, które rzucasz trwają o 10...35% dłużej.','Zaklęcia mnicha jakie rzucasz trwają o 10...35% dłużej.'],
257=>['Egida','Przez 6...15 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie ataków.','Nakłada zaklęcie na wszystkich członków drużyny w zasięgu słuchu (6...15 sek.). 50% szans na blokowanie.'],
258=>['Strażnik','Przez 2...7 sek., wybrany sojusznik ma 50% szans na blokowanie ataków.','(2...7 sek.) 50% szans na blokowanie.'],
259=>['Tarcza Odbicia','Przez 3...10 sek., wybrany sojusznik ma 75% szans na zablokowanie ataków i otrzymuje 15...30 pkt. pancerza.','(3...10 sek.) 75% szans na blokowanie. +15...30 pkt. pancerza.'],
260=>['Aura Wiary','Przez 3 sek. wybrany sojusznik otrzymuje podczas uzdrawiania o 50...100% więcej żywotności i otrzymuje o 5...50% mniej obrażeń.','(3 sek.) Wybrany sojusznik otrzymuje podczas uzdrawiania o 50...100% więcej żywotności i otrzymuje o 5...50% mniej obrażeń.'],
261=>['Tarcza Regeneracji','Przez 5...13 sek. wybrany sojusznik ma regenerację żywotności +3...10 i otrzymuje 20...45 pkt. pancerza.','(5...13 sek.). Regeneracja żywotności +3...10 i +20...45 pkt. pancerza.'],
262=>['Tarcza Osądu','Przez 8...20 sek., ktokolwiek zaatakuje wybranego sojusznika zostanie powalony i otrzyma 5...50 pkt. świętych obrażeń.','(8...20 sek.) Przeciwnikom atakującym wybranego sojusznika zadaje 5...50 pkt. świętych obrażeń. Powoduje powalenie.'],
263=>['Ochronne Więzy','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik na skutek pojedynczego ataku lub czaru nie może stracić więcej niż 5% pkt. żywotności. Za każdym razem, kiedy Ochronne Więzy uchronią przed obrażeniami, tracisz 6...3 pkt. energii lub czar przestaje działać.','Wybrany sojusznik nie może stracić więcej niż 5% maksymalnej żywotności na skutek pojedynczego ataku lub czaru. Za każdym razem, kiedy obrażenia są obniżane, tracisz 6...3 pkt. energii lub ten czar przestaje działać.'],
264=>['Pacyfizm','Przez 4...8 sek., wybrany przeciwnik nie może atakować. Działanie czaru skończy się, gdy cel otrzyma obrażenia.','(4...8 sek.) Wybrany przeciwnik nie może atakować. Przestanie działać, jeśli ten przeciwnik otrzyma obrażenia.'],
265=>['Zgoda','Przez 4...12 sek., przeciwnicy bezpośrednio przy tobie nie mogą atakować. Zgoda skończy się, gdy jeden z tych przeciwników otrzyma obrażenia.','(4...12 sek.) Przeciwnicy bezpośrednio przy tobie nie mogą atakować. Przestanie działać na danym przeciwniku, jeśli otrzyma on obrażenia.'],
266=>['Pokój i Harmonia','Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...9. Przez 1...3 sek. przypadłości i klątwy na tym sojuszniku trwają o 90% krócej. Wszystkie twoje umiejętności związane z Modlitwami Ofensywnymi zostają zablokowane na 20 sek.','Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...9. Przypadłości i klątwy na tym sojuszniku trwają o 90% krócej (1...3 sek.). Wyłącza twoje umiejętności Modlitw Ofensywnych (20 sek.).'],
267=>['Intuicja Sędziego','Przez 8...20 sek., ataki wybranego sojusznika zadają święte obrażenia i mają +20% przebicie pancerza.','(8...20 sek.) Powoduje, że ataki wybranego sojusznika zadają święte obrażenia i mają +20% przebicie pancerza.'],
268=>['Aura Nieustępliwości','Kiedy utrzymujesz to zaklęcie twoje czary mnicha uzdrawiając, dodają +15...60% dodatkowych pkt. żywotności. Kiedy to zaklęcie przestanie działać, jeden z martwych członków drużyny innych niż ty (losowo wybrany), zmartwychwstanie z pełną energią i zostanie przeniesiony do ciebie.','Twoje czary mnicha dodają +15...60% dodatkowych pkt. żywotności. Efekt końcowy: losowy sojusznik zostaje wskrzeszony z pełną energią i przeniesiony do ciebie.'],
269=>['Ochronny Symbol','Przez 10 sek., za każdym razem, kiedy wybrany sojusznik będzie miał otrzymać obrażenia, dostanie w zamian tyle samo pkt. żywotności, ale nie więcej niż 6...60. Wszystkie twoje Modlitwy Ochronne będą niedostępne przez 5 sek.','(10 sek.) Zamienia obrażenia (maksymalnie 6...60) w leczenie. Wszystkie twoje umiejętności Modlitw Ochronnych są wyłączone (5 sek.).'],
270=>['Bariera Życia','Podczas gdy utrzymujesz to zaklęcie, obrażenia zadawane wybranemu sojusznikowi innemu niż ty zmniejszane są o 20...50%. Jeśli w momencie, gdy ten sojusznik otrzyma obrażenia, twoja żywotność będzie poniżej 50%, to Bariera Życia przestanie działać.','Obniża obrażenia o 20...50%. Na cel nie można wybrać siebie. Jeśli w momencie, gdy cel otrzyma obrażenia, twoja żywotność będzie poniżej 50%, to Bariera Życia przestanie działać.'],
271=>['Ogień Fanatyka','Przez 60 sek., za każdym razem, kiedy użyjesz umiejętności, której celem będzie sojusznik, wszyscy przeciwnicy bezpośrednio przy tej osobie otrzymają 5...35 pkt. obrażeń od ognia, a ty stracisz 1 pkt. energii.','(60 sek.) Za każdym razem, kiedy na sojuszniku użyjesz umiejętności, wszyscy przeciwnicy bezpośrednio przy tej osobie otrzymają po 5...35 pkt. obrażeń od ognia. Koszt obrażeń: tracisz 1 pkt. energii.'],
272=>['Aura Baltazara','Przez 8 sek., przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują w każdej sekundzie 10...30 pkt. świętych obrażeń.','(8 sek.) Przeciwnikom bezpośrednio przy wybranym sojuszniku w każdej sekundzie zadaje po 10...30 pkt. świętych obrażeń.'],
273=>['Łamacz Czarów','Przez 5...17 sek., wybrany sojusznik nie może być celem zaklęć wrogich czarów.','(5...17 sek.) Wybrany sojusznik nie może być celem wrogich czarów.'],
274=>['Uzdrawiające Ziarno','Przez 10 sek., za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia, on i wszyscy sojusznicy w kontakcie z nim otrzymają 3...30 pkt. żywotności.','(10 sek.) Za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia, on i sojusznicy bezpośrednio przy nim otrzymują po 3...30 pkt. żywotności. Na cel nie można wybrać siebie.'],
275=>['Usunięcie Przypadłości','Usuwa z wybranego sojusznika jedną przypadłość (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję lub głęboką ranę). Jeżeli przypadłość zostanie usunięta, sprzymierzeniec zostaje uzdrowiony za 5...70 żywotności.','Usuwa przypadłość. Efekt usunięcia: dodaje 5...70 pkt. żywotności. Na cel nie można wybrać siebie.'],
276=>['Przywrócenie Stanu','Usuwasz z wybranego sojusznika innego niż ty wszystkie przypadłości (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję i głęboką ranę). Za każdą usuniętą przypadłość, sojusznik ten otrzyma 10...70 pkt. żywotności.','Usuwa wszystkie przypadłości. Efekt usunięcia: za każdą usuniętą przypadłość dodaje 10...70 pkt. żywotności. Na cel nie można wybrać siebie.'],
277=>['Usunięcie Przypadłości','Z wybranego sojusznika usuwasz jedną przypadłość (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję lub głęboką ranę). Za każdą pozostałą przypadłość, osoba ta otrzyma 5...70 pkt. żywotności.','Usuwa przypadłość. Efekt usunięcia: za każdą pozostałą przypadłość dodaje 5...70 pkt. żywotności.'],
278=>['Oczyszczenie z Przypadłości','Usuwa z wybranego sojusznika wszystkie przypadłości (zatrucie, chorobę, oślepienie, oszołomienie, krwawienie, okulawienie, płonięcie, osłabienie, pękniętą zbroję i głęboką ranę).','Usuwa wszystkie przypadłości.'],
279=>['Boskie Uzdrowienie','Uzdrawiasz siebie i członków drużyny w zasięgu słuchu dodając każdemu 15...60 pkt. żywotności.','Tobie i członkom drużyny w zasięgu słuchu dodaje po 15...60 pkt. żywotności.'],
280=>['Uzdrowienie Obszarowe','Uzdrawiasz siebie i wszystkie stworzenia bezpośrednio przy tobie dodając każdemu 30...180 pkt. żywotności.','Tobie oraz sojusznikom i przeciwnikom bezpośrednio obok ciebie dodaje po 30...180 pkt. żywotności.'],
281=>['Uzdrawiająca Modlitwa','Uzdrawiasz wybranego sojusznika dodając mu 30...80 pkt. żywotności.','Dodaje 30...80 pkt. żywotności.'],
282=>['Słowo Uzdrowienia','Uzdrawiasz wybranego sojusznika dodając mu 5...100 pkt. żywotności. Jeśli jego żywotność znajduje się poniżej 50%, to uzdrawiasz go o dodatkowe 30...115 punktów.','Dodaje 5...100 pkt. żywotności. Dodatkowo dodaje 30...115 pkt. żywotności, jeśli żywotność wybranego sojusznika jest poniżej 50%.'],
283=>['Pocałunek Dwayny','Wybranemu sojusznikowi innemu niż ty dodajesz 20...65 pkt. żywotności i dodatkowe 15...40 pkt. żywotności za każde zaklęcie lub klątwę na nim.','Dodaje 20...65 pkt. żywotności. Dodaje 15...40 pkt. dodatkowej żywotności za każdą klątwę lub zaklęcie na wybranym sojuszniku. Na cel nie można wybrać siebie.'],
284=>['Boski Dar','Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy rzucisz czar z grupy Modlitw Ochronnych lub Łaski Bogów, którego celem jest sojusznik, osoba ta otrzymuje 15...60 pkt. żywotności, a ty tracisz 1 punkty energii.','Dodaje wybranemu sojusznikowi 15...60 pkt. żywotności, za każdym razem, kiedy rzucisz na niego czar z grupy Modlitw Ochronnych lub Łaski Bogów. Koszt uzdrowienia: tracisz 1 pkt. energii.'],
285=>['Uzdrawiające Dłonie','Przez 10 sek., za każdym razem, kiedy wybrany sojusznik otrzyma obrażenia, zostanie uzdrowiony otrzymując 5...35 pkt. żywotności.','(10 sek.) Dodaje 5...35 pkt. żywotności, za każdym razem, kiedy cel otrzymuje obrażenia.'],
286=>['Uzdrowienie Innej Osoby','Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 35...180 pkt. żywotności.','Dodaje 35...180 pkt. żywotności. Na cel nie można wybrać siebie.'],
287=>['Uzdrowienie Drużyny','Uzdrawiasz każdego członka drużyny o 30...75 pkt. żywotności.','Każdemu członkowi drużyny dodaje 30...75 pkt. żywotności.'],
288=>['Bryza Uzdrowienia','Przez 15 sek., wybrany sojusznik posiada regenerację żywotności +4...9.','(15 sek.) Regeneracja żywotności +4...9.'],
289=>['Życiodajne Błogosławieństwo','Podczas gdy utrzymujesz to zaklęcie, maksymalna żywotność wybranego sojusznika będzie większa o +40...200 pkt.','+40...200 pkt. do maksymalnej żywotności.'],
290=>['Odnowienie','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik posiada regenerację żywotności +1...4.','Regeneracja żywotności +1...4.'],
291=>['Zastępcze Życie','Podczas gdy utrzymujesz to zaklęcie, za każdym razem, kiedy wybrany sojusznik trafia przeciwnika, otrzymuje 2...17 pkt. żywotności.','Otrzymujesz 2...17 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik trafi przeciwnika.'],
292=>['Podarowanie Żywotności','Tracisz połowę aktualnej liczby pkt. żywotności. Wybrany sojusznik inny niż ty otrzymuje 100...136% pkt., które ty straciłeś.','Dodaje 100...136% połowy twojej aktualnej żywotności. Tracisz połowę aktualnej żywotności. Na cel nie można wybrać siebie.'],
293=>['Sygnet Oddania','Uzdrawiasz wybranego sojusznika dodając mu 20...120 pkt. żywotności.','Dodaje 20...120 pkt. żywotności.'],
294=>['Sygnet Osądu','Cel zostaje powalony. Wybrany przeciwnik i wszyscy przeciwnicy przy nim otrzymują 15...75 pkt. świętych obrażeń.','Powala cel. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 15...75 pkt. świętych obrażeń.'],
295=>['Sygnet Oczyszczenia','Z wybranego sojusznika usuwasz wszystkie klątwy i zaklęcia. Za każdą usuniętą klątwę i każde usunięte zaklęcie tracisz 10 pkt. energii.','Usuwa wszystkie klątwy i przypadłości. Koszt usunięcia: 10 pkt. energii za każdą.'],
296=>['Sygnet Zguby','Wybrany przeciwnik otrzymuje 30...60 pkt. świętych obrażeń. Jeśli wybrany przeciwnik atakował, zostaje powalony.','Zadaje 30...60 pkt. świętych obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik atakuje.'],
297=>['Błogosławiony Sygnet','Za każde zaklęcie, które utrzymujesz, otrzymujesz 3 pkt. energii. W ten sposób nie możesz otrzymać więcej niż 3...24 pkt. energii.','Za każde zaklęcie, które utrzymujesz, otrzymujesz 3 punkty Energii. W ten sposób nie możesz otrzymać więcej niż 3...24 pkt. energii.'],
298=>['Męczennik','Przenosisz na siebie wszystkie przypadłości (wraz z ich pozostałymi czasami działania), pod których działaniem są członkowie drużyny.','Przenosi wszystkie przypadłości z wszystkich sojuszników na ciebie.'],
299=>['Ochraniające Dłonie','Przez 8 sek., obrażenia oraz żywotność wykradana wybranemu sojusznikowi są zmniejszone o 3...18. Kiedy Ochraniające Dłonie przestają działać, sojusznik ten odzyskuje 5...50 żywotności.','(8 sek].) Zmniejsza obrażenia oraz kradzież żywotności o 3...18. Efekt końcowy: przywraca 5...50 pkt. żywotności.'],
300=>['Kontemplacja Czystości','Tracisz wszystkie zaklęcia. Za każde stracone otrzymujesz 0...80 pkt. żywotności, oczyszczasz się z jednej klątwy i jednej przypadłości (maksymalna liczba klątw i przypadłości, które zostaną zdjęte: 1...8).','Za każde zaklęcie, które masz na sobie otrzymujesz 0...80 pkt. żywotności i tracisz klątwę oraz przypadłość (maksymalna liczba dla klątw i przypadłości to 1...8). Tracisz wszystkie zaklęcia.'],
301=>['Usunięcie Klątwy','Z wybranego sojusznika usuwasz jedną klątwę.','Z wybranego sojusznika usuwa jedną klątwę.'],
302=>['Pogrom Klątwy','Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta, to każdy przeciwnik w okolicy otrzyma 10...85 pkt. świętych obrażeń.','Z wybranego sojusznika usuwa jedną klątwę. Efekt usunięcia: przeciwnikom w okolicy wybranego sojusznika zadaje 10...85 pkt. świętych obrażeń.'],
303=>['Przemiana Klątw','Z wybranego sojusznika innego niż ty usuwasz wszystkie klątwy. Ten sojusznik otrzymuje na 8...20 sek. +10 punktów pancerza na każdą klątwę nekromanty, która została z niego zdjęta.','Usuwa wszystkie klątwy; +10 pkt. pancerza za każdą usuniętą klątwę nekromanty (8...20 sek.). Na cel nie można wybrać siebie.'],
304=>['Światło Dwayny','Wskrzeszasz wszystkich członków drużyny w okolicy. Każdy z nich wraca do życia z 25% pkt. żywotności i bez energii.','Wskrzesza wszystkich martwych członków drużyny w okolicy (25% żywotności, 0 pkt. energii).'],
305=>['Wskrzeszenie','Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 25% pkt. żywotności i bez energii.','Wskrzesza wybranego członka drużyny (25% żywotności, 0 pkt. energii).'],
306=>['Odrodzenie','Wskrzeszasz wybranego członka drużyny. Wraca on do życia z 25% pkt. żywotności i bez energii, zostaje też przeniesiony do miejsca, w którym się aktualnie znajdujesz. Wszystkie umiejętności wskrzeszonego będą niedostępne przez 10...3 sek. Ten czar pochłania całą twoją pozostałą energię.','Wskrzesza wybranego członka drużyny (25% żywotności, 0 pkt. energii). Teleportuje cel do ciebie. Wyłącza umiejętności celu (10...3 sek.). Tracisz całą energię.'],
307=>['Odwrócenie Losu','Przez 8 sek., kiedy następnym razem wybrany sojusznik miałaby otrzymać obrażenia lub stracić żywotność na rzecz przeciwnika, dostanie w zamian tyle samo pkt. żywotności, ale nie więcej niż 15...80.','(8 sek.) Zamienia następne obrażenia lub wykradzioną żywotność (maksymalnie 15...80) w leczenie.'],
308=>['Wsparcie','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik inny niż ty posiada regenerację żywotności +1 i regenerację energii +1, ale ty tracisz 1 pkt. energii za każdym razem, gdy rzuci on czar.','Regeneracja żywotności +1 i regeneracja energii +1. Na cel nie można wybrać siebie. Tracisz 1 pkt. energii, za każdym razem, kiedy wybrany sojusznik rzuca czar.'],
309=>['Święty Całun','Podczas gdy utrzymujesz to zaklęcie, rzucanie klątw na wybranego sojusznika zabiera dwa razy więcej czasu. Kiedy Święty Całun przestanie działać, z wybranego sojusznika usuwana jest jedna klątwa.','Podwójny czas rzucania klątw przeciwko wybranemu sojusznikowi. Efekt końcowy: usuwa klątwę.'],
310=>['Boski Duch','Przez 1...14 sek. wszystkie czary mnicha, które rzucasz kosztują o 5 pkt. energii mniej. (Koszt minimalny: 1 pkt. energii.)','(1...14 sek.) Czary mnicha kosztują cię o 5 pkt. energii mniej. Minimalny koszt: 1 pkt. energii.'],
311=>['Przejęcie Przypadłości','Wszystkie przypadłości z wybranego sojusznika innego niż ty przenoszone są na ciebie. Za każdą przejętą w ten sposób przypadłość, otrzymujesz 6...26 pkt. żywotności.','Przenosi wszystkie przypadłości z wybranego sojusznika na ciebie. Efekt przeniesienia: za każdą przypadłość otrzymujesz 6...26 pkt. żywotności. Na cel nie można wybrać siebie.'],
312=>['Święte Uderzenie','Dotknięty przeciwnik otrzymuje 10...55 świętych obrażeń. Jeśli był powalony, otrzymuje dodatkowe 10...55 pkt. świętych obrażeń.','Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...55 pkt. dodatkowych świętych obrażeń, jeżeli cel jest powalony.'],
313=>['Uzdrawiający Dotyk','Dotkniętemu sojusznikowi dodajesz 20...80 pkt. żywotności. Punkty żywotności otrzymywane dzięki Łasce Bogów są w przypadku tego czaru podwajane.','Dodaje 20...80 pkt. żywotności. Punkty żywotności otrzymywane dzięki Łasce Bogów są w przypadku tego czaru podwajane.'],
314=>['Przywracanie Życia','Dotykasz ciała martwego członka drużyny. Wraca on do życia z 20...65% pkt. żywotności i 42...90% pkt. energii.','Wskrzesza wybranego członka drużyny (20...65% żywotności, 42...90% energii).'],
315=>['Zemsta','Przywraca do życia martwego członka drużyny z pełną żywotnością i energią. Po 30 sek. ten członek drużyny zadaje o 25% więcej obrażeń. Kiedy to zaklęcie przestanie działać, członek drużyny zginie. Śmierci poniesione podczas działania tego zaklęcia nie zwiększają kary za śmierć.','(30 sek.) Wskrzesza wybranego członka drużyny (pełna żywotności, pełna energia). Ten sojusznik zadaje o 25% więcej obrażeń i nie otrzymuje kary za śmierć. Efekt końcowy: ten sojusznik ginie.'],
316=>['Do granic możliwości!','Za każdego wroga w zasięgu słuchu (maksymalnie 1...6) otrzymujesz jedną dawkę adrenaliny. Przez 10...20 sek., twoja maksymalna żywotność zostaje zwiększona o 10...60.','(10...20 sek.) Otrzymujesz +10...60 do maksymalnej żywotności. Efekt początkowy: otrzymujesz jedną dawkę adrenaliny za każdego wroga w zasięgu słuchu (maksymalnie 1...6).'],
317=>['Szał Bojowy','Przez 5...20 sek. poruszasz się o 33% szybciej i otrzymujesz z ataków podwójne dawki adrenaliny. Szał Bojowy przestanie działać, jeśli użyjesz umiejętności nie opartej na adrenalinie.','(5...20 sek.) Poruszasz się o 33% szybciej i za swoje ataki otrzymujesz podwójną adrenalinę. Koniec działania, jeśli użyjesz umiejętności nie opartej na adrenalinie.'],
318=>['Ignorowanie Bólu','Przez 20 sek. otrzymujesz dodatkowo 90...300 pkt. żywotności, 20 pkt. pancerza oraz -1...10 pkt. obrażeń mniej.','(12 sek.) Posiadasz dodatkowe 90...300 pkt. żywotności, dodatkowe 20 pkt. pancerza i otrzymujesz o 1...10 pkt. mniej obrażeń.'],
319=>['Pośpiech','Przez 8...20 sek., poruszasz się o 25% szybciej.','(8...20 sek.) Poruszasz się o 25% szybciej.'],
320=>['Podcięcie Ścięgien','Jeśli atak trafi, twój cel zostanie okulawiony na 3...15 sek., przez co spadnie jego szybkość ruchu.','Wywołuje przypadłość okulawienie (3...15 sek.).'],
321=>['Dziki Cios','Tracisz całą adrenalinę. Jeśli atak trafi, spowoduje trafienie krytyczne i przerwanie wszystkich postaw, pod których działaniem był twój cel. Tego ataku nie można zablokować.','Zawsze trafienie krytyczne. Przerywa postawę. Nie do zablokowania. Pochłania całą adrenalinę.'],
322=>['Potężny Atak','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń.'],
323=>['Desperacki Cios','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń, a twój cel otrzyma jedną z następujących przypadłości: głęboka rana (na 20 sek.), osłabienie (na 20 sek.), krwawienie (na 25 sek.) lub okulawienie (na 15 sek.). Po wykonaniu Desperackiego Ciosu, zostajesz powalony.','Zadaje +10...40 pkt. obrażeń. Wywołuje jedną losową przypadłość spośród następujących: głęboka rana (20 sek.), osłabienie (20 sek.), krwawienie (25 sek.) lub okulawienie (15 sek.). Zostajesz powalony.'],
324=>['Dreszcz Zwycięstwa','Jeśli ten cios trafi, otrzymujesz +20...40 pkt. obrażeń. Jeśli posiadasz więcej żywotności niż wybrany przeciwnik, otrzymujesz dawki adrenaliny w liczbie 1...2.','Zadaje +20...40 pkt. obrażeń. Jeśli masz większą żywotność od przeciwnika, otrzymujesz dawki adrenaliny w liczbie 1...2.'],
325=>['Rozpraszający Cios','Wyprowadź cios, który nie zadaje obrażeń, ale przerywa aktualną czynność celu (i czynności przeciwników w kontakcie z celem).','Trafia także przeciwników bezpośrednio przy twoim celu. Przerywa czynność. Trafia nie zadając obrażeń.'],
326=>['Uderzenie Obrońcy','Jeśli atak trafi przeciwnika w ruchu, zadajesz 10...40 pkt. dodatkowych obrażeń.','Zadaje +10...40 pkt. obrażeń, jeżeli cel się porusza.'],
327=>['Zamach Gryfa','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli atak jest zablokowany, cel zostaje powalony i otrzymuje 10...34 pkt. obrażeń.','Zadaje +5...20 pkt. obrażeń. Powala i zadaje 10...34 pkt. obrażeń, jeżeli nastąpiło blokowanie.'],
328=>['Czyste Uderzenie','Jeśli Czyste Uderzenie trafi, zadajesz +1...30 pkt. obrażeń. Jeśli nie przyjąłeś żadnej postawy, to Czyste Uderzenie nie może zostać zablokowane.','Zadaje +1...30 pkt. obrażeń. Nie do zablokowania, chyba że przyjąłeś postawę.'],
329=>['Rozłupanie Czaszki','Jeżeli atak trafi, przerywasz aktualną czynność wybranego przeciwnika. Jeśli przeciwnik rzucał czar, to na 15 sek. zostaje oszołomiony.','Przerywa czynność. Wywołuje przypadłość oszołomienie (15 sek.), jeżeli cel rzuca czar.'],
330=>['Młyniec','Kolisty zamach toporem zadający wszystkim przeciwnikom bezpośrednio przy tobie +4...12 pkt. obrażeń.','Przeciwnikom bezpośrednio przy tobie zadaje po +4...12 pkt. obrażeń.'],
331=>['Miażdżący Młot','Tracisz całą adrenalinę. Jeśli Miażdżący Młot trafi, twój cel zostaje powalony.','Powoduje powalenie. Pochłania całą adrenalinę.'],
332=>['Uderzenie Byka','Jeśli atak trafi przeciwnika będącego w ruchu, zadajesz +5...30 pkt. obrażeń, a twój cel zostaje powalony.','Zadaje +5...30 pkt. obrażeń i powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
333=>['Pomszczę Cię!','Za każdego martwego sojusznika, otrzymujesz 10 sek. regeneracji żywotności +3...7 i szybkość twoich ataków zwiększa się o 25%.','Posiadasz regenerację żywotności +3...7 i atakujesz o 25% szybciej (10 sek. za każdego martwego sojusznika).'],
334=>['Podcięcie Toporem','Jeśli atak trafi przeciwnika z głęboką raną, zadajesz +4...16 pkt. obrażeń, a ten przeciwnik na 15 sek. zostaje okulawiony.','Zadaje +4...16 pkt. obrażeń i wywołuje przypadłość okulawienie (15 sek.), jeżeli wybrany przeciwnik ma głęboką ranę.'],
335=>['Rozłupanie','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń oraz zadajesz 1...2 wrogom 10...40 pkt. obrażeń ciętych.','Zadaje +10...40 pkt. obrażeń oraz zadaje 1...2 wrogom w bezpośrednim sąsiedztwie 10...40 pkt. obrażeń ciętych.'],
336=>['Uderzenie Kata','Jeśli atak trafi, zadajesz +15...45 pkt. obrażeń.','Zadaje +15...45 pkt. obrażeń.'],
337=>['Rozczłonkowanie','Jeśli ten cios toporem trafi, zadaje głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Wywołuje przypadłość głęboka rana (5...20 sek.).'],
338=>['Patroszenie','Jeśli Patroszenie trafi, zadajesz +10...45 pkt. obrażeń i głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Zadaje +10...45 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.).'],
339=>['Przeszywające Uderzenie','Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Ten atak toporem posiada 20% przebicia pancerza.','Zadaje +10...25 pkt. obrażeń. 20% przebicie pancerza.'],
340=>['Przerywające Cięcie','Jeżeli atak trafi, przerywasz aktualną czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, to czar ten zostaje wyłączony na 20 sek.','Przerywa czynność. Efekt przerwania: przerwana umiejętność jest niedostępna przez +20 sek.'],
341=>['Szybkie Cięcie','Jeśli ten atak trafi swój cel, zadajesz +1...20 obrażeń. Jeśli Szybkie Cięcie zostanie zablokowane, cel otrzymuje 1...20 pkt. obrażeń i głęboką ranę przez 20 sek.','Zadaje +1...20 pkt. obrażeń. Zadaje 1...20 pkt. obrażeń i wywołuje przypadłość głęboka rana (20 sek.), jeżeli nastąpiło blokowanie.'],
342=>['Osłabiający Topór','Jeśli atak trafi przeciwnika z głęboką raną, zadajesz 5...25 pkt. dodatkowych obrażeń i ten przeciwnik przez 20 sek. będzie cierpiał na osłabienie.','Zadaje +5...25 pkt. obrażeń i wywołuje przypadłość osłabienie (20 sek.), jeżeli wybrany przeciwnik ma głęboką ranę.'],
343=>['Za Większą Sprawiedliwość!','Przez 20 sek., za każdym razem, kiedy otrzymujesz adrenalinę, otrzymujesz jej o 100% więcej.','(20 sek.) Otrzymujesz o 100% więcej adrenaliny.'],
344=>['Nawałnica Ciosów','Przez 5 sek., twoja szybkość wyprowadzania ataków zwiększa się o 33%, ale zadajesz o 25% mniej obrażeń.','(5 sek.) Atakujesz o 33% szybciej. Zadajesz o 25% mniej obrażeń.'],
345=>['Postawa Obronna','Przez 1...5 sek., masz 75% szans na zablokowanie ataków wręcz i pocisków. Kiedy Postawa Obronna przestaje działać, otrzymujesz jedną dawkę adrenaliny za każdą posiadaną umiejętność walki wręcz (maksymalnie 0...4).','(1...5 sek.) Masz 75% szans na zablokowanie ataków. Efekt końcowy: otrzymujesz jedną dawkę adrenaliny za każdą posiadaną umiejętność walki wręcz (maksymalnie 0...4).'],
346=>['Furia','Przez 8 sek. atakujesz o 33% szybciej, ale odnosisz 175...125% obrażeń.','(8 sek.) Atakujesz o 33% szybciej. Odnosisz 175...125% obrażeń.'],
347=>['Odporność na Ból','Przez 7...18 sek., otrzymujesz dodatkowe 90...300 pkt. żywotności.','(7...18 sek.) Twoja maksymalna żywotność zwiększa się o +90...300 pkt.'],
348=>['Pilnujcie się!','Członkowie drużyny w zasięgu słuchu na 10 sek. otrzymują +5...25 pkt. pancerza. Ten zaśpiew przestanie działać po otrzymaniu 10 ataków.','(10 sek.) Członkowie drużyny w zasięgu słuchu posiadają +5...25 pkt. pancerza. Przestanie działać po otrzymaniu 10 ataków.'],
349=>['Sprint','Przez 8...14 sek., poruszasz się o 25% szybciej.','(8...14 sek.) Poruszasz się o 25% szybciej.'],
350=>['Uderzenie w Brzuch','Jeśli ten atak trafi powalnego przeciwnika, to wzbije się chmura pyłu, która na 3...7 sek. oślepi sąsiadujących przeciwników.','Wywołuje przypadłość oślepienie u sąsiadujących przeciwników (3...7 sek.), jeżeli wybrany przeciwnik zostanie powalony.'],
351=>['Potężny Cios','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń.'],
352=>['Miażdżące Uderzenie','Jeśli atak trafi, zadajesz +1...20 pkt. obrażeń. Jeśli trafisz powalonego przeciwnika zadajesz głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Zadaje +1...20 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
353=>['Niedbały Zamach','Atakujesz wszystkich sąsiadujących przeciwników. Każdy trafiony otrzymuje +1...20 pkt. obrażeń.','Atakuje wszystkich sąsiadujących przeciwników zadając im +1...20 pkt. obrażeń.'],
354=>['Wstrząsotwórca','Wszyscy przeciwnicy bezpośrednio przy tobie zostają powaleni. (50% szans na niepowodzenie, jeśli Biegłość w Młotach wynosi 4 lub mniej.)','Powalasz wybranego przeciwnika i przeciwników bezpośrednio przy nim. 50% szans na niepowodzenie, chyba że wartość Biegłości w Młotach wynosi 5 lub więcej.'],
355=>['Druzgoczący Młot','Jeśli Druzgoczący Młot trafi, twój cel zostaje powalony i przez 5...20 sek. cierpi na osłabienie.','Powoduje powalenie. Wywołuje przypadłość osłabienie (5...20 sek.).'],
356=>['Nieblokowalne Uderzenie','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli Nieblokowalne Uderzenie zostanie zablokowane, twój cel zostanie powalony i otrzyma 5...20 pkt. obrażeń.','Zadaje +5...20 pkt. obrażeń. Zadaje 5...20 pkt. obrażeń i powala, jeżeli nastąpiło blokowanie.'],
357=>['Kontruderzenie','Jeśli atak trafi atakującego przeciwnika, ten przeciwnik zostaje powalony.','Powoduje powalenie, jeżeli wybrany przeciwnik atakuje.'],
358=>['Łamacz Kręgosłupa','Jeśli Łamacz Kręgosłupa trafi, zadajesz +1...20 pkt. obrażeń, a twój cel zostaje powalony. Jeśli masz siłę 8 lub większą, powalenie trwa 4 sekundy.','Zadaje +1...20 pkt. obrażeń. Powoduje powalenie. Powalenie trwa 4 sek. w przypadku siły na poziomie 8 lub wyższym.'],
359=>['Ciężki Cios','Tracisz całą adrenalinę. Jeśli atak trafi osłabionego przeciwnika, to zostaje on powalony i otrzymuje +1...30 pkt. obrażeń.','Zadaje +1...30 pkt. obrażeń i powala, jeżeli wybrany przeciwnik jest osłabiony. Pochłania całą adrenalinę.'],
360=>['Osłabiający Cios','Jeśli cios trafi, twój cel na 5...20 sek. zostanie osłabiony.','Wywołuje przypadłość osłabienie (5...20 sek.).'],
361=>['Sygnet Doljaka','Przez 8...20 sek. posiadasz +10...40 pkt. pancerza i nie możesz zostać powalony, ale twoja prędkość ruchu jest zmniejszona o 75%.','(8...20 sek.) Posiadasz +10...40 pkt. pancerza i nie możesz zostać powalony. Poruszasz się o 75% wolniej.'],
362=>['Spryt Wojownika','Przez 5...11 sek., twoich ataków wręcz nie można zablokować.','(5...11 sek.) Twoich ataków wręcz nie można blokować.'],
363=>['Uderzenie Tarczą','Przez 5...11 sek. kiedy trzymasz tarczę, następna umiejętność walki wręcz użyta przeciwko tobie zostanie zablokowana, napastnik zostaje powalony, zaś sama umiejętność staje się niedostępna przez dodatkowe 15 sek.','(5...11 sek.) Blokujesz następną umiejętność walki wręcz. Powoduje powalenie i zwiększa odnowienie tej umiejętności o +15 sek. Bez efektu, jeśli nie dzierżysz tarczy.'],
364=>['Szarża!','Wszyscy sojusznicy w zasięgu przestają być okulawieni. Oprócz tego, przez 5...13 sek., sojusznicy ci poruszają się o 33% szybciej.','(5...13 sek.) Sojusznicy w zasięgu słuchu poruszają się o 33% szybciej. Efekt początkowy: sojusznicy przestają być okulawieni.'],
365=>['Zwycięstwo Jest Moje!','Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...68 pkt. żywotności i 3...7 pkt. energii.','Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...68 pkt. żywotności i 3...7 pkt. energii.'],
366=>['Poznajcie Co To Strach!','Wszyscy pobliscy przeciwnicy tracą 2...6 pkt. energii. Przez 1...15 sek., twoje ataki wręcz mają +5...30% szansy na zadanie trafienia krytycznego nieruchomym wrogom.','(1...15 sek.) Masz o +5...30% większą szansę na trafienie krytyczne w nieruchomych wrogów. Efekt początkowy: pobliscy wrogowie tracą 2...6 pkt. energii.'],
367=>['Tarcze w Górę!','Przez 5...11 sek. ty i wszyscy członkowie drużyny w zasięgu słuchu posiadacie +60 pkt. pancerza przeciwko atakom dystansowym.','(5...11 sek.) Członkowie drużyny w zasięgu słuchu otrzymują po +60 pkt. pancerza przeciwko atakom zasięgowym.'],
368=>['Przetrwam!','Za każdą przypadłość, pod której działaniem jesteś, otrzymujesz regenerację punkty żywotności +3. Ta regeneracja kończy się po 5...11 sek.','(5...11 sek.) Za każdą przypadłość, pod której działaniem jesteś, otrzymujesz regenerację żywotności +3.'],
370=>['Postawa Berserkera','Przez 8...14 sek., atakujesz o 33% szybciej i otrzymujesz o 100% adrenaliny więcej. Postawa Berserkera przestanie działać, kiedy użyjesz umiejętności.','(8...14 sek.) Atakujesz o 33% szybciej i otrzymujesz o 100% więcej adrenaliny. Przestanie działać, jeśli użyjesz umiejętności.'],
371=>['Postawa Zrównoważona','Przez 8...20 sek., nie możesz zostać powalony i nie otrzymujesz dodatkowych obrażeń od trafień krytycznych.','(8...20 sek.) Nie możesz zostać powalony i nie otrzymujesz dodatkowych obrażeń z trafień krytycznych.'],
372=>['Obrona Gladiatora','Przez 5...11 sek., masz 75% szans na blokowanie skierowanych przeciwko tobie ataków. Jeśli zablokujesz w ten sposób atak w walce wręcz, atakujący otrzymuje 5...35 pkt. obrażeń.','(5...11 sek.) Masz 75% szans na blokowanie. Atakujący otrzymuje 5...35 pkt. obrażeń, za każdym razem, kiedy zablokujesz w ten sposób atak wręcz.'],
373=>['Odbijanie Strzał','Przez 1...6 sek., masz 75% szans na zablokowanie ataków. Jeśli zablokujesz pocisk, pobliscy wrogowie zaczyną krwawić przez 5...15 sek.','(1...6 sek) Masz 75% szans na zablokowanie ataków. Pobliscy wrogowie zaczyną krwawić przez (5...15 sek.), jeśli uda ci się zablokować pocisk.'],
374=>['Wytrzymałość Wojownika','Przez 5...35 sek., za każdym razem kiedy trafisz w walce wręcz, otrzymujesz 3 punkty Energii. Wytrzymałość Wojownika nie może zwiększyć twojej energii powyżej 10...25 pkt.','(5...35 sek.) Otrzymujesz 3 punkty Energii, za każdym razem, kiedy twój atak wręcz trafi. Nie otrzymujesz energii, jeżeli masz więcej niż 10...25 pkt. energii.'],
375=>['Krasnoludzka Postawa Bojowa','Przez 5...11 sek., jeśli walczysz młotem, atakujesz 33% szybciej, otrzymujesz +40 do pancerza, a twoja umiejętność przerywa akcję przeciwnika po trafieniu.','(5...11 sek.) Atakujesz 33% szybciej, otrzymujesz +40 do pancerza, a twoje umiejętności ataku przerywają akcje przeciwnika. Bez efektu, jeśli nie korzystasz z młota.'],
376=>['Postawa Zdyscyplinowana','Przez 1...4 sek. posiadasz +10 punktów pancerza i masz 75% szans na blokowanie ataków. Postawa Zdyscyplinowana przestaje działać, jeśli użyjesz umiejętności opartej na adrenalinie.','(1...4 sek.) Posiadasz 75% szans na blokowanie i +10 pkt. pancerza. Kończy się, jeśli użyjesz umiejętności opartej na adrenalinie.'],
377=>['Czujna Postawa','Przez 1...6 sek., blokujesz wszystkie umiejętności związane z atakiem, których jesteś celem. Za każdy udany blok otrzymujesz adrenalinę i 5 pkt. energii. Czujna Postawa przestaje działać, jeśli użyjesz umiejętności.','(1...6 sek.) Blokujesz umiejętności związane z atakowaniem. Za każdy blok otrzymujesz adrenalinę i 5 pkt. energii. Przestanie działać, jeśli użyjesz umiejętności.'],
378=>['Postawa Tarczownika','Przez 1...6 sek, jeśli używasz tarczy, masz 75% szans na zablokowanie ataków, a otrzymywane obrażenia są zmniejszone o 2 za każdy poziom siły (maksymalna redukcja obrażeń to 15 pkt.).','(1...6 sek.) Masz 75% szans na zablokowanie ataków. Otrzymywane obrażenia zostają zmniejszone o 2 za każdy poziom siły (maksymalna redukcja obrażeń to 15 pkt/). Bez efektu, jeśli nie używasz tarczy.'],
379=>['Szarża Byka','Przez 1...7 sek. poruszasz się o 50% szybciej i jeśli trafisz w walce wręcz poruszającego się przeciwnika, ten przeciwnik zostanie powalony. Szarża Byka przestaje działać, gdy użyjesz umiejętności.','(1...7 sek.). Poruszasz się o 50% szybciej. Powala, jeśli atakiem wręcz trafisz poruszającego się przeciwnika. Przestanie działać, jeśli użyjesz umiejętności.'],
380=>['Obrona Bonetti\'ego','Przez 5...11 sek. masz 75% szans na blokowanie ataków wręcz i ataków zasięgowych. Za każdy zablokowany atak wręcz otrzymujesz 5 pkt. energii. Obrona Bonetti\'ego przestanie działać, kiedy użyjesz umiejętności.','(5...11 sek.) Masz 75% szans na blokowanie. Za każdy zablokowany atak wręcz otrzymujesz 5 pkt. energii. Przestanie działać, jeśli użyjesz umiejętności.'],
381=>['Sto Ostrzy','Przez 15 sek., za każdym razem, kiedy zaatakujesz mieczem, wszyscy przeciwnicy bezpośrednio przy tobie otrzymają po 10...35 pkt. obrażeń ciętych.','(15 sek.) Przeciwnikom bezpośrednio przy tobie zadaje po 10...35 pkt. obrażeń ciętych, jeśli atakujesz mieczem.'],
382=>['Przecięcie Tętnicy','Jeśli atak trafi, twój cel na 5...25 sek. zaczyna krwawić, tracąc wtedy żywotność.','Wywołuje przypadłość krwawienie (5...25 sek.).'],
383=>['Cięcie Galratha','Jeśli atak trafi, zadajesz +1...40 pkt. obrażeń.','Zadaje +1...40 pkt. obrażeń.'],
384=>['Głębokie Cięcie','Jeśli atak trafi krwawiącego przeciwnika, zadajesz 5...20 pkt. dodatkowych obrażeń i głęboką ranę, obniżając na 5...20 sek. maksymalną żywotność celu o 20%.','Zadaje +5...20 pkt. obrażeń i wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli twój cel krwawi.'],
385=>['Kończące Pchnięcie','Tracisz całą adrenalinę. Jeśli Kończące Pchnięcie trafi, zadajesz 5...40 pkt. dodatkowych obrażeń. Te obrażenia zostają podwojone, jeśli żywotność twojego celu była poniżej 50%.','Zadaje +5...40 pkt. obrażeń. Zadaje +5...40 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma poniżej 50% żywotności. Pochłania całą adrenalinę.'],
386=>['Przeszywające Ostrze','Jeśli atak trafi, zadajesz +1...20 pkt. obrażeń. Jeśli Przeszywające Ostrze zostanie zablokowane, twój cel zaczyna krwawić na 25 sek. i otrzymuje 1...20 pkt. obrażeń.','Zadaje +1...20 pkt. obrażeń. Zadaje 1...20 pkt. obrażeń i wywołuje przypadłość krwawienie (25 sek.), jeżeli nastąpiło blokowanie.'],
387=>['Riposta','Przez 8 sek., kiedy trzymasz miecz, blokujesz następny atak w walce wręcz skierowany w ciebie, a napastnik otrzymuje 20...80 pkt. obrażeń.','(8 sek.) Blokujesz następny atak wręcz, a atakujący otrzymuje 20...80 pkt. obrażeń. Bez efektu, jeśli nie dzierżysz miecza.'],
388=>['Zabójcza Riposta','Przez 8 sek., kiedy trzymasz miecz, blokujesz następny atak w walce wręcz skierowany w ciebie, a napastnik otrzymuje 15...90 pkt. obrażeń i zaczyna krwawić przez 3...25 sek.','(8 sek.) Blokujesz następny atak wręcz, a atakujący otrzymuje 15...90 pkt. obrażeń. Wywołuje przypadłość krwawienie (3...25 sek.). Bez efektu, jeśli nie dzierżysz miecza.'],
389=>['Popis bronią','Wszystkie twoje umiejętności związane z atakiem się odnawiają. Za każdą umiejętność odnowioną w ten sposób otrzymujesz 2...7 pkt. energii.','Odnawia twoje umiejętności związane z atakowaniem. Za każdą odnowioną umiejętność otrzymujesz 2...7 pkt. energii.'],
390=>['Brutalne Cięcie','Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeśli tą czynnością było użycie czaru, to zadajesz 1...40 pkt. dodatkowych obrażeń.','Przerywa czynność. Efekt przerwania: zadaje +1...40 pkt. obrażeń, jeżeli czynnością było rzucanie czaru.'],
391=>['Strzał Myśliwego','Jeśli Strzał Myśliwego trafi, twój cel zaczyna krwawić na 3...25 sek.','Wywołuje przypadłość krwawienie (3...25 sek.).'],
392=>['Przygwożdżenie','Jeśli Przygwożdżenie trafi, twój cel zostanie okulawiony na 3...15 sek.','Wywołuje przypadłość okulawienie (3...15 sek.).'],
393=>['Okulawiający Strzał','Jeśli Okulawiający Strzał trafi, twój cel zostanie okulawiony na 4...14 sek. Tego ataku nie można zablokować.','Nie do zablokowania. Powoduje okulawienie (4...14 sek.).'],
394=>['Potężny Strzał','Jeśli Potężny Strzał trafi, wybrany przeciwnik otrzymuje +25...50 pkt. obrażeń.','Wybrany przeciwnik otrzymuje 25...50 pkt. obrażeń.'],
395=>['Grad Strzał','Wszystkie przygotowania zostają usunięte. Wystrzeliwuje strzały w wybranego wroga i maksymalnie 5 stojących obok celów. Każda z tych strzał zadaje +5...20 pkt. obrażeń, jeśli trafi.','Zadaje 5...20 pkt. obrażeń. Trafia 5 wrogów stojących obok celu. Wszystkie przygotowania zostają usunięte.'],
396=>['Podwójny Strzał','Wystrzeliwujesz w wybranego przeciwnika na raz dwie strzały. Strzały zadają o 25% mniej obrażeń.','W wybranego przeciwnika wystrzeliwujesz jednocześnie dwie strzały. Te strzały zadają o 25% mniej obrażeń.'],
397=>['Szybki Strzał','Wystrzeliwujesz strzałę, która leci dwa razy szybciej.','Wystrzeliwujesz strzałę, która leci dwa razy szybciej.'],
398=>['Przeszywający Atak','Jeśli Przeszywający Atak trafi, zadajesz +5...25 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Zadaje +5...25 pkt. obrażeń. 10% przebicie pancerza.'],
399=>['Przerywający Strzał','Jeśli Przerywający Strzał trafi, przerywa bieżącą czynność celu, ale zadaje jedynie 1...16 pkt. obrażeń. Jeśli tą czynnością było użycie umiejętności, to ta umiejętność będzie niedostępna przez dodatkowe 20 sek.','Przerywa czynność. Efekt przerwania: przerwana umiejętność jest niedostępna przez +20 sek. Zadaje jedynie 1...16 pkt. obrażeń.'],
400=>['Precyzyjny Strzał','Jeśli Precyzyjny Strzał trafi, zadajesz +3...10 pkt. obrażeń. Precyzyjnego Strzału nie można zablokować. Atak ten łatwo przerwać.','Zadaje +3...10 pkt. obrażeń. Nie do zablokowania. Łatwo przerwać.'],
402=>['Zdecydowany Strzał','Jeśli Zdecydowany Strzał trafi, zadajesz +5...20 pkt. obrażeń. Jeśli natomiast chybi, wszystkie twoje umiejętności związane z atakiem odnowią się.','Zadaje +5...20 pkt. obrażeń. Odnawia twoje umiejętności związane z atakowaniem, jeżeli nie trafi.'],
403=>['Pewny Strzał','Wystrzeliwujesz strzałę, która leci trzy razy szybciej i nie można jej zablokować.','Wystrzeliwujesz strzałę, która leci trzy razy szybciej. Nie do zablokowania.'],
404=>['Zatruta Strzała','Jeśli Zatruta Strzała trafi, twój cel przez 5...20 sek. będzie zatruty.','Wywołuje przypadłość zatrucie (5...20 sek.).'],
405=>['Obiecany Strzał','Jeśli Strzał Przysięgi trafi w cel, wszystkie pozostałe umiejętności zostaną odnowione. Jeśli nie trafi, wszystkie twoje umiejętności zostaną zablokowane na 10...4 sek. (50% szansy na spudłowanie przy Biegłości 7 lub mniej.)','Jeśli trafi, odnawia wszystkie pozostałe umiejętności. Jeśli spudłuje, blokuje wszystkie umiejętności (10...4 sek.) 50% szansy na spudłowanie, o ile nie masz Biegłości 8 lub wyżej.'],
406=>['Wyniszczający Strzał','Jeśli Wyniszczający Strzał trafi, twój cel traci 1...10 pkt. energii.','Powoduje utratę 1...10 pkt. energii.'],
407=>['Strzał z Bliska','Wystrzeliwujesz strzałę, która ma połowę normalnego zasięgu, ale zadaje +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń.'],
408=>['Oszałamiający Strzał','Jeśli Oszałamiający Strzał trafi przeciwnika rzucającego czar, rzucanie czaru zostanie przerwane, a cel będzie oszołomiony przez 5...20 sek. Ten strzał zadaje jedynie 1...16 pkt. obrażeń.','Przerywa czar. Efekt przerwania: wywołuje przypadłość oszołomienie (5...20 sek.). Zadaje jedynie 1...16 pkt. obrażeń.'],
409=>['Karzący Strzał','Jeśli Karzący Strzał trafi, zadajesz +10...20 pkt. obrażeń, a czynność celu zostaje przerwana.','Zadaje +10...20 pkt. obrażeń. Przerywa czynność.'],
411=>['Oswojenie Zwierzęcia','Oswajasz wskazane zwierzę. Po oswojeniu, twój zwierzęcy towarzysz będzie z tobą podróżował, jeśli tylko na pasku umiejętności będziesz miał Oswojenie Zwierzęcia. Nie możesz oswoić zwierzęcia, które przewyższa cię więcej niż o 4 poziomy.','Oswajasz wskazane zwierzę. Po oswojeniu, twój zwierzęcy towarzysz będzie z tobą podróżował, jeśli tylko na pasku umiejętności będziesz miał Oswojenie Zwierzęcia. Nie możesz oswoić zwierzęcia, które przewyższa cię więcej niż o 4 poziomy.'],
412=>['Zew Ochrony','Przez 120 sek. twój zwierzęcy towarzysz posiada 5...20 pkt. redukcję obrażeń.','(120 sek.) Twój zwierzęcy towarzysz posiada 5...20 pkt. redukcję obrażeń.'],
415=>['Zew Pośpiechu','Przez 30 s twój zwierzęcy towarzysz atakuje i porusza się o 33% szybciej.','(30 sekund) Twój zwierzak porusza się i atakuje o 33 % szybciej.'],
422=>['Ożywienie Zwierzęcia','Wskrzeszasz wszystkich zaprzyjaźnionych zwierzęcych towarzyszy w okolicy. Każdy z nich wraca do życia z 10...94% żywotności.','Wskrzeszasz wszystkie sojusznicze zwierzaki w okolicy (10...94% żywotności).'],
423=>['Symbiotyczne Więzy','Przez 120...300 sek., twój zwierzęcy towarzysz otrzymuje regenerację żywotności równą 1...3 i połowa fizycznych obrażeń zadawanych twojemu zwierzęcemu towarzysz jest przenoszona na ciebie.','(120...300 sek.) Twój zwierzęcy towarzysz posiadasz regenerację żywotności +1...3. Połowa obrażeń zadawanych twojemu zwierzęcemu towarzyszowi jest przekierowywana na ciebie.'],
424=>['Rzut Piachem','Dotknięty cel i przeciwnicy bezpośrednio przy nim zostają oślepieni na 3...15 sek.','Wywołuje przypadłość oślepienie (3...15 sek.). Działa także na przeciwników bezpośrednio przy wybranym przeciwniku.'],
425=>['Unik','Przez 5...11 sek., poruszasz się o 33% szybciej i masz 27...75% szans na zablokowanie nadlatujących pocisków. Unik skończy się kiedy zaatakujesz.','(5...11 sek.) Poruszasz się o 33% szybciej i masz 27...75% szans na blokowanie pocisków. Przestanie działać, jeśli zaatakujesz.'],
426=>['Brutalny Strzał','Jeśli Brutalny Strzał trafi, przerywa bieżącą czynność celu. Jeśli tą czynnością było użycie czaru, to zadajesz +13...28 pkt. obrażeń.','Przerywa czynność. Efekt przerwania: zadaje +13...28 pkt. obrażeń, jeżeli czynnością było rzucanie czaru.'],
427=>['Sygnet Antidotum','Oczyszczasz się z zatrucia, choroby, oślepienia i jednej dodatkowej przypadłości.','Usuwa z ciebie zatrucie, chorobę, oślepienie i jedną dodatkową przypadłość.'],
428=>['Zapalające Strzały','Wystrzeliwujesz strzały w wybranego przeciwnika i maksymalnie 2 przeciwników będących w pobliżu niego. Trafieni przeciwnicy zostają podpaleni na 1...3 sek.','Trafia 2 przeciwników w pobliżu twojego celu i podpala ich (1...3 sek.).'],
429=>['Strzały Melandru','Przez 18 sek., kiedy tylko twoje strzały trafią, wywołują krwawienie na 3...25 sek. i dodatkowo, jeśli trafią w cel, który jest pod działaniem zaklęcia, zadają +8...28 pkt. obrażeń.','(18 sek.) Twoje strzały wywołują przypadłość krwawienie (3...25 sek.) i zadają +8...28 pkt. obrażeń przeciwnikom pod działaniem zaklęcia.'],
430=>['Ryzyko Strzelca','Przez 18 sek., za każdym razem kiedy twoja strzała trafi otrzymujesz 5...10 pkt. energii, ale za każdym razem kiedy chybi tracisz 10 pkt. energii.','(18 sek.) Otrzymujesz 5...10 pkt. energii, za każdym razem, kiedy twoje strzały trafiają. Tracisz 10 pkt. energii, jeśli nie trafisz.'],
431=>['Strzały Wybuchające','Przez 24 sek. twoje strzały eksplodują przy trafieniu, zadając celowi i wszystkim przeciwnikom znajdującym się bezpośrednio przy nim 3...18 pkt. obrażeń od ognia.','(24 sek.) Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim twoje strzały zadają po 3...18 pkt. obrażeń od ognia.'],
432=>['Czytanie Wiatru','Przez 24 sek., twoje strzały lecą dwa razy szybciej i zadają 3...10 pkt. dodatkowych obrażeń.','(24 sek.) +3...10 pkt. obrażeń. Twoje strzały lecą dwa razy szybciej.'],
433=>['Płonące Strzały','Przez 24 sek., twoje strzały zadają obrażenia od ognia i dodatkowe 3...24 pkt. obrażeń od ognia.','(24 sek.) +3...24 pkt. obrażeń od ognia. Twoje strzały zadają obrażenia od ognia.'],
434=>['Duszący Gaz','Przez 1...12 sek. twoje strzały zadają 1...8 pkt. dodatkowych obrażeń i roznoszą Duszący Gaz na wszystkich przeciwników bezpośrednio przy celu. Duszący Gaz przerywa próby rzucania czarów.','(1...12 sek.) +1...8 pkt. obrażeń. Roznosi Duszący Gaz na przeciwników bezpośrednio przy celu. Duszący Gaz przerywa rzucanie czarów.'],
435=>['Nakładanie Trucizny','Przez 24 sek., cele trafione przez twoje fizyczne ataki zostają zatrute na 3...15 sek.','(24 sek.) Twoje fizyczne ataki wywołują przypadłość zatrucie (3...15 sek.).'],
436=>['Uzdrowienie Zwierzęcia','Leczysz swojego zwierzęcego towarzysza dodając mu 40...120 pkt. żywotności. Jeśli jest martwy, wskrzeszasz go z 10...58% punktami żywotności. Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.','Twój zwierzęcy towarzysz otrzymuje 40...120 pkt. żywotności. Wskrzesza twojego zwierzęcego towarzysza (10...58% żywotności). Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.'],
437=>['Bestialski Skok','Twój zwierzęcy towarzysz wykonuje Bestialski Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika rzucającego czar, to przeciwnik ten zostanie powalony.','Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik rzuca czar.'],
438=>['Okaleczające Uderzenie','Twój zwierzęcy towarzysz wykonuje Okaleczające Uderzenie, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika, to przeciwnik ten zostanie okulawiony na 3...15 sek.','Zadaje +5...20 pkt. obrażeń. Po trafieniu powoduje okulawienie (na 3...15 sek.).'],
439=>['Dzikie Pchnięcie','Twój zwierzęcy towarzysz wykonuje Dzikie Pchnięcie, które zadaje +5...35 pkt. obrażeń. Jeśli atak trafi atakującego przeciwnika, to przeciwnik ten przez 5...25 sek. będzie krwawił.','Zadaje +5...35 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...25 sek.), jeżeli wybrany przeciwnik atakuje.'],
440=>['Uderzenie Padlinożercy','Twój zwierzęcy towarzysz wykonuje Uderzenie Padlinożercy, które zadaje +10...25 pkt. obrażeń. Jeśli atak trafi przeciwnika, pod działaniem przypadłości, to otrzymujesz +3...15 pkt. energii.','Zadaje +10...25 pkt. obrażeń. Otrzymujesz 3...15 pkt. energii, jeżeli wybrany przeciwnik jest pod działaniem przypadłości.'],
441=>['Natarcie Melandru','Twój zwierzęcy towarzysz próbuje wykonać Natarcie Melandru, które zadaje +5...20 pkt. obrażeń wszystkim przeciwnikom znajdującym się w pobliżu.','Zadaje +5...20 pkt. obrażeń przeciwnikom znajdującym się w pobliżu.'],
442=>['Zajadłe Uderzenie','Twój zwierzęcy towarzysz wykonuje Zajadłe Uderzenie, które zadaje +13...28 pkt. obrażeń. Jeśli atak trafi, to otrzymujesz adrenalinę i 3...10 pkt. energii.','Zadaje +13...28 pkt. obrażeń. Otrzymujesz adrenalinę i 3...10 pkt. energii.'],
443=>['Skok Drapieżnika','Twój zwierzęcy towarzysz wykonuje Skok Drapieżnika, który zadaje +5...35 pkt. obrażeń. Jeśli atak trafi, to twój zwierzęcy towarzysz otrzymuje 5...50 pkt. żywotności.','Zadaje +5...35 pkt. obrażeń. Twój zwierzęcy towarzysz otrzymuje 5...50 pkt. żywotności, jeżeli ten atak trafi.'],
444=>['Brutalne Uderzenie','Twój zwierzęcy towarzysz wykonuje Brutalne Uderzenie, które zadaje +5...35 pkt. obrażeń. Jeśli atak trafi przeciwnika, którego żywotność jest poniżej 50%, to przeciwnik ten otrzyma +5...35 pkt. dodatkowych obrażeń.','Zadaje +5...35 pkt. obrażeń. Zadaje +5...35 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
445=>['Przerywające Uderzenie','Twój zwierzęcy towarzysz wykonuje Przerywające Uderzenie, które zadaje +1...12 pkt. obrażeń. Jeśli atak trafi przeciwnika używającego umiejętności, to umiejętność ta zostanie przerwana i będzie niedostępna przez dodatkowe 20 sek.','Zadaje +1...12 pkt. obrażeń. Przerywa umiejętność. Efekt przerwania: przerwana umiejętność będzie niedostępna przez +20 sek.'],
446=>['Maść z Trolla','Przez 13 sek. posiadasz regenerację żywotności równą +3...10.','(13 sek.) Posiadasz regenerację żywotności +3...10.'],
447=>['Ryk Otyugha','Przez 10...25 sek., twój zwierzęcy towarzysz posiada +24 pkt. pancerza, dodatkowo jego ataków nie można zablokować.','(10...25 sek.) Twój zwierzęcy towarzysz ma +24 pkt. pancerza, a jego ataków nie można blokować.'],
448=>['Ucieczka','Przez 1...8 sek., poruszasz się o 33% szybciej i masz 75% szansy na zablokowanie ataków.','(1...8 sek.) Poruszasz się o 33% szybciej i masz 75% szans na blokowanie.'],
449=>['Postawa Wyćwiczona','Przez 20...35 sek. twoje przygotowania odnawiają się o 50% szybciej i trwają o 30...300% dłużej.','(20...35 sek.) Twoje przygotowania odnawiają się o 50% szybciej i trwają o 30...300% dłużej.'],
450=>['Wirująca Obrona','Przez 8...20 sek., masz 75% szans na zablokowanie ataków. Jeśli zablokujesz w ten sposób atak strzelecki, przeciwnicy bezpośrednio przy tobie otrzymają 5...11 pkt. obrażeń.','(8...20 sek.) Masz 75% szans na blokowanie. Zadaje 5...11 pkt. obrażeń przeciwnikom bezpośrednio przy tobie, za każdym razem, kiedy zablokujesz atak zasięgowy.'],
451=>['Wytrzymałość Melandru','Przez 8...20 sek., za każdą przypadłość i klątwę, pod których jesteś działaniem, otrzymujesz regenerację żywotności równą +4 i regenerację energii równą +1.','(8...20 sek.) Za każdą przypadłość i klątwę, pod których jesteś działaniem, otrzymujesz regenerację żywotności +4 i regenerację energii +1.'],
452=>['Obrona Drydera','Przez 5...11 sek., masz 75% szans na zablokowanie ataków i otrzymujesz 34...60 pkt. pancerza przeciwko obrażeniom od żywiołów.','(5...11 sek.) Masz 75% szans na blokowanie i +34...60 pkt. pancerza przeciwko obrażeniom od żywiołów.'],
453=>['Błyskawiczny Refleks','Przez 5...11 sek., masz 75% szans na zablokowanie ataków wręcz i strzeleckich, a dodatkowo atakujesz o 33% szybciej.','(5...11 sek.) Atakujesz o 33% szybciej i masz 75% szans na blokowanie.'],
454=>['Tygrysia Furia','Wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek. Przez 5...11 sek., atakujesz o 33% szybciej.','(5...11 sek.) Atakujesz o 25% szybciej. Wyłacza twoje umiejętności nie związane z atakami (5 sek.).'],
455=>['Łowca Burz','Przez 8...20 sek., poruszasz się o 25% szybciej i za każdym razem kiedy otrzymasz obrażenia od żywiołów, dostaniesz 1...5 pkt. energii.','(8...20 sek.) Poruszasz się o 25% szybciej i otrzymujesz 1...5 pkt. energii, za każdym razem, kiedy otrzymujesz obrażenia od żywiołów.'],
456=>['Szybkość Węża','Przez 15...30 sek., czas odnawiania twoich umiejętności zmniejsza się o 33%. Szybkość Węża skończy się kiedy twoja żywotność spadnie poniżej 50%.','(15...30 sek.) Twoje umiejętności odnawiają się o 33% szybciej. Przestanie działać, jeśli twoja żywotność spadnie poniżej 50%.'],
457=>['Pyłowa Pułapka','Kiedy Pyłowa Pułapka zostanie uaktywniona, to w każdej sekundzie (5 sek. łącznie), wszyscy przeciwnicy w pobliżu zostaną oślepieni na 3...8 sek. i otrzymają po 10...25 pkt. obrażeń od ziemi. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać. Pyłowa Pułapka przestanie działać po 90 sek.','(90 sek.) Działa na przeciwników w pobliżu. W każdej sekundzie zadaje 10...25 pkt. obrażeń (5 sek.). Co sekundę (5 sek.) wywołuje przypadłość oślepienie (3...8 sek.). Łatwo przerwać.'],
458=>['Kolczasta Pułapka','Kiedy Kolczasta Pułapka zostanie uruchomiona, to wszyscy przeciwnicy w pobliżu otrzymują 7...23 obrażeń przebijających, zostają okulawieni i na 3...25 sek. zaczynają krwawić. Kolczasta Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. Zadaje 7...23 pkt. obrażeń przebijających. Wywołuje przypadłości okulawienie oraz krwawienie (3...25 sek.). Łatwo przerwać.'],
459=>['Płomienna Pułapka','Kiedy Płomienna Pułapka zostanie uruchomiona, to w każdej sekundzie (z 3 łącznie) wszyscy przeciwnicy w pobliżu otrzymują 5...20 pkt. obrażeń od ognia i zaczynają płonąć przez 1...3 sek. Płomienna Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. W każdej sekundzie zadaje 5...20 pkt. obrażeń od ognia (3 sek.). Wywołuje przypadłość płonięcie (1...3 sek.). Łatwo przerwać.'],
460=>['Uzdrawiające Źródło','Przez 10 sek., wszyscy sojusznicy znajdujący się bezpośrednio przy źródle są uzdrawiani co 2 sekundy, otrzymując 15...60 pkt. żywotności. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(10 sek.) Działa na sojuszników w bezpośredniej odległości. Co 2 sek. dodaje 15...60 pkt. żywotności. Łatwo przerwać.'],
461=>['Pułapka z Ostrzy','Kiedy Pułapka z Ostrzy zostanie uruchomiona, to w każdej sekundzie (przez 2 sek.) wszyscy przeciwnicy w pobliżu otrzymują po 10...40 pkt. obrażeń przebijających, zostaną okulawieni na 3...25 sek. i powaleni. Pułapka z Ostrzy przestanie działać po 90 sek. W czasie, kiedy będziesz używać tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. Co sekundę (przez 2 sek.) zadaje 10...40 pkt. obrażeń przebijających, powala i wywołuje przypadłość okulawienie (3...25 sek.). Łatwo przerwać.'],
462=>['Zima','Tworzysz 1...10 poziomowego ducha. Dla stworzeń w jego zasięgu wszystkie obrażenia od żywiołów stają się obrażeniami od zimna. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Dla stworzeń w zasięgu zamienia obrażenia od żywiołów na obrażenie od zimna. Nie działa na duchy.'],
463=>['Odsiew','Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu otrzymują 4 dodatkowe obrażenia za każdym razem, kiedy otrzymają fizyczne obrażenia. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). O +4 zwiększa obrażenia fizyczne zadawane przez stworzenia w zasięgu. Nie działa na duchy.'],
464=>['Skraj Wymarcia','Tworzysz 1...10 poziomowego ducha. Jeśli w jego zasięgu zginie jakieś stworzenie nie-duch, to Skraj Wymarcia zada 14...50 pkt. obrażeń wszystkim stworzeniom tego samego typu w swoim zasięgu, które posiadają mniej niż 90% żywotności. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Zadaje 14...50 pkt. obrażeń stworzeniom w zasięgu, za każdym razem, kiedy zginie stworzenie tego samego rodzaju. Nie działa na duchy. Bez obrażeń dla stworzeń, które mają więcej niż 90% żywotności.'],
465=>['Większa Pożoga','Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu wszystkie obrażenia fizyczne stają się w zamian obrażeniami od ognia. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Dla stworzeń w zasięgu zamienia obrażenia fizyczne na obrażenia od ognia. Nie działa na duchy.'],
466=>['Pożoga','Tworzysz 1...10 poziomowego ducha. Wszystkie strzały, które trafiają stworzenia nie-duchy w jego zasięgu zadają obrażenia od ognia. Ten duch ginie po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Wszystkie strzały stworzeń w zasięgu zadają obrażenia od ognia. Nie działa na duchy.'],
467=>['Czas Obfitości','Tworzysz 1...10 poziomowego ducha. Wszystkim stworzeniom nie-duchom w jego zasięgu maksymalna żywotność zwiększa się o +50...150 i pancerz o +8. Duch umiera po 15...90 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...90 sek.). Stworzenia w zasięgu posiadają +50...150 pkt. do maksymalnej żywotności i +8 pkt. pancerza. Nie działa na duchy.'],
468=>['Symbioza','Tworzysz 1...10 poziomowego ducha. Na każde zaklęcie, pod którego działaniem jest stworzenie nie-duch w zasięgu, maksymalna żywotność tego stworzenia zwiększa się o +27...150 pkt. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu otrzymują +27...150 pkt. do maksymalnej żywotności na każde zaklęcie, pod którego są działaniem. Nie działa na duchy.'],
469=>['Pierwotne Echa','Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu użycie sygnetów kosztuje 10 pkt. energii. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Użycie sygnetu przez stworzenia w zasięgu kosztuje 10 pkt. energii. Nie działa na duchy.'],
470=>['Sezon Łowów','Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu, uleczanie jest obniżone o 20%. Za każdy swój trafiony atak otrzymujesz 5 pkt. żywotności. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu otrzymują o 20% mniej pkt. żywotności. Stworzenia otrzymują 5 pkt. energii, za każdym razem, kiedy ich atak wręcz trafi. Nie działa na duchy.'],
471=>['Zmarznięta Ziemia','Tworzy 1...10 poziomowego Ducha. Żadne stworzenie nie-Duch w jego zasięgu nie może używać umiejętności wskrzeszania. Duch umiera po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia w zasięgu nie mogą używać umiejętności wskrzeszania. Nie działa na duchy.'],
472=>['Sprzyjające Wiatry','Tworzysz 1...10 poziomowego ducha. Strzały stworzeń nie-duchów w jego zasięgu lecą dwa razy szybciej i zadają +6 obrażeń. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Strzały stworzeń w zasięgu lecą dwa razy szybciej i zadają +6 pkt. obrażeń. Nie działa na duchy.'],
474=>['Pobudzający Wiatr','Tworzysz 1...6 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu wszystkie umiejętności kosztują o 15 pkt. energii mniej (minimalny koszt to 10 pkt. energii), ale odnawiają się o 25% wolniej. Duch umiera po 1...60 sek.','Tworzy ducha na poziomie 1...6 (czas życia 1...60 sek.). Umiejętności stworzeń w zasięgu kosztują o 15 pkt. energii mniej (minimalny koszt 10 pkt. energii) i odnawiają się o 25% wolniej. Nie działa na duchy.'],
475=>['Ożywczy Zefir','Tworzysz 1...10 poziomowego ducha. Dla stworzeń nie-duchów w jego zasięgu, wszystkie umiejętności odnawiają się dwa razy szybciej, ale kosztują o 30% więcej energii. Duch umiera po 15...90 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...90 sek.). Umiejętności stworzeń w zasięgu kosztują o 30% pkt. energii więcej i odnawiają się dwa razy szybciej. Nie działa na duchy.'],
476=>['Odnowienie Natury','Tworzysz 1...10 poziomowego ducha. Przez 30...240 sek. zaklęcia i klątwy używane przez stworzenia nie-duchy, potrzebują dwa razy więcej czasu na rzucenie, a energetyczny koszt utrzymania zaklęć zwiększa się dwukrotnie. Duch umiera po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Stworzenia w zasięgu dwa razy dłużej rzucają zaklęcia i klątwy, a energetyczny koszt utrzymania ich zaklęć jest dwa razy większy. Nie działa na duchy.'],
477=>['Błotnisty Teren','Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu poruszają się o 10% wolniej i nie działają zwiększenia prędkości. Duch umiera po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia w zasięgu poruszają się o 10% wolniej; neguje także premie do szybkości. Nie działa na duchy.'],
570=>['Piętno Niepewności','Przez 5...25 sek. wybrany przeciwnik posiada degenerację żywotności -1...5, a zaklęcia i postawy, pod których jest działaniem kończą się o 20...60% szybciej. Wszystkie twoje umiejętności spoza profesji skrytobójcy będą niedostępne przez 5 sek.',' (5...25 sek.). Powoduje degenerację żywotności -1...5. Zaklęcia i postawy wskazanego przeciwnika kończą się o 20...60% szybciej. Wyłącza umiejętności nienależące do zabójcy (5 sek.).'],
571=>['Przerywający Sztylet','Rzucasz Przerywającym Sztyletem w wybranego przeciwnika i zadajesz mu 10...35 pkt. obrażeń od ziemi. Jeśli przeciwnik aktywuje umiejętność, to zostaje ona przerwana. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Pocisk: zadaje 10...35 pkt. obrażeń od ziemi. Przerywa umiejętność.'],
572=>['Zabójczy Paradoks','Wszystkie twoje umiejętności związane z atakowaniem są niedostępne przez 10 sek. Przez 5...15 sek. twoje umiejętności zabójcy aktywują się i odnawiają się o 33% szybciej.','(5...15 sek.) Twoje umiejętności zabójcy aktywują i odnawiają się o 33% szybciej. Wyłącza twoje umiejętności związane z atakami (10 sek.).'],
763=>['Zawistne Spojrzenie','Usuwa zaklęcie z wybranego przeciwnika. Jeśli zaklęcie się skończy, przez kolejne 1...20 sek., twoje następne zaklęcie będzie mogło być rzucone 0...1 sek. szybciej i zużyje 1...10 pkt. energii mniej.','Usuwa zaklęcie z wybranego przeciwnika.Efekt usunięcia: twoje następne zaklęcie będzie mogło być rzucone 0...1 sek. szybciej i zużyje 1...10 pkt. energii mniej. (1...20 sek.)'],
764=>['Lament Zagłady','Przez 2...6 sek. wszystkie atrybuty wybranego przeciwnika wynoszą 0.','(2...6 sek.) Atrybuty wybranego przeciwnika wynoszą 0.'],
766=>['Pogardliwe Spojrzenie','Jeżeli wybrany przeciwnik ma więcej niż 50% pkt. żywotności, to ten przeciwnik traci wszystkie zaklęcia.','Zdejmujesz zaklęcia wybranego przeciwnika. Bez efektu, chyba że ten przeciwnik ma więcej niż 50% żywotności.'],
769=>['Obrona Żmiji','Wszyscy przeciwnicy w bezpośredniej odległości zostają na 5...20 sek. zatruci, a ty wykonujesz krok cienia w kierunku przeciwnym do twojego celu.','U wszystkich przeciwników w bezpośredniej odległości wywołuje zatrucie (5...20 sek.), a ty wykonujesz krok cienia w kierunku przeciwnym do twojego celu.'],
770=>['Powrót','Wszyscy przeciwnicy bezpośrednio przy Tobie zostają okulawieni na 3...8 sek. Wykonujesz krok cienia do wybranego sojusznika.','Okulawia (3...8 sek.) wszystkich przeciwników bezpośrednio przy tobie. Wykonujesz krok cienia do miejsca wybranego sojusznika. Na cel nie można wybrać siebie.'],
771=>['Aura Przemieszczenia','Rzucając Aurę Przemieszczenia wykonujesz krok cienia do wybranego przeciwnika. Gdy przestaniesz utrzymywać Aurę Przemieszczenia, wracasz do miejsca gdzie została rzucona.','Wykonujesz krok cienia do wybranego przeciwnika. Efekt końcowy: wracasz do swojego początkowego miejsca.'],
772=>['Hojnym Był Tsungrai','Trzymaj prochy Tsungraia przez maksymalnie 15...60 sek., aby otrzymać +50...140 do maksymalnych pkt. żywotności. Gdy upuścisz jego prochy, otrzymasz 100...280 pkt. żywotności.','(15...60 sek.) Twoja maksymalna żywotność zwiększa się o +50...140 pkt. Efekt upuszczenia: otrzymujesz 100...280 pkt. żywotności.'],
773=>['Potężnym Był Vorizun','Trzymaj prochy Vorizuna przez maksymalnie 15...60 sek. Trzymając jego prochy, zyskujesz +15 pkt. pancerza oraz zwiększasz maksimum pkt. energii o 30.','(15...60 sek.) Posiadasz +15 pkt. pancerza, a twoja maksymalna energia zwiększa się o +30 pkt.'],
775=>['Zabójczy Kwiat','Musi nastąpić po ataku drugą ręką. Zabójczy Kwiat zadaje wybranemu przeciwnikowi +20...45 pkt. obrażeń, wszyscy przeciwnicy bezpośrednio przy nim otrzymują 20...45 pkt. obrażeń.','Zadaje +20...45 pkt. obrażeń. Działa także na przeciwników bezpośrednio przy wybranym przeciwniku. Musi nastąpić po ataku drugą ręką.'],
776=>['Skręcone Kły','Musi nastąpić po ataku drugą ręką. Jeżeli atak trafi, Skręcone Kły zadają +10...20 pkt. obrażeń, a uderzony przeciwnik zaczyna krwawić i otrzymuje głęboką ranę na 5...20 sek.','Zadaje +10...20 pkt. obrażeń. Wywołuje przypadłości krwawienie i głęboka rana (5...20 sek.). Musi nastąpić po ataku drugą ręką.'],
777=>['Rogi Wołu','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, Rogi Wołu zadają +1...11 pkt. obrażeń. Jeśli zaatakowany przeciwnik nie znajduje się bezpośrednio przy żadnym sojuszniku, zostaje powalony.','Zadaje +1...11 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik nie jest bezpośrednio przy żadnym swoim sojuszniku. Musi nastąpić po ataku drugą ręką.'],
778=>['Opadający Pająk','Musi uderzyć powalonego przeciwnika. Jeżeli atak trafi, Opadający Pająk zadaje +15...35 pkt. obrażeń, a wybrany przeciwnik zostaje zatruty na 5...20 sek.','Zadaje +15...35 pkt. obrażeń. Wywołuje przypadłość zatrucie (5...20 sek.). Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
779=>['Uderzenie Czarnego Lotosu','Jeśli atak trafi, Uderzenie Czarnego Lotosu zadaje +10...31 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod działaniem klątwy, otrzymujesz 5...13 pkt. energii.','Zadaje +10...31 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod działaniem klątwy, otrzymujesz 5...13 pkt. energii.'],
780=>['Lisie Kły','Musi nastąpić po ataku poprzedzającym. Lisie Kły nie mogą zostać zablokowane i zadają +10...35 pkt. obrażeń, jeżeli trafią.','Zadaje +10...35 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
781=>['Uderzenie Moebiusa','Musi nastąpić po ataku podwójnym. Jeśli atak trafi, Uderzenie Moebiusa zadaje +10...35 pkt. obrażeń. Jeżeli uderzysz przeciwnika, który posiada mniej niż 50% pkt. żywotności, wszystkie twoje pozostałe umiejętności ataku zostają odnowione.','Zadaje +10...35 pkt. obrażeń. Odnawia twoje pozostałe umiejętności związane z atakami, jeżeli żywotność wybranego przeciwnika jest poniżej 50%. Musi nastąpić po ataku podwójnym.'],
782=>['Rozdzierające Uderzenie','Jeśli Rozdzierające Uderzenie trafi, twój cel zaczyna krwawić przez 5...20 sek.','Wywołuje przypadłość krwawienie (5...20 sek.).'],
783=>['Niespodziewane Uderzenie','Jeśli atak trafi, zadajesz +19...31 pkt. obrażeń. Jeżeli ten przeciwnik miał ponad 90% pkt. żywotności, zdajesz dodatkowe 15...75 pkt. obrażeń.','Zadaje +19...31 pkt. obrażeń. Zadaje 15...75 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik ma powyżej 90% żywotności.'],
784=>['Wijąca się Żmija','Wijąca się Żmija musi nastąpić po ataku poprzedzającym. Wybrany przeciwnik zostaje powalony oraz zatruty na 5...20 sek.','Powoduje powalenie. Wywołuje przypadłość zatrucie (5...20 sek.). Musi nastąpić po ataku poprzedzającym.'],
785=>['Piętno Śmierci','Przez 4...10 sek., wybrany przeciwnik otrzymuje przy leczeniu 50% mniej pkt. żywotności.','(4...10 sek.) Wybrany przeciwnik otrzymuje o 50% mniej pkt. żywotności.'],
786=>['Żelazna Dłoń','Wybrany dotknięty przeciwnik otrzymuje 5...50 pkt. obrażeń oraz jeżeli cierpiał na przypadłość lub był pod wpływem klątwy, zostaje powalony. Żelazna Dłoń liczy się jako atak poprzedzający.','Zadaje 5...50 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik ma na sobie klątwę lub przypadłość. Traktuje się jako atak poprzedzający.'],
787=>['Wytrzymały Oręż','Przez 3...12 sek. wybrany sojusznik posiada Wytrzymały Oręż. Pod wpływem klątwy lub przypadłości, ten sojusznik zyskuje regenerację żywotności +1...6 i otrzymuje +24 pkt. pancerza.','(3...12 sek.) Regeneracja żywotności +1...6 i +24 pkt. pancerza. Bez efektu, chyba że wybrany sojusznik jest pod wpływem klątwy lub przypadłości.'],
788=>['Ślepym Był Mingson','Trzymaj prochy Mingsona przez maksymalnie 15...60 sek. Gdy upuścisz jego prochy, wszyscy przeciwnicy w pobliżu zostaną oślepieni na 3...8 sek.','(15...60 sek.) Efekt upuszczenia: oślepia (3...8 sek.) wszystkich przeciwników w pobliżu.'],
789=>['Zachłannym Był Kuurong','Trzymaj prochy Kuuronga przez maksymalnie 15...60 sek. Gdy upuścisz jego prochy, wszyscy przeciwnicy w okolicy otrzymują 15...75 pkt. obrażeń od oraz zostają powaleni.','(15...60 sek.) Efekt upuszczenia: wszystkim przeciwnikom w okolicy zadaje po 15...75 pkt. obrażeń i powala ich.'],
790=>['Mściwym Był Khanhei','Trzymaj prochy Khanheia przez maksymalnie 5...11 sek. Za każdym razem, kiedy przeciwnik uderzy cię w walce, gdy trzymasz prochy Khanheia, wykradniesz mu 10...45 pkt. żywotności.','(5...11 sek.) Każdemu przeciwnikowi, który cię trafi, wykradasz 10...45 pkt. żywotności.'],
791=>['Ciało z Mego Ciała','Tracisz połowę aktualnej liczby punktów żywotności. Wskrzeszasz wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...20% pkt. energii.','Wskrzeszasz wybranego członka drużyny (połowa twojej aktualnej żywotności i 5...20% energii). Tracisz połowę żywotności.'],
792=>['Odłamkowy Oręż','Przez 20 sek. wskazany sprzymierzeniec otrzymuje Odłamkowy Oręż. Kolejne ataki sojusznika (1...5 ) zadają 5...50 pkt.obrażeń maksymalnie 4 pobliskim wrogom.','(20 sek.) Ataki zadają po 5...50 pkt. obrażeń 3 przeciwnikom w bezpośredniej odległości. Koniec po 1...5 atakach.'],
793=>['Ochronny Oręż','Na 3...8 sek., wybrany sojusznik zyskuje Ochronny Oręż, który zapewnia mu +2...4 regeneracji żywotności oraz 50% szans na zablokowanie ciosu.','(3...8 sek.) Regeneracja żywotności +2...4. 50% szans na blokowanie.'],
794=>['Zawodzący Oręż','Na 3...14 sek., wybrany sojusznik zyskuje Zawodzący Oręż. Za każdym razem, kiedy Zawodzący Oręż trafi atakującego przeciwnika, czynność tego przeciwnika zostaje przerwana.','(3...14 sek.) Ataki przerywają czynności atakujących przeciwników.'],
795=>['Upiorny Oręż','Na 12 sek., wybrany sojusznik zyskuje Upiorny Oręż. Kolejne (3) ataki tego sojusznika zadają 10...50 pkt. obrażeń mniej i wykradają do 10...50 pkt. żywotności.','(12 sek.) Ataki wybranego sojusznika wykradają 10...50 pkt. żywotności, ale zadają 10...50 pkt. obrażeń mniej. Koniec po 3 atakach.'],
799=>['Czarująca Ułuda','Wykonujesz Krok Cienia w stronę wskazanego przeciwnika, który zostaje oszołomiony na 3...9 sek.','Wykonujesz krok cienia do tego przeciwnika. Wywołuje przypadłość oszołomienie (3...9 sek.).'],
800=>['Trwała Trucizna','Przez 5 sek., wybrany przeciwnik posiada degeneracji żywotności -1...5. Jeżeli przeciwnik ten porusza się, gdy Trwała Trucizna powinna przestać działać, zostaje ona odnowiona na kolejne 5 sek.','(5 sek.) Powoduje degenerację żywotności -1...5. Odnowienie: jeżeli wybrany przeciwnik jest w ruchu, kiedy ta klątwa się kończy.'],
801=>['Całun Ciszy','Wszystkie twoje czary będą niedostępne przez 15 sek. Przez 1...6 sek. wybrany dotknięty przeciwnik nie może rzucać czarów.','(1...6 sek.) Wybrany przeciwnik nie może rzucać czarów. Twoje czary są wyłączone (15 sek.).'],
802=>['Przełamanie Zasłony','Przez 1...11 sek., wybrany przeciwnik nie może blokować twoich ataków.','(1...11 sek.) Wybrany przeciwnik nie może blokować twoich ataków.'],
803=>['Spijanie Mocy','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a jeśli w ciągu 10 sek. ten przeciwnik rzuci zaklęcie, przejmujesz od niego do 5...15 pkt. energii.','Przerywa użycie czaru lub pieśni. Skutek przerwania: przejmuje 5...15 pkt. energii, gdy wybrany przeciwnik rzuca czar (10 sek.).'],
804=>['Magiczna Ospałość','Przez 1...10 sek. wszystkie czary rzucane przez wybranego przeciwnika powodują u niego 10 punktów Przemagicznienia.','(1...10 sek.) Zaklęcia rzucane przez cel powodują 10 punktów Przemagicznienia.'],
805=>['Ożywienie Wampirycznej Poczwary','Wykorzystaj najbliższe zwłoki by ożywić Wampiryczną Poczwarę na 1...17 poziomie. Za każdym razem, kiedy Wampiryczna Poczwara zadaje obrażenia, zyskujesz taką samą liczbę pkt. żywotności.','Tworzy wampiryczną poczwarę na poziomie 1...17. Otrzymujesz liczbę punktów żywotności równą punktom obrażeń, jakie ona zadaje. Zużywa świeże ciało.'],
806=>['Żarliwość Kultysty','Przez 5 sek. plus 3 sek. za każdy poziom Wydzierania Duszy, twoje czary nekromantyczne kosztują -1...6 mniej Energii, ale za każdym razem gdy rzucisz taki czar, zaczynasz krwawić przez 10 sek.','(5 sek. plus 3 sek. za każdy poziom Wydzierania Duszy) Twoje czary nekromantyczne kosztują -1...6 mniej Energii. Zaczynasz krwawić (10 sek.) za każdym razem, gdy rzucisz taki czar.'],
808=>['Piętno Żniwiarza','Przez 30 sek. wybrany przeciwnik posiada degenerację żywotności -1...5. Jeżeli ten przeciwnik umrze będąc pod działaniem Piętna Żniwiarza, otrzymujesz 5...15 pkt. energii.','(30 sek.) Powoduje degenerację żywotności -1...5. Otrzymujesz 5...15 pkt. energii, jeżeli wybrany przeciwnik umrze, będąc pod działaniem tej klątwy.'],
809=>['Lodowa Skała','Wybrany przeciwnik otrzymuje 25...100 pkt. obrażeń od zimna, porusza się o 66% wolniej i zostaje przeklęty Lodową Skałą na 3 sek. Gdy Lodowa Skała przestanie działać, ten przeciwnik otrzymuje 25...100 pkt. obrażeń od zimna.','(3 sek.) Efekt początkowy: zadaje 25...100 pkt. obrażeń od zimna i spowalnia cel o 66%. Efekt końcowy: zadaje 25...100 pkt. obrażeń od zimna celowi i wszystkim pobliskim przeciwnikom.'],
810=>['Zastawa Obrońcy','Przez 5...11 sek., sojusznicy bezpośrednio przy tobie mają 75% szans na blokowanie ataków. Zastawa Obrońcy skończy się, jeśli się poruszysz.','(5...11 sek.) Sojusznicy w bezpośredniej odległości mają 75% szans na blokowanie. Przestanie działać, jeśli się ruszysz.'],
811=>['Jedność w Biegu','Przez 5...15 sek., ty i twój zwierzęcy towarzysz poruszacie się o 25% szybciej.','(5...15 sek.) Ty i twój zwierzęcy towarzysz poruszacie się o 25% szybciej.'],
812=>['Buntowniczą Była Xinrae','Trzymaj prochy Xinrae przez maksymalnie 15...60 sek. Gdy trzymasz jej prochy, w pojedynczym trafieniu nie możesz stracić więcej niż 20% swojej maksymalnej żywotności. Kiedy upuścisz jej prochy, od pobliskich przeciwników wykradasz 5...50 pkt. żywotności.','(15...60 sek.) Jeden atak nie może ci zabrać więcej niż 20% twojej maksymalnej żywotności. Efekt zdjęcia: wykrada 5...50 pkt. żywotności z pobliskich przeciwników.'],
813=>['Aura Lyssy','Przez 10 sek. posiadasz regenerację energii +0...5. Czar zaczyna ponownie działać, za każdym razem, kiedy rzucisz czar na przeciwnika.','(10 sek.) Posiadasz regenerację energii +0...5. Odnawianie: za każdym razem, kiedy rzucisz czar na przeciwnika.'],
814=>['Cieniste Schronienie','Przez 6 sek., otrzymujesz regenerację żywotności równą 5...10. Gdy Cieniste Schronienie przestanie działać, otrzymujesz 40...100 pkt. żywotności jeżeli atakujesz.','(6 sek.) Posiadasz regenerację żywotności +5...10. Efekt końcowy: otrzymujesz 40...100 pkt. żywotności, jeżeli atakujesz.'],
815=>['Nić Skorpiona','Przez 8...20 sek., następnym razem, kiedy wybrany przeciwnik oddali się od ciebie na więcej niż 23 metrów, wykonujesz krok cienia do niego, a on zostaje powalony. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','(8...20 sek.) Wykonujesz krok cienia do wybranego przeciwnika i powalasz go, kiedy znajdzie się w odległości większej niż 23 m od ciebie.'],
816=>['Lustrzana Postawa','Przez 10...35 sek., za każdym razem, kiedy wybrany przeciwnik przyjmuje postawę, ty przyjmujesz taką samą postawę.','(10...35 sek.) Przyjmujesz postawę, pod której działaniem jest wybrany przeciwnik.'],
817=>['Niezgoda','Jeżeli wybrany przeciwnik cierpi na przypadłość i jest pod wpływem klątwy lub zaklęcia, przeciwnik ten otrzymuje 30...110 pkt. obrażeń.','Zadaje 30...110 pkt. obrażeń. Bez efektu, chyba że wybrany przeciwnik jest pod działaniem przypadłości i ma na sobie klątwę lub zaklęcie.'],
818=>['Studnia Zmęczenia','Wykorzystaj wybrane zwłoki lub poświęć 66% swojej żywotności, by na 10...55 sek. utworzyć Studnię Zmęczenia. Wrogowie na obszarze Studni Zmęczenia cierpią -1 degeneracji pkt. energii.','(10...55 sek.). Przeciwnicy w tej studni mają degenerację energii -1. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
819=>['Wampiryczny Duch','Wybranemu przeciwnikowi wykradasz 15...60 pkt. żywotności. Przez 10 sek. posiadasz regenerację żywotności +5...10.','Wybranemu przeciwnikowi wykradasz 15...60 pkt. żywotności. Posiadasz regenerację żywotności +5...10 (10 sek.).'],
820=>['Deprawacja','Przez 5...20 sek., za każdym razem, kiedy wybrany przeciwnik rzuca czar, ten przeciwnik i jeden przeciwnik w pobliżu tracą po 1...5 pkt. energii.','(5...20 sek.) Powoduje utratę 1...5 pkt. energii, za każdym razem, kiedy wybrany przeciwnik rzuca czar. Energię traci również jeden przeciwnik w pobliżu twojego celu.'],
821=>['Lodowate Żyły','Wybrany przeciwnik otrzymuje 10...90 pkt. obrażeń od zimna. Przez 10...35 sek., jeżeli wybrany przeciwnik umrze, wszyscy pobliscy przeciwnicy otrzymują 20...110 pkt. obrażeń od zimna.','(10...35 sek.) Przeciwnikom w pobliżu zadaje 20...110 pkt. obrażeń od zimna, jeżeli wybrany przeciwnik umrze. Efekt początkowy: zadaje 10...90 pkt. obrażeń od zimna.'],
822=>['Osłabienie Kolan','Przez 1...16 sek. wybrany przeciwnik posiada degenerację żywotności -1...4 oraz otrzymuje 5...20 pkt obrażeń będąc w ruchu.','(1...16 sek.) Wybrany przeciwnik posiada degenerację żywotności -1...4 oraz otrzymuje 5...20 pkt obrażeń będąc w ruchu.'],
823=>['Płonąca Szybkość','Przez 7 sek. płoniesz i poruszasz się 30...45% szybciej. Kiedy Płonąca Szybkość dobiegnie końca, wszyscy znajdujący się w bezpośrednim sąsiedztwie wrogowie zostają podpaleni na 3...9 sek.','(7 sek.) Poruszasz się 30...45% szybciej. Płoniesz (przez 3...9 sek.). Efekt końcowy: podpala (3...9 sek.) przeciwników w bezpośrednim sąsiedztwie.'],
824=>['Magmowe Strzały','Magmowe Strzały lecą w kierunku maksymalnie 3 przeciwników w pobliżu twojego celu i jeżeli trafią, zadają 20...65 pkt. obrażeń od ognia.','Pocisk: zadaje 20...65 pkt. obrażeń od ognia. Efekt dodatkowy: wystrzeliwuje pociski w 2 innych przeciwników w pobliżu twojego celu.'],
825=>['Rozżarzone Węgle','Tworzy pod wybranym wrogiem Rozżarzone Węgle. Przez 5 sek. przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują co sekundę po 5...29 pkt. obrażeń od ognia. Każdy przeciwnik powalony na Rozżarzonych Węglach zostaje podpalony na 3...7 sek.','Zadaje 5...29 pkt. obrażeń na sek. (przez 5 sek.) na obszarze wokół celu. Trafia wrogów stojących obok celu. Podpala (na 3...7 sek.) powalonych przeciwników.'],
826=>['Cienisty Kształt','Przez 5...21 sek., nie możesz być celem wrogich czarów, a twoje obrażenia są zmniejszone o 5 za każde nałożone na ciebie zaklęcie Zabójcy. Nie możesz zadać więcej niż 5...25 pkt. obrażeń jednym atakiem lub umiejętnością.','(5...21 sek.) Nie możesz być celem wrogich czarów. Twoje obrażenia zostają zmniejszone o 5 za każde nałożone na ciebie zaklęcie zabójcy. Nie możesz zadać więcej niż 5...25 pkt. obrażeń jednym atakiem lub umiejętnością.'],
827=>['Wyssanie Siły','Przez 5...20 sek., wybrany przeciwnik zadaje atakami -5...50 pkt. obrażeń, a wszystkie twoje ataki na tego przeciwnika maja 50% więcej szans na uzyskanie trafienia krytycznego.','(5...20 sek.) Wybrany przeciwnik zadaje -5...50 pkt. obrażeń. Posiadasz +50% szans na wykonanie trafienia krytycznego w tego przeciwnika.'],
828=>['Ohydny Fetor','Wybrany przeciwnik otrzymuje 10...65 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik cierpi na jakąś przypadłość, to ten przeciwnik przez 10 sek. posiada dodatkowo degenerację żywotności -1...5.','Powoduje degenerację żywotności -1...5 (10 sek.). Efekt początkowy: zadaje 10...65 pkt. obrażeń od zimna. Klątwa zostaje nałożona tylko, jeśli wybrany przeciwnik cierpi na przypadłość.'],
830=>['Promień Osądu','Wywołujesz Promień Osądu w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy bezpośrednio przy tym miejscu otrzymują w każdej sekundzie po 10...50 pkt. świętych obrażeń i zaczynają płonąć na 1...3 sek.','W każdej sekundzie (5 sek.) zadaje 10...50 pkt. świętych obrażeń i wywołuje przypadłość płonięcie (1...3 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
831=>['Pierwotny Szał','Przez 1...9 sek. atakujesz 33% szybciej i poruszasz się 33% szybciej, ale odnosisz 150...125% obrażeń.','(1...9 sek.) Atakujesz 33% szybciej i poruszasz się 33% szybciej. Odnosisz 150...125% obrażeń.'],
832=>['Ożywienie Golema Tkankowego','Wykorzystaj najbliższe zwłoki, by ożywić golema tkankowego na 3...25 poziomie. Golem tkankowy pozostawia 1...4 szt. zwłok, które można wykorzystać. Możesz mieć tylko jednego golema tkankowego naraz.','Tworzy golema tkankowego na poziomie 3...25, który po śmierci zostawia 1...4 szt. świeżych ciał. Zużywa świeże ciało. W danej chwili możesz mieć tylko jednego golema tkankowego.'],
834=>['Nieostrożny Pośpiech','Przez 6...12 sek. wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim znajdują się pod działaniem klątwy Nieostrożny Pośpiech. Pod wpływem klątwy atakują o 25% szybciej, ale mają 50% szans na nietrafiony atak.','Klątwa działa także na przeciwników bezpośrednio przy twoim celu (6...12 sek.). Ci przeciwnicy mają 50% szans na nietrafianie, ale atakują o 25% szybciej.'],
835=>['Krwawe Więzy','Przez 3...12 sek., wybrany przeciwnik oraz wszyscy sąsiadujący wrogowie zostają dotknięci klątwą Krwawe Więzy. Za każdym razem, kiedy sojusznik trafi któregoś z nich podczas ataku, sojusznik ten otrzyma 5...20 pkt. żywotności. Jeśli jeden z tych przeciwników zginie podczas działania Krwawych Więzów, wszyscy sojusznicy w jego bezpośrednim sąsiedztwie odzyskają 20...100 pkt. żywotności.','Klątwa zostaje także rzucona na wrogów w bezpośrednim sąsiedztwie celu (3...12 sek.). Sojusznicy trafiający w tych wrogów otrzymują 5...20 pkt. żywotności. Jeśli któryś z tych wrogów zginie podczas działania klątwy, sąsiadujący z nim sojusznicy odzyskają 20...100 pkt. żywotności.'],
836=>['Skok Błyskawicy','Błyskawicznie skaczesz do wybranego przeciwnika. Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza, ale powoduje wyczerpanie.','Zadaje 10...70 pkt. obrażeń od błyskawic. 25% przebicie pancerza. Natychmiast ruszasz do tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
837=>['Dar Energii','Przez 20 sek. twoja maksymalna energia zwiększa się o +1...12 pkt. oraz otrzymujesz regenrację żyworności +5. Gdy Dar Energii przestanie działać zyskujesz +1...3 pkt. energii oraz 1...3 pkt. żywotności.','(20 sek.) Twoja maksymalna energia zwiększa się o +1...12 pkt. Otrzymujesz regenerację żyworności +5. Efekt końcowy: otrzymujesz 36...60 pkt. energii oraz 1...3 pkt. żywotności.'],
838=>['Smutek Dwayny','Przez 30 sek. wybrany sojusznik i wszyscy sojusznicy w pobliżu będą pod działaniem Smutku Dwayny. Jeśli zginie sojusznik będący pod działaniem Smutku Dwayny, to każdy członek drużyny otrzymuje 5...50 pkt. żywotności.','Zaklęcie działa także na sojuszników w pobliżu twojego celu (30 sek.). Twoja drużyna otrzymuje 5...50 pkt. żywotności, kiedy jeden z tych sojuszników zginie.'],
839=>['"Wycofać Się!"','Jeśli w zasięgu słuchu znajdują się martwi sojusznicy, to przez 5...11 sek. twoja drużyna porusza się o 33% szybciej.','(5...11 sek.) Członkowie drużyny w zasięgu słuchu poruszają się o 33% szybciej. Bez efektu, chyba że w zasięgu słuchu są martwi sojusznicy.'],
840=>['Zatrute Serce','Ty oraz wszyscy znajdujący się przy tobie przeciwnicy zostajecie zatruci na 5...15 sek.','Wywołuje zatrucie (5...15 sek.) u sąsiadujących z tobą przeciwników. Ty również ulegasz zatruciu.'],
841=>['Cuchnąca Ziemia','Wybrany przeciwnik otrzymuje 15...65 pkt. obrażeń od zimna. Jeśli ten przeciwnik jest powalony, zostaje on zatruty na 5...20 sek.','Zadaje 15...65 pkt. obrażeń od zimna. Wywołuje przypadłość zatrucie (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
842=>['Błyskawica Łukowa','Wybrany przeciwnik otrzymuje 5...40 pkt. obrażeń od elektryczności. Jeśli jesteś pod wpływem Przemagicznienia, dwóch przeciwników w pobliżu twojego celu zostanie uderzonych przez piorun za 15...85 pkt. obrażeń od elektryczności. Obrażenia od Błyskawicy Łukowej mają 25% penetracji pancerza.','Zadaje 5...40 pkt. obrażeń od elektryczności. Zadaje 5...40 pkt. obrażeń od elektryczności dwóm przeciwnikom w pobliżu celu podczas Przemagicznienia. 25% penetracji pancerza.'],
843=>['Poryw Wiatru','Przez 5...11 sek. ty i wskazany sojusznik poruszacie się 33% szybciej. Gdy rzucasz to zaklęcie, wszyscy sąsiadujący z tobą i wskazanym sojusznikiem przeciwnicy odnoszą 15...70 pkt. obrażeń od zimna. Wrogowie trafieni Porywem Wiatru podczas atakowania lub poruszania się są powalani.','(5...11 sek.). Ty i wskazany sojusznik poruszacie się 33% szybciej. Początkowy efekt: wrogowie sąsiadujący z tobą lub wskazanym sojusznikiem odnoszą 15...70 pkt. obrażeń od zimna. Atakujący lub poruszający się wrogowie są powalani.'],
844=>['Wzburzona Ziemia','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Wzburzoną Ziemię. Przez następne 5 sek., co sekundę, Wzburzona Ziemia zadaje przeciwnikom w pobliżu tego miejsca po 10...40 pkt. obrażeń od ziemi. Każdy, poruszający się szybciej niż normalnie, przeciwnik na obszarze Wzburzonej Ziemi zostaje powalony.','W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca celu. Powala przeciwników, którzy się poruszają szybciej niż normalnie.'],
845=>['Płynny Płomień','Wybrany przeciwnik otrzymuje 7...112 pkt. obrażeń od ognia. Jeżeli przeciwnik ten atakuje lub rzuca czar, wszyscy przeciwnicy w pobliżu także otrzymują po 7...112 pkt. obrażeń od ognia.','Zadaje 7...112 pkt. obrażeń od ognia. Przeciwnikom w pobliżu twojego celu zadaje 7...112 pkt. obrażeń od ognia, jeżeli ten przeciwnik atakuje lub rzuca czar.'],
846=>['Para','Wybrany przeciwnik otrzymuje 20...60 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik płonie, para oślepia go na 5...10 sek. i zadaje mu dodatkowe 20...60 pkt. obrażeń od ognia.','Zadaje 20...60 pkt. obrażeń od zimna. Powoduje oślepienie (5...10 sek.) i zadaje 20...60 pkt. obrażeń od ognia, jeżeli wybrany przeciwnik płonie.'],
847=>['Sygnet Daru','Uzdrawiasz wybranego sojusznika dodając mu 20...80 pkt. żywotności. Twój następny czar z Modlitw Uzdrawiających lub Ochronnych, który rzucany jest na sojusznika, dodaje dodatkowe 20...100 pkt. żywotności.','Dodaje 20...80 pkt. żywotności. Twój następny czar z Modlitw Uzdrawiających lub Ochronnych, który rzucany jest na sojusznika, dodaje +20...100 pkt. żywotności.'],
848=>['Odwrócenie Klątwy','Usuwasz z wybranego sojusznika jedną klątwę. Jeśli doszło w ten sposób do usunięcia klątwy, to kiedy przez 5...10 sek. wybrany sojusznik miałby otrzymać obrażenia, zostaną one zmniejszane o 5...50 pkt.','(5...10 sek.) Z wybranego sojusznika usuwa jedną klątwę. Następne obrażenia, jakie ten sojusznik otrzyma zostaną zmniejszone o 5...50 pkt. Bez efektu, chyba że ten sojusznik jest pod wpływem klątwy.'],
849=>['Rozdzierające Cięcie','Jeśli Rozdzierające Cięcie trafi, zadajesz +5...20 pkt. obrażeń. Jeśli trafi powalonego przeciwnika, twój cel zaczynie krwawić przez 5...20 sek.','Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
850=>['Wściekły Cios','Jeżeli Wściekły Atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli cel jest pod działaniem osłabienia, to na 1...8 sek. otrzymuje także głęboką ranę.','Zadaje +5...20 pkt. obrażeń. Powoduje powstanie głębokiej rany (1...8 sek.), jeżeli wybrany przeciwnik jest osłabiony.'],
851=>['Cięcie Słońca i Księżyca','Atakujesz wybranego przeciwnika dwa razy. Ataki te nie mogą zostać zablokowane.','Wybranego przeciwnika atakujesz dwa razy. Nie do zablokowania.'],
852=>['Strzał Rozpryskowy','Jeśli Strzał Rozpryskowy trafi, zadajesz +3...15 pkt. obrażeń. Jeśli Strzał Rozpryskowy zostanie zablokowany, wszyscy przeciwnicy w pobliżu celu otrzymają 5...65 pkt. obrażeń.','Zadaje +3...15 pkt. obrażeń. Zadaje 5...65 pkt, obrażeń przeciwnikom w pobliżu, jeśli atak zostanie zablokowany.'],
853=>['Strzał Melandru','Jeśli Strzał Melandru trafi, przeciwnik zaczyna krwawić przez 5...25 sek. Jeśli trafiony zostanie powalony lub poruszający się przeciwnik , to otrzyma +10...25 pkt. obrażeń i będzie okulawiony przez 5...15 sek.','Wywołuje krwawienie (5...25 sek.). Zadaje +10...25 pkt. obrażeń oraz powoduje okulawienie (5...15 sek.), jeżeli twój cel się porusza lub jest powalony.'],
854=>['Sidła','Kiedy Sidła zadziałają, wszyscy przeciwnicy w pobliżu zostaną okulawieni na 3...15 sek. Sidła przestają działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. Wywołuje przypadłość okulawienie (3...15 sek.). Łatwo przerwać.'],
858=>['Tańczące Sztylety','Wyślij trzy Tańczące Sztylety, z których każdy, jeżeli trafi, zadaje wybranemu przeciwnikowi 5...35 pkt. obrażeń od ziemi. Tańczące Sztylety posiadają zasięg dwa razy mniejszy niż zwykły czar. Ta umiejętność liczy się jako atak poprzedzający.','Trzy pociski: każdy zadaje 5...35 pkt. obrażeń od ziemi. Traktuje się jako atak poprzedzający.'],
859=>['Przyzwanie Nocnej Zmory','Przez 2...16 sek., wybrany przeciwnik posiada degenerację żywotności -8.','(2...16 sek.) Powoduje degenerację żywotności -8.'],
860=>['Sygnet Przerwania','Jeśli cel rzuca właśnie czar, zostaje on przerwany, a cel otrzymuje 10...51 pkt. obrażeń. Jeśli dany cel jest przeklęty, Sygnet Przerwania może przerwać wszystkie umiejętności poza czarami.','Przerywa rzucenie czaru. Może przerwać dowolną umiejętność, jeżeli cel jest przeklęty. Skutek przerwania: zadaje 10...51 pkt. obrażeń.'],
862=>['Chciwe Spojrzenie','Zadaje 20...40 pkt. obrażeń i wykrada 20...40 pkt. żywotności wyrbanemu wrogowi i wszystkim przeciwnikom w pobliżu.','Zadaje 20...40 pkt. obrażeń i wykrada 20...40 pkt. żywotności wybranemu wrogowi i wszystkim przeciwnikom w pobliżu.'],
863=>['Rozkaz Apostazji','Przez 5 sek., za każdym razem, kiedy członek drużyny trafi przeciwnika zadając obrażenia fizyczne, ten przeciwnik traci jedno zaklęcie. Za każde zdjęte zaklęcie mnicha, tracisz 10...3% maksymalnych pkt. żywotności.','Zaklina wszystkich członków drużyny (5 sek.). Ci członkowie drużyny usuwają po jednym zaklęciu, kiedy zadają fizyczne obrażenia. Koszt usunięcia: za każde zaklęcie mnicha, tracisz 10...3% maksymalnych punktów żywotności.'],
864=>['Gnębiące Spojrzenie','Wybrany przeciwnik oraz sąsiadujący z nim wrogowie otrzymują 10...30 pkt. obrażeń od cienia. Wrogowie cierpiący już na jakąś przypadłość zostają otruci oraz osłabieni na 3...12 sek.','Zadaje 10...30 pkt. obrażeń celowi i sąsiadującym przeciwnikom. Wywołuje zatrucie i osłabienie (3...12 sek.) u wrogów cierpiących na jakąś przypadłość.'],
865=>['Młot Błyskawic','Wybrany przeciwnik otrzymuje 10...100 pkt. obrażeń od elektryczności a jego zbroja pęka na 5...20 sek. Młot Błyskawic ma 25% penetrację pancerza.','Zadaje 10...100 pkt. obrażeń od elektryczności. Wywołuje przypadłość pęknięta zbroja (5...20 sek.). 25% penetracji pancerza.'],
866=>['Mgliste Ostrze','Wybrany przeciwnik otrzymuje 15...135 pkt. obrażeń od zimna. Mgliste Ostrze zadaje połowę obrażeń, jeżeli ten przeciwnik ma na sobie jakieś zaklęcia.','Zadaje 15...135 pkt. obrażeń od zimna. Połowa obrażeń, jeżeli wybrany przeciwnik ma na sobie zaklęcie.'],
867=>['Uzdrawiające Światło','Uzdrawiasz wybranego sojusznika dodając mu 40...120 pkt. żywotności. Jeśli cel ma na sobie zaklęcie, to otrzymujesz 1...3 pkt. energii.','Dodaje 40...120 pkt. żywotności. Otrzymujesz 1...3 pkt. energii, jeżeli wybrany sojusznik jest pod działaniem zaklęcia.'],
869=>['"Tchórz!"','Jeśli przeciwnik się porusza, zostaje powalony.','Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
870=>['Zaraza','Tworzysz 1...10 poziomowego ducha. Jeśli w jego zasięgu zginie jakieś stworzenie nie-duch, to przypadłości tego stworzenia przenoszą się na inne stworzenie w okolicy będące już pod działaniem przypadłości. Duch ginie po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Jeśli w jego zasięgu zginie jakieś stworzenie, to przypadłości tego stworzenia przenoszą się na inne stworzenia w okolicy będące już pod działaniem przypadłości. Nie działa na duchy.'],
871=>['Pieśń Cienia','Tworzy ducha o poziomie 1...10. Ataki ducha zadają 5...20 pkt. obrażeń i powodują ślepotę przez 1...6 sek. Duch umiera po 30 sekundach.','Tworzy ducha o poziomie 1...10 (długość życia: 30 sek.). Jego ataki zadają 5...20 pkt. obrażeń i powodują ślepotę (1...6 sek.).'],
876=>['Sygnet Cienia','Wybrany przeciwnik otrzymuje 5...35 pkt. obrażeń. Jeżeli ten przeciwnik był oślepiony, zdajesz dodatkowe 15...60 pkt. obrażeń.','Zadaje 5...35 pkt. obrażeń. Zadaje 15...60 pkt. dodatkowych obrażeń, jeżeli cel jest oślepiony.'],
877=>['Równowaga Lyssy','Wybrany przeciwnik traci 1 zaklęcie. Jeżeli posiadasz więcej zaklęć niż wybrany przeciwnik, umiejętność nie daje żadnego efektu.','Z wybranego przeciwnika zdejmuje jedno zaklęcie. Bez efektu, jeżeli masz więcej zaklęć niż ten przeciwnik.'],
878=>['Wizje Żalu','Przez 10 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu otrzymują 15...45 pkt. obrażeń za każdym razem, kiedy użyją umiejętności oraz 5...50 pkt. dodatkowych obrażeń jeśli nie znajdują się pod wpływem innej klątwy mesmera.','Klątwa działa także na przeciwników bezpośrednio przy celu (10 sek.) Przeciwnicy ci otrzymują 15...45 pkt. obrażeń za każdym razem, kiedy użyją umiejętności oraz 5...50 pkt. dodatkowych obrażeń jeśli nie znajdują się pod wpływem innej klątwy mesmera.'],
879=>['Iluzja Bólu','Przez 8 sek., wybrany przeciwnik ma degenerację żywotności -3...10 oraz otrzymuje co sekundę 3...10 pkt. obrażeń. Kiedy Iluzja Bólu dobiega końca, wybrany przeciwnik odzyskuje 36...120 pkt. żywotności.','(8 sek.) Powoduje degenerację żywotności -3...10 u wybranego przeciwnika, który dodatkowo otrzymuje co sekundę 3...10 pkt. obrażeń. Efekt końcowy: wybrany przeciwnik odzyskuje 36...120 pkt. żywotności.'],
880=>['Skradziona Szybkość','Przez 1...10 sek., cel i wszyscy pobliscy przeciwnicy rzucają czary 100% dłużej. Twoje lub sojusznicze czary wycelowane w tych przeciwników rzucane są 50% szybciej.','Klątwa działa także na wrogów w bezpośrednim sąsiedztwie (1...10 sek.). Podwaja czas rzucania czarów. Twoje lub sojusznicze czary wycelowane w przeciwników pod działaniem klątwy, rzucane są 50% szybciej.'],
881=>['Eteryczny Sygnet','Jeżeli masz mniej niż 5...10 pkt. energii, zyskujesz 10...20 pkt. energii.','Otrzymujesz 10...20 pkt. energii. Bez efektu, chyba że masz mniej niż 5...10 pkt. energii.'],
882=>['Sygnet Antyzaklęcia','Tracisz całą energię. Wybrany przeciwnik traci jedno zaklęcie.','Usuwa jedno zaklęcie. Tracisz całą energię.'],
883=>['Odebranie Głosu','Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu nie mogą używać okrzyków ani pieśni.','Klątwa działa także na przeciwników w pobliżu celu (5...20 sek.). Ci przeciwnicy nie mogą używać okrzyków ani zaśpiewów.'],
884=>['Wypalające Płomienie','Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu padają ofiarą Wypalających Płomieni. Przeciwnicy płonący w momencie, kiedy zostanie użyta ta umiejętność otrzymują po 10...100 pkt. obrażeń od ognia. Pozostali zaczynają płonąć na 1...7 sek.','Trafia przeciwników w pobliżu twojego celu. Przeciwnikom, którzy płoną zadaje po 10...100 pkt. obrażeń od ognia. U przeciwników, którzy nie płoną, wywołuje przypadłość płonięcie (1...7 sek.).'],
885=>['Uzdrawiający Strażnik','Przez 2...6 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 75% szans na blokowanie ataków. Jeśli atak zostanie zablokowany, wszyscy sojusznicy w zasięgu słuchu odzyskują 10...40 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.','(2...6 sek.) Członkowie drużyny w zasięgu słuchu mają 75% szans na zablokowanie ataków. Efekt zablokowania: Sojusznicy w zasięgu słuchu odzyskują 10...40 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.'],
886=>['Kojąca Bryza','Przez 8...18 sek. wybrany sojusznik posiada regenerację żywotności +10. To zaklęcie przestanie działać, kiedy sojusznik wykona atak lub użyje umiejętności.','(8...18 sek.) Regeneracja żywotności +10. Przestanie działać, jeśli wybrany sojusznik zaatakuje lub użyje umiejętności.'],
887=>['Sygnet Odmłodzenia','Uzdrawiasz wybranego sojusznika dodając mu 15...75 pkt. żywotności. Jeśli wybrany sojusznik rzuca czar lub atakuje, otrzymuje dodatkowe 15...75 pkt. żywotności.','Dodaje 15...75 pkt. żywotności. Dodaje dodatkowo 15...75 pkt. żywotności, jeżeli wybrany sojusznik atakuje lub rzuca czar.'],
888=>['Wirujący Topór','Jeśli Wirujący Topór trafi, zadajesz +5...20 pkt. obrażeń i dodatkowo przestają działać wszystkie postawy, pod których działaniem był twój cel. Tego ataku nie można zablokować.','Zadaje +5...20 pkt. obrażeń i wyłącza postawy. Nie do zablokowania.'],
889=>['Mocny Cios','Jeśli Mocny Cios trafi, zadajesz +10...30 pkt. obrażeń, a postawa bojowa używana przez zaatakowanego przeciwnika przestaje działać. Przeciwnik zostaje osłabiony na 5...20 sek. Ten atak nie może zostać zablokowany.','Zadaje +10...30 pkt. obrażeń. Usuwa postawę przeciwnika. Wywołuje osłabienie (5...20 sek.). Nie do zablokowania.'],
891=>['"Nikt Nie Przejdzie!"','Wszyscy pobliscy wrogowie, którzy się poruszają, zostają powaleni. Umiejętność ta odnawia się 1...8 sek. szybciej za każdego powalonego wroga (maksymalnie 25 sek.).','Powala wszystkich poruszających się wrogów, którzy znajdują się w pobliżu. Odnawia się 1...8 sek. szybciej za każdego powalonego w ten sposób wroga (maksymalnie 25 sek.).'],
892=>['Drżące Ostrze','Jeśli Drżące Ostrze trafi, zadajesz +10...40 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwka, zostanie on oszołomiony na 10 sek.','Zadaje +10...40 pkt. obrażeń. Wywołuje przypadłość oszołomienie (10 sek.), jeżeli cel się poruszał.'],
893=>['Poszukujące Strzały','Przez 3...14 sek., twoich strzał nie można zablokować. Poszukujące Strzały przestaną działać, kiedy nie trafisz.','(3...14 sek.) Twoich strzał nie można blokować. Przestanie działać, jeśli nie trafisz.'],
898=>['Przeciążenie','Przez 5 sek., wybrany wróg otrzymuje -1...3 pkt. degeneracji żywotności. Jeśli wybrany przeciwnik używa jakiejś umiejętności, Przeciążenie zadaje mu 15...75 pkt. obrażeń, a wszystkim wrogom w jego bezpośrednim sąsiedztwie 75% tych obrażeń.','(5 sek.). Powoduje degenerację żywotności -1...3. Jeśli wybrany przeciwnik używa umiejętności, odnosi 15...75 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują 75% tych obrażeń.'],
899=>['Wizje Skruchy','Przez 5...10 sek., wybrany przeciwnik cierpi -1...3 degeneracji żywotności. Jeżeli ten przeciwnik atakował, to otrzymuje 10...52 pkt. obrażeń.','(5...10 sek.) Powoduje degenerację żywotności -1...3. Efekt początkowy: 10...52 pkt. obrażeń, jeżeli wybrany przeciwnik atakuje.'],
900=>['Wspólne Brzemię','Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy na obszarze ataku rzucają zaklęcia i poruszają się o 50% wolniej.','Klątwa działa także na przeciwników w pobliżu twojego celu (5...20 sek.). Ci przeciwnicy atakują, rzucają zaklęcia i poruszają się o 50% wolniej.'],
901=>['Spętanie Duszy','Przez 30 sek. za każdym razem, kiedy wybrany przeciwnik otrzyma punkty żywotności, uzdrawiający otrzyma 20...80 pkt. obrażeń. Ta klątwa przestanie działać, kiedy na cel zostanie rzucona klątwa z Modlitw Ofensywnych.','(30 sek.) Za każdym razem, kiedy wybrany przeciwnik otrzyma punkty żywotności, uzdrawiający otrzyma 20...80 pkt. obrażeń. Koniec, kiedy na cel zostanie rzucona klątwa z Modlitw Ofensywnych.'],
902=>['Krew Napastnika','Wykradasz do 5...45 pkt. żywotności wybranemu przeciwnikowi. Jeśli przeciwnik ten wykonywał atak, zostaje osłabiony na 3...12 sek.','Wykrada 5...45 pkt. żywotności. Powoduje osłabienie (3...12 sek.), jeśli cel atakował.'],
903=>['Lodowy Pryzmat','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń od zimna. Jeśli przeciwnik jest pod działaniem klątwy Magii Wody, Lodowy Pryzmat zadaje +15...75 obrażeń od zimna wszystkim pobliskim przeciwnikom.','Zadaje 15...75 pkt. obrażeń od zimna. zadaje +15...75 obrażeń od zimna wszystkim pobliskim przeciwnikom, jeśli cel jest pod działaniem zaklęcia Magii Wody.'],
904=>['Wściekły Topór','Jeśli Wściekły Topór trafi, zadajesz +5...35 pkt. obrażeń. Jeśli przeciwnik zablokuje atak, to otrzymujesz 3 dawki adrenaliny.','Zadaje +5...35 pkt. obrażeń. Dodaje ci 3 dawki adrenaliny, jeśli zostanie zablokowana.'],
905=>['Skuteczne Uderzenie','Jeśli Skuteczne Uderzenie trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz 3...8 pkt. energii. Jeśli przeciwnik był osłabiony, ataku tego nie można zablokować.','Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz 3...8 pkt. energii. Nie do zablokowania, jeżeli wybrany przeciwnik jest osłabiony.'],
906=>['"Na Kolana!"','Tracisz całą adrenalinę. Jeśli jeden z przeciwników bezpośrednio przy tobie jest powalony, wszystkie twoje postawy zostają automatycznie odnowione.','Automatycznie odnawia twoje postawy, jeżeli jesteś w bezpośredniej odległości od powalonego przeciwnika. Tracisz całą adrenalinę.'],
907=>['Smocze Cięcie','Jeśli Smocze Cięcie trafi, zadajesz +10...40 pkt. obrażeń i otrzymujesz dawki adrenaliny w liczbie 1...5.','Zadaje +10...40 pkt. obrażeń. Jeżeli trafisz, otrzymujesz adrenalinę w liczbie dawek: 1...5.'],
908=>['Strzał Bandyty','Jeśli Strzał Bandyty trafi, zadajesz +25...55 pkt. obrażeń i wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek.','Zadaje +25...55 pkt. obrażeń. Wszystkie twoje umiejętności nie związane z atakami są wyłączone (5 sek.), jeżeli ten atak trafi.'],
909=>['Strzał w Skupieniu','This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Duchowa Rozpadlina','Otwiera duchową szczelinę w miejscu pobytu wroga. Po 3 sek., wszyscy przeciwnicy w bezpośrednim sąsiedztwie otrzymują 25...125 pkt. obrażeń od błyskawic oraz przez 1...20 sek. znajdą się pod działaniem Pękniętej Zbroi.','(3 sek.) Działa na przeciwników w bezpośrednim sąsiedztwie początkowej lokacji wybranego wroga. Zadaje 25...125 pkt. obrażeń od błyskawic i powoduje pęknięcie zbroi (1...20 sek.)'],
911=>['Przymierze','Tworzysz 1...12 poziomowego ducha. Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty zostają zmniejszone o 15 pkt., a duch otrzymuje 15 pkt. obrażeń. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty te zostają zmniejszone o 15, a duch otrzymuje 15 pkt. obrażeń.'],
913=>['Cichym Był Tanasen','Trzymaj prochy Tanasena przez maksymalnie 5...20 sek. Trzymając jego prochy, zyskujesz +10...25 pkt. pancerza, a twoje czynności nie mogą zostać przerwane.','(5...20 sek.) Posiadasz +10...25 pkt. pancerza. Twoje czynności nie mogą zostać przerwane.'],
914=>['Pożarcie Duszy','Wykradasz 5...70 pkt. żywotności od wybranego przeciwnika. Wszystkie wrogie przywołane stworzenia w pobliżu przeciwnika otrzymują 25...125 pkt. obrażeń.','Wykrada 5...70 pkt. żywotności. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w pobliżu wybranego przeciwnika.'],
915=>['Duchowe Światło','Wybrany sojusznik zostaje uleczony, otrzymując 60...180 pkt. żywotności. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, nie poświęcasz żywotności.','Dodaje 60...180 pkt. żywotności. Nie poświęcasz żywotności, jeżeli jesteś w zasięgu słuchu ducha.'],
916=>['Opłakiwanie','Przez 5...20 sek., wybrany przeciwnik i wszyscy wrogowie znajdujący się w pobliżu cierpią na degenerację żywotności 0...3. Jeśli w momencie nałożenia klątwy znajdujesz się w zasięgu słuchu od zwłok lub ducha, wrogowie otrzymują dodatkowo 10...50 pkt. obrażeń.','Nakłada klątwę także na wrogów w pobliżu celu (5...20 sek.). Powoduje degenerację żywotności na poziomie 0...3. Efekt początkowy: zadaje 10...50 pkt/ obrażeń, jeśli znajdujesz się w zasięgu słuchu od zwłok lub ducha.'],
917=>['Rozerwanie Duszy','Wybrany sojuszniczy duch zostaje zniszczony. Wszyscy przeciwnicy w pobliżu otrzymują 50...140 pkt. obrażeń od błyskawic oraz zostają oślepieni na 3...12 sek.','Niszczy wybranego sojuszniczego ducha. Przeciwnikom w pobliżu zadaje po 50...140 pkt. obrażeń od błyskawic i wywołuje u nich przypadłość oślepienie (3...12 sek.).'],
918=>['Duch Ciałem Się Staje','Wybrany dotknięty sojuszniczy duch zostaje zniszczony. Wszyscy sojusznicy w pobliżu otrzymują 30...240 pkt. żywotności.','Niszczy wybranego dotkniętego sojuszniczego ducha. Sojusznikom w pobliżu dodaje po 30...240 pkt. żywotności.'],
919=>['Duchowy Płomień','Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu jest jakiś duch, Duchowy Płomień podpali przeciwnika na 1...5 sek.','Zadaje 5...50 pkt. obrażeń od błyskawic. Powoduje płonięcie (1...5 sek.), jeżeli w zasięgu słuchu znajduje się duch.'],
920=>['Zniszczenie','Tworzysz ducha na poziomie 1...14, który ginie po 30 sek. Gdy duch ten zginie, wszyscy przeciwnicy w okolicy otrzymują 5...25 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).','Tworzysz ducha na poziomie 1...14, który ginie po 30 sek. Gdy duch ten zginie, wszyscy przeciwnicy w okolicy otrzymują 5...25 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).'],
921=>['Dysonans','Tworzysz 1...12 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a czynność każdego kto otrzyma od niego obrażenia, zostaje przerwana. Duch ginie po 10...25 sek.','Tworzy ducha na poziomie 1...12 (czas życia 10...25 sek.). Jego ataki zadają 5...20 pkt. obrażeń i przerywają czynności.'],
923=>['Antyzaklęcie','Tworzysz 1...12 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a każdy kto otrzyma od niego obrażenia, traci jedno zaklęcie. Duch ginie po 10...35 sek.','Tworzy ducha na poziomie 1...12 (czas życia 10...35 sek.). Jego ataki zadają 5...20 pkt. obrażeń i usuwają zaklęcie.'],
925=>['Przywołanie','Tak długo jak utrzymujesz Przywołanie, nic się nie dzieje. Gdy Przywołanie przestanie działać, wykonujesz krok cienia do sojusznika, którego miałeś na celu aktywując tę umiejętność, a wszystkie twoje umiejętności będą niedostępne przez 3 sek.','Efekt końcowy: wykonujesz krok cienia do wybranego sojusznika. Na cel nie można wybrać siebie i kiedy przestanie działać wyłącza wszystkie twoje umiejętności na 3 sek.'],
926=>['Ostre Sztylety','Przez 5...30 sek., ataki twojego zwierzęcego towarzysza wywołują zatrucie na 5...15 sek.','(5...30 sek.) Twoje ataki sztyletem wywołują krwawienie (5...15 sek.).'],
927=>['Haniebny Strach','Przez 10 sek., wybrany przeciwnik porusza się 10% szybciej niż normalnie. Co sekundę, jeżeli ten przeciwnik się porusza, to otrzymuje on 5...20 pkt. obrażeń.','(10 sek.) Wybrany przeciwnik porusza się o 10% szybciej, ale w każdej sekundzie otrzymuje 5...20 pkt. obrażeń, jeżeli jest w ruchu.'],
928=>['Całun Cienia','Przez 3...9 sek. wybrany przeciwnik nie może być celem zaklęć.','(3...9 sek.) Wybrany przeciwnik nie może być celem zaklęć.'],
929=>['Cień Pośpiechu','Przez 10...40 sek. poruszasz się o 15% szybciej. Gdy Cień Pośpiechu przestanie działać, wykonujesz krok cienia do miejsca, gdzie umiejętność została użyta.','(10...40 sek.) Poruszasz się o 15% szybciej. Efekt końcowy: wracasz do swojego początkowego miejsca.'],
930=>['Inkantacja Pomyślności','Przez 20 sek., następny czar, który rzucisz będzie niedostępny przez dodatkowe 10...5 sek., a ty otrzymasz 110...200% energetycznego kosztu tego czaru.','(20 sek.) Twój następny czar daje ci 110...200% swojego energetycznego kosztu. Ten czar odnawia się o dodatkowe 10...5 sek. dłużej.'],
931=>['Przywrócenie Mocy','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel otrzymuje 10...5 pkt. energii.','Przerywa użycie czaru lub pieśni. Skutek przerwania: cel otrzymuje 10...5 pkt. energii.'],
932=>['Komplikacja','Jeśli wybrany wróg używa jakiejś umiejętności, to jej działanie zostaje przerwane, zaś sama umiejętność staje się niedostępna na dodatkowe 5...12 sek. dla tego wroga i wszystkich przeciwników w okolicy.','Przerywa umiejętność. Efekt przerwania: wyłącza przerwaną umiejętność (+25...12 sek.) u wybranego wroga i wszystkich przeciwników na danym obszarze.'],
933=>['Burza Rozproszenia','Wybrany przeciwnik traci wszystkie zaklęcia. Za każde zaklęcie zdjęte w ten sposób, Burza Rozproszenia zostaje wyłączona na dodatkowe 7 sek.','Usuwa wszystkie zaklęcia. Koszt usunięcia: Burza Rozproszenia jest niedostępna przez +7 sek. za każde zdjęte zaklęcie.'],
934=>['Nienaturalny Sygnet','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeśli jest on pod działaniem klątwy lub zaklęcia, przeciwnicy w bezpośrednim sąsiedztwie celu otrzymują 5...50 pkt. obrażeń.','Zadaje 15...75 pkt. obrażeń. Zadaje 5...50 pkt. obrażeń innym wrogom w sąsiedztwie, jeśli cel jest pod działaniem klątwy lub zaklęcia.'],
935=>['Wzbierająca Żółć','Przez 20 sek. klątwa ta nic nie robi. Gdy Wzbierająca Żółć przestanie działać, wybrany przeciwnik i wszyscy przeciwnicy w okolicy otrzymają po 1...6 pkt. obrażeń za każdą sekundę działania Wzbierającej Żółci.','(20 sek.) Efekt końcowy: zadaje 1...6 pkt. obrażeń za każdą sekundę, w której Wzbierająca Żółć była aktywna. Działa także na innych przeciwników w okolicy.'],
936=>['Zatruwające Zaklęcia','Wybrany przeciwnik traci jedno zaklęcie. Na każde pozostałe zaklęcie, wybrany przeciwnik zostaje zatruty na 3...10 sek.','Z wybranego przeciwnika usuwa jedno zaklęcie. Wywołuje przypadłość zatrucie (3...10 sek. za każde pozostałe zaklęcie na tym przeciwniku).'],
937=>['Fala Uderzeniowa','Przeciwnicy w kontakcie otrzymują 15...60 pkt. obrażeń od ziemi, przeciwnicy w pobliżu otrzymują 15...60 pkt. obrażeń od ziemi, a przeciwnicy w okolicy otrzymują 15...60 pkt. obrażeń od ziemi.','Przeciwnikom w okolicy zadaje po 15...60 pkt. obrażeń od ziemi. Przeciwnicy w pobliżu otrzymują obrażenia dwa razy, przeciwnicy w bezpośredniej odległości otrzymują obrażenia trzy razy.'],
938=>['Ochrona przed Powaleniem','W miejscu, w którym przebywasz, tworzysz Ochronę przed Powaleniem. Przez 10...25 sek. sojusznicy nie-duchy nie mogą zostać powaleni.','(10...25 sek.) Sojusznicy w granicach tej ochrony nie mogą zostać powaleni. Nie działa na sojusznicze duchy.'],
939=>['Lodowe Kajdany','Przez 1...10 sek. szybkość ruchu wybranego przeciwnika jest obniżona o 66% za każde zaklęcie, pod którego działaniem się znajduje. Jeżeli przeciwnik jest pod wpływem zaklęcia, jego ruch zostaje spowolniony o 90%.','(1...10 sek.) Wybrany przeciwnik porusza się o 66% wolniej. Ten przeciwnik porusza się o 90% wolniej, jeżeli jest pod działaniem zaklęcia.'],
941=>['Błogosławione Światło','Uzdrawiasz wybranego sojusznika dodając mu 10...120 pkt. żywotności i zdejmujesz z niego po jednej klątwie i przypadłości.','Dodaje 10...120 pkt. żywotności. Usuwa jedną przypadłość i jedną klątwę.'],
942=>['Wycofanie Klątw','Usuwa wszystkie klątwy z wybranego sojusznika i wszystkich sojuszników bezpośrednio przy nim. Za każdą usuniętą w ten sposób klątwę, czar będzie się odnawiał o 2 sek. dłużej. (50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 4 lub mniej).','Usuwa wszystkie klątwy. Działa także na sąsiadujących sojuszników. Koszt usunięcia: +2 sek. do czasu odnawiania za każda usuniętą klątwę. 50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 5 lub więcej.'],
943=>['Ugaszenie','Z każdego członka drużyny usuwasz po jednej przypadłości. Członkowie drużyny, którzy w ten sposób zostali uwolnieni od płonięcia, otrzymują po 10...100 pkt. żywotności.','Działa na wszystkich członków drużyny. Usuwa przypadłość. Członkowie drużyny uwolnieni od płonięcia otrzymują po 10...100 pkt. żywotności.'],
944=>['Sygnet Siły','Twoje kolejne ataki w liczbie 1...16 zadają +5 pkt. obrażeń każdy.','Twoje ataki zadają +5 pkt. obrażeń. Koniec po 1...16 atakach.'],
946=>['Skupienie Trapera','Przez 12...36 sek. nie będzie ci łatwo przerwać, kiedy będziesz używał umiejętności związanych z ustawianiem pułapek. Atrybut Przetrwanie w Dziczy zwiększa się o 0...4.','(12...36 sek.) Twoje umiejętności związane z pułapkami nie są już łatwe do przerwania. Otrzymujesz +0...4 do atrybutu Przetrwanie w Dziczy.'],
947=>['Ciernie','Tworzysz 1...10 poziomowego ducha. Każde stworzenie nie-duch, które zostanie powalone w jego zasięgu otrzyma 5 pkt. obrażeń i będzie krwawić przez 5...20 sek. Ten duch ginie po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Powalone stworzenia otrzymują po 5 pkt. obrażeń i zaczynają krwawić (5...20 sek.). Nie działa na duchy.'],
948=>['Desperackie Uderzenie','Jeżeli masz mniej niż 50...80% pkt. żywotności, zadajesz +15...60 pkt. obrażeń.','Zadaje +15...60 pkt. obrażeń, jeżeli posiadasz mniej niż 50...80% żywotności.'],
949=>['Ścieżka Lisa','Przez 10...35 sek., twoich kolejnych 1...6 ataków nie można zablokować','(10...35 sek.) Twoich ataków nie można blokować. Koniec po 1...6 atakach.'],
950=>['Cieniste Brzemię','Przez 3...15 sek. wybrany przeciwnik porusza się o 25% wolniej i tak długo, jak nie ma na sobie innych klątw, posiada 20...30 pkt. pancerza mniej przeciwko twoim atakom.','(3...15 sek.) Wybrany przeciwnik porusza się o 25% wolniej i posiada 20...30 pkt. pancerza mniej przeciwko twoim atakom. Obniżenie pancerza działa na tego przeciwnika tylko, gdy nie jest on pod działaniem innych klątw.'],
951=>['Wyssanie Szybkości','Przez 5...15 sek. wybrany przeciwnik porusza się o 33% wolniej, a ty poruszasz się o 33% szybciej. Ten czar odnawia się o 50% szybciej, jeżeli został rzucony na poruszającego się przeciwnika.','(5...15 sek.) Wybrany przeciwnik porusza się o 33% wolniej, a ty poruszasz się o 33% szybciej. Odnowienie szybsze o 50%, jeżeli cel się poruszał.'],
952=>['Szarża Śmierci','Wykonaj krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik ma więcej pkt. żywotności niż ty, otrzymujesz 65...200 pkt. żywotności.','Wykonujesz krok cienia do wybranego przeciwnika. Otrzymujesz 65...200 pkt. żywotności, jeżeli ten przeciwnik ma więcej żywotności niż ty.'],
953=>['Strumień Energii','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a przez 4...10 sek. cel otrzymuje -2 do degeneracji energii.','Przerywa użycie czaru lub pieśni. Skutek przerwania: -2 do degeneracji energii (4...10 sek.).'],
954=>['Wypędzenie Klątw','Usuwasz z wybranego sojusznika do 2 klątw.','Z wybranego sojusznika usuwa dwie klątwy.'],
955=>['Rozdarcie Zaklęcia','Z wybranego przeciwnika zdejmujesz zaklęcia w liczbie 1. Jeżeli zaklęcie zostało zdjęte, przeciwnik ten przez 5...25 sek. będzie krwawił.','Usuwa zaklęcia w liczbie 1. Efekt usunięcia: wywołuje przypadłość krwawienie (5...25 sek.).'],
957=>['Tarcza Przeciw Czarom','Przez 5...20 sek., w momencie kiedy rzucasz czary, nie możesz być celem wrogich czarów. Kiedy Tarcza Przeciw Czarom przestanie działać, wszystkie twoje umiejętności będą niedostępne przez 8...4 sek.','(5...20 sek.) W momencie kiedy rzucasz czary, nie możesz być celem wrogich czarów. Efekt końcowy: twoje umiejętności są wyłączone (8...4 sek.).'],
958=>['Uzdrawiający Szept','Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 40...100 pkt. żywotności. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Dodaje 40...100 pkt. żywotności. Na cel nie można wybrać siebie.'],
959=>['Eteryczne Światło','Uzdrawiasz wybranego sojusznika dodając mu 25...100 pkt. żywotności. Jest to czar łatwy do przerwania.','Dodaje 25...100 pkt. żywotności. Łatwo przerwać.'],
960=>['Uwolnienie Zaklęć','Tracisz wszystkie zaklęcia. Za każde zaklęcie mnicha, które straciłeś, każdy członek drużyny otrzymuje 5...35 pkt. żywotności.','Usuwa wszystkie twoje zaklęcia. Za każde usunięte zaklęcie mnicha dodaje każdemu członkowi drużyny 5...35 pkt. żywotności.'],
961=>['Okaleczenie','Tworzysz 1...10 poziomowego ducha. Krwawiące stworzenia w jego zasięgu otrzymują degenerację żywotności -2. Kiedy duch umrze, wszystkie stworzenia nie-duchy w jego zasięgu posiadające mniej niż 90% żywotności będą krwawić przez 5...25 sek. Ten duch ginie po 30...240 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...240 sek.). Krwawiące stworzenia w zasięgu posiadają degenerację żywotności -2. Efekt końcowy: u stworzeń w zasięgu, które mają mniej niż 90% żywotności, wywołuje przypadłość krwawienie (5...25 sek.). Nie działa na duchy.'],
962=>['Duchowy Transfer','Najbliższy duch traci 5...50 pkt. żywotności. Wybrany sojusznik otrzymuje 5 pkt. żywotności za każdy stracony przez ducha pkt. żywotności.','Najbliższy duch traci 5...50 pkt. żywotności. Wybranemu sojusznikowi dodaje 5 pkt. żywotności za każdy stracony pkt. żywotności.'],
963=>['Odnowa','Tworzysz 1...14 poziomowego ducha. Gdy ten duch ginie, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 5...50% pkt. żywotności i z zerem pkt. energii. Ten duch ginie po 30 sek.','Tworzy ducha na poziomie 1...14 (czas życia 30 sek.). Efekt końcowy: wskrzesza martwych członków drużyny w okolicy (5...50% żywotności, 0 pkt. energii).'],
964=>['Mściwy Oręż','Przez 8 sek., następnym razem, kiedy wybrany sojusznik otrzyma cios lub zostanie mu wykradziona żywotność, to sojusznik ten wykrada przeciwnikowi do 15...60 pkt. żywotności.','(8 sek.) Wykrada 15...60 pkt. żywotności następnemu przeciwnikowi, kt&oacute;ry zada obrażenia lub wykradnie żytwotność wybranemu sojusznikowi.'],
973=>['Proszek Oślepiający','Musi nastąpić po ataku drugą ręką. Wybrany przeciwnik zostaje oślepiony na 3...15 sek.','Oślepia (3...15 sek.) wybranego przeciwnika i wszystkich przeciwników bezpośrednio przy nim. Musi nastąpić po ataku drugą ręką.'],
974=>['Dotyk Modliszki','Wybrany przeciwnik zostaje okulawiony na 5...20 sek. Ta umiejętność liczy się jako atak drugą ręką.','Powoduje okulawienie (5...20 sek.). Ta umiejętność traktowana jest jako atak drugą ręką.'],
975=>['Wyczerpujące Natarcie','Musi nastąpić po ataku poprzedzającym. Przerywa czynność celu. Jeśli przerwaną czynnością było rzucanie zaklęcia, cel otrzymuje 10 punktów Przemagicznienia.','Przerywa czynność przeciwnika. Powoduje 10 punktów Przemagicznienia, jeśli przerwaną czynnością było rzucenie zaklęcia. Musi nastąpić po ataku poprzedzającym.'],
976=>['Powtarzające się Uderzenie','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +10...30 pkt. obrażeń. Jeżeli atak nie trafi, będzie się odnawiał dodatkowe 15 sek.','Zadaje +10...30 pkt. obrażeń. Ta umiejętność odnawia się o 15 sek. dłużej, jeżeli nie trafi. Musi nastąpić po ataku drugą ręką.'],
977=>['Ścieżka Lotosu','Przez 20 sek., następnym razem, gdy twoja umiejętność związana z atakiem podwójnym trafi, zyskujesz 5...20 pkt. energii.','(20 sek.) Otrzymujesz 5...20 pkt. energii następnym razem, kiedy trafisz atakiem podwójnym.'],
978=>['Piętno Niestabilności','Przez 20 sek., następnym razem, gdy zadasz wybranemu przeciwnikowi atak podwójny, przeciwnik ten zostaje powalony.','(20 sek.) Powala, kiedy następnym razem trafisz wybranego przeciwnika atakiem podwójnym.'],
979=>['Nieufność','Przez 6 sek. następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...80 pkt. obrażeń, a wszyscy przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.','(6 sek.). Następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...80 pkt. obrażeń, a przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.'],
980=>['Uczta Dusz','Niszczysz wszystkie sojusznicze duchy w pobliżu. Za każdego zniszczonego w ten sposób ducha, każdy z członków drużyny otrzymuje 50...100 pkt. żywotności.','Każdy członek drużyny otrzymuje 50...100 pkt. żywotności na każdego sojuszniczego ducha w pobliżu. Wszystkie sojusznicze duchy w pobliżu zostają zniszczone.'],
981=>['Rekonwalescencja','Tworzysz 1...14 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu posiadają regenerację żywotności +1...3. Ten duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...14 (czas życia 15...45 sek.). Sojusznicy nie-duchy w zasięgu posiadają regenerację żywotności +1...3.'],
982=>['Schronienie','Tworzysz 1...12 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Za każdym razem, kiedy ten duch zapobiega obrażeniom, traci 75...45 pkt. żywotności. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu, od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Koszt ochrony przed obrażeniami: ten duch traci 75...45 pkt. żywotności.'],
983=>['Cienisty Oręż','Na 1...7 sek., wybrany sojusznik zyskuje Cienisty Oręż. Za każdym razem, kiedy ten sojusznik otrzymuje cios, atakujący go zostaje oślepiony na 5 sek. Następne 1...3 razy, gdy ten sojusznik zostanie trafiony, atakujący go zostaje oślepiony na 5 sek.','(1...7 sek.) Oślepia (na 5 sek.) każdego, kto zaatakuje wybranego sojusznika. Kolejne ataki sprzymierzeńca (1...3) powodują w przypadku trafienia ślepotę (na 5 sek.).'],
985=>['Kolczatka','Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Uderzenie Dziewiątego Ogona','Musi nastąpić po ataku drugą ręką. Uderzenie Dziewięciu Ogonów nie może zostać zablokowane i zadaje +15...40 pkt. obrażeń, jeśli trafi.','Zadaje +15...40 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku drugą ręką.'],
987=>['Ścieżka Pustej Dłoni','Przez 5...15 sek. ataki drugą ręką oraz ataki podwójne kosztują zero punktów energii i odnawiają się 25...50% szybciej.','(5...15 sek.). Twoje ataki drugą ręką oraz ataki podwójne kosztują zero punktów energii i odnawiają się 25...50% szybciej.'],
988=>['Rozbicie Skroni','Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, wybrany przeciwnik zostaje oszołomiony i oślepiony na 1...10 sek., a jeżeli przeciwnik ten rzucał czar, zostaje on przerwany.','Przerywa czar. Wywołuje przypadłości oszołomienie i oślepienie (1...10 sek.). Musi nastąpić po ataku poprzedzającym.'],
989=>['Uderzenie Złotego Feniksa','Jeżeli nie masz na sobie zaklęcia, ten atak nie trafia. Jeśli atak trafi, Uderzenie Złotego Feniksa zadaje +10...30 pkt. obrażeń, zaś wszyscy sąsiadujący przeciwnicy otrzymują 10...30 pkt. obrażeń.','Zadaje +10...30 pkt. obrażeń celowi oraz 10...30 pkt. obrażeń sąsiadującym przeciwnikom. Nie działa, jeśli nie masz na sobie zaklęcia.'],
990=>['Przegnanie Zaklęć','Wybrany przeciwnik traci 1 zaklęcie. Wszystkie twoje pozostałe umiejętności, nie związane z atakowaniem, zostają wyłączone na 8...4 sek. Za każdą umiejętność wyłączoną w ten sposób, wybrany dotknięty przeciwnik traci jedno dodatkowe zaklęcie.','Zdejmuje jedno zaklęcie na każdą umiejętność nie związaną z atakami, którą posiadasz. Wszystkie twoje umiejętności nie związane z atakami są wyłączone (8...4 sek.).'],
991=>['Wyparcie Klątw','Za każdą odnawiającą się umiejętność Łaski Bogów na twoim pasku umiejętności, zdejmujesz z wybranego sojusznika jedną klątwę.','Za każdą odnawiającą się umiejętność Łaski Bogów na twoim pasku umiejętności, zdejmujesz z wybranego sojusznika jedną klątwę.'],
992=>['Potrójne Cięcie','Atakujesz wybranego przeciwnika i przeciwników bezpośrednio przy nim. Każdy celny atak zadaje +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń. Trafia także przeciwników w bezpośredniej odległości.'],
993=>['Gniewne Uderzenie','Jeśli Gniewne Uderzenie trafi, otrzymujesz dawki adrenaliny w liczbie 1...4. Jeżeli trafisz poruszającego się przeciwnika, zadajesz +10...40 pkt. obrażeń, a twój cel zostaje powalony.','Jeżeli trafisz, daje ci dawki adrenaliny w liczbie 1...4. Zadaje +10...40 pkt. obrażeń i powala, jeżeli cel porusza się.'],
994=>['Cios Odnowy','Jeśli Cios Odnowy trafi, zadaje +10...40 pkt. obrażeń. Jeśli trafisz powalonego wroga, otrzymujesz 3 pkt. energii, a atak ten natychmiast się odnawia.','Zadaje +10...40 pkt. obrażeń. Otrzymujesz 3 pkt. energii, zaś atak ten natychmiast się odnawia, jeśli wybrany przeciwnik był powalony.'],
995=>['Postawa Tygrysa','Przez 4...10 sek., atakujesz o 33% szybciej. Postawa Tygrysa skończy się jeśli jakiś z twoich ataków nie trafi.','(4...10 sek.) Atakujesz o 33% szybciej. Przestanie działać, jeśli nie trafisz.'],
996=>['Cięcie w Postawie','Jeśli Cięcie w Postawie trafi, zadaje +5...20 pkt. obrażeń oraz dodatkowo 5...20 pkt. obrażeń, jeśli jesteś pod działaniem jakiejś postawy.','Zadaje +5...20 pkt. obrażeń. Zadaje 5...20 pkt. dodatkowych obrażeń, jeżeli przyjąłeś postawę.'],
997=>['Klęska Głodu','Tworzysz 1...10 poziomowego ducha. Za każdym razem, kiedy energia stworzenia nie-ducha w jego zasięgu spadnie do 0, stworzenie to otrzymuje 20...70 pkt. obrażeń. Ten duch ginie po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzeniom w zasięgu, których energia spadnie do 0, zadaje 20...70 pkt. obrażeń. Nie działa na duchy.'],
1018=>['Krytyczne Oko','Przez 10...35 sek., otrzymujesz dodatkowe 3...15% szans na zadanie trafienia krytycznego podczas ataku. Zyskujesz 1 pkt. energii za każdym razem, gdy wykonasz trafienie krytyczne.','(10...35 sek.) Posiadasz +3...15% szans na wykonanie trafienia krytycznego. Otrzymujesz 1 pkt. energii, za każdym razem, kiedy wykonasz trafienie krytyczne.'],
1019=>['Krytyczne Uderzenie','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +10...30 pkt. obrażeń, ma miejce trafienie krytyczne i zyskujesz 1...3 pkt. energii.','Zadaje +10...30 pkt. obrażeń. Automatyczne trafienie krytyczne. Otrzymujesz 1...3 pkt. energii. Musi nastąpić po ataku drugą ręką.'],
1020=>['Stalowe Ostrza','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +5...16 pkt. obrażeń (maksymalnie 60) za każdy odnawiający się atak sztyletem.','Zadaje +5...16 pkt. obrażeń (maksymalnie 60) za każdy odnawiający się atak sztyletem. Musi nastąpić po ataku drugą ręką.'],
1021=>['Uderzenie Dżungli','Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Jeżeli uderzenie trafi okulawionego przeciwnika, on oraz wszyscy sąsiadujący z nim przeciwnicy otrzymują 1...31 pkt. obrażeń.','Zadaje +10...25 pkt. obrażeń. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 1...31 pkt. obrażeń, jeżeli ten przeciwnik jest okaleczony. Musi nastąpić po ataku poprzedzającym.'],
1022=>['Dzikie Uderzenie','Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadaje +10...35 pkt. obrażeń i dodatkowo przestają działać wszystkie postawy, pod których działaniem był wybrany przeciwnik. Tego ataku nie można zablokować.','Zadaje +10...35 pkt. obrażeń. Przerywa postawę wybranego przeciwnika. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
1023=>['Żądło Skaczącej Modliszki','Jeżeli Żądło Modliszki trafi, wybrany przeciwnik otrzymuje 5...15 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwnika, zostaje on okulawiony na 3...15 sek.','Zadaje +5...15 pkt. obrażeń. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik porusza się.'],
1024=>['Pchnięcie Czarnej Modliszki','Jeśli atak trafi, zadajesz +8...20 pkt. obrażeń. Jeśli wybrany przeciwnik jest pod wpływem klątwy, zostaje on okulawiony na 3...15 sek.','Zadaje +8...20 pkt. obrażeń. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik jest pod działaniem klątwy.'],
1025=>['Przerywające Pchnięcie','Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, zostaje on wyłączony na 3...10 sek.','Przerywa czynność. Jeżeli przerwaną czynnością było rzucanie czaru, to zostaje on wyłączony (3...10 sek.).'],
1026=>['Uderzenie Złotego Lotosu','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli masz na sobie zaklęcie, otrzymujesz 5...8 pkt. energii.','Zadaje +5...20 pkt. obrażeń. Otrzymujesz 5...8 pkt. energii, jeżeli jesteś pod działaniem zaklęcia.'],
1027=>['Krytyczna Obrona','Przez 4...10 sekund, masz 75% szans na blokowanie ataków. Krytyczna Obrona zaczyna działać od nowa za każdym razem, gdy wykonasz trafienie krytyczne.','(4...10 sek.) Masz 75% szans na blokowanie. Odnowienie: za każdym razem, gdy wykonasz trafienie krytyczne.'],
1028=>['Ścieżka ku Doskonałości','Przez 60 sek., za każdym razem, gdy wykonasz trafienie krytyczne, otrzymasz 10...40 pkt. żywotności.','(60 sek.) Twoje trafienia krytyczne dodają ci 10...40 pkt. żywotności.'],
1029=>['Mroczna Apostazja','Przez 3...17 sek., za każdym razem, gdy wykonasz trafienie krytyczne, zdejmiesz jedno zaklęcie ze swojego celu. Jeżeli zdejmiesz zaklęcie w ten sposób, stracisz 10...3 pkt. energii albo Mroczna Apostazja przestanie działać.','(3...17 sek.) Twoje trafienia krytyczne zdejmują zaklęcie. Koszt usunięcia: utrata 10...3 pkt. energii lub koniec Mrocznej Apostazji.'],
1030=>['Furia Szarańczy','Przez 10...35 sek., otrzymujesz dodatkowe 50% szans na wykonanie podwójnego uderzenia sztyletami.','(10...35 sek.) Masz +50% szans na podwójne uderzenie. Bez efektu, jeśli nie dzierżysz sztyletów.'],
1031=>['Całun Boleści','Przez 30...60 sek., jeżeli masz mniej niż 50% żywotności, otrzymujesz +3...8 regeneracji żywotności oraz masz 75% szansy na zablokowanie ataków.','(30...60 sek.) Otrzymujesz +3...8 regeneracji żywotności oraz masz 75% szans na blokowanie. Bez efektu, chyba że twoja żywotność jest poniżej 50%.'],
1032=>['Serce Cienia','Otrzymujesz 30...150 pkt. żywotności; wykonujesz krok cienia w kierunku przeciwnym do twojego celu.','Otrzymujesz 30...150 pkt. żywotności; wykonujesz krok cienia w kierunku przeciwnym do twojego celu.'],
1033=>['Przebicie','Musi nastąpić po ataku podwójnym. Wybrany przeciwnik otrzymuje 25...100 pkt. obrażeń od ziemi oraz przez 5...20 sek. cierpi z powodu głębokiej rany.','Zadaje 25...100 pkt. obrażeń od ziemi. Wywołuje przypadłość głęboka rana (5...20 sek.). Musi nastąpić po ataku podwójnym.'],
1034=>['Ropiejąca Rana','For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','(1...7 sek.) Wybrany przeciwnik porusza się 33% wolniej. Przeciwnik ten otrzymuje co sekundę 5...25 pkt. obrażeń, jeśli cierpi na jakąś przypadłość.'],
1035=>['Obietnica Zabójcy','Przez 5...15 sek., jeżeli wybrany przeciwnik umrze, zyskujesz 5...20 pkt. energii oraz wszystkie twoje umiejętności zostają odnowione.','(5...15 sek.) Otrzymujesz 5...20 pkt. energii i wszystkie twoje umiejętności odnowią się, jeżeli wybrany przeciwnik umrze.'],
1036=>['Sygnet Podłości','Za każdą przypadłość, na którą cierpi wybrany przeciwnik, tracisz jedną ze swych przypadłości.','Tracisz jedną przypadłość za każdą przypadłość, pod której działaniem jest wybrany przeciwnik.'],
1037=>['Mroczna Ucieczka','Przez 5...15 sek., poruszasz się 25% szybciej i otrzymujesz połowę obrażeń. Mroczna Ucieczka przestanie działać z twoim kolejnym trafionym atakiem.','(5...15 sek.) Poruszasz się o 25% szybciej i otrzymujesz połowę obrażeń. Przestanie działać, jeśli twój atak trafi.'],
1038=>['Okulawiający Sztylet','Rzuć Okulawiający Sztylet w wybranego przeciwnika. Jeżeli atak trafi, Okulawiający Sztylet zadaje 15...60 pkt. obrażeń od ziemi oraz okulawia poruszających się przeciwników na 3...15 sek. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Pocisk: zadaje 15...60 pkt. obrażeń od ziemi. Wywołuje przypadłość okulawienie (3...15 sek.), jeżeli wybrany przeciwnik porusza się.'],
1040=>['Spacer Ducha','Wykonaj krok cienia do wybranego ducha.','Wykonujesz krok cienia do wybranego ducha.'],
1041=>['Niewidoczna Furia','Wszyscy przeciwnicy w kontakcie zostaną oślepieni na 3...10 sek. Przez 10...30 sek., oślepieni przeciwnicy nie mogą cię blokować.','Wywołuje oślepienie wśród sąsiednich przeciwników (3...10 s). Nie możesz zostać zablokowany przez oślepionych przeciwnikĂłw (10...30 s).'],
1042=>['Błyskające Ostrza','Przez 5...30 sek., otrzymujesz dodatkowe 75% szans na blokowanie ataków podczas walki. Jeżeli zablokujesz atak w ten sposób, to atakujący otrzyma 5...20 pkt. obrażeń.','(5...30 sek.) Masz 75% szans na blokowanie, kiedy atakujesz. Efekt zablokowania: 5...20 pkt. obrażeń dla atakującego przeciwnika.'],
1043=>['Pęd','Przez 3 sek., biegniesz 50% szybciej.','(3 sek.) Poruszasz się o 50% szybciej.'],
1044=>['Mroczne Więzienie','Wykonaj krok cienia do wybranego przeciwnika. Przez 1...6 sek., wybrany przeciwnik porusza się 33% wolniej.','Wykonujesz krok cienia do wybranego przeciwnika. Ten przeciwnik porusza się o 33% wolniej (1...6 sek.).'],
1045=>['Uderzenie Dłonią','Wybrany dotknięty przeciwnik otrzymuje 10...65 pkt. obrażeń i zostaje okulawiony na 1...5 sek. Ta umiejętność liczy się jako atak drugą ręką.','Zadaje 10...65 pkt. obrażeń i wywołuje przypadłość okulawienie (1...5 sek.). Ta umiejętność traktowana jest jako atak drugą ręką.'],
1048=>['Ujawnienie Zaklęcia','Z wybranego przeciwnika zdejmujesz jedno zaklęcie i otrzymujesz 3...15 pkt. energii. Na 20 sekund Ujawnienie Zaklęcia zostaje zastąpione zaklęciem zdjętym z wybranego przeciwnika.','Z wybranego przeciwnika usuwa zaklęcie. Efekty usunięcia: otrzymujesz 3...15 pkt. energii; ten czar zamieniany jest na to zaklęcie (20 sek.).'],
1049=>['Ujawnienie Klątwy','Z wybranego sojusznika zdejmujesz jedną klątwę i otrzymujesz 4...10 pkt. energii. Na 20 sekund Ujawnienie Klątwy zostaje zastąpione klątwą zdjętą z wybranego sojusznika.','Z wybranego sojusznika usuwa jedną klątwę. Efekty usunięcia: otrzymujesz 4...10 pkt. energii; ten czar zamieniany jest na tę klątwę (20 sek.).'],
1052=>['Nagromadzenie Bólu','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod wpływem 2 lub więcej klątw, to ten przeciwnik otrzymuje Głęboką Ranę na 5...20 sek.','Zadaje 15...75 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest pod działaniem 2 lub więcej klątw.'],
1053=>['Rozkojarzenie','Twoje pozostałe umiejętności są wyłączone na 8 sek. Jeśli cel używał właśnie umiejętności, zostanie ona przerwana i wyłączona na dodatkowe 5...12 sek.','Przerywa użycie umiejętności. Skutek przerwania: wyłącza przerwaną umiejętność (+5...12 sek.). Twoje pozostałe umiejętności są wyłączone (8 sek.).'],
1054=>['Oblicze Przodka','Przez 4...10 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony atakiem wręcz, wszyscy przeciwnicy bezpośrednio przy nim stracą całą adrenalinę i po 3 punkty energii.','(4...10 sek.) Wszyscy przeciwnicy w kontakcie tracą adrenalinę i 3 pkt. energii, za każdym razem, kiedy atak wręcz trafi wybranego sojusznika.'],
1055=>['Powracająca Niepewność','Przez 5 sek., cel otrzymuje -1...6 pkt. degeneracji żywotności. Jeżeli dany cel jest obłożony inną klątwą, gdy Powracająca Niepewność się skończy, zostaje ona nałożona ponownie.','(5 sek.) Odejmuje 1...6 regeneracji żywotności. Odnowienie: jeśli dany cel jest obłożony inną klątwą, gdy Powracająca Niepewność się skończy.'],
1056=>['Brzemię Kitaha','Przez 6...12 sek., wybrany przeciwnik porusza się 50% wolniej. Gdy Brzemię Kitaha przestanie działać, otrzymujesz 10...18 pkt. energii.','(6...12 sek.) Wybrany przeciwnik porusza się o 50% wolniej. Efekt końcowy: otrzymujesz 10...18 pkt. energii.'],
1057=>['Psychiczna Niestabilność','Przerywa akcję wybranego przeciwnika. Jeśli tą akcją jest umiejętność, przeciwnik i wszyscy pobliscy wrogowie zostają powaleni na 2...4 sek. (50% szans na niepowodzenie, jeśli Szybkie Rzucanie Czarów jest na poziomie 4 lub mniejszym.)','Przerywa akcję. Efekt przerwania: jeśli tą akcją jest umiejętność, przeciwnik i wszyscy pobliscy wrogowie zostają powaleni na 2...4 sek. 50% szans na niepowodzenie, chyba że Szybkie Rzucanie Czarów jest na poziomie 5 lub wyższym.'],
1059=>['Sygnet Pożeracz Klątw','Wybrany dotknięty sojusznik i maksymalnie 2...5 sojuszników bezpośrednio przy nim tracą po jednej klątwie. Otrzymujesz 1...4 pkt. energii za każdą klątwę zdjętą w ten sposób.','Usuwa po jednej klątwie z celu i 2...5 sojuszników bezpośrednio przy nim. Efekt usunięcia: otrzymujesz 1...4 pkt. energii za każdą usuniętą klątwę.'],
1061=>['Sprzężenie Zwrotne','Wybrany przeciwnik traci jedno zaklęcie. Jeśli zaklęcie zostanie zdjęte w ten sposób, to ten przeciwnik traci 4...10 pkt. energii.','Usuwa jedno zaklęcie. Efekt usunięcia: wybrany przeciwnik traci 4...10 pkt. energii.'],
1062=>['Magiczna Kradzież','Na 5...35 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Magiczna Kradzież zostaje zastąpiona tym czarem.','(5...35 sek.) Wyłącza jeden losowy czar. Ta umiejętność staje się tym czarem.'],
1066=>['Łup Zwycięzcy','Przez 3...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje lub rzuca czar na stworzenie z mniejszą liczbą punktów żywotności od siebie, traci 25...100 pkt. żywotności.','(3...15 sek.) Powoduje utratę 25...100 pkt. żywotności, za każdym razem, kiedy wybrany przeciwnik atakuje lub rzuca czar na stworzenie z mniejszą żywotnością.'],
1067=>['Zgubne Uderzenie','Wybrany przeciwnik otrzymuje 12...48 pkt. obrażeń od cienia. Jeżeli ten przeciwnik ma ponad 50% pkt. żywotności, wykradasz mu 12...48 pkt. żywotności.','Zadaje 12...48 pkt. obrażeń. Wykrada 12...48 pkt. żywotności, jeżeli wybrany przeciwnik ma powyżej 50% żywotności.'],
1068=>['Bolesny Chłód','Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od zimna. Jeżeli ten przeciwnik miał więcej życia niż ty, Bolesny Chłód odnawia się natychmiastowo.','Zadaje 15...60 pkt. obrażeń od zimna. Natychmiast się odnawia, jeżeli wybrany przeciwnik ma więcej żywotności niż ty.'],
1069=>['Smak Bólu','Jeżeli wybrany przeciwnik ma mniej niż 50% pkt. żywotności, otrzymujesz 30...150 pkt. żywotności.','Otrzymujesz 30...150 pkt. żywotności. Bez efektu, chyba że wybrany przeciwnik ma poniżej 50% żywotności.'],
1070=>['Splugawienie Zaklęć','Wybrany przeciwnik i przeciwnicy w pobliżu otrzymują po 6...60 pkt. obrażeń od cienia oraz po 4...20 pkt. obrażeń od cienia za każde zaklęcie, które mają na sobie.','Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 6...60 pkt. obrażeń. Zadaje 4...20 pkt. dodatkowych obrażeń za każde zaklęcie, pod którego są działaniem.'],
1071=>['Dreszcze Grozy','Przez 10...40 sek., za każdym razem, kiedy wybrany przeciwnik otrzymuje obrażenia od zimna podczas używania umiejętności, ten przeciwnik zostaje rozproszony, a ty tracisz 8...3 pkt. energii albo Dreszcze Grozy przestają działać.','(10...40 sek.) Obrażenia od zimna przerywają umiejętności wybranego przeciwnika. Koszt przerwania: tracisz 8...3 pkt. energii lub klątwa się kończy.'],
1075=>['Wampiryczny Rój','Wampiryczny R&oacute;j wykrada do 15...60 pkt. żywotności maksymalnie trzem przeciwnikom w okolicy.','Wykrada 15...60 pkt. żywotności. Trafia dw&oacute;ch dodatkowych przeciwnik&oacute;w w okolicy.'],
1076=>['Krwiopijca','Jeżeli posiadasz ponad 90 pkt. żywotności, zaczynasz krwawić przez 6 sek. Od wybranego przeciwnika wykradasz do 20...65 pkt. żywotności.','Wykrada 20...65 pkt. żywotności. Zaczynasz krwawić (6 sek.), jeżeli twoja żywotność jest powyżej 90%.'],
1077=>['Wampiryczne Ukąszenie','Dotknij wybranego przeciwnika by wykraść mu do 29...74 pkt. żywotności.','Wykrada 29...74 pkt. żywotności.'],
1078=>['Ugryzienie Błotniaka','Wybrany dotknięty przeciwnik otrzymuje 20...58 pkt. obrażeń.','Zadaje 20...58 pkt. obrażeń.'],
1079=>['Osłabiające Dotknięcie','Wybrany dotknięty przeciwnik traci 5...65 pkt. żywotności i cierpi na osłabienie przez 5...20 sek.','Powoduje utratę 5...65 pkt. żywotności. Wywołuje przypadłość osłabienie (5...20 sek.).'],
1081=>['Wiatr Teinai','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 10...40 pkt. obrażeń od zimna. Płonący przeciwnicy trafieni Wiatrem Teinai otrzymują dodatkowo 40...80 pkt. obrażeń i wykonywana przez nich czynność zostaje przerwana.','Zadaje 10...40 pkt. obrażeń od zimna. Płonący przeciwnicy otrzymują +40...80 obrażeń, a ich czynność zostaje przerwana. Zadaje obrażenia znajdującym się w sąsiedztwie.'],
1082=>['Strzała Porażenia','Wyślij porażającą strzałę, która leci w kierunku wybranego przeciwnika, zadając 5...50 pkt. obrażeń od błyskawic. Jeśli Strzała Porażenia trafi przeciwnika pod wpływem Pękniętej Zbroi, otrzymujesz 5 pkt. energii oraz 1 pkt. energii za każde dwa stopnie pojemności energii. Strzała Porażenia czar posiada 25% przebicia pancerza.','Szybki pocisk: zadaje 5...50 pkt. obrażeń od elektryczności. Bonus 5 do energii oraz 1 pkt. energii za każde 2 stopnie pojemności energii, jeśli trafisz przeciwnika pod wpływem Pękniętej Zbroi. 25% penetracji pancerza.'],
1083=>['Niestabilny Grunt','Stwórz Niestabilny Grunt w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w pobliżu otrzymują co sekundę 10...40 pkt. obrażeń od ziemi. Atakujący przeciwnicy uderzeni Niestabilnym Gruntem zostają powaleni.','W każdej sekundzie zadaje 10...40 pkt. obrażeń od ziemi (5 sek.) i powala atakujących przeciwników. Trafia przeciwników w pobliżu początkowego miejsca celu.'],
1084=>['Zbroja z Odłamków','Przez 5...11 sek. masz 25...50% szans na blokowanie ataków oraz za każdym razem, kiedy jesteś celem wrogiego czaru lub ataku, jeden przeciwnik w pobliżu otrzymuje 5...35 pkt. obrażeń od ziemi.','(5...11 sek.) Masz 25...50% szans na blokowanie. Jednemu przeciwnikowi w pobliżu zadaje 5...35 pkt. obrażeń od ziemi, za każdym razem, kiedy jesteś celem wrogiego czaru lub ataku.'],
1085=>['Wybuch Popiołu','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 35...65 pkt. obrażeń od ziemi. Płonący przeciwnicy trafieni przez Wybuch Popiołu zostają przeklęci na 5 sek. i mają 20...75% szansę na nieudane ataki.','Zadaje 35...65 pkt. obrażeń od ziemi. Płonący przeciwnicy pozostają pod wpływem klątwy przez 5 sek. i unikają 20...75% ataków. Dotyczy również postaci w bezpośrednim sąsiedztwie.'],
1086=>['Tupnięcie Smoka','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Tupnięcie Smoka. Wszyscy przeciwnicy na tym obszarze zostają powaleni i otrzymują 26...100 pkt. obrażeń od ziemi. Ten czar powoduje wyczerpanie.','Zadaje 26...100 pkt. obrażeń od ziemi. Powoduje powalenie. Trafia także przeciwników w pobliżu tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
1088=>['Drugi Oddech','Uzyskujesz 1 punktów energii i 5 punktów żywotności za każdy punkt energii ograniczony przez limit aktywacyjny. Tracisz wszystkie zaklęcia.','Uzyskujesz 1 punktów energii i 5 punktów żywotności za każdy punkt limitu aktywacyjnego. Tracisz wszystkie zaklęcia.'],
1090=>['Rozżarzone Zgliszcze','Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, ten przeciwnik zostanie przeklęty Rozżarzonymi Zgliszczami na 3 sek. i co sekundę będzie otrzymywał 5...25 pkt. dodatkowych obrażeń od ognia.','Zadaje wybranemu przeciwnikowi 10...70 pkt. obrażeń od ognia. Jeśli jesteś pod wpływem Przemagicznienia, przeciwnik zostanie przeklęty na 3 sek. i co sekundę będzie otrzymywał 5...25 pkt. obrażeń od ognia.'],
1091=>['Podwójny Smok','Przeciwnicy bezpośrednio przy tobie otrzymują po 1...4 pkt. obrażeń od ognia. Przez 8 sek. twój atrybut Magia Ognia jest większy o +10...40.','Wszystkim przeciwnikom w pobliżu zadaje po 1...4 pkt. obrażeń od ognia. Otrzymujesz +10...40 do Magii Ognia (8 sek.).'],
1093=>['Żar Teinai','Stawia w twoim miejscu znak Żaru Teinai na 10...15 sek. Przeciwnicy w zasięgu działania znaku otrzymują degenerację żywotności -2...5. Osłabieni przeciwnicy atakują 33% wolniej. Ta umiejętność zostanie wyłączona na 20 sek.','(10...15 sek.) Powoduje degenerację żywotności -2...5. Osłabieni działaniem znaku przeciwnicy atakują 33% wolniej. Nieaktywne przez 20 sek.'],
1094=>['Ogniste Tchnienie','Wywołaj Ogniste Tchnienie w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy w tym obszarze otrzymują w każdej sekundzie 10...40 pkt. obrażeń od ognia.','W każdej sekundzie zadaje 10...40 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu celu.'],
1095=>['Gwiezdny Wybuch','Wybrany dotknięty przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 7...112 pkt. obrażeń od ognia. Jeżeli obrażenia otrzymał więcej niż jeden przeciwnik, tracisz 5 pkt. energii.','Zadaje 7...112 pkt. obrażeń od ognia. Trafia także przeciwników w pobliżu. Tracisz 5 punktów energii, jeżeli został trafiony więcej niż jeden przeciwnik.'],
1096=>['Glif Esencji','Przez 15 sek. twój następny czar zostanie rzucony natychmiastowo, ale stracisz wszystkie punkty energii.','(15 sek.) Twój następny czar zostaje rzucony natychmiastowo. Tracisz całą energię.'],
1097=>['Więzienie Teinai','Przez 1...8 sek., nogi wybranego przeciwnika zostają skute lodem, co powoduje, że porusza się on 66% wolniej. Jeśli przeciwnik jest pod wpływem Pękniętego Pancerza, chłód wnika głębiej, powodując degenerację żywotności 5...9.','(1...8 sek.) Cel porusza się 66% wolniej. U przeciwników z Pękniętym Pancerzem powoduje degenerację żywotności 5...9.'],
1098=>['Lodowe Lustro','Przez 2...6 sek., zadajesz dodatkowe 15...70 pkt. obrażeń od zimna, za każdym razem gdy rzucisz klątwę Magii Wody.','(2...6 sek.) Zadajesz dodatkowe 15...70 pkt. obrażeń od zimna, za każdym razem gdy rzucisz klątwę Magii Wody.'],
1099=>['Kryształy Teinai','Wybrany przeciwnik otrzymuje 20...40 pkt. obrażeń. Jeśli cel jest przeklęty Magią Wody, to zaklęcie trafia cel i pobliskich przeciwników za dodatkowe 20...40 pkt. obrażeń, a pobliscy przeciwnicy cierpią przez 5...15 sek. z powodu Pękniętego Pancerza.','Zadaje wybranemu przeciwnikowi 20...40 pkt. obrażeń. Zadaje przeciwnikowi +20...40 więcej obrażeń i powoduje Pęknięty Pancerz (przez 5...15 sek.) u pobliskich przeciwników, jeśli cel był pod wpływem klątwy Magii Wody.'],
1113=>['Gniew Kirina','Przez 5 sek., przeciwnicy bezpośrednio przy miejscu, w którym ten czar został rzucony, otrzymują w każdej sekundzie po 8...32 pkt. świętych obrażeń.','W każdej sekundzie zadaje 8...32 pkt. świętych obrażeń (5 sek.). Trafia przeciwników bezpośrednio przy twoim początkowym miejscu.'],
1114=>['Duchowa Więź','Przez 8 sek., za każdym razem, kiedy wybrany sojusznik z kolejnych 10 ataków lub czarów otrzyma więcej niż 50 pkt. obrażeń, dostanie 30...90 pkt. żywotności.','(8 sek.) Dodaje 30...90 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 50 pkt. obrażeń. Przestanie działać, jeśli ten sojusznik otrzyma obrażenia z 10 ataków lub czarów.'],
1115=>['Zaklęte Powietrze','Przez 4...10 sek. zaklęcia rzucane na wybranego sojusznika innego niż ty kosztują o 10 pkt. energii mniej (minimalnie 1 pkt. energii).','(4...10 sek.) Zaklęcia rzucane na wybranego sojusznika kosztują o 10 pkt. energii mniej (minimalnie 1 pkt. energii). Na cel nie można wybrać siebie.'],
1117=>['Niebiańska Rozkosz','Uzdrawia ciebie i członków drużyny w zasięgu słuchu dodając każdemu 15...60 pkt. żywotności.','Tobie i członkom drużyny w zasięgu słuchu dodaje po 15...60 pkt. żywotności.'],
1118=>['Uzdrawiający Wybuch','Wybrany sojusznik odzyskuje 20...120 pkt. żywotności. Wszyscy członkowie drużyny w zasięgu słuchu od celu odzyskują żywotność równą premii z Łaski Bogów. Twoje modlitwy ofensywne zostają zablokowane na 20 sekund.','Leczy 20...120 pkt. żywotności. Członkowie drużyny w zasięgu słuchu celu otrzymują żywotność równą premii z Łaski Bogów. <c x="SkillDull">Blokuje twoje modlitwy ofensywne (20 sekund).'],
1119=>['Uzdrawiający Krąg Karei','Uzdrawiasz siebie i wszystkie stworzenia bezpośrednio przy tobie dodając każdemu 30...180 pkt. żywotności.','Otrzymujesz 30...180 pkt. żywotności. Dodaje żywotność także stworzeniom w bezpośredniej odległości.'],
1120=>['Spojrzenie Jamei','Uzdrawiasz wybranego sojusznika innego niż ty dodając mu 35...180 pkt. żywotności.','Dodaje 35...180 pkt. żywotności. Na cel nie można wybrać siebie.'],
1121=>['Dar Życia','Wszystkie twoje umiejętności oparte na Modlitwach Uzdrawiających będą niedostępne przez 10...5 sek. Wybrany sojusznik inny niż ty otrzymuje 15...150 pkt. żywotności.','Dodaje 15...150 pkt. żywotności. Wyłącza twoje pozostałe umiejętności Modlitw Uzdrawiających (10...5 sek.). Na cel nie można wybrać siebie.'],
1123=>['Osłona Życia','Z wybranego sojusznika usuwasz 0...2 przypadłości. Przez 8 sek., kiedy następnym razem wybrany sojusznik miałaby otrzymać obrażenia lub stracić żywotność na rzecz przeciwnika, dostanie w zamian tyle samo pkt. żywotności (maksymalnie 20...100).','(8 sek.) Zamienia następne obrażenia lub wykradzioną żywotność (maksymalnie 20...100) w leczenie. Efekt początkowy: Usuwa przypadłości (0...2).'],
1126=>['Empatyczne Usunięcie','Ty i inny wybrany sojusznik tracicie po jednej przypadłości i klątwie. Otrzymujecie też po 50 pkt. żywotności.','Z wybranego sojusznika i ciebie usuwa jedną klątwę oraz przypadłość. Dodaje wam też po 50 pkt. żywotności. Na cel nie można wybrać siebie.'],
1128=>['Wskrzeszający Chorał','Wskrzeszasz wybranego członka drużyny, który wraca do życia z tyloma pkt. żywotności ile aktualnie posiadasz i 5...35% energii. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...35% energii.'],
1129=>['Słowo Potępienia','Wybrany przeciwnik otrzymuje 30...130 pkt. świętych obrażeń. Jeśli twój cel miał mniej niż 50% żywotności, Słowo Potępienia będzie się odnawiało o 20 sek. dłużej.','Zadaje 30...130 pkt. świętych obrażeń. +20 sek. do czasu odnawiania, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
1130=>['Włócznia Światła','Jeśli Włócznia Światła trafi w wybranego przeciwnika, zadaje 26...56 pkt. świętych obrażeń. Jeśli trafi w atakującego przeciwnika zadaje +15...60 pkt. obrażeń.','Pocisk: zadaje 26...56 pkt. świętych obrażeń. Zadaje 15...60 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik atakuje.'],
1131=>['Uderzenie Kamiennej Duszy','Dotknięty przeciwnik otrzymuje 10...55 świętych obrażeń. Jeśli był powalony, otrzymuje dodatkowe 10...55 pkt. świętych obrażeń.','Zadaje 10...55 pkt. świętych obrażeń. Zadaje 10...55 pkt. dodatkowych świętych obrażeń, jeżeli wybrany przeciwnik jest powalony.'],
1133=>['Cios Pijaka','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń, a twój cel otrzyma jedną z następujących przypadłości: głęboka rana (na 20 sek.), osłabienie (na 20 sek.), krwawienie (na 25 sek.) lub okulawienie (na 15 sek.). Po wykonaniu Ciosu Pijaka, zostaniesz powalony.','Zadaje +10...40 pkt. obrażeń. Wywołuje jedną losową przypadłość spośród następujących: głęboka rana (20 sek.), osłabienie (20 sek.), krwawienie (25 sek.) lub okulawienie (15 sek.). Zostajesz powalony.'],
1134=>['Zamach Lewiatana','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli przeciwnik zablokuje ten atak, to zostaje powalony i otrzymuje 10...34 pkt. obrażeń.','Zadaje +5...20 pkt. obrażeń. Powala i zadaje 10...34 pkt. obrażeń, jeżeli nastąpiło blokowanie.'],
1135=>['Uderzenie Jaizhenju','Jeśli Uderzenie Jaizhenju trafi, zadajesz +1...30 pkt. obrażeń. Jeśli nie przyjąłeś żadnej postawy, to Uderzenie Jaizhenju nie może zostać zablokowane.','Zadaje +1...30 pkt. obrażeń. Nie do zablokowania, chyba że przyjąłeś postawę.'],
1136=>['Przebijające Cięcie','Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Ten atak toporem posiada 20% przebicie pancerza.','Zadaje +10...25 pkt. obrażeń. 20% przebicie pancerza.'],
1137=>['Uderzenie Yeti','Tracisz całą adrenalinę. Atakujesz wszystkich wrogów w bezpośrednim sąsiedztwie. Jeśli atak trafi wroga cierpiącego na jakąś przypadłość, zostanie on powalony. (50% szans na niepowodzenie jeśli biegłość w używaniu młotów wynosi 4 lub mniej.)','Atakuje wszystkich wrogów w bezpośrednim sąsiedztwie. Powala wrogów cierpiących na jakąś przypadłość. Tracisz całą adrenalinę. 50% szans na niepowodzenie, chyba że biegłość w używaniu młotów wynosi 5 lub więcej.'],
1141=>['"Umrzesz!"','Jeśli żywotność przeciwnika wynosi mniej niż 90%, otrzymujesz dawki adrenaliny w liczbie 1...3.','Otrzymujesz adrenalinę w następującej liczbie dawek: 1...3. Nie ma efektu, chyba że wybrany przeciwnik ma poniżej 90% żywotności.'],
1142=>['Pomyślne Parowanie','Przez 8 sek., następny atak skierowany w ciebie zostanie zablokowany. Otrzymasz dawki adrenaliny w liczbie 1...4 po zakończeniu działania tej postawy.','(8 sek.) Blokuje jeden atak. Efekt końcowy: otrzymujesz dawki adrenaliny (1...4).'],
1144=>['Cięcie Srebrnoskrzydłego','Jeśli atak trafi, zadajesz +1...40 pkt. obrażeń.','Zadaje +1...40 pkt. obrażeń.'],
1146=>['Popchnięcie','Dotknięty wrogi cel odnosi 15...75 pkt. obrażeń, jego postawa dobiega końca i zostaje powalony.','Dotknięty wrogi cel odnosi 15...75 pkt. obrażeń, jego postawa dobiega końca i zostaje powalony.'],
1191=>['Rozdzielający Atak','Jeśli Rozdzielający Atak trafi, zadajesz +5...25 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Zadaje +5...25 pkt. obrażeń. 10% przebicie pancerza.'],
1192=>['Strzał Zojuna','Wystrzeliwujesz strzałę, która ma połowę normalnego zasięgu, ale zadaje +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń.'],
1194=>['Drapieżcza Więź','Przez 5...20 s ataki twojego zwierzęcego towarzysza są o 25% szybsze i dodają Ci 1...31 pkt. żywotnośći przy każdym udanym ataku.','(5...20 s) Twój zwierzak atakuje 25% szybciej i zyskujesz 1...31 pkt. żywotności za każdym razem, gdy wykona on udany atak.'],
1195=>['Jedność w Uzdrowieniu','Przez 15 sek., twój zwierzęcy towarzysz wykrada 1...20 pkt. żywotności, za każdym razem gdy jego atak dojdzie celu. Zarówno ty, jak i twój zwierzęcy towarzysz odzyskujecie 20...104 pkt. żywotności. Jeśli twój towarzysz nie żyje, zostaje wskrzeszony z 50% żywotności. Jeśli posiadasz tę umiejętność na wyposażeniu, twój towarzysz będzie podróżował wraz z tobą.','(15 sek.) Z każdym atakiem twój zwierzęcy towarzysz wykrada 1...20 pkt. żywotności. Efekt początkowy: przywraca 20...104 pkt. żywotności tobie i twojemu zwierzęciu; wskrzesza twojego zwierzęcego towarzysza (50% żywotności), jeśli ten nie żyje. Jeśli posiadasz tę umiejętność na wyposażeniu, twój towarzysz będzie podróżował wraz z tobą.'],
1196=>['Pośpiech Zojuna','Przez 5...11 sek., poruszasz się o 33% szybciej i masz 27...75% szans na zablokowanie nadlatujących pocisków. Pośpiech Zojuna skończy się, jeśli zaatakujesz.','(5...11 sek.) Poruszasz się o 33% szybciej i masz 27...75% szans na blokowanie pocisków. Przestanie działać, jeśli zaatakujesz.'],
1197=>['Strzał Dobijający','Strzał Dobijający zadaje jedynie 10...30 pkt. obrażeń, ale porusza się szybciej niż normalny. Jeśli Strzał Dobijający trafi w przeciwnika, kt&oacute;ry będzie miał mniej niż 50% żywotności, to ta umiejętność odnowi się automatycznie. Twoje pozostałe umiejętności ofensywme nie działają przez 2 sek.','Szybko lecąca strzała. Zadaje 10...30 pkt. obrażeń. Natychmiast się odnawia, jeżeli wybrany przeciwnik ma poniżej 50% żywotności. Twoje pozostałe umiejętności ofensywne nie działają (2 sek).'],
1198=>['Strzała z Szerokim Grotem','Wystrzeliwujesz strzałę o szerokim grocie, która leci wolniej niż normalnie. Jeśli atak trafi, wybrany przeciwnik zostanie oszołomiony na 5...20 sek., a jeśli rzucał czar, to czar zostanie przerwany.','Wolno lecąca strzała. Przerywa czar. Wywołuje przypadłość oszołomienie (5...20 sek.).'],
1199=>['Szklane Strzały','Przez 10...35 sek., twoje strzały po trafieniu zadają +6...20 pkt. obrażeń, a jeśli zostaną "zablokowane", to powodują, że na 10...20 sek. cel zaczyna krwawić.','(10...35 sek.) Twoje strzały zadają +6...20 pkt. obrażeń. Wywołuje przypadłość krwawienie (10...20 sek.), jeżeli zostanie zablokowana.'],
1200=>['Sygnet Łucznika','Przez 1...24 sek. wszystkie przypadłości, które nakładasz przy pomocy łuku trwają o 150% dłużej.','(1...24 sek.) Przypadłości, które nakładasz przy pomocy łuku trwają o 150% dłużej.'],
1201=>['Wściekły Skok','Twój zwierzęcy towarzysz wykonuje Wściekły Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika rzucającego czar, to ten przeciwnik zostaje powalony.','Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik rzuca czar.'],
1202=>['Rozszalałe Uderzenie','Twój zwierzęcy towarzysz wykonuje Rozszalałe Uderzenie, które powoduje u przeciwnika głęboką ranę na 5...20 sek. oraz zadaje +10...50 pkt. obrażeń..','Powoduje głęboką ranę (5...20 sek.) i zadaje +10...50 pkt. obrażeń.'],
1203=>['Bestialskie Zmiażdżenie','Twój zwierzęcy towarzysz wykonuje Bestialskie Zmiażdżenie, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi powalonego przeciwnika, to będzie on oszołomiony przez 4...10 sek.','Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość oszołomienie (4...10 sek.), jeżeli wybrany przeciwnik jest powalony.'],
1205=>['Trujące Ugryzienie','Twój zwierzęcy towarzysz wykonuje Trujące Ugryzienie, które zatruwa cel na 5...20 s.','Wywołuje przypadłość zatrucie (5...20 s).'],
1206=>['Skok','Twój zwierzęcy towarzysz wykonuje Skok, który zadaje +5...20 pkt. obrażeń. Jeśli atak trafi poruszającego się przeciwnika, ten przeciwnik zostaje powalony.','Zadaje +5...20 pkt. obrażeń. Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
1209=>['Furia Bestii','Wszystkie twoje umiejętności nie związane z atakami będą niedostępne przez 5 sek. Przez 5...11 sek., atakujesz o 33% szybciej.','(5...11 sek.) Atakujesz o 25% szybciej. Twoje umiejętności nie związane z atakami są wyłączone (5 sek.).'],
1211=>['Gniazdo Żmij','Tworzysz Gniazdo Żmij. Kiedy się ono uaktywni, każdy przeciwnik w pobliżu otrzyma 5...35 pkt. obrażeń przebijających i przez 5...20 sek. będzie zatruty. Gniazdo Żmij dezaktywuje się po 90 sek. Jest to pułapka łatwa do przerwania.','(90 sek.) Działa na przeciwników w pobliżu. Zadaje 5...35 pkt. obrażeń przebijających. Wywołuje przypadłość zatrucie (5...20 sek.). Łatwo przerwać.'],
1212=>['Równonoc','Tworzy ducha o poziomie 1...10. Zaklęcia powodujące Przemagicznienie rzucone w jego pobliżu powodują dodatkowe 10 punktów Przemagicznienia. Duch umiera po 30...240 sek.','Tworzy ducha o poziomie 1...10 (długość życia: 30...240 sek.). Zaklęcia powodujące Przemagicznienie rzucone w zasięgu przeciwnika powodują dodatkowe 10 punktów Przemagicznienia.'],
1213=>['Spokój','Tworzysz 1...10 poziomowego ducha. Zaklęcia rzucane przez stworzenia nie-duchy w jego zasięgu kończą się o 20...50% szybciej. Ten duch ginie po 15...120 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...120 sek.). Zaklęcia na stworzeniach w zasięgu przestają działać o 20...50% szybciej. Nie działa na duchy.'],
1215=>['Krzyk Dusz','Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu otrzymują po 10...65 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy lub trzymasz przedmiot, to otrzymujesz 10 pkt. energii.','Wybranemu przeciwnikowi i wszystkim przeciwnikom w pobliżu zadaje po 10...65 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy lub trzymasz przedmiot, to otrzymujesz 10 pkt. energii.'],
1217=>['Władca Rytuałów','Przez 5...35 sek., twoje atrybuty Rytualisty zostaną zwiększone o 2...4 na potrzeby kolejnej umiejętności. Jeśli ta umiejętności jest rytuałem spętania, odnawia się 10...60% szybciej, zaś Władca Rytuałów odnawia się natychmiast.','Przez 5...35 sek., twoje atrybuty Rytualisty zostaną zwiększone o +2...4 na potrzeby kolejnej umiejętności. Jeśli ta umiejętności jest rytuałem spętania, odnawia się 10...60% szybciej, zaś Władca Rytuałów odnawia się natychmiast.'],
1218=>['Okrutnym Był Daoshen','Trzymaj prochy Daoshena przez maksymalnie 15...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Gdy upuścisz jego prochy, wszyscy przeciwnicy w pobliżu otrzymają 15...85 pkt. obrażeń od błyskawic.','(15...60 sek.) Twoje umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w pobliżu otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
1219=>['Opiekuńczym Był Kaolai','Trzymaj prochy Kaolaia przez maksymalnie 15...60 sek. Trzymając jego prochy, otrzymujesz 20 do pancerza. Kiedy upuścisz prochy, wszyscy członkowie drużyny odzyskują 20...95 pkt. żywotności.','(15...60 sek.) Posiadasz +20 pkt. pancerza. Efekt upuszczenia: wszyscy członkowie drużyny otrzymują po 20...95 pkt. żywotności.'],
1220=>['Zestrojoną Była Songkai','Trzymaj prochy Songkai przez maksymalnie 45 sek. Kiedy trzymasz jej prochy, twoje czary i rytuały spętania kosztują o -5...50% podstawowego kosztu energetycznego mniej.','(45 sek.) Twoje czary i rytuały spętania kosztują -5...50% bazowej energii.'],
1221=>['Odporną Była Xiko','Unieś prochy Xiko na maks. 5...20 s. Za każdą klątwę lub przypadłość, na kt&oacute;rą cierpisz unosząc jej prochy, otrzymujesz +3 do regeneracji żywotności. W momencie wyrzucenia jej proch&oacute;w tracisz 1...4 przypadłość.','(5...20 sek.) Za każdą przypadłość lub klątwę, pod której jesteś działaniem, otrzymujesz regenerację żywotności +3. Efekt upuszczenia: tracisz przypadłości w liczbie 1...4.'],
1222=>['Żywotną Była Naomei','Trzymaj prochy Naomei przez maksymalnie 45 sek. Gdy upuścisz jej prochy, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 15...75% pkt. żywotności i z zerem pkt. energii.','(45 sek.) Efekt upuszczenia: wskrzesza martwych członków drużyny w okolicy (15...75% żywotności, 0 pkt. energii).'],
1223=>['Udręczoną Była Lingwah','Trzymaj prochy Lingwah przez maksymalnie 10...60 sek. Kiedy je trzymasz, wszystkie klątwy Rytualisty kosztują o 1...5 mniej energii i trwają 50% dłużej. Gdy upuścisz jej prochy, wszystkie twoje klątwy Rytualisty zostaną odnowione.','(10...60 sek.) Twoje klątwy Rytualisty kosztują o 1...5 mniej energii i trwają 50%. Efekt upuszczenia: wszystkie twoje klątwy Rytualisty zostaną odnowione.'],
1224=>['Przemieszczenie Ducha','Przenosisz wybranego sojuszniczego ducha do miejsca, w którym się znajdujesz.','Przenosisz wybranego sojuszniczego ducha do miejsca, w którym się znajdujesz.'],
1225=>['Połączone Uderzenie','Wybrany przeciwnik otrzymuje 5...95 pkt. obrażeń od błyskawic. Ten przeciwnik otrzymuje dodatkowe 5...35 pkt. obrażeń od błyskawic, jeżeli trzymasz przedmiot.','Zadaje 5...95 pkt. obrażeń od błyskawic. Zadaje 5...35 pkt. dodatkowych obrażeń od błyskawic, jeżeli trzymasz przedmiot.'],
1226=>['Uderzenie Duchowego Daru','Wybrany przeciwnik otrzymuje 20...65 obrażeń od błyskawic, a wszystkie duchy pod twoją kontrolą w zasięgu słuchu zyskują 20...65 pkt. żywotności.','Zadaje 20...65 pkt. obrażeń od błyskawic. Kontrolowane przez ciebie duchy w zasięgu słuchu otrzymują po 20...65 pkt. żywotności.'],
1227=>['Uderzenie Esencji','Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od błyskawic. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, zyskujesz 1...9 pkt. energii.','Zadaje 15...60 pkt. obrażeń od błyskawic. Otrzymujesz 1...9 pkt. energii, jeżeli w zasięgu słuchu jest jakiś duch.'],
1228=>['Duchowe Wysysanie','Duch znajdujący się najbliżej ciebie traci całą energię. Otrzymujesz 30...60% tej energii.','Duch znajdujący się najbliżej ciebie traci całą energię. Otrzymujesz 30...60% tej energii.'],
1229=>['Wybuchowy Byt','Przez 15...60 sek., za każdym razem, kiedy tworzysz kreaturę, maksymalnie 5 przeciwników w pobliżu tej kreatury otrzymuje 20...65 pkt. obrażeń od błyskawicy.','(15...60 sek.) Za każdym razem, kiedy stworzysz stworzenie, umiejętność zadaje po 20...65 pkt. obrażeń od błyskawic 5 przeciwnikom w pobliżu tego stworzenia.'],
1230=>['Dar Tworzenia','Przez 15...60 sek., za każdym razem, kiedy tworzysz kreaturę, zyskujesz +5...50 pkt. żywotności oraz 1...6 pkt. energii.','(15...60 sek.) Otrzymujesz 5...50 pkt. żywotności i 1...6 pkt. energii, za każdym razem, kiedy stworzysz stworzenie.'],
1231=>['Duchowe Połączenie','Przez 12 sek., otrzymujesz +1...6 do regeneracji energii. Jeśli podczas rzucania tego czaru w zasięgu słuchu znajduje się duch, otrzymujesz 3...12 pkt. energii.','(12 sek.) Otrzymujesz +1...6 do regeneracji energii. Efekt początkowy: jeśli w zasięgu słuchu znajduje się duch, otrzymujesz 3...12 pkt. energii.'],
1232=>['Zbroja Nieczułości','Przez 10...35 sek., twoje duchy w zasięgu słuchu otrzymują 50% mniej obrażeń i są odporne na trafienia krytyczne.','(10...35 sek.) Twoje duchy w zasięgu słuchu otrzymują 50% mniej obrażeń i są odporne na trafienia krytyczne.'],
1233=>['Kojące Wspomnienia','Uzdrawiasz wybranego sojusznika dodając 10...100 pkt. żywotności. Jeżeli trzymasz przedmiot, otrzymujesz 3 pkt. energii.','Dodaje 10...100 pkt. żywotności. Otrzymujesz 3 pkt. energii, jeżeli trzymasz przedmiot.'],
1234=>['Odnowa Ciała i Duszy','Wybrany sojusznik otrzymuje 20...115 pkt. żywotności. Sojusznik ten traci jedną przypadłość za każdego ducha w zasięgu słuchu.','Dodaje 20...115 pkt. żywotności. Usuwa jedną przypadłość na każdego ducha w zasięgu słuchu.'],
1235=>['Stępiony Oręż','Przez 5...20 sek., wybrany przeciwnik i wszyscy sąsiadujący wrogowie nie mogą wykonać krytycznego trafiania i zadają 3...20 pkt. obrażeń mniej.','Klątwa działa także na przeciwników w bezpośrednim sąsiedztwie celu (5...20 sek.). Neguje zdolność wykonywania trafień krytycznych. Zmniejsza obrażnia o 3...20.'],
1236=>['Unieruchamiające Łańcuchy','Przez 3 sek., wybrany przeciwnik i wszyscy wrogowie w pobliżu poruszają się 90% wolniej, a podczas ruchu otrzymują co sekundę 1...30 pkt. obrażeń.','Klątwa działa także na przeciwników w pobliżu twojego celu (3 sek.). Przeciwnicy ci poruszają się o 90% wolniej , a podczas ruchu otrzymują co sekundę 1...30 pkt. obrażeń.'],
1237=>['Bolesne Więzy','Przez 10...20 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu zostają przeklęci Bolesnymi Więzami i otrzymują 8...20 pkt. obrażeń za każdym razem, kiedy otrzymają uderzenie od ducha.','Klątwa działa także na przeciwników w pobliżu twojego celu (10...20 sek.). Duchy zadają tym przeciwnikom 8...20 pkt. dodatkowych obrażeń.'],
1238=>['Sygnet Tworzenia','Otrzymujesz 4 pkt. energii za każde przywołane i kontrolowane przez ciebie stworzenie w zasięgu słuchu (maksymalnie 3...12 pkt. energii).','Otrzymujesz 4 pkt. energii (maksymalnie 3...12) za każde przywołane i kontrolowane przez ciebie stworzenie w zasięgu słuchu.'],
1239=>['Sygnet Duchów','Tworzysz trzy duchy na poziomie 1...12. Ataki tych duchów zadają po 5...20 pkt. obrażeń. Duchy giną po 60 sek.','Tworzy trzy duchy na poziomie 1...12 (czas życia 60 sek.). Ich ataki zadają 5...20 pkt. obrażeń.'],
1240=>['Skręcenie Duszy','Przez 5...45 sek., twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się natychmiast. Skręcenie Duszy kończy się po przeprowadzeniu rytuałów spętania (w liczbie 1...3).','(5...45 sek.) Twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się natychmiast. Kończy się po przeprowadzeniu rytuałów spętania (w liczbie 1...3).'],
1244=>['Duchowy Pośpiech','Przez 5...30 sek. rzucane czary odnawiają się o 25% szybciej, jeżeli znajdujesz się w okolicy ducha.','(5...30 sek.) Czary, które rzucasz odnawiają się o 25% szybciej. Bez efektu, jeśli nie jesteś w zasięgu słuchu ducha.'],
1245=>['Spojrzenie z Zaświatów','Wybrany przeciwnik otrzymuje 20...65 pkt. obrażeń od błyskawic. Jeśli w zasięgu słuchu znajduje się duch, przeciwnik zostaje dodatkowo oślepiony na 2...6 sek.','Zadaje 20...65 pkt. obrażeń od błyskawic. Wywołuje ślepotę (2...6 sek.), jeżeli w zasięgu słuchu znajduje się duch.'],
1246=>['Gniew Przodków','Przez 1 sek. nic się nie dzieje. Kiedy umiejętność przestanie działać, wszyscy przeciwnicy bezpośrednio przy wybranym sojuszniku otrzymują po 5...110 pkt. obrażeń od błyskawic.','(1 sek.) Efekt końcowy: Przeciwnikom bezpośrednio przy wybranym sojuszniku zadaje po 5...110 pkt. obrażeń od błyskawic.'],
1247=>['Ból','Tworzysz 1...12 poziomowego ducha. Ataki tego ducha zadają 5...30 pkt. obrażeń. Ten duch ginie po 30...150 sek.','Tworzy ducha na poziomie 1...12 (czas życia 30...150 sek.). Jego ataki zadają 5...30 pkt. obrażeń.'],
1249=>['Przemieszczenie','Tworzysz 1...14 poziomowego ducha. Wszyscy sojusznicy nie-duchy w jego zasięgu mają 75% szans na blokowanie ataków. Za każdym razem, gdy atak zostanie w ten sposób zablokowany, duch otrzyma 60 pkt. obrażeń. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu mają 75% szans na blokowanie. Efekt zablokowania: ten duch otrzymuje 60 pkt. obrażeń.'],
1250=>['Zabezpieczenie','Tworzysz 1...14 poziomowego ducha. Co 4 sek. ten duch leczy jednego nie będącego duchem sojusznika w okolicy dodając mu 10...115 pkt. żywotności. Ten duch ginie po 90 sek.','Tworzy ducha na poziomie 1...14 (czas życia 90 sek.). Co 4 sek. ten duch leczy jednego sojusznika nie-ducha, dodając mu 10...115 pkt. żywotności.'],
1251=>['Życie','Tworzysz 1...14 poziomowego ducha. Gdy ten duch ginie, wszyscy nie będący duchami sojusznicy w jego zasięgu otrzymują 1...7 pkt. żywotności za każdą sekundę życia tego ducha. Ten duch ginie po 20 sek.','Tworzy ducha na poziomie 1...14 (czas życia 20 sek.). Działa na sojuszników nie-duchy w zasięgu. Efekt końcowy: dodaje 1...7 pkt. żywotności na każdą sekundę życia tego ducha.'],
1252=>['Uziemienie','Tworzysz 1...14 poziomowego ducha. Wszyscy nie będący duchami przeciwnicy powaleni w zasięgu tego ducha, zostają powaleni na przynajmniej 3 sek. Za każdym razem, kiedy tak się dzieje, ten duch traci 50...25 pkt. żywotności. Ten duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...14 (czas życia 15...45 sek.). Za każdym razem, kiedy przeciwnik nie-duch w zasięgu zostanie powalony, będzie powalony przez przynajmniej 3 sek. Koszt powalenia: ten duch traci 50...25 pkt. żywotności.'],
1253=>['Pieśń Krwi','Tworzysz ducha na poziomie 1...12, który ginie po 30...150 sek. Ataki tego ducha wykradają do 5...25 pkt. żywotności.','Tworzy ducha na poziomie 1...12 (czas życia 30...150 sek.). Jego ataki wykradają 5...25 pkt. żywotności.'],
1255=>['Żądza Wędrowania','Tworzysz 1...12 poziomowego ducha. Za każdym razem, kiedy ten duch trafia stojącego w miejscu przeciwnika, ten przeciwnik zostaje powalony, a duch traci 70...50 pkt. żywotności. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...12 (czas życia 30...60 sek.). Jego ataki powalają przeciwników stojących w miejscu. Koszt powalenia: ten duch traci 70...50 pkt. żywotności.'],
1257=>['Oręż Duchowego Światła','Przez 10 sek. wybrany sojusznik otrzymuje co sekundę 5...25 pkt. żywotności oraz dodatkowo 5...25 pkt. żywotności co sekundę, jeśli sojusznik ten znajduje się w pobliżu ducha.','(10 s). Cel otrzymuje 5...25 pkt. żywotności na sekundę. Dodatkowo leczy 5...25 pkt. na sekundę w zasięgu słuchu ducha.'],
1258=>['Brutalny Oręż','Na 10...40 sek. wybrany sojusznik otrzymuje Brutalny Oręż. Dzierżący ten oręż zadaje +5...15 pkt. obrażeń tak długo, jak nie ma na sobie żadnego zaklęcia.','(10...40 sek.) Ataki zadają +5...15 pkt. obrażeń. Bez efektu, kiedy wybrany sojusznik jest pod wpływem zaklęcia.'],
1259=>['Prowadzony Oręż','Przez 4...10 sek., ciosy tego sojusznika nie mogą być blokowane.','(4...10 sek.) Ataków nie można blokować.'],
1260=>['Potulność','Przez 5...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w okolicy atakują o 50% wolniej.','Klątwa działa także na przeciwników w okolicy celu (5...30 sek.). Ci przeciwnicy atakują o 50% wolniej.'],
1261=>['Lodowata Zbroja','Na 10...25 sek., otrzymujesz +10...40 punktów pancerza przeciwko obrażeniom fizycznym i nie możesz w tym czasie zostać podpalony.','(10...25 sek.) Otrzymujesz +10...40 pkt. pancerza przeciwko obrażeniom fizycznym i niewrażliwość na płonięcie.'],
1262=>['Uzdrawiający Krąg','Stworzenia w bezpośredniej odległości otrzymują po 30...180 pkt. żywotności. Rzucający czar nie otrzymuje pkt. żywotności.','Sojusznikom i przeciwnikom w bezpośredniej odległości dodaje 30...180 pkt. żywotności. Rzucający czar nie otrzymuje pkt. żywotności.'],
1263=>['Odnowienie Życia','Wskrzeszasz wybranego dotkniętego martwego członka drużyny z 50% pkt. żywotności i 5...20% pkt. energii. On i wszyscy sojusznicy w zasięgu słuchu otrzymują 55...130 pkt. żywotności.','Wskrzesza wybranego członka drużyny (50% żywotności, 5...20% pkt. energii). Sojusznikom w zasięgu słuchu dodaje 55...130 pkt. żywotności.'],
1264=>['Zagłada','Zadaj wybranemu przeciwnikowi 10...60 pkt. obrażeń od błyskawic (maksymalnie 135) za każdy odnawiający się rytuał spętania, który posiadasz.','Zadaje 10...60 pkt. obrażeń od błyskawic (maksymalnie 135) za każdy odnawiający się rytuał spętania.'],
1265=>['Dar Posiadacza','Uzdrawiasz wybranego sojusznika dodając mu 15...60 pkt. żywotności. Jeżeli ten sojusznik posiada zaczarowaną broń, Dar Posiadacza dodaje dodatkowe 15...75 pkt. żywotności.','Dodaje 15...60 pkt. żywotności. Dodaje dodatkowo 15...75 pkt. żywotności, jeżeli ten sojusznik ma zaczarowaną broń.'],
1266=>['Ukojenie','Tworzysz 1...12 poziomowego ducha. Wszyscy przeciwnicy w jego zasięgu otrzymują adrenalinę dwa razy wolniej. Ten duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...12 (czas życia 15...45 sek.). Przeciwnicy w zasięgu dwa razy dłużej gromadzą adrenalinę.'],
1267=>['Życiodajny Oręż','Na 5...30 sek., wybrany sojusznik zyskuje Życiodajny Oręż, który zwiększa maksymalne pkt. żywotności o +40...175.','(5...30 sek.) +40...175 pkt. do maksymalnej żywotności.'],
1268=>['Oręż Przyspieszenia','Na 5...25 sek. wybrany sojusznik otrzymuje Oręż Przyspieszenia, który zwiększa o 33% szybkość odnawiania czarów i rytuałów spętania.','(5...25 sek.) Czary i rytuały spętania odnawiają się o 33% szybciej.'],
1269=>['Sygnet Szału','Wybrany przeciwnik otrzymuje 5...50 pkt. świętych obrażeń i 5...10 pkt. świętych obrażeń za każdą umiejętność opartą na adrenalinie, którą posiada.','Zadaje 5...50 pkt. świętych obrażeń. Zadaje 5...10 pkt. dodatkowych świętych obrażeń, za każdą umiejętność wybranego przeciwnika opartą na adrenalinie.'],
1333=>['Przedłużenie Przypadłości','Z wybranego przeciwnika przenosi wszystkie przypadłości na wszystkich przeciwników w pobliżu twojego celu. Czasy trwania tych przypadłości wydłużają się o 5...100% (maksymalnie 30 sek.).','Z wybranego przeciwnika przenosi wszystkie przypadłości na wszystkich przeciwników w pobliżu twojego celu. Czasy trwania tych przypadłości wydłużają się o 5...100% (maksymalnie 30 sek.).'],
1334=>['Hipochondria','Przenosi na cel wszystkie przypadłości ze wszystkich wrogów w okolicy.','Przenosi wszystkie przypadłości od wrogów w okolicy na wybranego przeciwnika.'],
1335=>['Upadek Marnotrawcy','Przez 5 sek., wybrany wróg zostaje dotknięty klątwą Upadku Marnotrawcy. Kiedy pozostaje pod działaniem klątwy, zarówno on jak i wszyscy wrogowie w jego bezpośrednim sąsiedztwie, otrzymują co sekundę 1...10 pkt. obrażeń oraz dodatkowe 1...10 pkt. za każdą sekundę działania tego czaru. Klątwa dobiega końca wcześniej, jeśli wybrany wróg użyje jakiejś umiejętności.','(5 sek.) Kiedy wybrany przeciwnik pozostaje pod działaniem klątwy, zarówno on jak i wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują co sekundę 1...10 pkt. obrażeń. Wrogowie otrzymują +1...10 pkt. obrażeń za każdą sekundę działania tej klątwy. Kończy się wcześniej, jeśli wybrany wróg użyje jakiejś umiejętności.'],
1336=>['Duchowy Ból','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Wszystkie wrogie przywołane stworzenia na obszarze w pobliżu wroga otrzymują 25...125 pkt. obrażeń.','Zadaje 15...75 pkt. obrażeń. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w rejonie wybranego przeciwnika.'],
1337=>['Wyssanie Urojeń','Zdejmujesz jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa została usunięta w ten sposób, to przeciwnik traci 1...5 pkt. energii, z kolei ty otrzymujesz 4 pkt. energii za każdy punkt stracony przez niego.','Z wybranego przeciwnika usuwa jedną klątwę mesmera. Powoduje utratę 1...5 pkt. energii. Otrzymujesz 4 pkt. energii za każdy punkt straconej energii. Bez efektu, chyba że została usunięta klątwa.'],
1338=>['Wytrwała Pamięć','Przez 5...20 sek., za każdym razem, kiedy czar, który rzucasz zostanie przerwany, czar natychmiast się odnowi.','(5...20 sek.) Twoje przerwane czary natychmiast się odnawiają.'],
1339=>['Symbole Inspiracji','Przez 6...40 sek. ta umiejętność staje się elitarną umiejętnością wybranego przeciwnika. Używane przez ciebie umiejętności elitarne wykorzystują atrybut Szybkie Rzucanie Czarów zamiast normalnego atrybutu.','(6...40 sek.) Ta umiejętność staje się elitarną umiejętnością wybranego przeciwnika. Używane przez ciebie umiejętności elitarne wykorzystują atrybut Szybkie Rzucanie Czarów zamiast normalnego atrybutu.'],
1340=>['Przyspieszenie Sygnetów','Przez 36...60 sek., wszystkie twoje sygnety używają wartości współczynnika Szybkiego Rzucania Czarów zamiast zwykłych atrybutów.','(36...60 sek.) Twoje sygnety używają współczynnika Szybkiego Rzucania Czarów.'],
1341=>['Frustracja','Przez 5...20 sek., wybrany przeciwnik rzuca czary o 50% wolniej i otrzymuje 5...50 pkt. obrażeń za każdym razem, kiedy jego akcja zostanie przerwana. Jeśli działanie umiejętności zostało przerwane, Frustracja zadaje podwójne obrażenia.','(5...20 sek.) Powoduje, że rzucanie czarów jest wolniejsze o 50%. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń, za każdym razem, kiedy jego czary zostaną przerwane. Zadaje podwójne obrażenia w momencie przerwania umiejętności.'],
1342=>['Dokuczliwość','Jeżeli wybrany przeciwnik używa umiejętności, aktualnie wykonywana czynność tego przeciwnika i czynność każdego przeciwnika w okolicy zostają przerwane. Dodatkowo wykradasz 0...5 energii od wszystkich wrogów w okolicy.','Przerywa umiejętność. Efekt przerwania: przerywasz także czynności innych wrogów w okolicy i wykradasz 0...5 energii od wszystkich wrogów w okolicy.'],
1343=>['Eteryczny Fantom','Przez 10 sek. wybrany przeciwnik posiada degenerację energii -1. Jeśli klątwa zostanie zdjęta przed tym czasem, to przeciwnik straci 1...5 pkt. energii.','(10 sek.) Powoduje degenerację energii -1. Powoduje utratę 1...5 pkt. energii, jeżeli klątwa przestanie przedwcześnie działać.'],
1344=>['Sieć Rozproszenia','Przerywasz czynność wybranego przeciwnika. Przez 10 sek., wybrany przeciwnik znajduje się pod działaniem klątwy Sieć Rozproszenia. Kiedy przestanie ona działać, czynność celu zostanie ponownie przerwana.','(10 sek.) Efekt początkowy: przerywa umiejętność. Efekt końcowy: przerywa umiejętność.'],
1345=>['Zagadka Zaklinacza','Przez 10 sek. wybrany przeciwnik rzuca zaklęcia 100...200% wolniej. Jeśli w momencie nałożenia klątwy wybrany przeciwnik nie znajduje się pod działaniem żadnego zaklęcia, przeciwnik ten odnosi 10...100 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Spowalnia o 100...200% rzucanie zaklęć (10 sek.). Początkowy efekt: jeśli wybrany przeciwnik nie jest pod wpływem zaklęcia, zadaje mu 10...100 pkt. obrażeń, a sąsiadującym z nim przeciwnikom zadaje 75% tych obrażeń.'],
1346=>['Sygnet Iluzji','Twoje następne nieiluzyjne czary (1...3) używają atrybutu Magia Iluzji, zamiast swojego normalnego atrybutu.','Twoje następne nieiluzyjne czary (1...3) używają atrybutu Magia Iluzji, zamiast swojego normalnego atrybutu.'],
1347=>['Rozładowanie Zaklęcia','Z wybranego przeciwnika zdejmujesz jedno zaklęcie. Jeśli przeciwnik jest pod działaniem klątwy, to umiejętność ta odnowi się o 20...50% szybciej.','Z wybranego przeciwnika usuwa jedno zaklęcie. Odnowa szybsza o 20...50%, jeżeli ten przeciwnik był pod działaniem klątwy.'],
1348=>['Wir Pożeracz Klątw','Z wybranego sojusznika usuwasz jedną klątwę. Jeśli klątwa zostanie usunięta w ten sposób, to każdy przeciwnik w pobliżu sojusznika otrzyma 30...90 pkt. obrażeń i straci jedno zaklęcie.','Usuwa z wybranego sojusznika jedną klątwę. Efekt usunięcia: Zadaje 30...90 pkt. obrażeń wrogom w pobliżu wybranego sojusznika i pozbawia ich po jednym zaklęciu.'],
1349=>['Zwierciadło Antyzaklęcia','Z wybranego przeciwnika zdejmujesz jedno zaklęcie. To samo zaklęcie tracą wszyscy członkowie drużyny tego przeciwnika.','Z wybranego przeciwnika usuwa jedno zaklęcie. To samo zaklęcie tracą członkowie drużyny wybranego przeciwnika.'],
1350=>['Łatwa Kradzież','Przerywa czynność przeciwnika. Jeżeli tą czynnością była umiejętność, to umiejętność ta będzie niedostępna przez 5...20 sek., a Łatwa Kradzież zostanie zastąpiona tą umiejętnością.','Przerywa czynność. Efekt przerwania: jeżeli tą czynnością była umiejętność, to umiejętność ta będzie niedostępna, a Łatwa Kradzież zostanie zastąpiona tą umiejętnością (5...20 sek.).'],
1351=>['Ożywienie Ociężałej Poczwary','Wykorzystujesz najbliższe zwłoki, by ożywić Ociężałą Poczwarę na 1...17 poz. Kiedy Ocieżała Poczwara zginie, zastępowany jest przez Strzępiastą Poczwarę na 0...15 poz., której ataki wywołują krwawienie.','Tworzy ociężałą poczwarę na poziomie 1...17. Kiedy ociężała poczwara zginie, zastępowana jest przez strzępiastą poczwarę na 0...15 poz., której ataki wywołują krwawienie. Zużywa świeże ciało.'],
1352=>['Rozkaz Ożywieńców','Przez 5 sek. twoje sługi zadają +3...16 pkt. obrażeń, ale za każdym razem, kiedy jeden z nich trafi, ty tracisz 2% swojej maksymalnej żywotności.','(5 sek.) Twoi nieumarli słudzy zadają +3...16 pkt. obrażeń. Efekt po trafieniu sługi: tracisz 2% twojej maksymalnej żywotności.'],
1353=>['Zgniłe Ciało','Niszczysz wybranego swojego nieumarłego sługę. Wszyscy przeciwnicy w pobliżu tego stworzenia na 5...15 sek. będą pod działaniem choroby.','Niszczy jednego z twoich nieumarłych sług. U przeciwników w pobliżu tego sługi wywołuje przypadłość choroba (5...15 sek.).'],
1354=>['Uczta Nieumarłych','Niszczysz wybranego, sojuszniczego nieumarłego sługę. Wszyscy twoi pozostali nieumarli sojusznicy otrzymują 10...100 punktów żywotności.','Niszczy jednego z twoich nieumarłych sług. Dodaje po 10...100 pkt. żywotności twoim sługom.'],
1355=>['Rozdzierające Kości','Przez 60 sek., kiedy zginie wybrany nieumarły sługa, zastąpi go Strzępiasta Poczwara na 0...15 poz., której ataki wywołują krwawienie.','(60 sek.) Kiedy wybrany nieumarły sługa zginie, zastępowany jest przez strzępiastą poczwarę na 0...15 poz., której ataki wywołują krwawienie.'],
1356=>['Zakażanie','Przez 60 sek., za każdym razem, kiedy zaczniesz cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczną cierpieć na tą samą przypadłość, a ty poświęcisz 10...5% swojej maksymalnej żywotności.','(60 sek.) Za każdym razem, kiedy otrzymujesz przypadłość, wszyscy przeciwnicy w okolicy otrzymują tą samą przypadłość. Za każdym razem, kiedy się to stanie, poświęcasz 10...5% maksymalnej żywotności.'],
1358=>['Wrzody Płuc','Przez 10...30 sek. wybrany przeciwnik i wszyscy przeciwnicy w pobliżu posiadają degenerację żywotności -4 podczas krwawienia i zaczną krwawić na 5...20 sek., kiedy tylko użyją okrzyku lub pieśni.','Klątwa działa także na przeciwników w pobliżu twojego celu (10...30 sek.). Powoduje degenerację żywotności -4 u przeciwników, którzy krwawią. Wywołuje przypadłość krwawienie (5...20 sek.), za każdym razem, kiedy ci przeciwnicy użyją okrzyku lub zaśpiewu.'],
1359=>['Ból Antyzaklęcia','Wybrany przeciwnik traci zaklęcia w liczbie 1...3. Jeżeli przeciwnik straci w ten sposób zaklęcie, to on i wszyscy przeciwnicy w bezpośredniej odległości tracą 10...100 pkt. żywotności.','Wybrany przeciwnik traci zaklęcia w liczbie 1...3. Efekt usunięcia: ten przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim tracą po 10...100 pkt. żywotności.'],
1360=>['Piętno Furii','Przez 5 sek., sojusznicy trafiający we wroga otrzymują dawki adrenaliny (0...2). Kiedy klątwa dobiegnie końca, trafiony przeciwnik znajdzie się na 1...15 sek. pod działaniem Pękniętej Zbroi.','(5 sek.) Sojusznicy trafiający wybranego przeciwnika otrzymują dawki adrenaliny w liczbie 0...2. Efekt końcowy: wywołuje pęknięcie zbroi (1...15 sek.)'],
1362=>['Skażenie Zaklęcia','Z wybranego przeciwnika zdejmujesz jedno zaklęcie. Jeżeli zaklęcie zostało zdjęte w ten sposób, to przez 10 sek. przeciwnik będzie posiadał degenerację żywotności -1...8.','Z wybranego przeciwnika usuwa jedno zaklęcie. Efekt usunięcia: degeneracja żywotności -1...8 (10 sek.).'],
1363=>['Sygnet Smutku','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Jeżeli wybrany przeciwnik znajduje się w pobliżu ciała lub jego zwierzak jest martwy, to umiejętność natychmiast się odnowi.','Zadaje 15...75 pkt. obrażeń. Natychmiast się odnawia, jeżeli wybrany przeciwnik znajduje się w pobliżu ciała lub jego zwierzęcy towarzysz jest martwy.'],
1364=>['Sygnet Cierpienia','Krwawisz przez 6 sek. Następna umiejętność nekromanty, która trafi we wrogi cel, spowoduje krwawienie przez 2...16 sek.','Krwawisz przez 6 sek. Powoduje krwawienie przeciwnika, który jest celem twojej następnej umiejętności nekromanckiej (2...16 sek.).'],
1365=>['Sygnet Zagubionych Dusz','Jeżeli wybrany przeciwnik ma mniej niż 50% pkt. żywotności, to otrzymujesz 10...100 pkt. żywotności i 1...10 pkt. energii.','Otrzymujesz 10...100 pkt. żywotności i 1...10 pkt. energii, jeżeli wybrany przeciwnik ma poniżej 50% żywotności.'],
1366=>['Studnia Ciemności','Wykorzystaj najbliższe zwłoki lub poświęć 66% swojej żywotności, by na 5...50 sek. utworzyć Studnię Ciemności. Przeciwnicy pod działaniem klątwy w zasięgu działania Studni Ciemności nie trafiają w 50% przypadków.','(5...50 sek.). Obłożeni klątwą przeciwnicy w tej studni mają 50% szans na chybienie. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
1367=>['Oślepiające Porażenie','Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od błyskawic, a także on i wszyscy przeciwnicy bezpośrednio przy nim zostają oślepieni na 3...8 sek. Ten czar posiada 25% przebicie pancerza.','Zadaje 5...50 pkt. obrażeń od błyskawic. U celu i u przeciwników bezpośrednio przy nim wywołuje przypadłość oślepienie (3...8 sek.). 25% przebicie pancerza.'],
1368=>['Lodowate Wiatry','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 30...60 pkt. obrażeń od zimna. Przez 10 sek. następna klątwa Magii Wody trafiająca przeklętego przeciwnika będzie trwać 25...100% dłużej.','(10 sek.) Następna klątwa wodna trafiająca przeklętego przeciwnika będzie trwać 25...100% dłużej. Efekt początkowy: 30...60 pkt. obrażeń od zimna. Zadaje obrażenia znajdującym się w sąsiedztwie.'],
1369=>['Błyskawica','Wystrzeliwujesz Błyskawicę, która po trafieniu zadaje 5...50 pkt. obrażeń od błyskawic. Jeżeli Błyskawicą zostanie trafiony poruszający się przeciwnik, to otrzyma on dodatkowe 5...50 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza.','Pocisk: zadaje 5...50 pkt. obrażeń od błyskawic. Zadaje 5...50 pkt. dodatkowych obrażeń od błyskawic, jeżeli wybrany przeciwnik jest w ruchu. 25% przebicie pancerza.'],
1370=>['Pośpiech Burzowego Dżinna','Przez 10...25 sek., poruszasz się o 25% szybciej. W każdej sekundzie, kiedy się poruszasz, tracisz 1 pkt. energii.','(10...25 sek.) Poruszasz się o 25% szybciej. Tracisz 1 pkt. energii w każdej sekundzie ruchu.'],
1371=>['Kamienny Napastnik','Przez 5...30 sek., za każdym razem, kiedy otrzymujesz lub zadajesz obrażenia od żywiołów lub fizyczne, obrażenia te zamieniane są na obrażenia od ziemi.','(5...30 sek.) Zamienia obrażenia fizyczne i obrażenia od żywiołów, jakie otrzymujesz, na obrażenia od ziemi.'],
1372=>['Burza Piaskowa','W miejscu, gdzie znajduje się wybrany przeciwnik wywołujesz Burzę Piaskową. Przez 10 sek., przeciwnicy w pobliżu co sekundę otrzymują 20...40 pkt. obrażeń od ziemi, co więcej przeciwnicy atakujący co sekundę otrzymują dodatkowe 10...30 obrażeń od ziemi.','W każdej sekundzie zadaje 20...40 pkt. obrażeń od ziemi (10 sek.). Trafia przeciwników w pobliżu początkowego miejsca wybranego przeciwnika. Co sekundę trafia atakujących przeciwników, zadając 10...30 pkt. dodatkowych obrażeń od ziemi.'],
1373=>['Kamienna Osłona','Przez 5...20 sek., ataki wykonywane przez wybranego przeciwnika i wszystkich przeciwników w pobliżu zadają obrażenia od ziemi i nie mogą powodować trafień krytycznych.','Klątwa działa także na przeciwników w pobliżu celu (5...20 sek.). Zamienia ataki na takie, które zadają obrażenia od ziemi i usuwa zdolność zadawania trafień krytycznych.'],
1374=>['Hebanowy Jastrząb','Wystrzeliwujesz pocisk, który po trafieniu zadaje wybranemu przeciwnikowi 10...85 pkt. obrażeń od ziemi i na 5...15 sek. powoduje u niego osłabienie.','Pocisk: zadaje 10...85 pkt. obrażeń i wywołuje osłabienie (5...15 sek.).'],
1375=>['Aura Kamiennego Ciała','Przez 5...15 sek., obrażenia, które otrzymujesz obniżane są o 1...31 pkt., a ty jesteś odporny na trafienia krytyczne.','(5...15 sek.) Obniża obrażenia, jakie otrzymujesz o 1...31 i stajesz się niewrażliwy na trafienia krytyczne.'],
1376=>['Glif Odnowy','Przez 15 sek. twoje następne 2 czary uzdrawiają cię dodając po 30...105 pkt. żywotności, dodatkowo jesteś uzdrawiany o 150...400% pkt. energii zużytych na te czary.','(15 sek.) Twoje następne 2 czary dodają ci 30...105 pkt. żywotności, dodatkowo jesteś uzdrawiany o 150...400% pkt. energii zużytych na te czary.'],
1377=>['Eteryczny Pryzmat','Przez 3 sek. wszystkie obrażenia jakie otrzymujesz są obniżane o 75%. Kiedy Eteryczny Pryzmat przestanie działać, otrzymujesz 5...20 pkt. energii.','(3 sek.) Wszystkie obrażenia jakie otrzymujesz są obniżane o 75%. Efekt końcowy: otrzymujesz 5...20 pkt. energii.'],
1378=>['Mistrz Magii','Przez 1...61 sek. wszystkie twoje atrybuty związane z żywiołami wynoszą 8...14 i twoje zaklęcia związane z żywiołami zwracają ci 1 pkt. energii oraz 30% ich kosztu.','(1...61 sek.) Wszystkie twoje atrybuty związane z żywiołami wynoszą 8...14 i twoje zaklęcia związane z żywiołami zwracają ci 1 pkt. energii oraz 30% ich kosztu.'],
1379=>['Rozżarzone Spojrzenie','Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od ognia. Jeżeli przeciwnik płonie, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Zadaje 5...50 pkt. obrażeń od ognia. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik płonie.'],
1380=>['Żar Sawanny','W miejscu, gdzie znajduje się wybrany przeciwnik tworzysz Żar Sawanny. Przez 5 sek. wszyscy przeciwnicy w pobliżu otrzymują co sekundę 5...20 pkt. obrażeń od ognia za każdą sekundę działania tego czaru.','W każdej sekundzie od rzucenia czaru zadaje 5...20 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca znajdowania się celu.'],
1381=>['Pośpiech Ognistego Dżinna','Przeciwnicy w bezpośredniej odległości otrzymują po 15...120 pkt. obrażeń od ognia. Przez 8...14 sek. poruszasz się o 25% szybciej. Pośpiech Ognistego Dżinna odnawia się o 50% szybciej, jeżeli efekty czaru dosięgły przeciwnika.','(8...14 sek.) Poruszasz się o 25% szybciej. Efekt początkowy: przeciwnikom bezpośrednio przy tobie zadaje po 15...120 pkt. obrażeń od ognia. Jeżeli czar zadał obrażenia przeciwnikowi, to odnawia się o 50% szybciej.'],
1382=>['Zamrażający Podmuch','Zadaje wybranemu przeciwnikowi 20...80 pkt. obrażeń od zimna. Jeśli przeciwnik ten jest po wpływem klątwy Magii Wody, otrzymuje dodatkowe 66 pkt. obrażeń od zimna.','Zadaje 20...80 pkt. obrażeń od zimna. Zadaje +66 pkt. obrażeń od zimna, jeśli przeciwnik znajduje się pod wpływem klątwy Magii Wody.'],
1390=>['Interwencja Sędziego','Przez 10 sek., kiedy następnym razem wybrany sojusznik ma otrzymać śmiertelne obrażenia, to są one negowane, a jeden przeciwnik w pobliżu otrzymuje 30...180 pkt. świętych obrażeń.','(10 sek.) Neguje następne śmiertelne obrażenia. Efekt zanegowania: przeciwnikowi w pobliżu wybranego sojusznika zadaje 30...180 pkt. świętych obrażeń.'],
1391=>['Wspierający Duch','Przez 5...23 sek., za każdym razem, kiedy wybrany sojusznik otrzyma obrażenia będąc powalonym, otrzyma 5...50 pkt. żywotności.','(5...23 sek.) Dodaje 5...50 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia będąc powalonym.'],
1392=>['Czujne Uzdrawianie','Przez 10 sek. wybrany sojusznik posiada regenerację żywotności równą +1...4. Jeżeli umiejętność przestanie działać przed tym czasem, to sojusznik otrzymuje 30...120 pkt. żywotności.','(10 sek.) Wybrany sojusznik posiada regenerację żywotności +1...4 i otrzymuje 30...120 pkt. żywotności, jeżeli to zaklęcie przedwcześnie przestanie działać.'],
1393=>['Dar Uzdrowiciela','Przez 10...55 sek. czary oparte na Modlitwach Uzdrawiających rzucasz o 50% szybciej i dodają one o 50% pkt. żywotności więcej.','(10...55 sek.) Czary z Modlitw Uzdrawiających rzucasz o 50% szybciej i dodają one o 50% więcej żywotności.'],
1394=>['Przymierze Uzdrowiciela','Podczas gdy utrzymujesz to zaklęcie, twoje czary Modlitw Uzdrawiających uzdrawiają o 20% pkt. żywotności mniej, ale kosztują o -1...4 pkt. energii mniej.','Twoje czary z Modlitw Uzdrawiających kosztują o 1...4 pkt. energii mniej. Te czary dodają o 20% mniej żywotności.'],
1395=>['Wahadło Baltazara','Przez 5...25 sek., następnym razem, gdy wybrany sojusznik ma zostać powalony przez przeciwnika, to przeciwnik zostaje powalony za niego.','(5...25 sek.) Powali następnego przeciwnika, który spróbuje powalić wybranego sojusznika.'],
1396=>['Słowa Otuchy','Uzdrawiasz wybranego sojusznika dodając mu 20...65 pkt. żywotności i dodatkowe 20...50 pkt. żywotności, jeśli cierpi na przypadłość.','Dodaje 20...65 pkt. żywotności. Dodatkowo dodaje 20...50 pkt. żywotności, jeśli wybrany sojusznik jest pod wpływem przypadłości.'],
1397=>['Światło Wybawienia','Uzdrawiasz wszystkich członków drużyny dodając każdemu 5...70 pkt. żywotności..','Każdemu członkowi drużyny dodaje 5...70 pkt. żywotności.'],
1398=>['Zgubne Zaklęcia','Przez 30 sek., za każdym razem, kiedy wybrany przeciwnik będzie celem zaklęcia, rzucający to zaklęcie otrzyma 15...75 pkt. obrażeń.','(30 sek.) Każdemu kto rzuca zaklęcie na wybranego przeciwnika zadaje 15...75 pkt. obrażeń.'],
1399=>['Pochłaniająca Tarcza','Przez 3...7 sek., za każdym razem, kiedy wybrany sojusznik zostanie trafiony będąc pod działaniem tego zaklęcia, obrażenia przez niego otrzymywane są obniżane o 5.','(3...7 sek.) Obniża otrzymywane obrażenia o 5, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia.'],
1400=>['Odwrócenie Obrażeń','Przez 8 sek., kiedy wybrany sojusznik będzie miał następnym razem otrzymać obrażenia, to w zamian otrzyma je przeciwnik, który je zadał (maksymalnie 5...75).','(8 sek.) Neguje następne obrażenia i zadaje źródłu tą samą liczbę pkt. obrażeń (maksymalnie 5...75).'],
1401=>['Odnawiający Dotyk','Dotknięty sojusznik traci dwie przypadłości i za każdą przypadłość usuniętą w ten sposób otrzymuje 15...60 pkt. żywotności.','Usuwa dwie przypadłości. Za każdą usuniętą przypadłość dodaje 15...60 pkt. żywotności.'],
1402=>['Krytyczne Cięcie','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeżeli atak spowodował trafienie krytyczne, przerywasz czynność wybranego przeciwnika.','Zadaje +5...20 pkt. obrażeń. Przerywa czynność, kiedy wykonasz trafienie krytyczne.'],
1403=>['Bolesne Cięcie','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli wybrany przeciwnik ma głęboką ranę, to przerywasz jego czynność.','Zadaje +5...20 pkt. obrażeń. Przerywa czynność, jeżeli wybrany przeciwnik ma głęboką ranę.'],
1404=>['Atak na Oślep','Przez 1...15 sek., atakujesz o 33% szybciej, ale poruszasz się o 33% wolniej.','(1...15 sek.) Atakujesz o 33% szybciej. Poruszasz się o 33% wolniej.'],
1405=>['Uderzenie w Szarży','Przez 1...10 sek. biegasz o 33% szybciej. Twoje kolejne trafienie wręcz zadaje +10...90 pkt. obrażeń, a ta postawa przestaje działać. Postawa przestanie działać, kiedy użyjesz umiejętności.','(1...10 sek.) Poruszasz się o 33% szybciej i w następnym celnym ataku wręcz zadajesz +10...90 pkt. obrażeń. Przestanie działać, kiedy trafisz lub jeśli użyjesz umiejętności.'],
1406=>['Uderzenie Głową','Wybrany dotknięty przeciwnik otrzymuje 40...100 pkt. obrażeń. Przez 10 sek. będziesz oszołomiony.','Zadaje 40...100 pkt. obrażeń. Jesteś oszołomiony (10 sek.).'],
1407=>['Lwie Uzdrowienie','Wszystkie twoje sygnety będą niedostępne przez 12 sek. Otrzymujesz 50...110 pkt. żywotności i dawki adrenaliny w liczbie 0...3.','Otrzymujesz 50...110 pkt. żywotności i dawki adrenaliny w liczbie 0...3. Wyłącza twoje sygnety (12 sek.).'],
1408=>['Szał Ntouki','Otrzymujesz adrenalinę w liczbie dawek: 1...7. Przez 8 sek., za każdym razem, kiedy użyjesz umiejętności opartej na adrenalinie, umiejętność ta odnowi się po 3 sek.','Otrzymujesz dawki adrenaliny w liczbie 1...7. Przez 8 sek. umiejętność oparte na adrenalinie posiadają 3 sek. czas odnowienia.'],
1409=>['Uderzenie Mokele','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz dawki adrenaliny w liczbie: 2.','Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz dawki adrenaliny w liczbie 2.'],
1410=>['Harde Uderzenie','Jeśli ten atak trafi swój cel, zadajesz +1...20 pkt. obrażeń. Jeśli cel jest powalony na ziemię, zostaje oszołomiony na 1...8 sek.','Zadaje +1...20 pkt. obrażeń. Jeśli wróg jest powalony na ziemię, zostaje oszołomiony (1...8 sek.).'],
1411=>['Sygnet Wytrzymałości','Twoja maksymalna żywotność zwiększa się o +50...300 pkt. Ten sygnet przestanie działać z twoim kolejnym trafionym atakiem.','Twoja maksymalna żywotność zwiększa się o +50...300 pkt. Przestanie działać, jeśli twój atak trafi.'],
1412=>['"Jesteś Sam!"','Jeśli wybrany przeciwnik nie jest w pobliżu sojusznika, to na 8 sek. zostaje okulawiony i osłabiony.','Wywołuje przypadłości okulawienie oraz osłabienie (8 sek.). Bez efektu, jeżeli wybrany przeciwnik jest w pobliżu jednego ze swoich sojuszników.'],
1413=>['Wybuch Agresji','Przez 2...10 sek. atakujesz o 33% szybciej. Kiedy ta postawa przestanie działać, tracisz całą adrenalinę.','(2...10 sek.) Atakujesz o 33% szybciej. Efekt końcowy: tracisz całą adrenalinę.'],
1414=>['Wściekła Szarża','Twoja szybkość poruszania się rośnie o 25% na najbliższe 5...15 sek. Wściekła Szarża dobiega końca, gdy uda ci się trafić jakiś cel. Jeśli trafisz go atakiem wręcz, zyskujesz wtedy również impulsy adrenaliny (0...3).','(5...15 sek.) Poruszasz się 25% szybciej. Zyskujesz +0...3 adrealiny przy następnym ataku wręcz. <c x="SkillDull">Kończy się, gdy trafisz wroga.'],
1415=>['Okulawiające Cięcie','Jeśli atak trafi, twój cel zostanie okulawiony na 5...15 sek. i zaczyna krwawić przez 10...25 sek.','Wywołuje przypadłości okulawienie (5...15 sek.) i przypadłość krwawienie (10...25 sek.).'],
1416=>['Barbarzyńskie Podcięcie','Jeśli atak trafi, zadaje +5...30 pkt. obrażeń. Jeżeli nie przyjąłeś żadnej postawy, to twój cel przez 5...15 sek. będzie krwawił.','Zadaje +5...30 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...15 sek.), jeżeli nie przyjąłeś postawy.'],
1465=>['Przygotowany Strzał','Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń. Jeżeli jesteś pod działaniem przygotowania, otrzymujesz 1...9 pkt. energii.','Zadaje +10...25 pkt. obrażeń. Otrzymujesz 1...9 pkt. energii, jeżeli jesteś pod działaniem przygotowania.'],
1466=>['Płonąca Strzała','Jeżeli atak trafi, zadaje +10...30 pkt. obrażeń, a cel będzie płonął przez 2...8 sek.','Zadaje +10...30 pkt. obrażeń. Wywołuje przypadłość płonięcie (2...8 sek.).'],
1467=>['Wysoki Strzał','Jeśli strzała trafi, zadaje +10...35 pkt. obrażeń. Nie można jej zablokować, ale leci o 50% wolniej.','Zadaje +10...35 pkt. obrażeń. Nie do zablokowania. Ta strzała leci o 50% wolniej.'],
1468=>['Jedność w Ataku','Twój zwierzęcy towarzysz natychmiast rusza do wybranego celu i kiedy trafi swoim następnym atakiem, wywoła u niego krwawienie na 5...15 sek. Kiedy twój następny atak trafi, wybrany cel zostanie okulawiony na 5...15 sek.','Twój zwierzęcy towarzysz natychmiast rusza do wybranego celu i kiedy trafi swoim następnym atakiem, wywoła u niego przypadłość krwawienie (5...15 sek.). Wywołuje przypadłość okulawienie (5...15 sek.), kiedy twój następny atak trafi.'],
1469=>['Ogień Krzyżowy','Jeżeli atak trafi, wybrany przeciwnik otrzymuje +5...20 pkt. obrażeń. Jeżeli przeciwnik jest w pobliżu twojego sojusznika, to atak nie może zostać zablokowany.','Zadaje +5...20 pkt. obrażeń. Nie do zablokowania, jeżeli wybrany przeciwnik jest w pobliżu jednego z twoich sojuszników.'],
1470=>['Kolczaste Strzały','Przez 24 sek. twoje strzały wywołują krwawienie, które trwa 3...15 sek. W czasie aktywacji tej umiejętności posiadasz -40 pkt. pancerza.','(24 sek.) Twoje strzały wywołują przypadłość krwawienie (3...15 sek.). W czasie aktywacji tej umiejętności posiadasz -40 pkt. pancerza.'],
1471=>['Skupienie Padlinożercy','Przez 10 sek., jeżeli trafisz przeciwnika pod działaniem przypadłości, otrzymasz 3...12 pkt. energii.','(10 sek.) Jeżeli trafisz przeciwnika pod działaniem przypadłości, otrzymujesz 3...12 pkt. energii.'],
1472=>['Toksyczność','Tworzysz 1...10 poziomowego ducha. Zatrute lub chore stworzenia w jego zasięgu otrzymują degenerację żywotności -2. Duch ginie po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Zatrute lub chore stworzenia w zasięgu otrzymują degenerację żywotności -2.'],
1473=>['Ruchome Piaski','Tworzysz 1...10 poziomowego ducha. Wszystkie stworzenia nie-duchy w jego zasięgu tracą po jednym pkt. energii za każdym razem, kiedy zaatakują lub użyją umiejętności. Duch ginie po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Stworzenia tracą 1 pkt. energii, za każdym razem, kiedy atakują lub używają umiejętności. Nie działa na duchy.'],
1474=>['Objęcia Burzy','Przez 10 sek. poruszasz się o 25% szybciej. Postawa odnawia się za każdym razem, kiedy otrzymasz obrażenia od żywiołów.','(10 sek.) Poruszasz się o 25% szybciej. Odnowienie: za każdym razem, kiedy otrzymujesz obrażenia od żywiołów.'],
1475=>['Szybkość Trapera','Przez 5...30 sek. twoje pułapki odnawiają się o 25% szybciej i aktywują o 25% szybciej. Ta postawa przestanie działać z twoim kolejnym trafionym atakiem.','(5...30 sek.) Twoje pułapki odnawiają się o 25% szybciej i aktywują o 25% szybciej. Przestanie działać, jeśli twój atak trafi.'],
1476=>['Potykacz','Kiedy Potykacz zostanie uaktywniony, wszyscy przeciwnicy w pobliżu otrzymują 5...20 obrażeń przebijających. Okulawieni przeciwnicy zostają powaleni. Potykacz przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Przeciwnikom w pobliżu zadaje po 5...20 pkt. obrażeń przebijających. Powala okulawionych przeciwników. Łatwo przerwać.'],
1478=>['Odnawialny Udar','Przez 8 sek., wybrany przeciwnik otrzymuje co sekundę 2...12 pkt. obrażeń. Kiedy klątwa dobiegnie końca, otrzymujesz 1...8 pkt. energii.','(8 sek.) Co sekundę zadaje 2...12 pkt. obrażeń. Efekt końcowy: otrzymujesz 1...8 pkt. energii.'],
1479=>['Duchowa Ofiara','Otrzymujesz 8...17 pkt. energii. Jeżeli w zasięgu słuchu znajdują się jakieś duchy, nie poświęcasz punktów żywotności.','Otrzymujesz 8...17 pkt. energii. Nie poświęcasz żywotności, jeżeli w zasięgu słuchu jest jakiś duch.'],
1480=>['Duchowy Dar','Przez 60 sek., za każdym razem, kiedy stworzysz stworzenie, wszyscy sojusznicy w jego pobliżu otrzymują 5...50 pkt. żywotności i tracą jedną przypadłość.','(60 sek.) Za każdym razem, kiedy stworzysz stworzenie, wszyscy sojusznicy w pobliżu otrzymują 5...50 pkt. żywotności i tracą jedną przypadłość.'],
1481=>['Sygnet Śmiertelnego Paktu','Wskrzeszasz wybranego członka drużyny, który powraca do życia z tyloma punktami żywotności ile masz ich ty i 15...100% maksymalnej energii. Kiedy następnym razem ten sojusznik zginie w ciągu 120 sek., zginiesz i ty.','Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i 15...100% maksymalnej energii. W ciągu 120 sek. umrzesz, kiedy następnym razem zginie ten członek drużyny.'],
1482=>['Odzyskanie Esencji','Wszystkie twoje duchy giną. Otrzymujesz 5...20 pkt. energii, a wszystkie twoje rytuały spętania natychmiast się odnawiają, jeżeli w ten sposób zginie jakiś duch.','Giną wszystkie twoje duchy. Jeżeli w ten sposób zginie duch, otrzymujesz 5...20 pkt. energii, a wszystkie twoje Rytuały Spętania natychmiast się odnawiają.'],
1483=>['Wypędzające Uderzenie','Jeśli ten atak trafi, zadajesz +10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.','Zadaje 10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.'],
1484=>['Mistyczny Zamach','Jeśli ten atak dojdzie celu, zadajesz +3...12 pkt. obrażeń. Jeśli znajdujesz się pod wpływem zaklęcia, atak ten zadaje dodatkowe +3...12 pkt. obrażeń.','Zadaje +3...12 pkt. obrażeń. Zadaje +3...12 pkt. obrażeń, jeżeli jesteś pod wpływem zaklęcia.'],
1485=>['Atak Eremity','Jeśli atak trafi, zadaje +1...10 pkt. obrażeń i usuwa zaklęcie derwisza. Jeśli zostanie usunięte jakieś zaklęcie, zadajesz dodatkowe +1...10 pkt. obrażeń i uderzasz we wszystkich wrogów w bezpośrednim sąsiedztwie.','Zadaje +1...10 pkt. obrażeń i usuwa zaklęcie derwisza. Efekt usunięcia: Zadaje +1...10 pkt. obrażeń i uderza we wszystkich wrogów w bezpośrednim sąsiedztwie.'],
1486=>['Żniwo Przypadłości','Jeśli ten atak dojdzie celu, zadajesz +3...15 pkt. obrażeń. Każdy trafiony wróg traci 1 przypadłość. W przypadku każdego wroga, który straci przypadłość, wszyscy przeciwnicy w jego sąsiedztwie otrzymują 10...40 pkt. świętych obrażeń.','Zadaje +3...15 pkt. obrażeń. Trafieni wrogowie tracą 1 przypadłość. Efekt usunięcia: Wszyscy wrogowie w sąsiedztwie trafionego otrzymują 10...40 pkt. świętych obrażeń.'],
1487=>['Zamach Podwójnego Księżyca','Tracisz 1 zaklęcie derwisza i zyskujesz 10...50 pkt. żywotności. Jeśli stracisz w ten sposób jakieś zaklęcie, nie można zablokować twojego ataku, uderzasz dwukrotnie i otrzymujesz dodatkowe 10...70 pkt. żywotności.','Usuwa jedno z twoich zaklęć derwisza. Zyskujesz 10...50 pkt. żywotności. Efekt usunięcia: Dwukrotny atak, który nie może być zablokowany, oraz dodatkowe 10...70 żywotności.'],
1488=>['Zwycięski Zamach','Jeśli atak trafi, zadaje +5...25 pkt. obrażeń. Jeśli wybrany przeciwnik ma mniej żywotności niż ty, otrzymujesz 30...80 pkt. żywotności.','Zadaje +5...25 pkt. obrażeń. Otrzymujesz 30...80 pkt. żywotności za każdego trafionego przeciwnika, który ma mniej żywotności niż ty.'],
1489=>['Niepowstrzymywalny Zamach','Zadaje +3...15 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracisz w ten sposób jakieś zaklęcie, Niepowstrzymany Zamach nie może zostać zablokowany, usuwa postawę i zadaje dodatkowo +3...15 pkt. obrażeń.','Zadaje +3...15 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Nie do zablokowania, usuwa postawę, zadaje dodatkowo +3...15 pkt. obrażeń.'],
1490=>['Nabożny Szturm','Jeśli atak trafi, zadaje +10...20 pkt. obrażeń i usuwa 1 zaklęcie derwisza. Jeśli zaklęcie derwisza zostało usunięte, umiejętność ta odnawia się 75% szybciej, zaś wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.','Zadaje +10...20 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Umiejętność ta odnawia się 75% szybciej, a wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.'],
1491=>['Mistyczny Wir','Wszystkim przeciwnikom w pobliżu zadaje po 10...60 pkt. obrażeń od zimna. Jeśli znajdujesz się pod wpływem zaklęcia, czar ten zadaje dodatkowe 10...60 pkt. obrażeń od zimna.','Wszystkim przeciwnikom w pobliżu zadaje po 10...60 pkt. obrażeń od zimna. Zadaje 10...60 obrażeń od zimna więcej, jeśli jesteś pod wpływem zaklęcia.'],
1493=>['Palce Grentha','Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od zimna. Przez 30 sek., twoje ataki zadają obrażenia od zimna. Kiedy zaklęcie to dobiegnie końca, przekazujesz swoje przypadłości (1...2) wszystkim wrogom w pobliżu.','(30 sek.) Twoje ataki zadają obrażenia od zimna. Efekt początkowy: Zadaje 10...40 pkt. obrażeń od zimna pobliskim wrogom. Efekt końcowy: Przekazuje przypadłości (1...2) wszystkim wrogom w pobliżu.'],
1495=>['Ciernista Aura','Wszyscy wybrani przeciwnicy zaczynają krwawić przez 5...15 sek. Następnie, przez 30 sek. zaklęcie to nic nie robi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną okulawieni na 3...8 sek.','(30 sek.) Efekt początkowy: Powoduje krwawienie (5...15 sek.) u pobliskich wrogów. Efekt końcowy: Powoduje okulawienie (3...8 sek.) u pobliskich wrogów.'],
1496=>['Szał Baltazara','Wszyscy pobliscy przeciwnicy zostają podpaleni na 1...3 sek. Następnie, przez 20 sek. zaklęcie to nic nie robi. Kiedy zaklęcie dobiegnie końca, otrzymujesz dawki (1...2) adrenaliny, jeśli w zasięgu słuchu są jeszcze jacyś wrogowie.','(20 sek.) Efekt początkowy: Podpala (1...3 sek.) przeciwników w pobliżu. Efekt końcowy: Zyskujesz dawki adrenaliny (1...2), jeśli w zasięgu słuchu są jacyś wrogowie.'],
1497=>['Okrycie Pyłem','Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną oślepieni na 1...4 sek.','(30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Wywołuje oślepienie (1...4 sek.) u pobliskich wrogów.'],
1498=>['Nadzwyczajna Moc','Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie mają pękniętą zbroję przez 1...10 sek.','(30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Powoduje pęknięcie zbroi (1...10 sek.) pobliskich przeciwników.'],
1499=>['Nabożna Odnowa','Przez 8 sek. nic się nie dzieje. Kiedy zaklęcie to dobiegnie końca, Nabożna Odnowa zostaje doładowana i zyskujesz 0...5 pkt. energii oraz 0...30 żywotności.','(8 sek.) Efekt końcowy: Odnawia się, zaś ty zyskujesz 0...5 pkt. energii oraz 0...30 żywotności.'],
1500=>['Okrycie Mirażem','Przez 20 sek. masz 40% szans na wykonanie bloku i dodatkowe 4...10% za każde dodatkowe zaklęcie (maks. 80%). Wszyscy pobliscy przeciwnicy otrzymują 10...40 pkt. obrażeń od ziemi za każdym razem, gdy jest z ciebie usuwane zaklęcie derwisza.','(20 sek.) 40% nas na wykonanie bloku i dodatkowe 4...10% za każde kolejne zaklęcie. 10...40 pkt. obrażeń od ziemi zadawanych pobliskim wrogom, gdy tracisz zaklęcie derwisza.'],
1502=>['Tajemna Gorliwość','Przez 10 sek., za każdym razem, kiedy rzucasz czar, zyskujesz 2 pkt. energii za każde zaklęcie, które masz na sobie (maksymalnie 2...7 pkt. energii).','(10 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 2 pkt. energii (maksymalnie 2...7) za każde zaklęcie na tobie.'],
1503=>['Mistyczny Wigor','Przez 20 sek., za każdym razem, kiedy twój atak trafi, otrzymujesz 3...15 pkt. żywotności za każde zaklęcie, które masz na sobie (maksymalnie 25 pkt. żywotności).','(20 sek.) Za każdym razem, kiedy twój atak trafi, otrzymujesz 3...15 pkt. żywotności (maksymalnie 25) za każde zaklęcie na tobie.'],
1504=>['Czujna Interwencja','Przez 60 sek., kiedy obrażenia sprowadzą żywotność wybranego sojusznika poniżej 25%, otrzymuje on 50...200 pkt. żywotności.','(60 sek.) Dodaje 50...200 pkt. żywotności, kiedy następnym razem obrażenia sprowadzą żywotność wybranego sojusznika poniżej 25%.'],
1505=>['Ślub Pobożności','Przez 20 sek. otrzymujesz +24 do pancerza i +1...4 do regeneracji żywotności. Ślub Pobożności odnawia się za każdym razem gdy kończy się rzucone na ciebie zaklęcie.','(20 sek.) +24 do pancerza oraz +1...4 do regeneracji żywotności. Odnowienie: za każdym razem gdy kończy się rzucone na ciebie zaklęcie.'],
1506=>['Życiodajny Dar','Na 20 sek. twoja maksymalna żywotność wzrasta o +40...100 pkt. Kiedy zaklęcie przestanie działać, otrzymujesz 75...200 pkt. żywotności.','(20 sek.) Twoja maksymalna żywotność zwiększa się o +40...100 pkt. Efekt końcowy: otrzymujesz 75...200 pkt. żywotności.'],
1507=>['Serce Świętego Płomienia','Wszyscy przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Następnie, przez 30 sek. twoje ataki zadają święte obrażenia. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostają podpaleni na 2...5 sek.','(30 sek.) Twoje ataki zadają święte obrażenia. Efekt początkowy: Przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Efekt końcowy: Podpala (2...5 sek.) przeciwników w pobliżu.'],
1508=>['Przedłużenie Zaklęć','Przez 10 sek., twoje kolejne zaklęcie derwisza trwa 10...150% dłużej.','(10 sek.) Twoje kolejne zaklęcie derwisza trwa 10...150% dłużej.'],
1509=>['Interwencja Wiary','Interwencja Wiary przestanie działać, kiedy obrażenia sprowadzą twoją żywotność poniżej 50%. Kiedy zaklęcie przestanie działać, otrzymasz 30...150 pkt. żywotności.','Otrzymujesz 30...150 pkt. żywotności następnym razem, kiedy twoja żywotność spadnie poniżej 50%.'],
1510=>['Piaskowe Odłamki','Przez 30 sek. twoje kolejne (1...5) trafienia kosą zadają 10...60 pkt. obrażeń od ziemi wszystkim wrogom w bezpośrednim sąsiedztwie.','(30 sek.) Zadaje 10...60 pkt. obrażeń od ziemi wszystkim sąsiadującym wrogom za każdym razem, gdy atakujesz kosą. Kończy się po określonej liczbie ataków (1...5).'],
1512=>['Pośpiech Lyssy','Przez 3...15 sek., twoje zaklęcia derwisza odnawiają się o 33% szybciej. Kiedy uaktywnisz to zaklęcie, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. Kiedy to zaklęcie dobiegnie końca, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. 50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.','(3...15 sek.) Twoje zaklęcia derwisza odnawiają się 33% szybciej. Efekt początkowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. Efekt końcowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. (50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.)'],
1513=>['Wiodące Dłonie','Przez 20 sek., twoich kolejnych 0...3 ataków nie można zablokować Kiedy ta umiejętność zostaje uaktywniona, usuwa ślepotę.','(20 sek.) Twoje kolejne ataki (0...3) nie mogą zostać zablokowane. Efekt początkowy: Usuwa ślepotę.'],
1514=>['Ulotna Stabilność','Przez 4...10 sek., nie możesz zostać powalony i poruszasz się 25% szybciej. Zaklęcie to kończy się przed czasem, jeśli zapobiegnie powaleniu.','(4...10 sek.) Nie możesz zostać powalony i poruszasz się 25% szybciej. Kończy się, jeśli zapobiegnie powaleniu.'],
1515=>['Zbroja Świętości','Przez 5...15 sek., wszyscy sąsiadujący z tobą przeciwnicy zaczynają cierpieć na osłabienie. Przez 15 sek. przeciwnicy cierpiący na przypadłości zadają ci 5...20 pkt. obrażeń mniej.','Wywołuje osłabienie u wszystkich sąsiadujących z tobą wrogów (5...15). Przeciwnicy cierpiący na przypadłości zadają ci 5...20 pkt. mniej obrażeń (15).'],
1516=>['Mistyczna Regeneracja','Na 5...20 sek., otrzymujesz regenerację żywotności +1...4 na każde zaklęcie (maksymalnie 8), pod którego jesteś działaniem.','(5...20 sek.) Otrzymujesz regenerację żywotności +1...4 na każde zaklęcie (maksymalnie 8), pod którego jesteś działaniem.'],
1517=>['Ślub Milczenia','Przez 5...10 sek., nie możesz być celem czarów, ale i sam nie możesz ich rzucać.','(5...10 sek.) Nie możesz być celem czarów. Nie możesz rzucać czarów.'],
1518=>['Awatar Baltazara','Przez 10...90 sek., otrzymujesz +20 do pancerza przeciwko obrażeniom fizycznym, zyskujesz adrenalinę 25% szybciej, twoje ataki zadają święte obrażenia, a za każdym razem gdy stracisz zaklęcie derwisza, pobliscy wrogowie zostają podpaleni na 1...3 sek. Umiejętność zostaje zablokowana na 45 sekund.','(10...90 sek.) Otrzymujesz +20 do pancerza przeciwko obrażeniom fizycznym, zyskujesz adrenalinę 25% szybciej, twoje ataki zadają święte obrażenia oraz powodujesz płonięcie (1...3 sek.) pobliskich wrogów, za każdym razem gdy stracisz zaklęcia derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1519=>['Awatar Dwayny','Przez 10...90 sek. twoje ataki zadają święte obrażenia. Za każdym razem, gdy używasz umiejętności ofensywnej derwisza, tracisz 1 klątwę. Gdy stracisz zaklęcie derwisza, wszyscy sprzymierzeńcy w zasięgu słuchu odzyskają 5...50 pkt. żywotności. Ta umiejętność zostanie wyłączona na 45 sek.','(10...90 sek.) Zadajesz święte obrażenia. Za każdym razem, gdy używasz umiejętności ataku derwisza, tracisz 1 klątwę. Sprzymierzeńcy w zasięgu słuchu odzyskują 5...50 pkt. żywotności za każdym razem, gdy tracisz zaklęcie derwisza. Ta umiejętność zostanie wyłączona na 45 sek.'],
1520=>['Awatar Grentha','Przez 10...90 sek. twoje ataki kosą zadają obrażenia od ciemności i wykradają 0...12 żywotności. Zyskujesz niewrażliwość na choroby i przez 3 sek. wywołujesz choroby u wszystkich wrogów w bezpośrednim sąsiedztwie za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.','(10...90 sek.) Twoje ataki kosą zadają obrażenia od ciemności i wykradają 0...12 żywotności. Jesteś niewrażliwy na działanie chorób. Wywołujesz chorobę u wszystkich wrogów w bezpośrednim sąsiedztwie (3 sek.) kiedy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1521=>['Awatar Lyssy','Przez 10...90 sek., twoje zaklęcia derwisza odnawiają się o 50% szybciej, a twoje ataki zadają obrażenia od chaosu. Za każdym razem gdy stracisz zaklęcie derwisza, wykradasz 1 energii u wszystkich wrogów w bezpośrednim sąsiedztwie. Umiejętność zostaje zablokowana na 45 sekund.','(10...90 sek.) Twoje zaklęcia derwisza odnawiają się 50% szybciej, zaś ataki zadają obrażenia od chaosu. Kiedy stracisz zaklęcie derwisza, wykradasz 1 pkt. energii wszystkim pobliskim wrogom. Umiejętność zostaje zablokowana na 45 sekund.'],
1522=>['Awatar Melandru','Przez 10...90 sek., masz +150 do żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Za każdym razem gdy stracisz zaklęcie derwisza, wszyscy członkowie drużyny w zasięgu słuchu tracą 1 przypadłość. Umiejętność zostaje zablokowana na 45 sekund.','(10...90 sek.) Otrzymujesz +150 do maksymalnej żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Leczysz 1 przypadłość u wszystkich członków drużyny w zasięgu słuchu za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
1523=>['Medytacja','Tracisz całą adrenalinę. Przez 20 sek., za każdym razem, gdy skończy się działające na tobie zaklęcie, otrzymasz 1...4 pkt. energii.','(20 sek.) Tracisz całą adrenalinę. Otrzymujesz 1...4 za każdym razem, gdy skończy się rzucone na ciebie zaklęcie.'],
1524=>['Gorliwość Eremity','Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8). Następnie, przez 10 sek. zaklęcie to nic nie robi. Kiedy zaklęcie dobiegnie końca, za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8).','(10 sek.) Efekt początkowy: Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8). Efekt końcowy: Za każdego wroga w zasięgu słuchu otrzymujesz 1...3 pkt. energii (maksymalnie 8).'],
1525=>['Naturalne Uzdrawianie','Odzyskujesz 50...170 pkt. żywotności! Jeśli jesteś pod wpływem zaklęcia, czar ten uaktywnia się 50% szybciej.','Odzyskujesz 50...170 pkt. żywotności. Umiejętność ta uaktywnia się 50% szybciej, jeśli nie jesteś pod wpływem zaklęcia.'],
1526=>['Nasycenie Życiem','Wybrany sojusznik inny niż ty otrzymuje 5...50% twojej aktualnej żywotności (maksymalnie 300 pkt. żywotności).','Dodaje 5...50% twojej aktualnej żywotności (maksymalnie 300). Na cel nie można wybrać siebie.'],
1527=>['Mistyczne Uzdrowienie','Odzyskujesz 5...65 pkt. żywotności! Przywracasz także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.','Odzyskujesz 5...65 pkt. żywotności. Przywraca także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.'],
1528=>['Dotyk Dwayny','Dotknięty wybrany sojusznik otrzymuje 60 pkt. żywotności na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 60...240).','Dodaje 60 pkt. żywotności (maksymalnie 60...240) za każde zaklęcie, pod którego jesteś działaniem.'],
1529=>['Nabożne Przywrócenie','Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Jeśli usunięto w ten sposób zaklęcie, tracisz także klątwy w liczbie 1...3.','Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Efekt usunięcia: Tracisz klątwy w liczbie 1...3.'],
1530=>['Sygnet Nabożnego Światła','Usuwa jedno zaklęcie derwisza. Wybrany sojusznik odzyskuje 30...150 pkt. żywotności. Jeśli w ten sposób zostanie usunięte zaklęcie, sygnet ten odnowi się 75% szybciej.','Przywraca 30...150 pkt. żywotności. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Odnawia się 75% szybciej.'],
1531=>['Aura Zastraszenia','Przez 60 sek., masz zwiększoną maksymalną żywotność o +40...100 i otrzymujesz 1...10 pkt. obrażeń mniej od przeciwników z mniejszą żywotnością od ciebie.','(60 sek.) Masz zwiększoną maksymalną żywotność o +40...100 i otrzymujesz -1...10 pkt. obrażeń od przeciwników z mniejszą żywotnością od ciebie.'],
1532=>['Mistyczna Burza Piaskowa','W miejscu swojego pobytu tworzysz piaskową burzę, która trwa 3 sek. Co sekundę wrogowie w pobliżu tego miejsca otrzymują 10...40 pkt. obrażeń od ziemi. Atakujący wrogowie otrzymują dodatkowe 10...20 pkt. obrażeń. Jeśli w momencie rzucenia czaru znajdujesz się pod wpływem zaklęcia, działa on dwa razy dłużej.','(3 sek.) Zadaje co sekundę 10...40 pkt. obrażeń od ziemi. Zadaje dodatkowe 10...20 pkt. obrażeń atakującym wrogom. Trafia przeciwników w pobliżu twojego początkowego miejsca pobytu. Trwa dwa razy dłużej, jeśli znajdujesz się pod wpływem zaklęcia.'],
1533=>['Wiatr Antyzaklęcia','Usuwa jedno z twoich zaklęć derwisza. Jeśli zostało usunięte jakieś zaklęcie, wszyscy pobliscy wrogowie tracą 1 zaklęcie i otrzymują 20...80 pkt. obrażeń od zimna.','Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Wszyscy pobliscy wrogowie tracą 1 zaklęcie i otrzymują 20...80 pkt. obrażeń od zimna.'],
1534=>['Rozrywający Dotyk','Zadaje wybranemu przeciwnikowi 15...65 pkt. obrażeń od zimna. Tracisz 1 zaklęcie derwisza. Jeśli zostało usunięte jakieś zaklęcie, wybrany przeciwnik traci 1 zaklęcie, a ty otrzymujesz dawki (2) adrenaliny.','Zadaje 15...65 pkt. obrażeń od zimna. Utrata 1 zaklęcie derwisza. Efekt usunięcia: wybrany przeciwnik traci 1 zaklęcie, a ty otrzymujesz dawki (2) adrenaliny.'],
1535=>['Okulawiający Zamach','Jeżeli ten atak trafi przeciwnika, to zostaje on okulawiony na 3...12 sek. Umiejętność ta zadaje +3...15 pkt. obrażeń, jeśli przeciwnik się porusza.','(3...12 sek.) Powoduje okulawienie. Zadaje +3...15 pkt. obrażeń poruszającym się wrogom.'],
1536=>['Raniące Uderzenie','Jeśli ten atak dojdzie celu, zadajesz +5...20 pkt. obrażeń, docelowy wróg zaczyna krwawić przez 5...20 sek. i tracisz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, docelowy wróg otrzymuje także głęboką ranę na 5...20 sek.','Zadaje +5...20 pkt. obrażeń i powoduje krwawienie (5...20 sek.). Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Powoduje głęboką ranę (5...20 sek.).'],
1537=>['Nużące Uderzenie','Usuwasz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, wybrany wróg otrzymuje głęboką ranę na 3...10 sek. Jeśli nie doszło do usunięcia zaklęcia, zostajesz osłabiony na 10 sekund.','Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Wywołuje głęboką ranę (3...10 sek.). Jeśli nie doszło do usunięcia zaklęcia, zostajesz osłabiony (10 sek.).'],
1538=>['Natarcie Lyssy','Jeśli ten atak trafi, powoduje przerwanie akcji. Jeśli znajdujesz się pod wpływem zaklęcia, każda umiejętność, którą przerwiesz, zostanie wyłączona na kolejne 1...10 sek. Ten atak zadaje 50% pkt. normalnych obrażeń.','Przerywa czynność przeciwnika. Jeśli znajdujesz się pod wpływem zaklęcia, przerwana umiejętność zostanie wyłączona na kolejne 1...10 sek. Ten atak zadaje 50% pkt. normalnych obrażeń.'],
1539=>['Lodowate Zwycięstwo','Jeśli atak dojdzie celu, zadaje +3...15 pkt. obrażeń. Za każdego trafionego wroga, który miał mniej żywotności od ciebie, dany wróg oraz wszyscy przeciwnicy w jego sąsiedztwie otrzymują 10...30 pkt. obrażeń od zimna.','Zadaje +3...15 pkt. obrażeń. Zadaje 10...30 pkt. obrażeń od zimna każdemu wrogowi, który ma mniej żywotności od ciebie, oraz wszystkim przeciwnikom w jego sąsiedztwie.'],
1540=>['Pewność Siebie','Przez 10 sek., otrzymujesz +10 do pancerza, jeśli masz jakąś przypadłość, oraz otrzymujesz 1...3 pkt. do regeneracji żywotności za każdą przypadłość, pod której wpływem jesteś. Kiedy to zaklęcie dobiega końca, zostajesz wyleczony z 1...2 przypadłości.','(10 sek.) Otrzymujesz +10 do pancerza będąc pod wpływem jakieś przypadłości. Otrzymujesz 1...3 pkt. żywotności za każdą przypadłość, pod której jesteś wpływem. Efekt końcowy: Usuwa 1...2 przypadłości.'],
1541=>['Zaklęty Pośpiech','Przez 7 sek., poruszasz się o 25% szybciej. Jeśli zaklęcie to zakończy się przedwcześnie, tracisz przypadłości (1).','(7 sek.) Poruszasz się 25% szybciej. Tracisz przypadłości (1), jeśli to zaklęcie zakończy się przedwcześnie.'],
1542=>['Nabożna Koncentracja','Przez 5...20 sek., twoje czynności nie mogą być przerywane, ale za każdym razem, gdy miałyby być przerwane, tracisz 1 zaklęcie derwisza albo Nabożna Koncentracja przestanie działać.','(5...20 sek.) Zapobiega przerwaniom. Koszt zapobieżenia: Tracisz jedno zaklęcie derwisza lub Nabożna Koncentracja dobiega końca.'],
1543=>['Nabożny Pośpiech','Usuwasz 1 zaklęcie derwisza i przez 1...7 sek. poruszasz się 25% szybciej. Jeśli zostało usunięte zaklęcie, możesz biec 50% szybciej.','(1...7 sek.) Tracisz 1 zaklęcie derwisza i poruszasz się 25% szybciej. Efekt usunięcia: Biegasz 50% szybciej.'],
1544=>['Wirująca Szarża','Przez 1...6 sek., poruszasz się o 33% szybciej niż normalnie. Kiedy następnym razem trafisz wroga, wszyscy pozostali przeciwnicy w pobliżu otrzymują 10...60 pkt. obrażeń od zimna, a zaklęcie dobiega końca.','(1...6 sek.) Poruszasz się 33% szybciej. Zadaje 10...60 obrażeń od zimna wszystkim wrogom w pobliżu, kiedy następnym razem trafisz jakiegoś przeciwnika, a to zaklęcie się skończy.'],
1545=>['Próba Wiary','Zadaje 15...75 pkt. obrażeń i zdejmuje 1 zaklęcie z wybranego przeciwnika. Jeśli przeciwnik ten nie znajdował się pod wpływem zaklęcia, zostaje oszołomiony na 2...6 sek.','Zadaje +15...75 pkt. obrażeń od zimna i usuwa 1 zaklęcie. Wybrany wróg zostaje oszołomiony na 2...6 sek., jeśli nie znajdował się pod wpływem zaklęcia.'],
1546=>['Płomienna Włócznia','Jeżeli atak trafi, zadaje +5...25 pkt. obrażeń, a wybrany przeciwnik zostaje podpalony na 1...3 sek.','Zadaje +5...25 pkt. obrażeń. Wywołuje przypadłość płonięcie (1...3 sek.).'],
1547=>['Potężny Rzut','Twoja włócznia leci trzy razy szybciej. Jeśli trafi, zadajesz +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń. Ta włócznia leci trzy razy szybciej.'],
1548=>['Okrutna Włócznia','Jeśli atak trafi, zadaje +10...50 pkt. obrażeń. Jeśli trafi nieruchomego przeciwnika, na 5...20 sek. zadaje mu głęboką ranę.','Zadaje +10...50 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik nie porusza się.'],
1549=>['Rzut Grabieżcy','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi poruszającego się przeciwnika, zadaje 5...40 pkt. dodatkowych obrażeń.','Zadaje +5...20 pkt. obrażeń. Zadaje 5...40 pkt. dodatkowych obrażeń, jeżeli cel porusza się.'],
1550=>['Nieblokowalny Rzut','Jeśli atak trafi, zadajesz +10...40 pkt. obrażeń. Tego ataku nie można zablokować.','Zadaje +10...40 pkt. obrażeń. Nie do zablokowania.'],
1551=>['Włócznia Błyskawicy','Atakuje wszystkich przeciwników znajdujących się między tobą a celem. Jeśli atak trafi, zadaje +10...20 pkt. obrażeń od piorunów. Atak ma 25% penetracji pancerza.','Zadaje +10...20 pkt. obrażeń od piorunów. 25% penetracji pancerza. Atakuje wszystkich wrogów między tobą a twoim celem.'],
1552=>['Włócznia Zmęczenia','Jeśli atak trafi, zadaje +10...40 pkt. obrażeń. Przez 5 sek. będziesz osłabiony.','Zadaje +10...40 pkt. obrażeń. Jesteś osłabiony (5 sek.).'],
1553=>['Hymn Furii','Przez 10 sek., kiedy następnym razem każdy członek drużyny w zasięgu słuchu użyje umiejętności związanej z atakami, otrzyma dawki adrenaliny w liczbie 2...5.','(10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują dawki adrenaliny w liczbie 2...5'],
1554=>['Okulawiający Hymn','Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu okulawi przeciwnika na 5...15 sek.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem wywołują przypadłość okulawienie (5...15 sek.).'],
1555=>['Obronny Hymn','Przez 4...10 sek. każdy członek drużyny w zasięgu słuchu ma 50% szans na blokowanie ataków. Zaśpiew przestanie działać, kiedy członek drużyny trafi używając umiejętności związanej z atakami.','(4...10 sek.) Członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie. Przestanie działać, kiedy trafi umiejętność związana z atakiem.'],
1556=>['Boska Prędkość','Przez 5...20 sek. wszyscy sojusznicy w zasięgu słuchu i pod działaniem zaklęcia poruszają się o 25% szybciej.','(5...20 sek.) Sojusznicy w zasięgu słuchu poruszają się o 25% szybciej, kiedy są pod działaniem zaklęcia.'],
1557=>['Hymn Płomienia','Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego członka drużyny w zasięgu słuchu podpali przeciwnika na 1...5 sek.','(10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem wywołują przypadłość płonięcie (1...5 sek.).'],
1558=>['"Po Oczach!"','Przez 10 sek., następny atak wykonany przez każdego sojusznika w zasięgu słuchu ma dodatkowe 30...100% szans na trafienie krytyczne.','(10 sek.) Sojusznicy w zasięgu słuchu mają +30...100% szans na wykonanie trafienia krytycznego w czasie swojego następnego ataku.'],
1559=>['Hymn Zazdrości','Przez 10 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu zadaje +10...25 pkt. obrażeń przeciwnikom posiadającym więcej niż 50% pkt. żywotności.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem zadają +10...25 pkt. obrażeń. Dodatkowe obrażenia zadawane są tylko przeciwnikom, którzy mają więcej niż 50% żywotności.'],
1560=>['Pieśń Potęgi','Przez 5...20 sek. każdy sojusznik w zasięgu słuchu, do czasu, gdy użyje umiejętności, posiada regenerację energii 4.','(5...20 sek.) Sojusznicy w zasięgu słuchu posiadają regenerację energii +4. Przestanie działać, kiedy zostanie użyta umiejętność.'],
1561=>['Hymn Gorliwości','Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem umiejętności związanej z atakami, otrzyma 1...8 pkt. energii.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem otrzymują 1...8 pkt. energii.'],
1562=>['Aria Gorliwości','Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem czaru, otrzyma 1...6 pkt. energii.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym czarem otrzymują 1...6 pkt. energii.'],
1563=>['Liryk Gorliwości','Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem sygnetu, otrzyma 1...8 pkt. energii.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym sygnetem otrzymują 1...8 pkt. energii.'],
1564=>['Ballada Odnowy','Przez 10 sek., każdy sojusznik w zasięgu słuchu z następnym otrzymaniem obrażeń, dostanie 15...75 pkt. żywotności.','(10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują 15...75 pkt. żywotności, kiedy następnym razem otrzymają obrażenia.'],
1565=>['Chorał Odnowy','Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem okrzyku lub zaśpiewu, otrzyma 30...90 pkt. żywotności.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym okrzykiem lub zaśpiewem otrzymują 30...90 pkt. żywotności.'],
1566=>['Aria Odnowy','Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym rzuceniem czaru, otrzyma 30...90 pkt. żywotności.','(10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoim następnym czarem otrzymują 30...90 pkt. żywotności.'],
1567=>['Pieśń Koncentracji','Przez 10 sek. następna umiejętność używana przez każdego sojusznika w zasięgu słuchu nie może być przerwana.','(10 sek.) Następna umiejętność sojuszników w zasięgu słuchu nie może zostać przerwana.'],
1568=>['Hymn Naprowadzenia','Przez 10 sek. następna umiejętność związana z atakiem, używana przez każdego członka drużyny w zasięgu słuchu, nie może być zablokowana.','(10 sek.) Członkowie drużyny w zasięgu słuchu nie mogą zostać zablokowani ze swoją następną umiejętnością związaną z atakiem.'],
1569=>['Energetyzujący Chorał','Przez 10 sek. następny okrzyk lub zaśpiew każdego sojusznika w zasięgu słuchu kosztują o 3...7 pkt. energii mniej.','(10 sek.) Następny okrzyk lub zaśpiew sojuszników w zasięgu słuchu kosztuje o 3...7 pkt. energii mniej.'],
1570=>['Pieśń Oczyszczenia','Przez 20 sek. następne umiejętności w liczbie 1...6 używane przez każdego sojusznika w zasięgu słuchu usuwają z niego 1 przypadłość.','(20 sek.) Sojusznicy w zasięgu słuchu, ze swoimi następnymi umiejętnościami w liczbie 1...6 tracą jedną przypadłość.'],
1571=>['Aria Łamiąca Klątwy','Przez 10 sek. każdy sojusznik w zasięgu słuchu z następnym rzuceniem czaru, traci 1 klątwę.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym czarem tracą jedną klątwę.'],
1572=>['"Ustój!"','Przez 5...15 sek., następnym razem, gdy wybrany sojusznik inny niż ty ma zostać powalony, Wszyscy przeciwnicy w pobliżu otrzymują w zamian 15...75 pkt. obrażeń.','(5...15 sek.) Ochroni przed następnym powaleniem i zadaje 15...75 pkt. obrażeń wszystkim przeciwnikom w pobliżu wybranego sojusznika. Na cel nie można wybrać siebie.'],
1573=>['Bojaźń','Jeśli ta umiejętność trafi powalonego wroga, wróg ten zostaje oszołomiony na 5...15 sek.','Wywołuje przypadłość oszołomienie (5...15 sek.). Bez efektu, chyba że cel jest powalony.'],
1574=>['Trwała Harmonia','Przez 10...35 sek. zaśpiewy i okrzyki na wybranym sojuszniku nie-duchu trwają o 50% dłużej.','(10...35 sek.) Zaśpiewy i okrzyki na wybranym sojuszniku trwają o 50% dłużej. Na cel nie można wybrać ducha.'],
1575=>['Ognisty Finał','Przez 10...35 sek., za każdym razem, kiedy zaśpiew lub okrzyk przestaną działać na wybranym sojuszniku nie-duchu, wszyscy przeciwnicy bezpośrednio przy tym sojuszniku zaczną płonąć przez 1...7 sek.','(10...35 sek.) U przeciwników w bezpośredniej odległości wywołuje przypadłość płonięcie (1...7 sek.), za każdym razem, kiedy zaśpiew lub okrzyk przestanie działać na wybranym sojuszniku. Na cel nie można wybrać ducha.'],
1576=>['Płonący Zaśpiew','Przez 20 sek., jeśli wybrany sojusznik nie-duch trafi przeciwnika, który posiada więcej żywotności niż on, to przeciwnik ten zaczyna płonąć przez 1...3 sek. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','(20 sek.) Wywołuje przypadłość płonięcie (1...3 sek.), jeżeli wybrany sojusznik trafi przeciwnika z większą żywotnością. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1577=>['Finał Odnowy','Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, otrzymuje on 15...75 pkt. żywotności.','(10...35 sek.) Wybrany sojusznik otrzymuje 15...75 pkt. żywotności za każdym razem, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1578=>['Zaśpiew Ozdrowienia','Przez 15 sek. wybrany sojusznik nie-duch posiada regenerację żywotności +2...3. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','(15 sek.) Wybrany sojusznik posiada regenerację żywotności +2...3. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1579=>['Oczyszczający Finał','Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, traci on 1 przypadłość.','(10...35 sek.) Wybrany sojusznik traci jedną przypadłość, za każdym razem, kiedy przestaje na nim działać okrzyk lub zaśpiew. Na cel nie można wybrać ducha.'],
1580=>['Zaśpiew Odpędzenia Ostrzy','Przez 20 sek. wybrany sojusznik, który nie jest duchem, ma 5...20% szans na zablokowanie ataków. To echo jest ponownie nakładane za każdym razem, kiedy na danym sojuszniku przestanie działać zaśpiew lub okrzyk.','(20 sek.) Wybrany sojusznik ma 5...20% szans na zablokowanie ataków. Odnowienie: za każdym razem, kiedy na tym sojuszniku przestaje działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1581=>['Rozżarzony Sygnet','Jeżeli wybrany przeciwnik płonie, otrzymujesz 5...15 pkt. energii.','Otrzymujesz 5...15 pkt. energii, jeżeli wybrany przeciwnik płonie.'],
1583=>['Gorliwość Dowódcy','Na każdego przeciwnika w pobliżu otrzymujesz 2...4 pkt. energii (maksymalnie 8...12 pkt. energii).','Na każdego sojusznika w pobliżu otrzymujesz 2...4 pkt. energii (maksymalnie 8...12).'],
1584=>['Pocieszenie Dowódcy','Otrzymujesz 30...75 pkt. żywotności. Na każdego sojusznika w zasięgu słuchu otrzymujesz także +10...20 pkt. żywotności (maksymalnie 140 pkt.).','Otrzymujesz 30...75 pkt. żywotności. Na każdego sojusznika w zasięgu słuchu otrzymujesz także 10...20 pkt. żywotności (maksymalnie 140).'],
1585=>['Sygnet Synergii','Wybrany sojusznik inny niż ty otrzymuje 40...100 pkt. żywotności. Jeżeli nie jesteś pod działaniem zaklęcia, to także ty otrzymujesz 40...100 pkt. żywotności.','Wybranemu sojusznikowi dodajesz 40...100 pkt. żywotności. Ty także otrzymujesz 40...100 pkt. żywotności, jeżeli nie jesteś pod wpływem zaklęcia. Na cel nie można wybrać siebie.'],
1586=>['Anielska Ochrona','Przez 10 sek., za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 250...80 pkt. obrażeń na sekundę, uzdrawiany jest o liczbę punktów ponad tę wartość.','(10 sek.) W każdej sekundzie, w której wybrany sojusznik otrzymuje obrażenia powyżej 250...80 pkt., otrzymuje jednocześnie punkty żywotności w liczbie równej obrażeniom powyżej tej liczby. Na cel nie można wybrać siebie.'],
1587=>['Anielska Więź','Przez 10 sek., kiedy następnym razem sojusznik w zasięgu słuchu ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 20...200 pkt. żywotności. Anielska Więź przestaje działać na wszystkich pozostałych sojusznikach.','(10 sek.) Kiedy następnym razem sojusznik w zasięgu słuchu ma otrzymać śmiertelne obrażenia, to są one negowane i w zamian otrzyma on 20...200 pkt. żywotności. Przestaje działać na wszystkich pozostałych sojusznikach.'],
1588=>['Sygnet Wypalenia','Wszyscy członkowie drużyny tracą wszystkie przypadłości. Zaczynasz płonąć przez 1 sekundę na każdą przypadłość usuniętą w ten sposób.','Wszyscy członkowie drużyny tracą wszystkie przypadłości. Krwawisz (1 sek. na każdą usuniętą przypadłość).'],
1589=>['"Utrzymać pozycje!"','Przez 5...20 sek., wszyscy nieruchomi członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza.','(5...20 sek.) Członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeżeli się nie poruszają.'],
1590=>['"Prowadź!"','Przez 1...5 sek. na każdego sojusznika w zasięgu słuchu, wybrany sojusznik porusza się o 25% szybciej (maksymalnie 30 sek.).','Wybrany sojusznik porusza się o 25% szybciej przez 1...5 sek. (maksymalnie 30 sek.) na każdego sojusznika w zasięgu słuchu.'],
1591=>['"Pospieszcie się!"','Przez 5...20 sek. wybrany sojusznik inny niż ty porusza się o 33% szybciej. Umiejętność przestanie działać z kolejnym trafionym atakiem tego sojusznika.','(5...20 sek.) Wybrany sojusznik porusza się o 33% szybciej. Przestanie działać, jeśli wybrany sojusznik trafi. Na cel nie można wybrać siebie.'],
1592=>['"Jeszcze Tu Wrócimy!"','Wszyscy członkowie drużyny w zasięgu słuchu zostają wskrzeszeni i posiadają 25...50% żywotności oraz 5...20% energii.','Wszyscy członkowie drużyny w zasięgu słuchu zostają wskrzeszeni (25...50% żywotności oraz 5...20% energii).'],
1593=>['"Trzymać Się!"','Wszyscy sojusznicy w zasięgu słuchu i posiadający mniej niż 75% pkt. żywotności otrzymują 1...10 pkt. energii.','Sojusznicy w zasięgu słuchu otrzymują 1...10 pkt. energii. Działa tylko na sojuszników posiadających mniej niż 75% żywotności.'],
1594=>['"Pomocy!"','Wskazany sojusznik niebędący duchem zyskuje 15...90 pkt. zdrowia. Przez 1...10 sek. zaklęcia innych sojuszników, których celem jest ten sojusznik, są rzucane o 50% szybciej.','(1...10 sek.) Wskazany sojusznik niebędący duchem zyskuje 15...90 pkt. zdrowia, zaklęcia sojuszników rzucane na niego są rzucane o 50% szybciej.'],
1595=>['"Wycofać Się!"','Przez 4...10 sek. wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość zwiększa się o 33%. "Wycofać Się!" przestanie działać na sojuszniku z jego kolejnym trafionym atakiem.','(4...10 sek.) Wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość ruchu zwiększa się o 33%. Przestanie działać na sojusznika, jeśli jego atak trafi.'],
1596=>['"Nadchodzą!"','Przez 4...10 sek., wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.','(4...10 sek.) Wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.'],
1597=>['"Płoną!"','Przez 10 sek., sojusznicy w zasięgu słuchu otrzymują o 5...35% mniej obrażeń od płonących przeciwników.','(10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują od płonących przeciwników o 5...35% obrażeń mniej.'],
1598=>['"Nie Poddawajcie Się!','Przez 15 sek., wszyscy członkowie drużyny w zasięgu słuchu i mający mniej niż 75% pkt. żywotności, posiadają regenerację żywotności +1...5.','(15 sek.) Członkowie drużyny w zasięgu słuchu posiadają regenerację żywotności +1...5. Działa tylko na członków drużyny posiadających mniej niż 75% żywotności.'],
1599=>['To Tylko Draśnięcie!','Wybrany sojusznik inny niż ty traci wszystkie przypadłości. Jeżeli przypadłość została zdjęta w ten sposób, to przez 1...10 sek. sojusznik porusza się o 25% szybciej.','Z wybranego sojusznika usuwa wszystkie klątwy. Jeżeli przypadłość została usunięta, to ten sojusznik porusza się o 25% szybciej (1...10 sek.). Na cel nie można wybrać siebie.'],
1600=>['Kolczasta Włócznia','Jeśli atak trafi, twój cel zaczyna krwawić na 5...20 sek.','Wywołuje przypadłość krwawienie (5...20 sek.).'],
1601=>['Zajadły Atak','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli spowoduje trafienie krytyczne, na 5...15 sek. zadaje celowi głęboką ranę.','Zadaje +5...20 pkt. obrażeń. Z trafieniem krytycznym wywołuje przypadłość głęboka rana (5...15 sek.).'],
1602=>['Ogłuszające Uderzenie','Jeśli atak trafi, zadaje +10...50 pkt. obrażeń. Jeśli cel cierpi na przypadłość, zostaje dodatkowo oszołomiony na 4...10 sek.','Zadaje +10...50 pkt. obrażeń. Wywołuje przypadłość oszołomienie (4...10 sek.), jeżeli cel jest pod działaniem przypadłości.'],
1603=>['Bezlitosna Włócznia','Jeżeli atak trafi przeciwnika, który ma mniej niż 50% pkt. żywotności, to przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Wywołuje przypadłość głęboka rana (5...20 sek.). Bez efektu, chyba że cel ma mniej niż 50% żywotności.'],
1604=>['Rozpraszający Rzut','Jeżeli atak trafi przeciwnika cierpiącego na przypadłość, to czynność tego przeciwnika zostanie przerywana.','Przerywa czynności. Bez efektu, chyba że cel jest pod działaniem przypadłości.'],
1605=>['Dziki Rzut','Jeśli ten atak trafi, zadaje +5...20 pkt. obrażeń i przerywa postawę używaną przez wroga. Tego ataku nie można zablokować. Umiejętności nie dotyczące ataków włócznią są zablokowane na 3 sek.','Zadaje +5...20 pkt. obrażeń. Nieblokowalny. Przerywa postawę celu.Wyłącza umiejętności nie dotyczące ataków włócznią na 3 sek.'],
1633=>['Podłe Uderzenie','Jeśli atak trafi przeciwnika cierpiącego na przypadłość, zadajesz +10...30 pkt. obrażeń oraz wykonujesz trafienie krytyczne.','Jeżeli wybrany przeciwnik jest pod działaniem przypadłości, atak zadaje +10...30 pkt. obrażeń i jest trafieniem krytycznym.'],
1634=>['Wstrząsające Natarcie','Musi nastąpić po ataku drugą ręką. Jeśli trafi, zadajesz 5...50 pkt. obrażeń, a przeciwnik traci jedno zaklęcie. Atak nie może zostać zablokowany.','Zadaje 5...50 pkt. obrażeń. Usuwa jedno zaklęcie. Nie do zablokowania. Musi nastąpić po ataku drugą ręką.'],
1635=>['Uderzenie Złotej Czaszki','Jeśli jesteś pod działaniem zaklęcia i ten atak trafi, wybrany przeciwnik zostaje oszołomiony na 1...12 sek.','Wywołuje przypadłość oszołomienie (1...12 sek.). Bez efektu, jeśli nie jesteś pod działaniem zaklęcia.'],
1636=>['Uderzenie Czarnego Pająka','Musi trafić przeciwnika pod działaniem klątwy. Jeżeli atak trafi, zadaje +5...20 pkt. obrażeń, a wybrany przeciwnik zostaje zatruty na 5...20 sek.','Zadaje +5...20 pkt. obrażeń. Wywołuje przypadłość zatrucie (5...20 sek.). Musi trafić przeciwnika pod działaniem klątwy.'],
1637=>['Uderzenie Złotego Lisa','Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...30 pkt. obrażeń. Jeśli jesteś pod działaniem zaklęcia, to atak nie może zostać zablokowany.','Zadaje +10...30 pkt. obrażeń. Nie do zablokowania, jeżeli jesteś pod działaniem zaklęcia.'],
1638=>['Śmiercionośny Pośpiech','Przez 10...35 sek., czary o połowie zasięgu rzucane są w czasie o 5...50% krótszym i odnawiają się o 5...60% szybciej.','(10...35 sek.) Twoje czary o połowie zasięgu rzucane są w czasie o 5...50% krótszym i odnawiają się o 5...60% szybciej.'],
1639=>['Remedium Zabójcy','Przez 30 sek. kolejne użyte przez ciebie umiejętności związane z atakiem (w liczbie 1...10) usuwają po jednej przypadłości.','(30 sek.) Twoje następne umiejętności związane z atakami w liczbie 1...10 usuwają po jednej przypadłości.'],
1640=>['Obietnica Lisa','Przez 5...20 sek. twoich ataków nie można zablokować. Zaklęcie przestanie działać, jeśli nie trafisz przeciwnika.','(5...20 sek.) Twoich ataków nie można blokować. Przestanie działać, kiedy nie trafisz.'],
1641=>['Udawana Neutralność','Na 4...10 sek. otrzymujesz regenerację żywotności +7 i +80 pkt. pancerza. To zaklęcie przestanie działać z twoim kolejnym trafionym atakiem lub użytą umiejętnością.','(4...10 sek.) Posiadasz regenerację żywotności +7 i +80 pkt. pancerza. Przestanie działać, jeśli twój atak trafi lub użyjesz umiejętności.'],
1642=>['Ukryta Kolczatka','Twoje umiejętności spoza profesji zabójcy są wyłączone na 3 sekundy. Przez 1...10 sek. cel porusza się 50% wolniej. Gdy klątwa dobiega końca, cel zostaje okulawiony na 1...15 sek.','(1...10 s). Zmniejsza szybkość ruchu o 50%. Efekt kończący: nakłada przypadłość Okaleczenie (1...15 s). Twoje umiejętności spoza profesji zab&oacute;jcy są wyłączone (10 sekund).'],
1643=>['Atak na Zaklęcia','Musi nastąpić po ataku podwójnym. Wybrany przeciwnik traci wszystkie zaklęcia.','Usuwa wszystkie zaklęcia. Musi nastąpić po ataku podwójnym.'],
1644=>['Powalenie Marnotrawcy','Wykonujesz krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik nie używa umiejętności, to zostaje powalony. Wszystkie twoje ataki nie związane ze sztyletami zostają wyłączone na 10 sek.','Wykonujesz krok cienia do wybranego przeciwnika. Jeżeli wybrany przeciwnik nie używa umiejętności, to zostaje powalony. Wyłącza twoje ataki nie związane ze sztyletami (10 sek.).'],
1645=>['Kradzież Zaklęcia','Jeżeli dotknięty wybrany przeciwnik jest powalony, to traci jedno zaklęcie.','Usuwa jedno zaklęcie. Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
1646=>['Wróżba Śmierci','Przez 5...35 sek., następnym razem, kiedy obrażenia zmniejszą żywotność wybranego przeciwnika poniżej 50%, zadasz mu głęboką ranę na 5...20 sek. i wykonasz do niego krok cienia. Ten czar posiada zasięg dwa razy mniejszy niż zwykły czar.','(5...35 sek.) Wywołuje przypadłość głęboka rana (5...20 sek.), a następnym razem, kiedy obrażenia zmniejszą żywotność przeciwnika poniżej 50%, wykonujesz krok cienia do tego przeciwnika.'],
1647=>['Sygnet Toksycznego Szoku','Jeżeli wybrany przeciwnik jest zatruty, to otrzymuje 10...100 pkt. obrażeń.','Zadaje 10...100 pkt. obrażeń. Bez efektu, jeśli wybrany przeciwnik nie jest zatruty.'],
1648=>['Sygnet Zmroku','Wybrany przeciwnik traci jedno zaklęcie na każdą klątwę, pod której jest działaniem.','Usuwa jedno zaklęcie na każdą klątwę działającą na wybranego przeciwnika.'],
1649=>['Ścieżka Zabójcy','Przez następne 20 sek., kiedy dzierżysz sztylety, atakujesz o 5...20% szybciej i posiadasz +5...35% szans na wykonanie trafienia krytycznego.','(20 sek.) Kiedy dzierżysz sztylety, atakujesz o 5...20% szybciej i posiadasz +5...35% szans na wykonanie trafienia krytycznego.'],
1650=>['Spacer w Cieniu','Krok przez cienie do wybranego wroga. Przez 15 sek. nic się nie dzieje. Twoje umiejętności ataku zostają zablokowane na 1 sekundę, a postawy i zaklęcia na 10 sek. Kiedy działanie tej postawy zakończy się, wrócisz na początkową pozycję.','(15 sek.) Krok przez cienie do wybranego wroga. Efekt końcowy: powrót na początkową pozycję. Wyłącza twoje umiejętności ataku na 1 sekundę. Wyłącza zaklęcia i postawy na 10 sek.'],
1651=>['Ucieczka Śmierci','Wykonaj krok cienia do wybranego sojusznika. Jeżeli masz mniej pkt. żywotności niż on, to otrzymujesz 40...130 pkt. żywotności.','Otrzymujesz 40...130 pkt. żywotności, jeżeli posiadasz mniej żywotności niż wybrany sojusznik. Efekt początkowy: wykonujesz krok cienia do tego sojusznika. Na cel nie można wybrać siebie.'],
1652=>['Więzienie Cienia','Wykonujesz krok cienia do wybranego przeciwnika. Przez 1...7 sek., wybrany przeciwnik porusza się o 66% wolniej.','Wykonujesz krok cienia do wybranego przeciwnika. Ten przeciwnik porusza się o 66% wolniej (1...7 sek.).'],
1653=>['Zamiana','Wybrane, przyzwane stworzenie i ty zamieniacie się miejscami, wykonując krok cienia.','Wybrane, przyzwane stworzenie i ty zamieniacie się miejscami, wykonując krok cienia.'],
1654=>['Cieniste Połączenie','Wykonujesz krok cienia do wybranego sojusznika innego niż ty. Gdy przestaniesz utrzymywać to zaklęcie, wracasz do miejsca, gdzie zostało rzucone.','Wykonujesz krok cienia do wybranego sojusznika. Efekt końcowy: wracasz do swojego początkowego miejsca. Na cel nie można wybrać siebie.'],
1655=>['Cena Dumy','Przez 5 sek., kiedy wybrany przeciwnik użyje następnym razem umiejętności elitarnej, straci 3...15 pkt. energii.','(5 sek.) Powoduje utratę 3...15 pkt. energii, następnym razem, kiedy wybrany przeciwnik użyje umiejętności elitarnej.'],
1656=>['Powietrze Antyzaklęć','Z wybranego przeciwnika i wszystkich przeciwników w pobliżu zdejmujesz po jednym zaklęciu. Przez 5...20 sek. zaklęcia rzucane na tych przeciwników kończą się o 150...300% szybciej.','Klątwa działa także na przeciwników bezpośrednio przy celu (5...20 sek.). Z wybranego przeciwnika i przeciwników w pobliżu usuwa po jednym zaklęciu. Zaklęcia na tych przeciwnikach kończą się o 150...300% szybciej.'],
1657=>['Sygnet Niezgrabności','Jeśli wybrany przeciwnik atakuje, zarówno on, jak i wrogowie w jego sąsiedztwie przerywają wykonywanie akcji i otrzymują 15...60 pkt. obrażeń. Wszyscy przeciwnicy korzystający z umiejętności ataku zostają powaleni.','Przerywa atak wybranego przeciwnika i sąsiadujących z nim wrogów. Efekt przerwania: zadaje 15...60 pkt. obrażeń. Powala wrogów używających umiejętności ataku.'],
1658=>['Symboliczna Poza','Przez 5...20 sek. następny sygnet, który aktywujesz będzie się odnawiał o 20...80% szybciej.','(5...20 sek.) Twój następny sygnet odnawia się o 20...80% szybciej.'],
1659=>['Toksyczny Chłód','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń od zimna. Jeżeli wybrany przeciwnik jest pod wpływem klątwy lub zaklęcia, to zostaje zatruty na 10...25 sek.','Zadaje 15...75 pkt. obrażeń od zimna. Wywołuje przypadłość zatrucie (10...25 sek.), jeżeli wybrany przeciwnik jest pod działaniem klątwy lub przypadłości.'],
1660=>['Studnia Milczenia','Wykorzystaj wybrane zwłoki lub poświęć 66% swojej żywotności, by na 10...30 sek. utworzyć Studnię Milczenia. Przeciwnicy w zasięgu działania studni nie mogą używać okrzyków ani pieśni i otrzymują -1...4 degeneracji żywotności.','(10...30 sek.). Przeciwnicy w tej studni nie mogą korzystać z okrzyków i pieśni oraz mają degenerację żywotności -1...4. Zużywa świeże ciało lub poświęca 66% zdrowia.'],
1661=>['Błyszczący Kamień','Wystrzeliwujesz pocisk, który po trafieniu zadaje 5...50 pkt. obrażeń od ziemi. Jeżeli czar trafi osłabionego przeciwnika, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Pocisk: zadaje 5...50 pkt. obrażeń od ziemi. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik jest osłabiony.'],
1662=>['Wybuch Umysłu','Wybrany przeciwnik otrzymuje 15...60 pkt. obrażeń od ognia. Jeżeli masz więcej energii niż wybrany przeciwnik, zyskujesz 1...8 pkt. energii.','Zadaje 15...60 pkt. obrażeń od ognia. Otrzymujesz 1...8 pkt. energii, jeżeli masz więcej energii niż wybrany przeciwnik.'],
1663=>['Żywiołowy Płomień','Przez 10...35 sek., za każdym razem, kiedy nałożysz klątwę żywiołu na wybranego przeciwnika, zacznie on płonąć przez 1...5 sek.','(10...35 sek.) Powoduje podpalenie (przez 1...5 sek.) za każdym razem, kiedy rzucisz klątwę żywiołu na cel.'],
1664=>['Wywołanie Błyskawicy','Wybrany przeciwnik i maksymalnie dwóch innych przeciwników w jego pobliżu otrzymują po 10...90 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza. Jeżeli nie jesteś pod działaniem zaklęcia, ten czar powoduje wyczerpanie.','Zadaje 10...90 pkt. obrażeń od błyskawic. Trafia dwóch przeciwników w pobliżu celu. 25% przebicie pancerza. Powoduje wyczerpanie, jeśli nie masz na sobie zaklęcia.'],
1683=>['Zadumany Strażnik','Przez 5...11 sek. wybrany sojusznik ma 50% szans na blokowanie ataków przeciwników będących pod działaniem zaklęć.','(5...11 sek.) 50% szans na blokowanie przeciwników znajdujących się pod działaniem zaklęcia.'],
1684=>['Intuicja Skryby','Przez 10...35 sek., za każdym razem, kiedy użyjesz sygnetu, otrzymasz 3 pkt. energii.','(10...35 sek.) Otrzymujesz 3 pkt. energii, za każdym razem, kiedy użyjesz sygnetu.'],
1685=>['Święty Pośpiech','Przez 1...60 sek. czary oparte na Modlitwach Uzdrawiających rzucasz o 50% szybciej. To zaklęcie przestanie działać, kiedy rzucisz inne zaklęcie.','(1...60 sek.) Czary z Modlitw Uzdrawiających rzucasz o 50% szybciej. Przestanie działać, jeśli rzucisz zaklęcie.'],
1686=>['Przebłysk Światła','Uzdrawiasz wybranego sojusznika dodając mu 10...115 pkt. żywotności.','Dodaje 10...115 pkt. żywotności.'],
1687=>['Błogosławieństwo Gorliwości','Uzdrawiasz wybranego sojusznika dodając mu 30...180 pkt. żywotności. Jeżeli miał on mniej niż 50% punktów żywotności, otrzymujesz 7 pkt. energii.','Dodaje 30...180 pkt. żywotności. Otrzymujesz 7 pkt. energii, jeśli żywotność wybranego sojusznika była poniżej 50%.'],
1688=>['Zapał Obrońcy','Przez 10...30 sek., za każdym razem, kiedy wybrany przeciwnik trafi wykonując atak, otrzymujesz 2 pkt. energii.','(10...30 sek.) Otrzymujesz 2 pkt. energii, za każdym razem, kiedy wybrany przeciwnik trafi wykonując atak.'],
1689=>['Sygnet Mistycznego Gniewu','Za każde zaklęcie, które masz na sobie, wybrany przeciwnik otrzymuje 25 pkt. świętych obrażeń (maksymalnie 30...120 pkt. świętych obrażeń).','Zadaje 25 pkt. świętych obrażeń za każde zaklęcie, które masz na sobie (maksymalnie 30...120 pkt. świętych obrażeń).'],
1690=>['Sygnet Usunięcia','Jeżeli wybrany sojusznik jest pod działaniem zaklęcia, to traci jedną klątwę i jedną przypadłość.','Usuwa jedną przypadłość i jedną klątwę. Bez efektu, chyba że wybrany sojusznik jest pod wpływem zaklęcia.'],
1691=>['Przegnanie Przypadłości','Z wybranego sojusznika usuwasz jedną przypadłość. Jeżeli wybrany sojusznik jest pod działaniem zaklęcia, to otrzymuje 15...75 pkt. żywotności.','Usuwa przypadłość. Dodaje 15...75 pkt. żywotności, jeżeli wybrany sojusznik jest pod wpływem zaklęcia.'],
1692=>['Przeobrażanie Klątw','Z wybranego sojusznika usuwasz do 1...3 klątw. Za każdą klątwę usuniętą w ten sposób, sojusznik traci jedną przypadłość i otrzymuje 15...75 pkt. żywotności.','Usuwa klątwy w liczbie 1...3. Za każdą usuniętą klątwę, wybrany sojusznik traci jedną przypadłość i otrzymuje 15...75 pkt. żywotności.'],
1693=>['Kontratak','Jeśli atak trafi, zadajesz +5...35 pkt. obrażeń. Jeśli trafisz atakującego przeciwnika, otrzymujesz 2...6 pkt. energii.','Zadaje +5...35 pkt. obrażeń. Otrzymujesz 2...6 pkt. energii, jeżeli wybrany przeciwnik atakuje.'],
1694=>['Cios Łowcy Magów','Jeśli atak trafi, zadajesz +7...25 pkt. obrażeń. Jeśli twój cel jest pod działaniem zaklęcia, to atak ten nie może zostać zablokowany.','Zadaje +7...25 pkt. obrażeń. Nie do zablokowania, jeżeli wybrany przeciwnik ma na sobie zaklęcie.'],
1695=>['Żołnierskie Uderzenie','Jeśli atak trafi, zadajesz +10...40 pkt. dodatkowych obrażeń. Jeśli jesteś pod działaniem zaśpiewu lub okrzyku, to atak nie może zostać zablokowany.','Zadaje +10...40 pkt. obrażeń. Nie do zablokowania, jeżeli jesteś pod działaniem zaśpiewu lub okrzyku.'],
1696=>['Ścięcie Głowy','You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Uderzenie Łowcy Magów','Jeśli atak trafi, wybrany przeciwnik zostaje powalony. Jeśli twój cel jest pod działaniem zaklęcia, to atak ten nie może zostać zablokowany.','Powoduje powalenie. Nie do zablokowania, jeżeli wybrany przeciwnik jest pod wpływem zaklęcia.'],
1698=>['Postawa Żołnierza','Przez 5...15 sek., masz 75% szans na blokowanie ataków. Atakujesz 33% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.','(5...15 sek.) Masz 75% szans na blokowanie ataków. Atakujesz 33% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.'],
1699=>['Żołnierska Obrona','Przez 1...6 sek., kiedy będziesz pod działaniem okrzyku lub pieśni, masz 75% szans na blokowanie ataków. Otrzymujesz 1 dawkę adrenaliny za każdy zablokowany atak.','(1...6 sek.) Masz 75% szans na blokowanie, jeżeli jesteś pod działaniem pieśni lub okrzyku. Efekt bloku: otrzymujesz 1 dawkę adrenaliny.'],
1700=>['Szalona Obrona','Przez 8 sek., masz 75% szans na blokowanie ataków, ale otrzymujesz podwójne obrażenia.','(8 sek.) Masz 75% szans na blokowanie. Otrzymujesz podwójne obrażenia.'],
1701=>['Stabilna Postawa','Przez 10 sek., kiedy następnym razem będziesz miał zostać powalony, otrzymasz w zamian 1...7 pkt. energii i dawki adrenaliny w liczbie 1...4.','(10 sek.) Kiedy następnym razem będziesz miał zostać powalony, otrzymasz w zamian 1...7 pkt. energii i dawki adrenaliny w liczbie 1...4.'],
1702=>['Cięcie Stalowego Kła','Jeśli atak trafi, zadaje +1...31 pkt. obrażeń. Jeśli trafisz powalonego przeciwnika, otrzymujesz dawki adrenaliny w liczbie: 1...5.','Zadaje +1...31 pkt. obrażeń. Otrzymujesz dawki adrenaliny w liczbie 1...5, jeżeli wybrany przeciwnik jest powalony.'],
1719=>['Wrzeszczący Strzał','Jeśli atak trafi, zadaje +10...25 pkt. obrażeń. Jeżeli twój cel jest w zasięgu słuchu, będzie krwawił przez 5...20 sek.','Zadaje +10...25 pkt. obrażeń. Wywołuje przypadłość krwawienie (5...20 sek.), jeżeli wybrany przeciwnik jest w zasięgu słuchu.'],
1720=>['Ostra Strzała','Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli jest to trafienie krytyczne, zdajesz dodatkowe +5...25 pkt. obrażeń.','Zadaje +5...20 pkt. obrażeń. Zadaje +5...25 pkt. dodatkowych obrażeń, jeżeli wykonasz trafienie krytyczne.'],
1721=>['Jedność w Szale','Przez 3...15 sek., ty i twój zwierzęcy towarzysz atakujecie o 33% szybciej i poruszacie się o 25% szybciej.','(3...15 sek.) Ty i twój zwierzęcy towarzysz atakujecie o 33% szybciej i poruszacie się o 25% szybciej. Bez efektu, chyba że twój zwierzęcy towarzysz żyje.'],
1722=>['Rozwidlona Strzała','Jednocześnie wystrzeliwujesz w przeciwnika dwie strzały. Jeżeli masz na sobie zaklęcie lub klątwę, to wystrzeliwujesz tylko jedna strzałę.','Wystrzeliwujesz jednocześnie dwie strzały. Wystrzeliwuje tylko jedną strzałę, jeśli jesteś pod działaniem klątwy lub zaklęcia.'],
1723=>['Rozpraszająca Celność','Przez 36 sek., za każdym razem, kiedy zadajesz trafienie krytyczne, czynność twojego celu zostaje przerwana.','(36 sek.) Przerywa czynność, za każdym razem, kiedy twoje strzały powodują trafienie krytyczne.'],
1724=>['Mistrzowska Sprawność','Przez 1...20 sek. atakujesz o 33% szybciej, a twoje Umiejętności Strzeleckie zwiększają się o 2.','(1...20 sek.) Atakujesz o 33% szybciej i posiadasz +2 do Umiejętności Strzeleckich.'],
1725=>['Ryczące Wiatry','Tworzysz 1...10 poziomowego ducha. Pieśni i okrzyki kosztują o 1...5 pkt. energii więcej. Ten duch ginie po 30...180 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...180 sek.). Zaśpiewy i okrzyki stworzeń w zasięgu kosztują o 1...5 pkt. energii więcej.'],
1726=>['Strzał Zguby Magów','Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było rzucanie czaru, zostaje on wyłączony na dodatkowe 10 sek. Tego ataku nie można zablokować.','Przerywa czynność. Efekt przerwania: przerwany czar jest niedostępny przez +10 sek. Nie do zablokowania.'],
1727=>['Naturalny Krok','Przez 1...8 sek. biegasz o 33% szybciej i masz 50% szans na blokowanie ataków. Naturalny Krok przestanie działać, jeśli znajdziesz się pod działaniem klątwy lub zaklęcia.','(1...8 sek.) Poruszasz się o 33% szybciej i masz 50% szans na blokowanie. Przestanie działać, jeśli otrzymasz klątwę lub zaklęcie.'],
1728=>['Szał Heketa','Przez 5...11 sek. atakujesz o 33% szybciej. Postawa przestanie działać, kiedy użyjesz umiejętności związanej z atakami.','(5...11 sek.) Atakujesz o 33% szybciej. Przestanie działać, jeśli użyjesz umiejętności związanej z atakami.'],
1729=>['Pułapka Dymna','Kiedy Pułapka Dymna zostanie uaktywniona, przeciwnicy w okolicy zostają oślepieni i oszołomieni na 5...10 sek. Pułapka Dymna przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(90 sek.). Wywołuje przypadłość oślepienie i oszołomienie (na 5...10 sek.) u wrogów na obszarze działania. Łatwo przerwać.'],
1730=>['Rozwścieczający Żar','Tworzysz 1...10 poziomowego ducha. Stworzenia nie-duchy w jego zasięgu otrzymują podwójne dawki adrenaliny. Duch ginie po 30...120 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...120 sek.). Podwaja adrenalinę otrzymywaną przez stworzenia w zasięgu.'],
1731=>['Hałaśliwym Był Sogolon','Przez 60 sek. wszystkie okrzyki i pieśni, których używasz trwają o 20...50% dłużej.','(60 sek.) Okrzyki i zaśpiewy, których używasz trwają o 20...50% dłużej.'],
1732=>['Niszczycielską Była Glewia','Trzymaj prochy Glewii przez maksymalnie 30...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 20% do penetracji pancerza. Gdy upuścisz jej prochy, wszyscy przeciwnicy w okolicy otrzymają 15...85 pkt. obrażeń od błyskawic.','(30...60 sek.) Twoje umiejętności Rytualisty otrzymują 20% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w okolicy otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
1733=>['Uderzenie Posiadacza','Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od błyskawic. Jeśli posiadasz zaczarowaną broń, zadajesz dodatkowe 10...50 pkt. obrażeń od błyskawic.','Zadaje 10...60 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic, jeżeli jesteś pod działaniem zaczarowanej broni.'],
1734=>['Spojrzenie Furii','Niszczysz wybranego ducha i tworzysz 1...14 poziomowego Ducha Furii. Ataki tego ducha zadają 5...20 pkt. obrażeń. Duch ginie po 30...60 sek.','Niszczy ducha. Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Jego ataki zadają 5...20 pkt. obrażeń.'],
1736=>['Duchowa Siła','Przez 15...60 sek., kiedy posiadasz zaczarowaną broń twoje ataki zadają 5...35 pkt. dodatkowych obrażeń.','(15...60 sek.) Twoje ataki zadają +5...35 pkt. obrażeń, jeżeli jesteś pod działaniem zaczarowanej broni.'],
1737=>['Gorliwość Posiadacza','Przez 10...40 sek., za każdym razem, kiedy rzucasz czar na broń sojusznika, otrzymujesz 1...5 pkt. energii.','(10...40 sek.) Otrzymujesz 1...5 pkt. energii, za każdym razem, kiedy zaczarujesz broń.'],
1738=>['Wewnętrzny Wzrok','Przez 8...20 sek., nie możesz zostać oślepiony.','(8...20 sek.) Jesteś odporny na oślepienie.'],
1739=>['Odnowienie Wspomnień','Przez 5...20 sek., kiedy trzymasz przedmiot, wszystkie twoje czary rzucane na broń lub wykorzystujące przedmiot kosztują o 5...35% energii mniej.','(5...20 sek.) Twoje czary na broń i tworzące przedmioty kosztują o 5...35% energii mniej. Bez efektu, chyba że trzymasz przedmiot.'],
1740=>['Remedium Posiadacza','Przez 10...30 sek. za każdym razem, kiedy rzucasz czar na broń sojusznika, to zdejmujesz z niego 2 przypadłości.','(10...30 sek.) Za każdym razem, kiedy rzucasz czar na broń, zdejmujesz z sojusznika będącego jego celem 2 przypadłości.'],
1741=>['Światło Lustrzanego Ducha','Wybrany sojusznik inny od ciebie otrzymuje 15...90 pkt. żywotności. Jeżeli znajdujesz się w pobliżu ducha, także i ty otrzymujesz 15...90 pkt. żywotności.','Dodaje 15...90 pkt. żywotności. Otrzymujesz 15...90 pkt. żywotności, jeżeli jesteś w zasięgu słuchu ducha. Na cel nie można wybrać siebie.'],
1742=>['Sygnet Niematerialnej Potęgi','Przez 5...20 sek. wszystkie duchy, które kontrolujesz w zasięgu słuchu atakują o 33% szybciej i zadają +5...10 pkt. obrażeń.','(5...20 sek.) Wszystkie duchy, które kontrolujesz w zasięgu słuchu atakują o 33% szybciej i zadają +5...10 pkt. obrażeń.'],
1743=>['Sygnet Spętania','Tracisz 200...50 pkt. żywotności, by przejąć kontrolę nad wybranym duchem nalezącym do wroga. (Szansa porażki wynosi 50%, jeśli twoja Moc Przywoływania ma wartość 4 lub mniejszą.)','Tracisz 200...50 pkt. żywotności. Zyskujesz kontrolę nad wybranym duchem wroga. <c x="SkillDull">Jeśli twoja Moc Przywoływania jest niższa niż 5, szansa porażki wynosi 50%.'],
1744=>['Szarża Opiekuna','Wybrany przeciwnik otrzymuje 20...85 pkt. obrażeń od błyskawic. Jeżeli trzymasz przedmiot, otrzymujesz 7 pkt. energii i 5...50 pkt. żywotności.','Zadaje 20...85 pkt. obrażeń od błyskawic. Otrzymujesz 7 pkt. energii i 5...50 pkt. żywotności, jeżeli trzymasz przedmiot.'],
1745=>['Katusze','Tworzysz 1...11 poziomowego ducha. Ataki tego ducha zadają 5...20 pkt. obrażeń, a przeciwnikom pod działaniem klątw zadają podwójne obrażenia. Duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...11 (czas życia 15...45 sek.). Jego ataki zadają 5...20 pkt. obrażeń. Podwójne obrażenia dla przeciwników pod działaniem klątwy.'],
1747=>['Wzmocnienie','Tworzysz 1...14 poziomowego ducha. Wszyscy sojusznicy w jego zasięgu, którzy trzymają przedmiot otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii. Duch ginie po 15...60 sek.','Tworzy ducha na poziomie 1...14 (czas życia 15...60 sek.). Sojusznicy w zasięgu, którzy trzymają przedmiot, otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii.'],
1748=>['Ozdrowienie','Tworzysz 1...14 poziomowego ducha. Przypadłości, na które cierpią sojusznicy w jego zasięgu kończą się o 20...50% szybciej. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...14 (czas życia 30...60 sek.). Przypadłości, na które cierpią sojusznicy w zasięgu, kończą się o 20...50% szybciej.'],
1749=>['Wściekły Oręż','Przez 5...20 sek., z każdym atakiem zakończonym trafieniem wybrany sojusznik otrzymuje o 100% więcej adrenaliny i 1 pkt. energii.','(5...20 sek.) 100% więcej adrenaliny i +1 pkt. energii, za każdym razem, kiedy trafi atak wybranego sojusznika.'],
1750=>['Oręż Xinrae','Przez 8 sek., następnym razem, kiedy wybrany sojusznik otrzyma obrażenia od przeciwnika, te obrażenia zostają zmniejszone o 5% maksymalnej żywotności tego sojusznika i sojusznik ten wykrada do 20...80 pkt. żywotności od przeciwnika.','(8 sek.) Kiedy następnym razem wybrany sojusznik otrzyma obrażenia od przeciwnika, obrażenia te zostają ograniczone do 5% maksymalnej żywotności tego sojusznika, sojusznik wykrada też przeciwnikowi 20...80 pkt. żywotności.'],
1751=>['Oręż Podżegacza','Przez 3...13 sek., jeżeli wybrany sojusznik atakuje przeciwnika, który nie atakuje, to czynność tego przeciwnika zostaje przerwana.','(3...13 sek.) Ataki przerywają czynności. Nie przerywa ataków przeciwników.'],
1752=>['Oręż Remedium','Przez 8 sek. następnym razem, kiedy wybrany sojusznik otrzyma obrażenia lub zostanie mu wykradziona żywotność, sojusznik ten wykrada przeciwnikowi do 20...80 pkt. żywotności i traci 2 przypadłości.','(8 sek.) Następnym razem, kiedy wybrany sojusznik otrzyma obrażenia lub zostanie mu wykradziona żywotność, ten sojusznik wykrada przeciwnikowi do 20...80 pkt. żywotności i traci 2 przypadłości.'],
1753=>['Rozrywający Zamach','Zadajesz +5...20 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracono zaklęcie, usuwasz zaklęcie z każdego trafionego wroga.','Zadaje +5...20 pkt. obrażeń. Tracisz 1 zaklęcie derwisza. Efekt usunięcia: Trafieni wrogowie tracą zaklęcie.'],
1754=>['Napaść','Przez 3...15 sek., atakujesz, poruszasz się oraz zyskujesz adrenalinę o 25% szybciej.','(3...15 sek.) Atakujesz, poruszasz się i zyskujesz adrenalinę 25% szybciej.'],
1755=>['Mistyczne Zepsucie','Wszyscy wrogowie w bezpośrednim sąsiedztwie cierpią przez 1...10 sek. z powodu choroby. Przez 20 sek. nic się nie dzieje. Czas trwania choroby zostaje podwojony, jeśli w momencie aktywacji tej umiejętności znajdujesz się pod wpływem zaklęcia. Kiedy zaklęcie to dobiegnie końca, wszyscy członkowie drużyny w zasięgu słuchu zostają wyleczeni z chorób.','(20 sek.) Efekt początkowy: Wszyscy wrogowie w bezpośrednim sąsiedztwie zaczynają chorować (1...10 sek). Podwojony czas trwania, jeśli już znajdujesz się pod wpływem zaklęcia. Efekt końcowy: Członkowie drużyny w zasięgu słuchu przestają chorować.'],
1756=>['Uścisk Grentha','For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','(20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Ciernista Zasłona','Kiedy rzucisz to zaklęcie, wszyscy wrogowie w pobliżu otrzymują 5...50 pkt. kłutych obrażeń. Przez 5...25 sek., otrzymujesz 5...35% mniej obrażeń od czarów.','(5...25 sek.) Obrażenia zadawane czarami są zmniejszone o 5...35%. Efekt początkowy: Wszyscy przeciwnicy w pobliżu otrzymują 5...50 pkt. kłutych obrażeń.'],
1758=>['Uścisk Grabieżcy','Przez 5...20 sek., ataki przeciwko poruszającym się wrogom dodatkowo okulawiają ich na 2...9 sek. Kiedy rzucisz to zaklęcie, przestaje działać na ciebie okulawienie i 1 inna przypadłość. Zaklęcie to kończy się kiedy okulawisz przeciwnika 1...3 razy.','(5...20 sek.) Ataki na poruszających się wrogów powodują ich okulawienie. Efekt początkowy: Przestaje na ciebie działać okulawienie i 1 inna przypadłość. Kończy się 1...3-krotnym okulawieniu wrogów.'],
1759=>['Ślub Siły','Przez 15 sek., za każdym razem gdy zaatakujesz wroga kosą, zadajesz 10...25 pkt. siecznych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie.','(15 sek.) Przy ataku kosą zadajesz 10...25 pkt. siecznych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie.'],
1760=>['Aura Hebanowego Pyłu','Kiedy rzucisz to zaklęcie, wszyscy pobliscy wrogowie zostaną oślepieni na 1...7 sek. Przez 30 sek., jeśli dzierżysz broń zadającą obrażenia od ziemi, twoje ataki wręcz zadają +3...30 pkt. obrażeń od ziemi. Kiedy to zaklęcie dobiega końca, zostajesz wyleczony ze ślepoty.','(30 sek.) Zadajesz +3...30 pkt. obrażeń od ziemi swoimi atakami w walce wręcz. Efekt początkowy: Pobliscy przeciwnicy zostają oślepieni na 1...7 sek. Efekt końcowy: Usuwa ślepotę. Działa tylko wtedy, gdy używasz broni zadającej obrażenia od ziemi.'],
1761=>['Ślub Gorliwości','Przez 20 sek., posiadasz regenerację energii -2, ale za każdym razem kiedy twój atak trafi, otrzymujesz 1...6 pkt. energii.','(20 sek.) Otrzymujesz 1...6 pkt. energii, za każdym razem, kiedy twój atak trafi. Posiadasz degenerację energii -2.'],
1762=>['Serce Furii','Przez 2...10 sek. atakujesz o 25% szybciej.','(2...10 sek.) Atakujesz 25% szybciej.'],
1763=>['Gorliwa Odnowa','Wszyscy przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Przez 5...25 sek. masz -1 do regeneracji energii i otrzymujesz 1 pkt. energii za każdym razem, gdy trafisz przeciwnika. Jeśli zaklęcie to zakończy się przedwcześnie, zyskujesz 1...5 pkt. energii.','(5...25 sek.) Efekt początkowy: Przeciwnicy w pobliżu otrzymują po 5...30 pkt. świętych obrażeń. Masz -1 do regeneracji energii i otrzymujesz 1 pkt. energii za każdym trafieniem. Otrzymujesz 1...5 pkt. energii, jeśli to zaklęcie zakończy się przedwcześnie.'],
1764=>['Intuicja Napastnika','Przez 3...10 sek., otrzymujesz dodatkowe 50% szans na blok podczas atakowania. Kiedy to zaklęcie dobiega końca, wywołujesz osłabienie trwające 3...15 sek. u wszystkich wrogów w bezpośrednim sąsiedztwie.','(3...10 sek.) Daje 50% szans na blok podczas atakowania. Efekt końcowy: Przez 3...15 sek. powoduje osłabienie u wrogów w bezpośrednim sąsiedztwie.'],
1765=>['Rozrywająca Aura','Kiedy rzucisz to zaklęcie, wszyscy wrogowie w pobliżu otrzymują 10...40 pkt. obrażeń od zimna. Przez 30 sek., twoje umiejętności związane z atakiem usuwają zaklęcia z powalonych przeciwników. Kiedy to zaklęcie dobiegnie końca, pobliscy wrogowie mają pękniętą zbroję przez 1...10 sek.','(30 sek.) Twoje umiejętności związane z atakiem usuwają zaklęcia z powalonych wrogów. Efekt początkowy: Wszystkim przeciwnikom w pobliżu zadaje po 10...40 pkt. obrażeń od zimna. Efekt końcowy: Pobliscy przeciwnicy przez 1...10 sek. posiadają pękniętą zbroję.'],
1766=>['Łaska Chyżych Stóp','Przez 5...20 sek. poruszasz się o 25% szybciej, a przypadłości, pod których jesteś działaniem trwają o 50% krócej.','(5...20 sek.) Poruszasz się o 25% szybciej, a przypadłości, pod których jesteś działaniem trwają o 50% krócej.'],
1767=>['Zamach Żniwiarza','Jeśli atak trafi, powoduje okulawienie celu na 3...15 sek. Tracisz 1 zaklęcie derwisza. Jeśli dojdzie do usunięcia zaklęcia, atak ten powala przeciwników na 2...3 sek.','(3...15 sek.) Powoduje okulawienie. Tracisz jedno zaklęcie derwisza. Efekt usunięcia: Powoduje powalenie na 2...3 sek.'],
1768=>['Pośpiech Grabieżcy','Przez 2...8 sek., poruszasz się o 25% szybciej, a poruszającym się przeciwnikom twoje ataki zadają +3...12 pkt. dodatkowych obrażeń.','(2...8 sek.) Poruszasz się o 25% szybciej i poruszającym się przeciwnikom zadajesz +3...12 pkt. obrażeń.'],
1769=>['Skupiona Złość','Przez 45 sek., otrzymujesz o 0...150% adrenaliny więcej.','(45 sek.) Otrzymujesz o 0...150% więcej adrenaliny.'],
1770=>['Naturalny Gniew','Przez 4...15 sek., kiedy nie będziesz pod działaniem zaklęcia, otrzymujesz o 33% adrenaliny więcej.','(4...15 sek.) Otrzymujesz o 33% więcej adrenaliny. Bez efektu, jeśli jesteś pod działaniem zaklęcia.'],
1771=>['Pieśń Odnowy','Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym użyciem umiejętności, otrzyma 45...110 pkt. żywotności.','(10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują 45...110 pkt. żywotności.'],
1772=>['Liryk Oczyszczenia','Przez 5...20 sek. każdy sojusznik w zasięgu słuchu z następnym użyciem sygnetu, traci 1 przypadłość.','(5...20 sek.) Sojusznicy w zasięgu słuchu, ze swoim następnym sygnetem tracą jedną przypadłość.'],
1773=>['Żołnierska Furia','Przez 10...35 sek., jeśli znajdujesz się pod działaniem okrzyku lub pieśni, atakujesz 33% szybciej i otrzymujesz 33% więcej adrenaliny, ale posiadasz -20 pkt. pancerza.','(10...35 sek.) Atakujesz o 33% szybciej oraz otrzymujesz 33% więcej adrenaliny, jeżeli jesteś pod działaniem okrzyku lub pieśni. Posiadasz -20 pkt. pancerza'],
1774=>['Agresywny Zaśpiew','Przez 5...25 sek., atakujesz 25% szybciej ale masz -20 pkt. pancerza. To echo jest ponownie nakładane za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk.','(5...25 sek.) Atakujesz o 25% szybciej. Odnowienie: za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk. Posiadasz -20 pkt. pancerza.'],
1775=>['Energetyzujący Finał','Przez 10...35 sek., za każdym razem, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, otrzymuje on 1...2 pkt. energii.','(10...35 sek.) Wybrany sojusznik otrzymuje 1...2 pkt. energii za każdym razem, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
1776=>['Sygnet Agresji','Jeżeli jesteś pod działaniem okrzyku lub zaśpiewu, otrzymujesz dawki adrenaliny w liczbie 2.','Otrzymujesz dawki adrenaliny w liczbie 2, jeżeli jesteś pod działaniem zaśpiewu lub okrzyku.'],
1777=>['Sygnet Remedium','Tracisz jedną przypadłość.','Tracisz jedną przypadłość.'],
1778=>['Sygnet Powrotu','Wskrzeszasz wybranego członka drużyny, który zmartwychwstaje z 5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu.','Wskrzesza wybranego członka drużyny (5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu).'],
1779=>['"Przygotować Się!"','Zyskujesz 2 dawki adrenaliny na każdego członka drużyny w zasięgu słuchu (maks. liczba dawek adrenaliny: 1...8).','Zyskujesz 2 dawki adrenaliny (maks. 1...8) na każdego członka drużyny w zasięgu słuchu.'],
1780=>['"Łapy Precz!"','Przez 20 sek. następne 1...5 umiejętności oparte na dotyku, użyte przeciwko sojusznikom w zasięgu słuchu nie zadziałają.','(20 sek.) Następne 1...5 umiejętności oparte na dotyku, użyte przeciwko sojusznikom w zasięgu słuchu nie zadziałają.'],
1781=>['"Odnajdźcie Ich Słabości!"','Przez 5...20 sek., kiedy następnym razem wybrany sojusznik wykona atak, zada +5...50 pkt. obrażeń oraz spowoduje powstanie głębokiej rany na 5...20 sek.','(5...20 sek.) Przy następnym ataku wybrany sojusznik zadaje +5...50 pkt. obrażeń oraz powoduje powstanie głębokiej rany (5...20 sek.).'],
1782=>['"Potęga Jest Wasza!"','Przez 2...4 sek. wszyscy sojusznicy w zasięgu słuchu posiadają regenerację energii 1...2.','(2...4 sek.) Wszyscy sojusznicy w zasięgu słuchu posiadają regenerację energii 1...2.'],
1783=>['Włócznia Pogromcy','Jeśli atak trafi, zadaje +5...25 pkt. obrażeń. Jeżeli cel ma więcej punktów żywotności niż ty, to na 5...20 sek. otrzymuje głęboką ranę.','Zadaje +5...25 pkt. obrażeń. Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli cel ma więcej żywotności niż ty.'],
1784=>['Szybki Oszczep','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli jesteś pod działaniem zaklęcia, to twoja włócznia leci dwa razy szybciej, a przeciwnik nie może jej zablokować.','Zadaje +5...20 pkt. obrażeń. Ta włócznia leci dwa razy szybciej i jest nie do zablokowania, jeżeli jesteś pod działaniem zaklęcia.'],
1814=>['Spojrzenie Niosącego Światłość','Wybrany demoniczny sługa Abaddona otrzymuje 100 pkt. świętych obrażeń, a jego czynność zostaje przerwana. Na każdy poziom Niosącego Światłość, który osiągnąłeś, umiejętność działa na dodatkowego przeciwnika. Po użyciu umiejętność będzie niedostępna przez 15 sek.','Wybrany demoniczny sługa Abaddona otrzymuje 100 pkt. świętych obrażeń, a jego czynność zostaje przerwana. Umiejętność działa na dodatkowego przeciwnika na każdy poziom Niosącego Światłość, który osiągnąłeś. Wyłącza umiejętność (15 sek.).'],
1815=>['Sygnet Niosącego Światłość','Jeśli jesteś w zasięgu demonicznego sługi Abaddona, otrzymujesz dawki adrenaliny w liczbie 3...5 oraz 16...24 pkt. energii.','Jeśli jesteś w zasięgu demonicznego sługi Abaddona, otrzymujesz dawki adrenaliny w liczbie 3...5 oraz 16...24 pkt. energii.'],
1816=>['Sygnet Odrodzenia Słonecznych Włóczni','Wskrzesza przy tobie wskazanego martwego członka drużyny, który będzie posiadać pełną żywotność i 10% energii za każdy zdobyty przez ciebie poziom Słonecznej Włóczni. Sygnet może być użyty tylko raz na misję, chyba że zostanie odnowiony za pomocą przypływu morale.','Wskrzesza przy tobie wskazanego martwego członka drużyny (pełna żywotność i 10% energii za każdy zdobyty poziom Słonecznej Włóczni). Sygnet odnawia się jedynie kiedy zwiększa się twoje morale.'],
1948=>['Cieniste Sanktuarium','Zostajesz oślepiony na 5 sek. Przez 10 sek. posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza.','(10 sek.) Posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza. Zostajesz oślepiony (5 sek.).'],
1949=>['Eteryczny Koszmar','Wybrany przeciwnik traci 5...8 pkt. energii. Za każdy stracony w ten sposób punkt energii, ten przeciwnik i wszyscy przeciwnicy w okolicy na 10 sek. posiadają degenerację żywotności -1.','Powoduje utratę 5...8 pkt. energii. Za każdy punkt utraconej energii, cel i przeciwnicy w okolicy posiadają degenerację żywotności -1 (10 sek.).'],
1950=>['Sygnet Zepsucia','Wybrany przeciwnik oraz wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń. Za każdego z tych przeciwników będącego pod wpływem przypadłości lub klątwy, otrzymujesz 2 pkt. energii (maksymalnie 12...20 pkt.).','Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 20...30 pkt. obrażeń. Otrzymujesz 2 pkt. energii (maksymalnie 12...20) za każdego z tych przeciwników, który jest pod działaniem klątwy lub przypadłości.'],
1951=>['Władca Żywiołów','Przez 40...60 sek., twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.','(40...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.'],
1952=>['Bezinteresowny Duch','Przez 15...20 s czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.','(15...20 s) Czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.'],
1953=>['Potrójny Strzał','W wybranego przeciwnika wystrzeliwujesz na raz 3 strzały, które zadają o 40...25% mniej obrażeń.','Jednocześnie wystrzeliwuje w wybranego przeciwnika 3 strzały. Te strzały zadają o 40...25% mniej obrażeń.'],
1954=>['Ratujcie się!','Przez 4...6 sek., wszyscy członkowie drużyny poza tobą posiadają +100 pkt. pancerza.','(4...6 sek.) Wszyscy inni członkowie drużyny otrzymują po +100 pkt. pancerza.'],
1955=>['Aura Świętej Mocy','Przez 45 sek. zadajesz 20...25 pkt. świętych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie, jeśli stracisz zaklęcie derwisza.','(45 sek.) Za każdym razem, gdy stracisz zaklęcie derwisza, wrogowie w bezpośrednim sąsiedztwie otrzymują 20...25 pkt. świętych obrażeń.'],
1957=>['Włócznia Furii','Atak zadaje +30...40 pkt. obrażeń. Jeżeli trafi przeciwnika pod wpływem przypadłości, otrzymujesz dawki adrenaliny w liczbie 3...6.','Zadaje +30...40 pkt. obrażeń. Otrzymujesz adrenalinę w liczbie dawek: 3...6, jeżeli trafisz przeciwnika z przypadłością.'],
1986=>['Wampiryczne Natarcie','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, wykradasz 10...40 pkt. żywotności.','Wykrada 10...40 pkt. żywotności, jeżeli ten atak trafi. Musi nastąpić po ataku drugą ręką.'],
1987=>['Uderzenie Lotosu','Musi nastąpić po ataku poprzedzającym. Jeśli atak trafi, zadajesz +10...25 pkt. obrażeń i otrzymujesz 5...20 pkt. energii.','Zadaje +10...25 pkt. obrażeń; otrzymujesz 5...20 pkt. energii. Musi nastąpić po ataku poprzedzającym.'],
1988=>['Cios Złotego Kła','Musi nastąpić po ataku poprzedzającym. Jeśli jesteś pod działaniem zaklęcia i ten atak trafi, wybrany przeciwnik na 5...20 sek. otrzyma głęboką ranę.','Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli jesteś pod działaniem zaklęcia. Musi nastąpić po ataku poprzedzającym.'],
1990=>['Uderzenie Spadającego Lotosu','Musi uderzyć powalonego przeciwnika. Jeśli atak trafi, zadajesz +15...35 pkt. obrażeń i otrzymujesz 1...12 pkt. energii.','Zadaje +15...35 pkt. obrażeń; otrzymujesz 1...12 pkt. energii. Bez efektu, chyba że wybrany przeciwnik jest powalony.'],
1991=>['Sygnet Sadysty','Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...45 pkt. żywotności.','Za każdą przypadłość, pod której działaniem jest wybrany przeciwnik, otrzymujesz 10...45 pkt. żywotności.'],
1992=>['Sygnet Rozproszenia','Jeżeli cel rzuca czar, zostaje on przerwany i zablokowany na 1...5 sek. za każdy założony sygnet.','Przerywa działanie czaru. Efekt przerwania: czar przeciwnika zostaje zablokowany na 1...5 sek. za każdy założony sygnet.'],
1993=>['Sygnet Przypomnienia','Przez 6 sek., posiadasz regenerację energii -4. Kiedy efekt przestanie działać, otrzymujesz 13...20 pkt. energii.','(6 sek.) Posiadasz degenerację energii -4. Efekt końcowy: otrzymujesz 13...20 pkt. energii.'],
1994=>['Zamknięcie Mocy','Jeśli cel rzuca właśnie czar lub pieśń, umiejętność zostaje przerwana, a cel traci 5...13 pkt. energii.','Przerywa użycie czaru lub pieśni. Skutek przerwania: przerwany czar lub pieśń zostają zablokowane na +5...13 sek.'],
1995=>['Nie Marnujesz, Nie Potrzebujesz','Jeżeli wybrany przeciwnik nie rzuca czaru ani nie atakuje otrzymujesz 8...13 pkt. energii.','Otrzymujesz 8...13 pkt. energii, jeżeli wybrany przeciwnik nie atakuje ani nie rzuca czaru.'],
1996=>['Suma Wszystkich Strachów','Przez 4...12 sek. wybrany przeciwnik porusza się, atakuje i rzuca czary o 33% wolniej.','(4...12 sek.) Wybrany przeciwnik porusza się, atakuje i rzuca czary o 33% wolniej.'],
1997=>['Osłabiająca Aura','Przez 5...20 sek., ataki wręcz sojusznika wywołują osłabienie trwające 5...20 sek.','(5...20 sek.) Ataki wręcz wybranego sojusznika wywołują przypadłość osłabienie (5...20 sek.).'],
1998=>['Kakofonia','Przez 15 sek., za każdym razem, kiedy wybrany przeciwnik użyje okrzyku lub zaśpiewu, otrzyma 30...105 pkt. obrażeń.','(15 sek.) Zadaje 30...105 pkt. obrażeń, za każdym razem, kiedy wybrany przeciwnik użyje okrzyku lub zaśpiewu.'],
1999=>['Objęcia Zimy','Przez 2...6 sek., wybrany przeciwnik porusza się o 66% wolniej i otrzymuje 5...15 pkt. obrażeń podczas ruchu.','(2...6 sek.) Wybrany przeciwnik porusza się o 66% wolniej i otrzymuje 5...15 pkt. obrażeń podczas ruchu.'],
2000=>['Gliniane Kajdany','Przez 3 sek., wybrany przeciwnik i wszyscy przeciwnicy w pobliżu poruszają się 90% wolniej. Kiedy Gliniane Kajdany się skończą, przeciwnik na 5...20 sek. zostaje osłabiony.','(3 sek.) Cel i pobliscy przeciwnicy poruszają się 90 wolniej. Osłabia przeciwnika na 5...20 sek. po zakończeniu.'],
2001=>['Osłabiająca Ochrona','W miejscu, w którym przebywasz tworzysz Osłabiającą Ochronę. Przez 5...20 sek., za każdym razem, kiedy przeciwnicy w zasięgu jej działania otrzymają obrażenia od żywiołów na 5...20 sek. zostaną osłabieni.','(5...20 sek.) U przeciwników będących w granicach tej ochrony, którzy otrzymają obrażenia od żywiołów, wywołuje przypadłość osłabienie (5...20 sek.).'],
2002=>['Glif Szybkości','Przez 15 sek. twoje następne czary w liczbie 1...5 odnawiają się o 25% szybciej, a pociski z nich poruszają się o 200% szybciej.','(15 sek.) Twoje następne czary w liczbie 1...5 odnawiają się o 25% szybciej, a pociski z nich poruszają się o 200% szybciej.'],
2003=>['Wyleczenie Klątwy','Usuwasz z wybranego sojusznika jedną klątwę. Jeśli klątwa zostanie usunięta, to sojusznik ten otrzyma 30...100 pkt. żywotności.','Usuwa klątwę. Efekt usunięcia: dodaje 30...100 pkt. żywotności.'],
2004=>['Pogrom Przypadłości','Z wybranego sojusznika usuwasz jedną przypadłość. Jeśli przypadłość zostanie usunięta, to każdy przeciwnik w okolicy otrzyma 10...60 pkt. świętych obrażeń.','Usuwa przypadłość. Efekt usunięcia: przeciwnikom w okolicy wybranego sojusznika zadaje 10...60 pkt. świętych obrażeń.'],
2005=>['Dar Pogromcy','Przez 30 sek., twoje czary oparte na Modlitwach Ofensywnych zapewniają podwójną premię pochodzącą od Łaski Bogów.','(30 sek.) Dla umiejętności z Modlitw Ofensywnych punkty żywotności otrzymywane dzięki Łasce Bogów są podwajane.'],
2006=>['Sygnet Skarcenia','Wybrany przeciwnik otrzymuje 26...56 świętych obrażeń. Jeżeli w tym czasie atakował, otrzymujesz 4...14 punktów energii.','Zadaje 26...56 pkt. świętych obrażeń. Otrzymujesz 4...14 pkt. energii, jeżeli wybrany przeciwnik atakuje.'],
2007=>['Oczyszczający Całun','Podczas gdy utrzymujesz to zaklęcie, przypadłości, pod których działaniem znajdzie się wybrany sojusznik będą trwały o 5...50% krócej. Kiedy to zaklęcie przestanie działać, z sojusznika zostanie usunięta jedna przypadłość.','Przypadłości na wybranym sojuszniku kończą się o 5...50% szybciej. Efekt końcowy: usuwa przypadłość.'],
2008=>['Druzgocące Uderzenie','Jeżeli trafisz powalonego przeciwnika, to na 5...20 sek. otrzyma on głęboką ranę i zostanie osłabiony.','Wywołuje przypadłości osłabienie i głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
2009=>['Ostre Cięcie','Jeśli ten atak trafi, to zawsze skutkuje trafieniem krytycznym.','Zawsze trafienie krytyczne.'],
2010=>['Podcięcie Kolan','Jeśli atak trafi okulawionego przeciwnika, otrzymujesz 2...7 pkt. energii i dawki adrenaliny w liczbie 1...3.','Otrzymujesz 2...7 pkt. energii i dawki adrenaliny w liczbie 1...3, jeżeli wybrany przeciwnik jest okulawiony.'],
2011=>['Chwyt','Ty i dotknięty przeciwnik zostajecie powaleni. Tracisz aktualną postawę.','Powoduje powalenie. Ty również zostajesz powalony. Twoja aktualna postawa zostaje zakończona.'],
2012=>['Promieniejąca Kosa','Za każdy punkt energii, który aktualnie posiadasz, atak ten zadaje +1 pkt. obrażeń (maksymalnie 5...30 pkt. obrażeń). Jeśli ten atak trafi, otrzymujesz 1...7 energii.','Zadaje +1 pkt. obrażeń (maksymalnie 5...30) za każdy punkt energii, który posiadasz. Zyskujesz 1...7 pkt. energii.'],
2013=>['Aura Grentha','Przez 20 sek., zadajesz 5...25 pkt. obrażeń mniej i wykradasz 5...25 żywotności przy każdym trafieniu kosą. Kiedy rzucasz to zaklęcie, wykradasz 5...25 żywotności wszystkim wrogom w bezpośrednim sąsiedztwie.','(20 sek.) Zadajesz 5...25 pkt. obrażeń mniej i wykradasz 5...25 żywotności przy każdym trafieniu kosą. Efekt początkowy: Wykradasz 5...25 żywotności wszystkim wrogom w bezpośrednim sąsiedztwie.'],
2014=>['Sygnet Nabożnej Powściągliwości','Usuwa jedno zaklęcie derwisza. Wybrany przeciwnik zostaje okulawiony na 5...15 sek. Jeśli zostało usunięte jakieś zaklęcie, wszyscy wrogowie w pobliżu twojego celu także zostają okulawieni, zaś sygnet odnawia się 75% szybciej.','Wywołuje okulawienie (5...15 sek.). Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Powoduje także okulawienie wrogów w pobliżu twojego celu i odnawia się 75% szybciej.'],
2015=>['Kosa Farmera','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeżeli trafisz więcej niż jednego przeciwnika, atak natychmiast się odnawia.','Zadaje +5...20 pkt. obrażeń. Natychmiast się odnawia, jeżeli trafisz więcej niż jednego przeciwnika.'],
2016=>['Energiczną Była Lee Sa','Trzymaj prochy Lee Sa\'y przez 5...15 sek. Kiedy trzymasz jej prochy, posiadasz regenerację energii +2. Gdy upuścisz jej prochy, otrzymujesz +1...10 pkt. energii.','(5...15 sek.) Posiadasz regenerację energii +2. Efekt upuszczenia: otrzymujesz +1...10 pkt. energii.'],
2017=>['Hymn Znużenia','Przez 8 sek. następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu, dodatkowo osłabi przeciwnika na 1...16 sek.','(8 sek.) Sojusznicy w zasięgu słuchu swoją następną umiejętnością związaną z atakiem wywołują osłabienie (1...16 sek.).'],
2018=>['Hymn Rozproszenia','Przez 1...10 sek. następna umiejętność związana z atakami, używana przez każdego sojusznika w zasięgu słuchu, przerywa także czynność przeciwnika.','(1...10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem przerywają czynność przeciwnika.'],
2051=>['Przyzwanie Duchów','Wszystkie duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.','Duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.'],
2052=>['Kieł Cienia','Wykonujesz krok cienia do wybranego przeciwnika. Przez 10 sek. klątwa nie daje żadnego efektu. Kiedy klątwa przestanie działać, powracasz do początkowego miejsca, a przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Wykonujesz krok cienia do wybranego przeciwnika. Efekt końcowy po 10 sek.: wywołuje przypadłość głęboka rana (5...20 sek.); wracasz do swojego początkowego miejsca.'],
2053=>['Przewidziane Ryzyko','Przez 3...24 sek., ataki wybranego przeciwnika zadają +10 obrażeń, ale istnieje 50% szansy, że obrażenia z każdego ataku otrzyma właśnie ten wróg. (Maksymalnie 15...100.)','(3...24 sek.) Ataki wybranego przeciwnika zadają +10 obrażeń. Przy każdym ataku istnieje 50% szansy, że obrażenia (maksymalnie 15...100) przejdą właśnie na tego przeciwnika.'],
2054=>['Skurczenie Zbroi','Przez 10 sek. wybrany przeciwnik posiada degenerację żywotności -1...4. Kiedy klątwa przestanie działać, przeciwnik na 5...20 sek. znajdzie się pod działaniem pękniętej zbroi.','(10 sek.) Powoduje degenerację żywotności -1...4. Efekt końcowy: wywołuje przypadłość pęknięta zbroja (5...20 sek.).'],
2055=>['Tętniak','Wybrany przeciwnik odzyskuje całą swoją energię. Za każdy zyskany w ten sposób punkt energii, otrzymuje 1...3 pkt. obrażeń, a wszyscy przeciwnicy w jego sąsiedztwie tracą 1 pkt. energii (maksymalna strata energii to 1...30).','Wybrany przeciwnik odzyskuje całą swoją energię. Za każdy zyskany w ten sposób punkt energii, otrzymuje 1...3 pkt. obrażeń, a wszyscy przeciwnicy w jego sąsiedztwie tracą 1 pkt. energii (maksymalnie 1...30).'],
2056=>['Błędne Oko','Przez 4 sek., następnym razem, gdy wybrany przeciwnik wykona atak, zostanie on przerwany, a wszyscy przeciwnicy w pobliżu otrzymają po 30...110 pkt. obrażeń.','(4 sek.) Przerywa następny atak wybranego przeciwnika. Efekt przerwania: 30...110 pkt. obrażeń dla przeciwników w pobliżu.'],
2057=>['Plugawa Uczta','Wszystkie przypadłości ze wskasanego sojusznika zostanją przekazane na ciebie. Za każdą przypadłość uzyskaną w ten sposób, otrzymujesz 0...45 pkt. żywotności i 2...4 pkt. energii. Umiejętność odnawia się dwa razy szybciej, jeżeli usuniesz chorobę z celu.','Przenosi wszystkie przypadłości z wybranego sojusznika na ciebie. Za każdą przekazaną przypadłość otrzymujesz 0...45 pkt. żywotności i 2...4 pkt. energii. Połowa odnowienia, jeżeli usuniesz chorobę. Nie można użyć na sobie.'],
2058=>['Splugawiona Żółć','Przez 5...25 sek. wybrany przeciwnik posiada degenerację żywotności -1...3. Jeśli umrze będąc pod działaniem tej klątwy, to wszyscy przeciwnicy w pobliżu otrzymają po 25...85 pkt. obrażeń.','(5...25 sek.) Powoduje degenerację żywotności -1...3. Przeciwnikom w pobliżu zadaje 25...85 pkt. obrażeń, jeżeli wybrany przeciwnik umrze.'],
2059=>['Wstrząs Pancerza','Wybrany przeciwnik otrzymuje 10...30 pkt. obrażeń od elektryczności a jego zbroja pęka na 5...20 sek. To zaklęcie ma 25% penetrację pancerza. Jeśli jesteś pod wpływem Przemagicznienia, to zaklęcie trafia również pobliskich wrogów.','Zadaje 10...30 pkt. obrażeń od elektryczności. Wywołuje przypadłość pęknięta zbroja (5...20 sek.). 25% penetracji pancerza. Podczas Przemagicznienia trafia pobliskich.'],
2060=>['Glif Podpalenia','Przez 15 sek. twoje następne czary w liczbie 1...4, których celem jest przeciwnik, na 1...4 sek. wywołują dodatkowo płonięcie.','(15 sek.) Twoje następne czary w liczbie 1...4, których celem jest przeciwnik, wywołują dodatkowo płonięcie (1...4 sek.).'],
2061=>['Cierpliwy Duch','Na 2 sek. wskazany sprzymierzeniec znajduje się pod wpływem Cierpliwego Ducha. Jeżeli zaklęcie zakończy się przedwcześnie, sprzymierzeniec zostanie uleczony za 30...120 pkt. zdrowia.','(2 sek.) Efekt końcowy: przywraca 30...120 pkt. żywotności. Bez efektu, jeżeli zakończy się przedwcześnie.'],
2062=>['Lecząca Wstęga','Wybrany sojusznik inny niż ty otrzymuje 20...110 pkt. żywotności. Nie więcej niż 2 dodatkowi sojusznicy w jego pobliżu otrzymują po 10...100 pkt. żywotności.','Dodaje 20...110 pkt. żywotności. Ulecza dwóch dodatkowych sojuszników w pobliżu wybranego sojusznika dodając im po 10...100 pkt. żywotności. Na cel nie można wybrać siebie.'],
2063=>['Pewna Dusza','Przez 3...8 sek., wybrany sojusznik inny niż ty nie może zostać powalony.','(3...8 sek.) Wybrany sojusznik nie może zostać powalony. Na cel nie można wybrać siebie.'],
2064=>['Nieskazitelny Umysł','Przez 1...15 sek. wybrany sojusznik inny niż ty co 5 sek. traci jedną klątwę.','(1...15 sek.) Co 5 sek. usuwa klątwę. Na cel nie można wybrać siebie.'],
2065=>['Nieskazitelna Dusza','Przez 1...15 sek. wybrany sojusznik inny niż ty co 3 sek. traci jedną przypadłość.','(1...15 sek.) Co 3 sek. usuwa przypadłość. Na cel nie można wybrać siebie.'],
2066=>['Rozbrojenie','Przerywasz czynność wybranego przeciwnika. Jeśli tą czynnością był atak, to wszystkie umiejętności związane z atakowaniem tego przeciwnika będą niedostępne przez 0...3 sek.','Przerywasz czynność wybranego przeciwnika. Efekt przerwania: wyłącza umiejętności związane z atakami tego przeciwnika (0...3 sek.), jeśli tą czynnością był atak.'],
2067=>['"Zrobiłem to Umyślnie!"','Jeżeli jesteś powalony, otrzymujesz dawki adrenaliny w liczbie 1...6.','Otrzymujesz dawki adrenaliny w liczbie 1...6, jeżeli jesteś powalony.'],
2068=>['Szybkostrzelność','Przez 5...25 sek. dzierżąc łuk atakujesz o 33% szybciej.','(5...25 sek.) Dzierżąc łuk atakujesz o 33% szybciej.'],
2069=>['Strzał Łowcy Ospałych','Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...25 pkt. obrażeń. Jeżeli przeciwnik ten nie używa umiejętności, to Strzał Łowcy Ospałych zadaje dodatkowe +10...35 pkt. obrażeń.','Zadaje +10...25 pkt. obrażeń. Zadaje +10...35 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik nie używa umiejętności.'],
2070=>['Rozcinacz Aur','Jeśli atak trafi, powoduje krwawienie przez 5...15 sek. Jeśli znajdujesz się pod wpływem zaklęcia, atak powoduje także pęknięcie zbroi przez 1...10 sek.','(5...15 sek.) Wywołuje krwawienie. Powoduje także pęknięcie zbroi (1...10 sek.), jeśli znajdujesz się pod wpływem zaklęcia.'],
2071=>['Gorliwy Zamach','Jeśli ten atak dojdzie celu, zadajesz +5...20 pkt. obrażeń. Za każdego trafionego wroga otrzymujesz 3 pkt. energii oraz 1 dawkę adrenaliny.','Zadaje +5...20 pkt. obrażeń. Za każdego trafionego wroga otrzymujesz 3 pkt. energii oraz 1 dawkę adrenaliny.'],
2072=>['Nieskalaną Była Li Ming','Trzymaj prochy Li Ming przez 5...20 sek. Kiedy trzymasz jej prochy, przypadłości, pod których jesteś działaniem trwają o 10...50% krócej. Gdy upuścisz jej prochy, wszyscy sojusznicy w zasięgu słuchu tracą przypadłości w liczbie 1...4.','(5...20 sek.) Przypadłości, pod których jesteś działaniem kończą się o 10...50% szybciej. Efekt upuszczenia: z sojuszników w zasięgu słuchu usuwa 1...4 przypadłości.'],
2073=>['Agresywny Oręż','Przez 5...15 sek. atakujesz o 25% szybciej.','(5...15 sek.) Atakujesz o 25% szybciej.'],
2074=>['Łamacz Żeber','Jeżeli atak trafi przeciwnika, który jest pod działaniem Pękniętej Zbroi, to przeciwnik ten na 5...20 sek. otrzymuje głęboką ranę.','Wywołuje przypadłość głęboka rana (5...20 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2075=>['Zaśpiew Pośpiechu','Przez 8...20 sek. wybrany sojusznik porusza się o 25% szybciej. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','(8...20 sek.) Wybrany sojusznik porusza się o 25% szybciej. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk.'],
2091=>['Cieniste Sanktuarium','Zostajesz oślepiony na 5 sek. Przez 10 sek. posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza.','(10 sek.) Posiadasz regenerację żywotności +7...10 i +40 pkt. pancerza. Zostajesz oślepiony (5 sek.).'],
2092=>['Eteryczny Koszmar','Wybrany przeciwnik traci 5...8 pkt. energii. Za każdy stracony w ten sposób punkt energii, ten przeciwnik i wszyscy przeciwnicy w okolicy na 10 sek. posiadają degenerację żywotności -1.','Powoduje utratę 5...8 pkt. energii. Za każdy punkt utraconej energii, cel i przeciwnicy w okolicy posiadają degenerację żywotności -1 (10 sek.).'],
2093=>['Sygnet Zepsucia','Wybrany przeciwnik oraz wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń. Za każdego z tych przeciwników będącego pod wpływem przypadłości lub klątwy, otrzymujesz 2 pkt. energii (maksymalnie 12...20 pkt.).','Wybranemu przeciwnikowi i przeciwnikom w pobliżu zadaje po 20...30 pkt. obrażeń. Otrzymujesz 2 pkt. energii (maksymalnie 12...20) za każdego z tych przeciwników, który jest pod działaniem klątwy lub przypadłości.'],
2094=>['Władca Żywiołów','Przez 40...60 sek., twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.','(40...60 sek.) Twoje atrybuty związane z żywiołami są zwiększone o 1. Za każdym razem, kiedy rzucasz czar, otrzymujesz 1 punkt energii za każde 10 poziomów Zapasu Energii oraz jesteś uzdrawiany o 100...300% pkt. energii zużytych na ten czar.'],
2095=>['Bezinteresowny Duch','Przez 15...20 s czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.','(15...20 s) Czary, które rzucasz na sojuszników kosztują o 3 pkt. energii mniej.'],
2096=>['Potrójny Strzał','W wybranego przeciwnika wystrzeliwujesz na raz 3 strzały, które zadają o 40...25% mniej obrażeń.','Jednocześnie wystrzeliwuje w wybranego przeciwnika 3 strzały. Te strzały zadają o 40...25% mniej obrażeń.'],
2097=>['Ratujcie się!','Przez 4...6 sek., wszyscy członkowie drużyny poza tobą otrzymują po +100 pkt. pancerza.','(4...6 sek.) Wszyscy inni członkowie drużyny otrzymują po +100 pkt. pancerza.'],
2098=>['Aura Świętej Mocy','Przez 45 sek. zadajesz 20...25 pkt. świętych obrażeń wszystkim wrogom w bezpośrednim sąsiedztwie, jeśli stracisz zaklęcie derwisza.','(45 sek.) Za każdym razem, gdy stracisz zaklęcie derwisza, wrogowie w bezpośrednim sąsiedztwie otrzymują 20...25 pkt. świętych obrażeń.'],
2099=>['Włócznia Furii','Atak zadaje +30...40 pkt. obrażeń. Jeżeli trafi przeciwnika pod wpływem przypadłości, otrzymujesz dawki adrenaliny w liczbie 3...6.','Zadaje +30...40 pkt. obrażeń. Otrzymujesz adrenalinę w liczbie dawek: 3...6, jeżeli trafisz przeciwnika z przypadłością.'],
2100=>['Przyzwanie Duchów','Wszystkie duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.','Duchy, które kontrolujesz wykonują krok cienia w miejsce, w którym się znajdujesz i otrzymują po 60...100 pkt. żywotności.'],
2101=>['Krytyczna Zwinność','Przez 4 sek. i 1 sekundę na każdy poziom Trafień Krytycznych atakujesz o 33% szybciej i posiadasz +15...25 pkt. pancerza. Ta umiejętność zadziała ponownie za każdym razem, kiedy wykonasz trafienie krytyczne.','(4 sek. plus 1 sek. za każdy poziom Trafień Krytycznych.) Atakujesz o 33% szybciej i posiadasz +15...25 pkt. pancerza. Odnowienie: za każdym razem, gdy wykonasz trafienie krytyczne.'],
2102=>['Okrzyk Bólu','Przerywa umiejętność wybranego przeciwnika. Jeżeli ten przeciwnik był pod działaniem klątwy mesmera, to zarówno on, jak i wszyscy przeciwnicy w okolicy otrzymują po 25...50 pkt. obrażeń, zaś ich żywotność spada o 3...5 na 10 sekund.','Przerywa umiejętność. Zadaje 25...50 pkt. obrażeń wybranemu przeciwnikowi i przeciwnikom w okolicy, jeżeli wybrany przeciwnik jest pod działaniem klątwy mesmera, a także powoduje spadek żywotości o 3...5 (10 sekund).'],
2103=>['Nekroza','Jeżeli wybrany przeciwnik jest pod działaniem przypadłości lub klątwy, otrzymuje 60...90 pkt. obrażeń.','Zadaje 60...90 pkt. obrażeń, jeżeli wybrany przeciwnik jest pod działaniem przypadłości lub klątwy.'],
2104=>['Spotęgowanie','Przez 10 sek., kiedy następnym razem zadasz celowi obrażenia od żywiołów za pomocą czaru, zadajesz także 60...70% tych obrażeń wszystkim wrogom w okolicy.','(10 sek.) Kiedy następnym razem zadajesz celowi obrażenia od żywiołów za pomocą czaru, wszyscy wrogowie w okolicy otrzymują 60...70% tych obrażeń.'],
2105=>['Ziarno Życia','Przez 2...5 sek., za każdym razem, kiedy wybrany sojusznik inny niż ty otrzyma obrażenia, wszyscy członkowie drużyny odzyskują po 2 pkt. żywotności na każdy twój poziom Łaski Bogów.','(2...5 sek.) Członkowie drużyny odzyskują po 2 pkt. żywotności za każdy poziom Łaski Bogów, za każdym razem, kiedy wybrany sojusznik otrzymuje obrażenia. Na cel nie można wybrać siebie.'],
2107=>['Wirujący Atak','Atakujesz cel i przeciwników bezpośrednio przy nim. Każdy celny atak zadaje +13...20 pkt. obrażeń.','Atakuje wybranego przeciwnika i przeciwników w bezpośredniej odległości, zadając każdemu +13...20 pkt. obrażeń.'],
2108=>['Nie Siej Zniszczenia Sam','Przez 18...25 sek., ty i twój zwierzęcy towarzysz atakujecie o 25% szybciej i posiadacie regenerację żywotności +1...3.','(18...25 sek.) Ty i twój zwierzęcy towarzysz atakujecie o 25% szybciej i posiadacie regenerację żywotności +1...3.'],
2109=>['Odwieczna Aura','Otrzymujesz +100 do maksymalnej żywotności. Kiedy to zaklęcie dobiegnie końca, wszyscy członkowie drużyny na danym obszarze zostaną wskrzeszeni, otrzymując 40...50% żywotności oraz 20...30% energii.','Otrzymujesz +100 do maksymalnej żywotności. Efekt końcowy: Wszyscy członkowie drużyny na danym obszarze zostaną wskrzeszeni, otrzymując 40...50% żywotności oraz 20...30% energii.'],
2110=>['Wampiryzm','Tworzysz ducha na poziomie 4...14, który ginie po 75...150 sek. Ataki tego ducha wykradają do 10...20 pkt. żywotności, a ty otrzymujesz 10...20 pkt. żywotności.','Tworzy ducha na poziomie 4...14 (czas życia 75...150 sek.). Jego ataki wykradają 10...20 pkt. żywotności, a ty otrzymujesz 10...20 pkt. żywotności.'],
2112=>['"Nie Ma się Czego Obawiać!"','Przez 4 sek. i 1 sekundę na każde 2 poziomy Przywództwa wszyscy sojusznicy w zasięgu słuchu otrzymują o 20...35% mniej obrażeń. Kiedy okrzyk się skończy, ci sojusznicy otrzymają po 35...60 pkt. żywotności.','(4 sek. plus 1 sek. za każde 2 poziomy Przywództwa.) Obniża obrażenia o 20...35% na każdego członka drużyny w zasięgu słuchu. Efekt końcowy: dodaje 35...60 pkt. żywotności.'],
2116=>['Atak z Zaskoczenia','Jeśli atak trafi, wybrany przeciwnik zostanie oślepiony na 5...8 sek. Ten atak liczy się jako atak poprzedzający.','Powoduje oślepienie (5...8 sek.). Traktuje się jako atak poprzedzający.'],
2135=>['Tratujący Wół','Musi nastąpić po ataku drugą ręką. Jeśli atak trafi, zadajesz +5...20 pkt. obrażeń. Jeśli atak trafi okulawionego przeciwnika, ten przeciwnik zostaje powalony.','Zadaje +5...20 pkt. obrażeń; powala, jeżeli wybrany przeciwnik jest okulawiony. Musi nastąpić po ataku drugą ręką.'],
2136=>['Zasłona Dymna','Przez 8 sek., następnym razem, kiedy zostaniesz trafiony, otrzymasz połowę obrażeń, a wszyscy przeciwnicy bezpośrednio przy tobie zostaną oślepieni na 2...6 sek.','(8 sek.) Następnym razem, kiedy zostaniesz trafiony, otrzymasz połowę obrażeń, a wszyscy przeciwnicy bezpośrednio przy tobie zostaną oślepieni (2...6 sek.).'],
2137=>['Mylące Obrazy','Przez 2...10 sek., wybrany przeciwnik potrzebuje dwa razy więcej czasu na używanie umiejętności nie związanych z atakiem.','(2...10 sek.) Wybrany przeciwnik potrzebuje dwa razy więcej czasu na używanie umiejętności nie związanych z atakiem.'],
2138=>['Zdrowie Przeklinającego','Przez 10 sek. posiadasz regenerację żywotności +1...8. Zdrowie Przeklinającego przestanie działać, jeżeli użyjesz umiejętności nie będącej klątwą.','(10 sek.) Posiadasz regenerację żywotności +1...8. Przestanie działać, jeśli użyjesz umiejętności niebędącej klątwą.'],
2139=>['Masochizm','Przez 10...40 sek., otrzymujesz +2 do Magii Śmierci oraz Wydzierania Duszy, a także poświęcasz 5...3% swojej maksymalnej żywotności, za każdym razem kiedy rzucasz czar.','(10...40 sek.) Otrzymujesz +2 do Magii Śmierci oraz Wydzierania Duszy.Poświęcasz 5...3% swojej maksymalnej żywotności, jeśli rzucasz czar.'],
2140=>['Przebijająca Pułapka','Kiedy Przebijająca Pułapka zostanie uaktywniona, wszyscy przeciwnicy w pobliżu otrzymują 5...50 pkt. obrażeń przebijających. Każdy przeciwnik znajdujący się pod działaniem Pękniętej Zbroi otrzymuje dodatkowe 15...60 pkt. obrażeń. Przebijająca Pułapka przestaje działać po 90 sekundach. Podczas aktywacji tej umiejętności, można ci łatwo przeszkodzić.','(90 sek.) Działa na przeciwników w pobliżu. Zadaje 5...50 pkt. obrażeń przebijających. Przeciwnikom z pękniętą zbroją zadaje po 15...60 pkt. dodatkowych obrażeń. Łatwo przerwać.'],
2141=>['Współpraca','Jeżeli masz mniej pkt. żywotności niż twój zwierzęcy towarzysz, to otrzymujesz 30...120 pkt. żywotności. Jeżeli twój zwierzęcy towarzysz ma mniej pkt. żywotności niż ty, to otrzymuje 30...120 pkt. żywotności.','Otrzymujesz 30...120 pkt. żywotności, jeżeli posiadasz mniej żywotności niż twój zwierzęcy towarzysz. Twój zwierzęcy towarzysz otrzymuje 30...120 pkt. żywotności, jeżeli posiada mniej żywotności niż ty.'],
2142=>['Zwierzęca Agresja','Przez 5...20 sek., twój zwierzęcy towarzysz atakuje o 33% szybciej i zadaje 3...10 pkt. dodatkowych obrażeń.','(5...20 sek.) Twój zwierzęcy towarzysz atakuje o 33% szybciej i zadaje +3...10 pkt. obrażeń.'],
2143=>['Rozpraszający Strzał','Jeżeli atak trafi, przerywasz czynność wybranego przeciwnika. Jeżeli tą czynnością było użycie umiejętności, zadajesz +10...40 pkt. obrażeń.','Przerywa czynność. Efekt przerwania: +10...40 pkt. obrażeń, jeżeli przerwałeś umiejętność.'],
2144=>['Salwa','Wszystkie twoje przygotowania zostają przerwane. Wystrzeliwujesz strzały w wybranego przeciwnika i maksymalnie 3 przeciwników będących bezpośrednio przy nim. Te strzały trafiając, zadają +1...10 pkt. obrażeń.','Zadaje +1...10 pkt. obrażeń. Trafia 3 przeciwników bezpośrednio przy twoim celu. Usuwane są twoje wszystkie przygotowania.'],
2145=>['Skupienie Specialisty','Przez 24 sek., twoje umiejętności ataku za pomocą łuku kosztują o 1...2 pkt. energii mniej i zadają 1...10 pkt. dodatkowych obrażeń.','(24 sek.) Twoje umiejętności ataku za pomocą łuku kosztują o 1...2 pkt. energii mniej i zadają +1...10 pkt. obrażeń.'],
2146=>['Nabożna Furia','Usuwa jedno zaklęcie derwisza. Przez 1...7 sek. atakujesz o 25% szybciej. Jeśli zostało usunięte jakieś zaklęcie, postawa ta trwa dwa razy dłużej.','(1...7 sek.) Atakujesz 25% szybciej i usuwasz 1 ze swoich zaklęć derwisza. Efekt usunięcia: Postawa ta trwa dwa razy dłużej.'],
2147=>['Okulawiające Zwycięstwo','Jeśli ten atak trafi przeciwnika, zostaje on okaleczony na 3...8 sek. Jeśli masz więcej żywotności niż cel, wszyscy pobliscy wrogowie otrzymują 10...30 pkt. obrażeń od ziemi.','(3...8 sek.) Okalecza cel. Jeśli masz więcej żywotności niż cel, wszyscy pobliscy wrogowie otrzymują 10...30 pkt. obrażeń od ziemi.'],
2148=>['Penetrująca Broń','Przez 4...10 sek., następne 3 ataki wybranego sojusznika posiadają 10% przebicie pancerza i na 5...20 sek. wywołują pękniętą zbroję.','(4...10 sek.) Następne 3 ataki wybranego sojusznika wywołują przypadłość pęknięta zbroja (5...20 sek.) i posiadają 10% przebicie pancerza.'],
2149=>['Oręż Odnowienia','Przez 5...20 sek., kiedy następnym razem wybrany sojusznik trafi używając umiejętności związanej z atakowaniem, otrzyma 1...7 pkt. energii.','(5...20 sek.) Wybrany sojusznik otrzymuje 1...7 pkt. energii następnym razem, kiedy trafi jego umiejętność związana z atakami.'],
2150=>['Włócznia Obłędu','Jeżeli twój atak trafi krwawiącego przeciwnika, to przeciwnik ten zostaje okulawiony na 5...20 sek.','Wywołuje przypadłość okulawienie (5...20 sek.), jeżeli wybrany przeciwnik krwawi.'],
2186=>['Sygnet Śmiertelnego Zepsucia','Zaatakowany wróg otrzymuje 5...35 pkt. obrażeń za każdą posiadaną przypadłość (maksymalnie 130 pkt. obrażeń).','Zadaje 5...35 pkt. obrażeń (maksymalnie 130) za każdą przypadłość na wybranym przeciwniku.'],
2187=>['Ścieżka Wojownika','Przez 60 sek., trzymając broń nie będącą sztyletami posiadasz 3...33% dodatkowych szans na wykonanie trafienia krytycznego.','(60 sek.) Trzymając broń nie będącą sztyletem posiadasz +3...33% szans na trafienia krytyczne.'],
2188=>['Splugawienie Obrony','Przez 5...20 sek., kiedy następnym razem wybrany przeciwnik zablokuje trafienie, otrzyma 30...120 pkt. obrażeń.','(5...20 sek.) Zadaje 30...120 pkt. obrażeń następnym razem, kiedy wybrany przeciwnik wykona blok.'],
2189=>['Spojrzenie Angorodona','Wybranemu przeciwnikowi wykradasz 10...50 pkt. żywotności. Jeżeli jesteś pod działaniem przypadłości, otrzymujesz 3...12 pkt. energii.','Wykrada 10...50 pkt. żywotności. Otrzymujesz 3...12 pkt. energii, jeżeli jesteś pod działaniem przypadłości.'],
2190=>['Fala Magnetyczna','Wybrany przeciwnik otrzymuje 15...75 pkt. obrażeń. Podczas Przemagicznienia, Fala Magnetyczna wzmacnia wszystkich sojuszników w zasięgu słuchu na 1...5 sek. w blokowaniu nadchodzących ataków.','Zadaje 15...75 pkt. obrażeń. Podczas Przemagicznienia, sojusznicy w zasięgu słuchu zostają wzmocnieni na 1...5 i blokują następny atak.'],
2191=>['Śliskie Podłoże','Jeśli cel lub sąsiadujący przeciwnicy są oślepieni lub w ruchu, to ci przeciwnicy zostają powaleni. istnieje 50% szansy na niepowodzenie Magii Wody poniżej 5.',' Powoduje powalenie, jeżeli przeciwnik jest w ruchu lub jest oślepiony. Dotyczy wrogów stojących obok celu. 50% szansy na porażkę chyba, że Magia Wody jest na poziomie 4 lub wyższym.'],
2192=>['Błyszczący Lód','Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń od zimna. Jeżeli jest on pod działaniem klątwy z Magii Wody, otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii.','Zadaje 5...50 pkt. obrażeń od zimna. Otrzymujesz 5 pkt. energii plus 1 pkt. energii na każde 2 poziomy Zapasu Energii, jeżeli wybrany przeciwnik jest pod działaniem klątwy z Magii Wody.'],
2193=>['Wybuch Energii','Za każdy punkt energii, który posiadasz, wybrany przeciwnik otrzymuje 1...2 pkt. obrażeń (maksymalnie 130 pkt. obrażeń).','Zadaje 1...2 pkt. obrażeń (maksymalnie 130) za każdy punkt energii, który posiadasz.'],
2194=>['Rozpraszające Uderzenie','Jeżeli Rozpraszające Uderzenie trafi, nie zadaje obrażeń, ale przerywa czynność wybranego przeciwnika. Jeżeli cel jest pod działaniem Pękniętej Zbroi, to ta umiejętność będzie niedostępna przez 30 sek.','Przerywa czynność. Efekt przerwania: Wyłącza przerwaną umiejętność (30 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję. Nie zadaje obrażeń.'],
2195=>['Symboliczne Uderzenie','Jeżeli atak trafi, zadajesz +12 pkt. obrażeń na każdy sygnet, który masz na pasku umiejętności (maksymalnie 70 pkt. obrażeń).','Zadaje +12 pkt. obrażeń (maksymalnie 70) za każdy sygnet, który masz na pasku umiejętności.'],
2196=>['Szybkość Żołnierza','Przez 3...18 sek., poruszasz się o 15% szybciej. Oprócz tego, poruszasz się jeszcze o 15% szybciej, jeśli znajdujesz się pod działaniem okrzyku lub pieśni.','(3...18 sek.) Poruszasz się o 15% szybciej oraz dodatkowo o 15% szybciej, jeśli jesteś pod działaniem okrzyku lub pieśni.'],
2197=>['Uderzenie w Korpus','Jeżeli atak trafi, wybrany przeciwnik otrzymuje +10...40 pkt. obrażeń. Jeżeli cel jest pod działaniem Pękniętej Zbroi, to na 0...15 sek. otrzymuje głęboką ranę.','Zadaje +10...40 pkt. obrażeń. Wywołuje przypadłość głęboka rana (0...15 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2198=>['Strzał w Korpus','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeżeli trafi przeciwnika będącego pod działaniem Pękniętej Zbroi, to otrzymujesz 5...10 punktów energii.','Zadaje +5...20 pkt. obrażeń. Otrzymujesz 5...10 pkt. energii, jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2199=>['Sygnet Zatrutego Oręża','Przez 60 sek., twój następny atak zatruwa także cel na 8...15 sek.','(60 sek.) Twój następny atak wywołuje przypadłość zatrucie (8...15 sek.).'],
2200=>['Sygnet Mistycznej Prędkości','Przez 30 sek., twoje kolejne (1...3) skierowane na ciebie zaklęcia są rzucane natychmiastowo. Zaklęcia błysku nie zużywają tej umiejętności.','(30 sek.) Twoje kolejne (1...3) skierowane na ciebie zaklęcia są rzucane natychmiast. Zaklęcia błysku nie zużywają tej umiejętności.'],
2201=>['Tarcza Mocy','Przez 1...16 sek., blokuje kolejne ataki (1) przeciwko tobie. Jeśli dojdzie do zablokowania ataku, wszyscy właśnie atakujący wrogowie w bezpośrednim sąsiedztwie zostają powaleni i cierpią na osłabienie przez 5...20 sek.','(1...16 sek.) Blokuje kolejne ataki (1) wymierzone w ciebie. Powala i powoduje osłabienie (na 5...20 sek.) wszystkich atakujących właśnie wrogów w bezpośrednim sąsiedztwie.'],
2202=>['Odnawiający Uchwyt','Uzdrawiasz wybranego sojusznika dodając mu 30...90 pkt. żywotności. Jeżeli wybrany sojusznik jest pod działaniem zaczarowanej broni, to traci jedną przypadłość.','Dodaje 30...90 pkt. żywotności. Usuwa jedną przypadłość, jeżeli wybrany sojusznik ma zaczarowaną broń.'],
2203=>['Aura Duchowej Pijawki','Przez 5...20 sek., wszystkie twoje duchy w zasięgu słuchu zadają o 5...20 mniej obrażeń i przy każdym ataku wykradają 5...20 pkt. żywotności.','(5...20 sek.) Wszystkie twoje duchy w zasięgu słuchu zadają o 5...20 mniej obrażeń i przy każdym ataku'],
2204=>['Odmłodzenie','Tworzysz 1...20 poziomowego ducha. Duch uzdrawia każdego członka drużyny w zasięgu słuchu, w każdej sekundzie dodając mu 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego członka drużyny uzdrowionego w ten sposób. Duch ginie po 30...90 sek.','Tworzy ducha na poziomie 1...20 (czas życia 30...90 sek.). Członkowie drużyny w zasięgu słuchu otrzymują co sekundę po 3...10 pkt. żywotności. Koszt uleczenia: ten duch traci 3...10 pkt. żywotności.'],
2205=>['Agonia','Tworzysz 1...12 poziomowego ducha. Obecność ducha powoduje, że każdy przeciwnik w jego zasięgu słuchu co sekundę traci 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego przeciwnika, który w ten sposób ucierpi. Duch ginie po 30...90 sek.','Tworzy ducha na poziomie 1...12 (czas życia 30...90 sek.). Przeciwnicy w zasięgu słuchu co sekundę tracą 3...10 pkt. żywotności. Ten duch traci 3...10 pkt. żywotności na każdego przeciwnika, który traci żywotność.'],
2206=>['Widmowy Oręż','Przez 5...20 sek., następny atak wybranego sojusznika innego niż ty nie może zostać zablokowany.','(5...20 sek.) Następny atak wybranego sojusznika jest nie do zablokowania. Na cel nie można wybrać siebie.'],
2207=>['Inspirująca Przemowa','Tracisz całą adrenalinę, a wybrany sojusznik inny niż ty otrzymuje dawki adrenaliny w liczbie 1...8.','Wybrany sojusznik otrzymuje dawki adrenaliny w liczbie 1...8. Na cel nie można wybrać siebie. Tracisz całą adrenalinę.'],
2208=>['Płonąca Tarcza','Przez 3...9 sek., kiedy trzymasz tarczę, następna umiejętność związana z atakiem użyta przeciwko tobie zostanie zablokowana. Jeżeli był to atak wręcz, to atakujący zostaje podpalony na 1...6 sek.','(3...9 sek.) Blokuje następną umiejętność związaną z atakiem, której jesteś celem. Wywołuje przypadłość płonięcie (1...6 sek.), jeżeli był to atak wręcz. Bez efektu, jeśli nie dzierżysz tarczy.'],
2209=>['Święta Włócznia','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi przyzwane stworzenie, to wszyscy przeciwnicy w pobliżu otrzymują po 15...90 pkt. świętych obrażeń i na 3 sek. zostają podpaleni.','Zadaje +5...20 pkt. obrażeń. Przeciwnikom w pobliżu zadaje 15...90 pkt. świętych obrażeń i wywołuje przypadłość płonięcie (3 sek.), jeżeli trafisz przyzwanie stworzenie.'],
2210=>['Zamach Włócznią','Jeżeli atak trafi, zadaje +5...20 pkt. obrażeń, a wybrany przeciwnik zostaje oszołomiony na 4...10 sek. Ten atak działa w zasięgu walki wręcz.','Zadaje +5...20 pkt. obrażeń i wywołuje przypadłość oszołomienie (4...10 sek.). Ten atak działa w zasięgu walki wręcz.'],
2211=>['Alchemiczny Kwas Alkara','Rzucasz Alchemicznym Kwasem Alkara w wybranego przeciwnika. Cel i przeciwnicy bezpośrednio przy nim otrzymują po 40...50 pkt. obrażeń. Niszczyciele otrzymują dodatkowe 45...70 pkt. obrażeń i na 14...20 sek. znajdą się pod działaniem kruchej zbroi.','Pocisk: wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 40...50 pkt. obrażeń. Niszczycielom zadaje 45...70 pkt. dodatkowych obrażeń i wywołuje u nich przypadłość pęknięta zbroja (14...20 sek.).'],
2212=>['Światło Deldrimoru','Wszyscy przeciwnicy w okolicy otrzymują po 55...80 pkt. świętych obrażeń. Położenie ukrytych obiektów będzie przez chwilę pokazane na twoim kompasie. Pokazane zostaną wszystkie ukryte obiekty w okolicy.','Przeciwnikom w okolicy zadaje po 55...80 pkt. świętych obrażeń. Pokazuje na kompasie wszystkie ukryte obiekty w okolicy.'],
2213=>['Ugryzienie w Ucho','Dotknięty wybrany przeciwnik otrzymuje 50...70 pkt. obrażeń przebijających i zaczyna krwawić na 15...25 sek.','Zadaje 50...70 pkt. obrażeń przebijających i wywołuje przypadłość krwawienie (15...25 sek.).'],
2214=>['Cios Poniżej Pasa','Wybranemu przeciwnikowi zadajesz +45...70 pkt. obrażeń. Jeżeli zostanie powalony, otrzymuje dodatkowe 30...50 pkt. obrażeń i cierpi z powodu pęknięcia zbroi przez 14...20 sek.','Zadaje 45...70 pkt. obrażeń. Zadaje dodatkowe 30...50 obrażeń i powoduje pęknięcie zbroi (14...20 sek.), jeżeli wybrany przeciwnik jest powalony.'],
2215=>['Awanturnicze Uderzenie Głową','Uderzasz głową dotkniętego wybranego przeciwnika i jeśli trafisz, zadajesz mu 45...70 pkt. obrażeń i powalasz go.','Zadaje 45...70 pkt. obrażeń; powala.'],
2216=>['"Nie Potykaj Się!"','Przez 3...5 sek., członkowie drużyny w zasięgu słuchu nie mogą zostać powaleni.','(3...5 sek.) Chroni przed powaleniem; działa na członków drużyny w zasięgu słuchu.'],
2217=>['"Na Młot Urala!"','Przez 30 sek., wszyscy martwi członkowie drużyny w zasięgu słuchu zostają wskrzeszeni z pełną żywotnością i energią. Wskrzeszeni członkowie drużyny zadają 25...33% więcej obrażeń. Kiedy ten efekt dobiegnie końca, członkowie drużyny będący pod jego wpływem umierają. Umiejętność ta nie powoduje kary za śmierć.','(30 sek.) Wskrzesza wszystkich martwych członków drużyny w zasięgu słuchu z pełną żywotnością i energią. Wskrzeszeni członkowie drużyny zadają 25...33% więcej obrażeń. Członkowie drużyny umierają, kiedy skończy się działanie tego efektu, ale nie otrzymują kary za śmierć.'],
2218=>['Pijacki Mistrz','Przez 72...90 sek. poruszasz się i atakujesz o 10...15% szybciej. Z kolei jeżeli jesteś pijany aktywując tą umiejętność, to poruszasz się i atakujesz o 25...33% szybciej.','(72...90 sek.) Poruszasz się i atakujesz o 10...15% szybciej, jeżeli nie jesteś pijany. Poruszasz się i atakujesz o 25...33% szybciej, jeżeli jesteś pijany.'],
2219=>['Oręż Wielkiego Krasnoluda','Przez 20 sek., broń wybranego sojusznika innego niż ty zadaje +15...20 pkt. obrażeń i posiada 28...40% szans na powalenie.','(20 sek.) +15...20 pkt. obrażeń od broni i 28...40% szans na powalenie w czasie ataków. Na cel nie można wybrać siebie.'],
2220=>['Wspaniała Krasnoludzka Zbroja','Przez 22...40 sek., wybrany sojusznik posiada +24 pkt. pancerza, +60 pkt. maksymalnej żywotności oraz dodatkowe +24 pkt. pancerza przeciwko niszczycielom.','(22...40 sek.) +24 pkt. pancerza i +60 pkt. do maksymalnej żywotności. Dodatkowo +24 pkt. pancerza przeciwko niszczycielom.'],
2221=>['Tchnienie Wielkiego Krasnoluda','Wszyscy członkowie drużyny przestają płonąć i otrzymują po 50...60 pkt. żywotności.','Usuwa płonięcie i dodaje 50...60 pkt. żywotności; działa na członków drużyny.'],
2222=>['Śnieżna Burza','Wywołujesz Śnieżną Burzę w miejscu, gdzie znajduje się wybrany przeciwnik. Przez 5 sek., przeciwnicy bezpośrednio przy tym miejscem otrzymują w każdej sekundzie po 30...40 pkt. obrażeń od zimna.','W każdej sekundzie zadaje 30...40 pkt. obrażeń od zimna (5 sek.). Trafia przeciwników bezpośrednio przy początkowym miejscu wybranego przeciwnika.'],
2223=>['Prochowa Mina','Kiedy Prochowa Mina zostanie uaktywniona, wszyscy przeciwnicy w pobliżu otrzymują po 20...30 pkt. obrażeń i przez 7...10 sek. będą oślepieni i będą krwawili. Prochowa Mina przestanie działać po 90 sek. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. Zadaje 20...30 pkt. obrażeń. Wywołuje przypadłości oślepienie oraz krwawienie (7...10 sek.). Łatwo przerwać.'],
2224=>['Przywołanie Mursaata','Przywołujesz mursaata na poziomie 14...20, który żyje przez 40...60 sek. i posiada Osłabiający Ładunek. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Przywołuje mursaata na poziomie 14...20 (czas życia 40...60 sek.), który posiada Osłabiający Ładunek. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2225=>['Przywołanie Rubinowego Dżinna','Przywołujesz rubinowego dżinna na poziomie 14...20, który żyje przez 40...60 sek. i posiada Samospalenie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Przywołuje rubinowego dżinna na poziomie 14...20 (czas życia 40...60 sek.), który posiada Samospalenie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2226=>['Przywołanie Lodowego Impa','Przywołujesz lodowego impa na poziomie 14...20, który żyje przez 40...60 sek. i posiada Lodowe Kolce. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Przywołuje lodowego impa na poziomie 14...20 (czas życia 40...60 sek.), który posiada Lodowe Kolce. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2227=>['Przywołanie Szamana Nag','Przywołujesz szamana nag na poziomie 14...20, który żyje przez 40...60 sek. i posiada Ukamienowanie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.','Przywołuje szamana nag na poziomie 14...20 (czas życia 40...60 sek.), który posiada Ukamienowanie. W danym momencie aktywne może być tylko 1 asuriańskie przywołanie.'],
2228=>['Wprawny Cios','Jeżeli atak trafi, wybrany przeciwnik otrzymuje 18...30 pkt. obrażeń. Jeżeli cel jest pod działaniem kruchej zbroi, będzie krwawił przez 18...30 sek.','Zadaje 18...30 pkt. obrażeń. Wywołuje przypadłość krwawienie (18...30 sek.), jeżeli wybrany przeciwnik ma pękniętą zbroję.'],
2229=>['Sygnet Infekcji','Jeżeli wybrany przeciwnik krwawi, to przez 13...20 sek. będzie pod działaniem choroby.','Wywołuje przypadłość choroba (13...20 sek.), jeżeli wybrany przeciwnik krwawi.'],
2230=>['Sygnet Tryptofanu','Przez 14...20 sek., wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim poruszają się i atakują o 23...40% wolniej.','(14...20 sek.) Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim poruszają się i atakują o 23...40% wolniej.'],
2231=>['Sztandar Odwagi Hebanowej Awangardy','W miejscu, w którym stoisz wbijasz Sztandar Odwagi Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze otrzymują +24 pkt. pancerza i dodatkowo +24 pkt. pancerza przeciwko popielcom.','(14...20 sek.) Sojusznicy w granicach tej ochrony posiadają +24 pkt. pancerza i dodatkowo +24 pkt. pancerza przeciwko popielcom. Nie działa na duchy.'],
2232=>['Sztandar Mądrości Hebanowej Awangardy','W miejscu, w którym stoisz wbijasz Sztandar Mądrości Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze mają 44...60% szans na skrócenie o połowę czasu odnawiania czarów.','(14...20 sek.) Czary rzucane przez sojuszników w granicach tej ochrony mają 44...60% szans na odnawianie się o 50% szybciej. Nie działa na duchy.'],
2233=>['Sztandar Honoru Hebanowej Awangardy','W miejscu, w którym stoisz wbijasz Sztandar Honoru Hebanowej Awangardy. Przez 14...20 sek., nie będący duchami sojusznicy na tym obszarze zadają +8...15 pkt. obrażeń i dodatkowo +7...10 pkt. obrażeń przeciwko popielcom.','(14...20 sek.) Sojusznicy w granicach tej ochrony zadają +8...15 pkt. obrażeń i dodatkowo +7...10 pkt. obrażeń przeciwko popielcom. Nie działa na duchy.'],
2234=>['Wsparcie Strzelca Hebanowej Awangardy','Wybrany przeciwnik otrzymuje 54...90 pkt. obrażeń przebijających i zaczyna krwawić na 5...25 sek.Ten atak posiada 10% szans na zadanie dodatkowych 540...900 pkt. obrażeń przebijających. Jeżeli trafi popielca ma 25% szans na zadanie dodatkowych 540...900 pkt. obrażeń przebijających.','Zadaje 54...90 pkt. obrażeń przebijających i wywołuje przypadłość krwawienie (5...25 sek.). 10% szans na +540...900 pkt. obrażeń przebijających. 25% szans na +540...900 pkt. obrażeń przebijających, jeżeli celem jest popielec.'],
2235=>['Wsparcie Zabójcy Hebanowej Awangardy','Przywołujesz Zabójcę Hebanowej Awangardy na poziomie 14...20, który posiada Żelazną Dłoń, Lisie Kły oraz Uderzenie Dziewięciu Ogonów. Ten przywołany zabójca wykonuje krok cienia do wybranego przeciwnika. Jeżeli wybranym przeciwnikiem jest popielec, to zabójca żyje przez 24...30 sek. Jeżeli wybranym przeciwnikiem nie jest popielec, to zabójca żyje przez 12...15 sek.','Przywołuje zabójcę na poziomie 14...20, który posiada Żelazną Dłoń, Lisie Kły oraz Uderzenie Dziewięciu Ogonów; wykonuje on krok cienia do tego przeciwnika. Jeżeli tym przeciwnikiem jest popielec, to zabójca żyje przez 24...30 sek. Jeżeli tym przeciwnikiem nie jest popielec, to zabójca żyje przez 12...15 sek.'],
2236=>['Studnia Zniszczenia','Wykorzystujesz najbliższe zwłoki lub poświęcasz 66% zdrowia, by utworzyć we wskazanym miejscu Studnię Zniszczenia. Przez 5...30 sek., gdy wybrany przeciwnik otrzyma obrażenia, będąc w studni, na 5...20 sek. ma pękniętą zbroję.','(5...30 sek.). U przeciwników będących w studni, którzy otrzymają obrażenia fizyczne, wywołuje przypadłość pękniętej zbroi (5...20 sek.). Zużywa świeże ciało lub poświęca 66% zdrowia.'],
2237=>['Zwyrodnienie','Przez 3...7 sek. atrybut podstawowy wybranego przeciwnika jest równy 0.','(3...7 sek.) Obniża atrybut podstawowy tego przeciwnika do 0.'],
2238=>['Włócznia Odkupienia','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli nie trafi, to tracisz jedną przypadłość.','Zadaje +5...20 pkt. obrażeń. Jeśli nie trafi, to tracisz jedną przypadłość.'],
2353=>['"Skończ z Nim!"','Jeżeli wybrany przeciwnik posiada mniej niż 50% żywotności, to otrzymuje 44...80 pkt. obrażeń i na 12...20 sek. znajdzie się pod działaniem Pękniętej Zbroi oraz głębokiej rany.','Zadaje 44...80 pkt. obrażeń i wywołuje przypadłości pęknięta zbroja oraz głęboka rana (12...20 sek.). Bez efektu, chyba że wybrany przeciwnik ma mniej niż 50% żywotności.'],
2354=>['"Uniknij Tego!"','Przez 16...20 sek. twój następny atak nie może zostać zablokowany i zadaje +14...20 pkt. obrażeń.','(16...20 sek.) Twój następny atak jest nie do zablokowania i zadaje +14...20 pkt. obrażeń.'],
2355=>['Jestem najpotężniejszy!','Twoje kolejne ataki w liczbie 5...8 zadają +14...20 pkt. obrażeń każdy.','Twoje kolejne ataki w liczbie 5...8 zadają +14...20 pkt. obrażeń.'],
2356=>['"Nikt Mnie Nie Zatrzyma!"','Przez 16...20 sek., posiadasz +24 pkt. pancerza i nie możesz zostać powalony ani okulawiony.','(16...20 sek.) Posiadasz +24 pkt. pancerza i nie możesz zostać powalony ani okulawiony.'],
2357=>['Podstępny Dotyk','Dotknięty wybrany przeciwnik otrzymuje 44...80 pkt. obrażeń. Jeśli ten przeciwnik jest powalony, to nie może atakować przez 5...8 sek.','Zadaje 44...80 pkt. obrażeń. Wybrany przeciwnik nie może atakować (5...8 sek.), jeżeli był powalony.'],
2358=>['"Ruszasz Się Jak Krasnolud!"','Cel zostaje powalony na ziemię i otrzymuje 44...80 pkt. obrażeń. Wróg ten zostaje też okulawiony na 8...15 sek.','Zadaje 44...80 obrażeń, powala na ziemię i powoduje okulawienie (8...15 sek).'],
2359=>['"Wszyscy Jesteście Słabeuszami!"','Wybrany przeciwnik i przeciwnicy bezpośrednio przy nim zostają osłabieni na 8...12 sek.','Wywołuje przypadłość osłabienie (8...12 sek.). Działa także na przeciwników w bezpośredniej odległości.'],
2360=>['Nie Czuję Bólu','Przez 30 sek. posiadasz regenerację żywotności +2...3. Jeżeli jesteś pijany aktywując tą umiejętność, to dodatkowo twoja maksymalna żywotność zwiększa się o +200...300 pkt.','(30 sek.) Posiadasz regenerację żywotności +2...3. Twoja maksymalna żywotność zwiększa się o +200...300 pkt., jeżeli jesteś pijany aktywując tą umiejętność.'],
2361=>['Maczuga Tysiąca Niedźwiedzi','Jeżeli atak trafi, zadajesz +6...9 pkt. obrażeń na każdego przeciwnika bezpośrednio przy tobie (maksymalnie 60 pkt. obrażeń). Jeśli przeciwnik nie jest człowiekiem, to zostaje powalony.','Zadaje +6...9 pkt. obrażeń za każdego przeciwnika w bezpośredniej odległości (maksymalnie 60). Powoduje powalenie, jeżeli wybrany przeciwnik nie jest człowiekiem.'],
2374=>['Błogosławieństwo Niedźwiedzicy','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu niedźwiedzicy. Przez 60 sek. posiadasz 100 pkt. pancerza i 750...800 pkt. żywotności. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki niedźwiedzicy.','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu niedźwiedzicy (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki niedźwiedzicy. Posiadasz 100 pkt. pancerza i 750...800 pkt. żywotności.'],
2379=>['Błogosławieństwo Wilka','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu wilka. Przez 60 sek. posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności oraz regenerację żywotności 2...4. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki wilka.','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu wilka (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki wilka. Posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności oraz regenerację żywotności 2...4.'],
2384=>['Błogosławieństwo Kruka','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu kruka. Przez 60 sek. posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności i 20...30% szans na blokowanie. Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki kruka.','Tracisz wszystkie efekty i znajdujesz się pod wpływem aspektu kruka (60 sek.). Wszystkie twoje atrybuty mają wartość 0, a umiejętności zamieniane są na ataki kruka. Posiadasz 80 pkt. pancerza, 660...700 pkt. żywotności i 20...30% szans na blokowanie.'],
2411=>['Umysłowe Upojenie','Przez 10...16 sek., poruszasz się o 20...33% szybciej, a rzucanie twoich czarów trwa 20% krócej.','(10...16 sek.) Poruszasz się o 20...33% szybciej, a czary rzucasz o 20% szybciej.'],
2412=>['Wykroczenie','Na 10...20 sek. jeden losowy czar wybranego przeciwnika zostaje wyłączony, a Wykroczenie zostaje zastąpione tym czarem. Otrzymujesz 5...10 pkt. energii.','(10...20 sek.) Wyłącza jeden czar. Ta umiejętność staje się tym czarem. Otrzymujesz 5...10 pkt. energii.'],
2413=>['Technobełkot','Wybrany przeciwnik i wszyscy przeciwnicy bezpośrednio przy nim otrzymują po 30...40 pkt. obrażeń. Jeżeli wybrany przeciwnik nie jest bossem, to on i wszyscy przeciwnicy bezpośrednio przy nim zostają oszołomieni na 3...5 sek.','Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 30...40 pkt. obrażeń. U tych przeciwników wywołuje przypadłość oszołomienie (3...5 sek.), jeżeli cel nie był bossem.'],
2414=>['Napromieniowany Obszar','Przez 5 sek., przeciwnicy w okolicy posiadają degenerację żywotności -4...6. Kiedy portal przestanie działać, przeciwnicy w okolicy znajdą się na 12...20 sek. pod działaniem choroby.','(5 sek.) Przeciwnicy w okolicy posiadają degenerację żywotności -4...6. Efekt końcowy: u przeciwników w okolicy wywołuje przypadłość choroba (12...20 sek.).'],
2415=>['Asuriańskie Rozpoznanie','Przez 9...12 sek., twoje ataki nie mogą chybić wybranego przeciwnika. Zabicie wroga, który znajdował się pod wpływem Asuriańskiego Rozpoznania, usuwa 5% kary za śmierć.','(9...12 sek.) Nie możesz chybić przeciwnika. Jeśli zabijesz tego przeciwnika, tracisz 5% kary za śmierć.'],
2416=>['Powietrze Doskonałości','Przez 20...30 sek., za każdym razem, kiedy zdobędziesz punkty doświadczenia za zabicie przeciwnika, otrzymasz losowy asuriański dar.','(20...30 sek.) Za każdym razem, kiedy zdobędziesz punkty doświadczenia za zabicie przeciwnika, otrzymasz losowy asuriański dar.'],
2417=>['Mentalny Blok','Przez 5...11 sek. masz 50% szans na blokowanie ataków. Zaklęcie zostaje ponownie nałożone za każdym razem, kiedy przeciwnik cię trafi.','(5...11 sek.) Masz 50% szans na blokowanie. Odnowienie: za każdym razem, kiedy przeciwnik cię trafi.'],
2418=>['Odwrócenie Bólu','Przez 6...10 sek., za każdym razem, kiedy wybrany przeciwnik zadaje obrażenia, otrzymuje 100...140% obrażeń, które zadaje (maksymalnie 80 pkt. obrażeń).','(6...10 sek.) Za każdym razem, kiedy wybrany przeciwnik zadaje obrażenia umiejętność zadaje mu 100...140% tych obrażeń (maksymalnie 80).'],
2420=>['Ucieczka Hebanowej Awangardy','Wykonujesz krok cienia do wybranego sojusznika innego niż ty. Ty i ten sojusznik otrzymujecie po 70...110 pkt. żywotności.','Tobie i wybranemu sojusznikowi dodaje po 70...110 pkt. żywotności. Efekt początkowy: wykonujesz krok cienia do tego sojusznika. Na cel nie można wybrać siebie.'],
2421=>['Osłabiająca Pułapka','Kiedy Osłabiająca Pułapka zostanie uaktywniona, wszyscy przeciwnicy w pobliżu zostają osłabieni na 10...20 sek. Wszyscy popielcy zostają powaleni. Osłabiająca Pułapka przestaje działać po 90 sekundach. W czasie, kiedy będziesz używał tej umiejętności, łatwo ci będzie przerwać.','(90 sek.) Działa na przeciwników w pobliżu. Zadaje 24...50 pkt. obrażeń od błyskawic. Wywołuje przypadłość osłabienie (10...20 sek.). Powala popielca. Łatwo przerwać.'],
2422=>['Wichry','Tworzysz ducha na 4...10 poziomie. Wszyscy przeciwnicy w jego zasięgu mają 15% szans na nietrafianie atakami zasięgowymi. Duch ginie po 54...90 sek.','Tworzy ducha na poziomie 4...10 (czas życia 54...90 sek.). Działa na przeciwników w zasięgu. 15% szans na nietrafianie ataków zasięgowych.'],
2423=>['Krasnoludzka Stabilność','Przez 24...30 sek. twoje postawy trwają o 55...100% dłużej. Jeśli aktywujesz tą umiejętność będąc pijanym, nie możesz zostać powalony.','(24...30 sek.) Twoje postawy trwają o 55...100% dłużej. Nie możesz zostać powalony, jeśli aktywowałeś tą umiejętność będąc pijanym.'],
2657=>['Zew Pośpiechu (PvP)','Przez 30 s twój zwierzęcy towarzysz atakuje i porusza się o 25% szybciej.','(30 sekund) Twój zwierzak porusza się i atakuje o 25% szybciej.'],
2734=>['Spustoszenie Umysłu (PvP)','Przez 5...40 sek., za każdym razem gdy dany przeciwnik będzie celem jednej z twoich klątw nie należących do mesmera, straci 1 energii. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.','(5...40 sek.) Powoduje utratę 1 energii za każdym razem, gdy dany przeciwnik staje się celem twojej klątwy spoza domeny mesmera. Jeśli energia wroga spadnie do 0, Spustoszenie Umysłu przestaje działać, a przeciwnik otrzymuje 15...100 pkt. obrażeń.'],
2803=>['Zamrożenie Umysłu','Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...60 pkt. obrażeń od zimna oraz porusza się o 90% wolniej przez 1...5 sek. Ten czar powoduje wyczerpanie.','Zadaje 10...60 pkt. obrażeń od zimna. Jeżeli masz więcej pkt. energii niż wybrany przeciwnik, to umiejętność zadaje 10...60 pkt. dodatkowych obrażeń od zimna i o 90% spowalnia ruch (1...5 sek.). Powoduje u ciebie wyczerpanie.'],
2804=>['Wstrząs Mózgu','Wybrany przeciwnik otrzymuje 10...50 pkt. obrażeń od błyskawic. Jeżeli masz więcej pkt. energii od wybranego przeciwnika, to przeciwnik ten otrzymuje dodatkowe 10...50 pkt. obrażeń od błyskawic oraz zostaje powalony. Ten czar posiada 25% przebicia pancerza, ale powoduje wyczerpanie.','Zadaje 10...50 pkt. obrażeń od błyskawic. Zadaje 10...50 pkt. dodatkowych obrażeń od błyskawic i powala, jeżeli masz więcej energii niż ten przeciwnik. 25% przebicie pancerza. Powoduje u ciebie wyczerpanie.'],
2805=>['Mglisty Kształt','Przez 10...45 sek., nie możesz otrzymać, ani zadać obrażeń podczas ataku.','(10...45 sek.) Nie otrzymujesz obrażeń z ataków. Twoje ataki nie zadają obrażeń.'],
2806=>['Ochrona przed Krzywdą','W miejscu, w którym przebywasz, tworzysz Ochronę przed Krzywdą. Przez 5...15 sek. nie będący duchami sojusznicy w tej okolicy otrzymują po 12...24 pkt. pancerza przeciwko obrażeniom od ognia i po 1...3 pkt. pancerza przeciwko innym obrażeniom.','(5...15 sek.) Sojusznicy w granicach tej ochrony posiadają +12...24 pkt. pancerza przeciwko obrażeniom od ognia i +1...3 pkt. pancerza przeciwko innym obrażeniom. Nie działa na duchy.'],
2807=>['Skok Błyskawicy','Błyskawicznie skaczesz do wybranego przeciwnika. Wybrany przeciwnik otrzymuje 10...70 pkt. obrażeń od błyskawic. Ten czar posiada 25% przebicie pancerza, ale powoduje wyczerpanie.','Zadaje 10...70 pkt. obrażeń od błyskawic. 25% przebicie pancerza. Natychmiast ruszasz do tego przeciwnika. Powoduje u ciebie wyczerpanie.'],
2808=>['Gniewne Uderzenie (PvP)','Jeśli Gniewne Uderzenie trafi, otrzymujesz dawki adrenaliny (1...3). Jeśli trafisz poruszającego się wroga, zadajesz +10...40 pkt. obrażeń, a cel zostaje powalony na ziemię.','Jeśli trafisz, otrzymujesz dawki adrenaliny (1...3). Jeśli przeciwnik się poruszał, zadaje mu +10...40 pkt. obrażeń i powala go na ziemię.'],
2809=>['Obsydianowy Płomień','Wybranemu przeciwnikowi zadajesz 22...92 pkt. obrażeń. Ten czar ignoruje pancerz, ale powoduje wyczerpanie.','Zadaje 22...92 pkt. obrażeń. Powoduje u ciebie wyczerpanie.'],
2857=>['Egida (PvP)','Przez 1...3 sek., wybrany inny członek drużyny nie może być celem wrogich zaklęć, a ataki przeciwko niemu nie udają się.','(1...3 sek.) Wybrany członek drużyny nie może być celem wrogich zaklęć. Ataki przeciwko niemu nie udają się. Nie można użyć na sobie.'],
2858=>['"Pilnujcie się!!" (PvP)','Członkowie drużyny w zasięgu słuchu na 10 sek. otrzymują +5...25 pkt. pancerza. Ten zaśpiew przestanie działać po otrzymaniu 1...3 ataków.','(10 sek.) Członkowie drużyny w zasięgu słuchu posiadają +5...25 pkt. pancerza. Przestanie działać po otrzymaniu 1...3 ataków.'],
2859=>['Osłabienie (PvP)','Przez 10...30 sek. wybrany przeciwnik cierpi na osłabienie.','Wywołuje przypadłość osłabienie (10...30 sek.).'],
2860=>['Eteryczna Odnowa (PvP)','Przez 10 sek., za każdym razem, kiedy rzucasz czar, otrzymujesz 1...3 pkt. energii i 5...20 pkt. żywotności za każde zaklęcie, które masz na sobie.','(10 sek.) Za każdym razem, kiedy rzucasz czar, otrzymujesz 1...3 pkt. energii i 5...20 pkt. żywotności, za każde zaklęcie, które masz na sobie.'],
2861=>['Przeszywający Atak (PvP)','Jeśli Przeszywający Atak trafi, zadajesz +5...15 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Zadaje +5...15 pkt. obrażeń. 10% przebicie pancerza.'],
2862=>['Cienisty Kształt (PvP)','Przez 5...15 sek. wszystkie wrogie czary, których jesteś celem, zawodzą oraz wszystkie ataki na ciebie nie trafiają. Gdy Cienisty Kształt przestanie działać, zostaje ci tylko 5...50 pkt. żywotności.','(5...15 sek.) Wrogie czary, których jesteś celem zawodzą, a ataki w ciebie nie trafiają. Efekt końcowy: twoja żywotność spada do 5...50 pkt.'],
2863=>['Niezgoda (PvP)','Jeżeli wybrany przeciwnik cierpi na przypadłość i jest pod wpływem klątwy lub zaklęcia, przeciwnik ten otrzymuje 30...110 pkt. obrażeń.','Zadaje 30...110 pkt. obrażeń. Bez efektu, chyba że wybrany przeciwnik jest pod działaniem przypadłości i ma na sobie klątwę lub zaklęcie.'],
2864=>['Rozdzielający Atak (PvP)','Jeśli Rozdzielający Atak trafi, zadajesz +5...15 pkt. obrażeń. Ten atak ma 10% przebicie pancerza.','Zadaje +5...15 pkt. obrażeń. 10% przebicie pancerza.'],
2866=>['Ciało z Mego Ciała (PvP)','Tracisz połowę aktualnej liczby punktów żywotności. Wskrzeszasz wybranego członka drużyny z twoim aktualnym poziomem żywotności i z 5...20% pkt. energii.','Wskrzeszasz wybranego członka drużyny (połowa twojej aktualnej żywotności i 5...20% energii). Tracisz połowę żywotności.'],
2867=>['Gniew Przodków (PvP)','Przez 3 sek., przeciwnicy w bezpośrednim sąsiedztwie wybranego sojusznika otrzymują co sekundę 4...50 pkt. obrażeń od błyskawic.','(3 sek.) Przeciwnikom bezpośrednio przy wybranym sojuszniku zadaje co sekundę po 4...50 pkt. obrażeń od błyskawic.'],
2868=>['Odłamkowy Oręż (PvP)','Przez 20 sek. wskazany sprzymierzeniec otrzymuje Odłamkowy Oręż. Kolejne ataki sojusznika (1...5 ) zadają 5...40 pkt.obrażeń maksymalnie 4 pobliskim wrogom.','(20 sek.) Ataki zadają po 5...40 pkt. obrażeń 3 przeciwnikom w bezpośredniej odległości. Koniec po 1...5 atakach.'],
2869=>['Remedium Zabójcy (PvP)','Przez 30 sek. kolejne użyte przez ciebie umiejętności związane z atakiem (w liczbie 1...10) usuwają po jednej przypadłości.','(30 sek.) Twoje następne umiejętności związane z atakami w liczbie 1...10 usuwają po jednej przypadłości.'],
2871=>['Światło Wybawienia (PvP)','Wszyscy członkowie drużyny odzyskują 5...70 pkt. żywotności. Wszystkie twoje modlitwy ofensywne są niedostępne przez 20 sek.','Przywraca 5...70 pkt. żywotności całej drużynie. Blokuje twoje modlitwy ofensywne (20 sek.).'],
2872=>['Sygnet Śmiertelnego Paktu (PvP)','Wskrzeszasz wybranego członka drużyny, który powraca do życia z tyloma punktami żywotności ile masz ich ty i 15...100% maksymalnych pkt. energii. Kiedy następnym razem ten sojusznik zginie w ciągu 120 sek., zginiesz i ty.','Wskrzesza wybranego członka drużyny z twoim aktualnym poziomem żywotności i 15...100% maksymalnej energii. W ciągu 120 sek. umrzesz, kiedy następnym razem zginie ten członek drużyny.'],
2875=>['Rzut Grabieżcy (PvP)','Jeśli atak trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafi poruszającego się przeciwnika, zadaje 5...40 pkt. dodatkowych obrażeń.','Zadaje +5...20 pkt. obrażeń. Zadaje 5...40 pkt. dodatkowych obrażeń, jeżeli cel porusza się.'],
2876=>['Obronny Hymn (PvP)','Przez 4...10 sek. każdy członek drużyny w zasięgu słuchu ma 50% szans na blokowanie ataków. Zaśpiew przestanie działać, kiedy członek drużyny trafi używając umiejętności związanej z atakami.','(4...10 sek.) Członkowie drużyny w zasięgu słuchu mają 50% szans na blokowanie. Przestanie działać, kiedy trafi umiejętność związana z atakiem.'],
2877=>['Ballada Odnowy (PvP)','Przez 10 sek., każdy sojusznik w zasięgu słuchu z następnym otrzymaniem obrażeń, dostanie 15...75 pkt. żywotności.','(10 sek.) Członkowie drużyny w zasięgu słuchu otrzymują po 15...75 pkt. żywotności, kiedy następnym razem otrzymają obrażenia.'],
2878=>['Pieśń Odnowy (PvP)','Przez 10 sek. każdy członek drużyny w zasięgu słuchu z następnym użyciem umiejętności, otrzyma 45...110 pkt. żywotności.','(10 sek.) Członkowie drużyny w zasięgu słuchu, ze swoją następną umiejętnością otrzymują 45...110 pkt. żywotności.'],
2879=>['"Nadchodzą!" (PvP)','Przez 4...10 sek., wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.','(4...10 sek.) Wszyscy sojusznicy w zasięgu słuchu poruszają się o 33% szybciej i zyskują 5...15 pkt. żywotności na sekundę podczas ruchu.'],
2880=>['Nie Poddawajcie Się! (PvP)','Przez 10 sek. wszyscy członkowie drużyny w zasięgu słuchu i mający mniej niż 75% pkt. żywotności, posiadają regenerację żywotności +1...5.','(10 sek.) Członkowie drużyny w zasięgu słuchu posiadają regenerację żywotności +1...5. Działa tylko na członków drużyny posiadających mniej niż 75% żywotności.'],
2883=>['"Za Większą Sprawiedliwość!" (PvP)','Przez 8 sekund, za każdym razem, kiedy trafisz podczas ataku, otrzymujesz adrenalinę w liczbie dawek: 1.','(8 sekund). Otrzymujesz adrenalinę w liczbie dawek: 1 za każdym razem, kiedy trafisz podczas ataku.'],
2884=>['Mistyczna Regeneracja (PvP)','Na 5...20 sek. otrzymujesz regenerację żywotności +1...4 na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 3).','(5...20 sek.) Posiadasz regenerację żywotności +1...4 na każde zaklęcie, pod którego jesteś działaniem (maksymalnie 3).'],
2885=>['Osłabiająca Krew (PvP)','Wybrany przeciwnik i wszyscy przeciwnicy w pobliżu cierpią na osłabienie przez 1...16 sek.','Osłabia (1...16 sek.) wybranego przeciwnika i wszystkich przeciwników w pobliżu.'],
2887=>['Sygnet Osądu (PvP)','Cel zostaje powalony. Wybrany przeciwnik i wszyscy przeciwnicy przy nim otrzymują 5...50 pkt. świętych obrażeń. Sygnet ma połowę normalnego zasięgu.','Powala cel. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po 5...50 pkt. świętych obrażeń.'],
2891=>['Aura Nieustępliwości (PvP)','Przywraca do życia martwego członka drużyny z pełną żywotnością i energią. Jeśli przestaniesz utrzymywać to zaklęcie lub jeśli zostanie ono zdjęte, ten członek drużyny umrze i pozostawi zużyte ciało. Śmierci poniesione podczas działania Aury Nieustępliwości nie zwiększają kary za śmierć. (50% szans na niepowodzenie, gdy wartość Łaski Bogów wynosi 4 lub mniej).','Wskrzesza wybranego członka drużyny (pełna żywotność, pełna energia). Efekt końcowy: ten sojusznik umiera i zostawia zużyte ciało. Nie zwiększa kary za śmierć. 50% szans na niepowodzenie, chyba że wartość Łaski Bogów wynosi 5 lub więcej.'],
2892=>['Duchowa Więź (PvP)','Przez 8 sek., za każdym razem, kiedy wybrany sojusznik z kolejnych 10 ataków lub czarów otrzyma więcej niż 50 pkt. obrażeń, dostanie 30...90 pkt. żywotności.','(8 sek.) Dodaje 30...90 pkt. żywotności, za każdym razem, kiedy wybrany sojusznik otrzymuje więcej niż 50 pkt. obrażeń. Przestanie działać, jeśli ten sojusznik otrzyma obrażenia z 10 ataków lub czarów.'],
2893=>['Ochronny Oręż (PvP)','Na 3...8 sek. wybrany sojusznik otrzymuje Ochronny Oręż, który zapewnia mu regenerację żywotności +2...4 oraz 50% szans na blokowanie ciosów. Ochronny Oręż przestanie działać, jeżeli ten sojusznik zaatakuje.','(3...8 sek.) Regeneracja żywotności +2...4. 50% szans na blokowanie.Kończy się, jeżeli wybrany sojusznik zaatakuje.'],
2895=>['Dar Pogromcy (PvP)','Przez 4 sek. twoje czary oparte na Modlitwach Ofensywnych zapewniają podwójną premię pochodzącą od Łaski Bogów.','(4 sek.) Dla umiejętności z Modlitw Ofensywnych punkty żywotności otrzymywane dzięki Łasce Bogów są podwajane.'],
2925=>['Strzał Łowcy Ospałych (PvP)','Jeżeli atak trafi, wybrany przeciwnik otrzymuje +5...15 pkt. obrażeń. Jeżeli przeciwnik ten nie używa umiejętności, to Strzał Łowcy Ospałych zadaje dodatkowe +5...20 pkt. obrażeń.','Zadaje +5...15 pkt. obrażeń. Zadaje +5...20 pkt. dodatkowych obrażeń, jeżeli wybrany przeciwnik nie używa umiejętności.'],
2959=>['Mistrzowska Sprawność (PvP)','Przez 1...20 sek. atakujesz o 15% szybciej, a twoje Umiejętności Strzeleckie zwiększają się o 1.','(1...20 sek.) Atakujesz o 15% szybciej i posiadasz +1 do Umiejętności Strzeleckich.'],
2965=>['Sygnet Duchów (PvP)','Otrzymujesz 3...12 pkt. energii za każdego ducha w zasięgu słuchu.','Otrzymujesz 3...12 pkt. energii. Bez efektu, jeśli nie jesteś w zasięgu słuchu ducha.'],
2966=>['Sygnet Niematerialnej Potęgi (PvP)','Ataki wybranego, sojuszniczego przyzwanego stworzenia zadają 5...35 pkt. dodatkowych obrażeń. Po 10 sek. stworzenie to zostaje zniszczone.','Wybrane, sojusznicze przyzwane stworzenie zadaje +5...35 pkt. obrażeń. Po 10 sek. stworzenie to zostaje zniszczone.'],
2969=>['Czytanie Wiatru (PvP)','Przez 24 sek. twoje strzały lecą dwa razy szybciej.','(24 sek.) Twoje strzały lecą dwa razy szybciej.'],
2998=>['Kruchość (PvP)','Przez 8...20 sek., wybrany cel i sąsiadujący przeciwnicy otrzymują 5...20 pkt. obrażeń za każdym razem, kiedy zaczynają cierpieć lub zdrowieć z przypadłości.','Klątwa działa także na przeciwników bezpośrednio przy celu (8...20 sek.). Przeciwnicy ci otrzymują 5...20 obrażeń za każdym razem gdy tracą lub otrzymują jakąś przypadłość.'],
2999=>['Siła Honoru (PvP)','Podczas gdy utrzymujesz to zaklęcie, wybrany sojusznik zadaje 1...5 pkt. dodatkowych obrażeń w walce wręcz.','W walce wręcz wybrany sojusznik zadaje 1...5 pkt. dodatkowych obrażeń.'],
3002=>['Wytrzymałość Wojownika (PvP)','Przez 5...35 sek., za każdym razem kiedy trafisz w walce wręcz, otrzymujesz 3 punkty Energii. Wytrzymałość Wojownika nie może zwiększyć twojej energii powyżej 10...25 pkt.','(5...35 sek.) Otrzymujesz 3 punkty Energii, za każdym razem, kiedy twój atak wręcz trafi. Nie otrzymujesz energii, jeżeli masz więcej niż 10...25 pkt. energii.'],
3003=>['Zbroja Nieczułości (PvP)','Przez 10...35 sek. otrzymywane przez ciebie obrażenia bazowe zostają zmniejszone o 10, jeżeli rzucasz rytuał spętania.','(10...35 sek.) Posiadasz bazową redukcję obrażeń 10, jeżeli rzucasz rytuał spętania.'],
3005=>['Przymierze (PvP)','Tworzysz 1...8 poziomowego ducha. Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty zostają zmniejszone o 15 pkt., a duch otrzymuje 15 pkt. obrażeń. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Za każdym razem, kiedy nie będący duchem sojusznik w zasięgu otrzymuje obrażenia lub zostaje mu wykradziona żywotność, efekty te zostają zmniejszone o 15, a duch otrzymuje 15 pkt. obrażeń.'],
3006=>['Pieśń Cienia (PvP)','Tworzy ducha o poziomie 1...6. Ataki ducha zadają 5...20 pkt. obrażeń i powodują ślepotę przez 1...6 sek. Duch umiera po 30 sekundach.','Tworzy ducha o poziomie 1...6 (długość życia: 30 sek.). Jego ataki zadają 5...20 pkt. obrażeń i powodują ślepotę (1...6 sek.).'],
3007=>['Ból (PvP)','Tworzysz 1...8 poziomowego ducha. Ataki tego ducha zadają 5...30 pkt. obrażeń. Ten duch ginie po 30...150 sek.','Tworzy ducha na poziomie 1...8 (czas życia 30...150 sek.). Jego ataki zadają 5...30 pkt. obrażeń.'],
3008=>['Zniszczenie (PvP)','Tworzysz ducha na poziomie 1...10, który ginie po 30 sek. Gdy ten duch ginie, wszyscy przeciwnicy w okolicy otrzymują 1...10 pkt. obrażeń za każdą sekundę życia ducha (maksymalnie 150 pkt. obrażeń).','Tworzy ducha na poziomie 1...10 (czas życia 30 sek.). W momencie śmierci zadaje wszystkim przeciwnikom w okolicy po 1...10 pkt. obrażeń na każdą sekundę swojego życia (maksymalnie 150 pkt. obrażeń).'],
3009=>['Ukojenie (PvP)','Tworzysz 1...8 poziomowego ducha. Wszyscy przeciwnicy w jego zasięgu otrzymują adrenalinę dwa razy wolniej. Ten duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...8 (czas życia 15...45 sek.). Przeciwnicy w zasięgu dwa razy dłużej gromadzą adrenalinę.'],
3010=>['Przemieszczenie (PvP)','Tworzysz 1...10 poziomowego ducha. Wszyscy sojusznicy nie-duchy w jego zasięgu mają 75% szans na blokowanie ataków. Za każdym razem, gdy atak zostanie w ten sposób zablokowany, duch otrzyma 60 pkt. obrażeń. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu mają 75% szans na blokowanie. Efekt zablokowania: ten duch otrzymuje 60 pkt. obrażeń.'],
3011=>['Zabezpieczenie (PvP)','Tworzysz 1...10 poziomowego ducha. Co 4 sek. ten duch leczy jednego nie będącego duchem sojusznika w okolicy dodając mu 10...115 pkt. żywotności. Ten duch ginie po 90 sek.','Tworzy ducha na poziomie 1...10 (czas życia 90 sek.). Co 4 sek. ten duch leczy jednego sojusznika nie-ducha, dodając mu 10...115 pkt. żywotności.'],
3012=>['Życie (PvP)','Tworzysz 1...10 poziomowego ducha. Gdy ten duch ginie, wszyscy nie będący duchami sojusznicy w jego zasięgu otrzymują 1...7 pkt. żywotności za każdą sekundę życia tego ducha. Ten duch ginie po 20 sek.','Tworzy ducha na poziomie 1...10 (czas życia 20 sek.). Działa na sojuszników nie-duchy w zasięgu. Efekt końcowy: dodaje 1...7 pkt. żywotności na każdą sekundę życia tego ducha.'],
3013=>['Rekonwalescencja (PvP)','Tworzy ducha o poziomie 1...10. Sojusznicy w jego zasięgu, którzy nie są duchami, otrzymują premię +1...3 do regeneracji żywotności. Duch umiera po 15...45 sek.','Tworzy ducha o poziomie 1...10 (długość życia: 15...45 sek.). Sojusznicy w jego zasięgu, którzy nie są duchami, otrzymują premię +1...3 do regeneracji żywotności.'],
3014=>['Dysonans (PvP)','Tworzysz 1...8 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a czynność każdego kto otrzyma od niego obrażenia, zostaje przerwana. Duch ginie po 10...25 sek.','Tworzy ducha na poziomie 1...8 (czas życia 10...25 sek.). Jego ataki zadają 5...20 pkt. obrażeń i przerywają czynności.'],
3015=>['Uziemienie (PvP)','Tworzysz 1...10 poziomowego ducha. Wszyscy nie będący duchami przeciwnicy powaleni w zasięgu tego ducha, zostają powaleni na przynajmniej 3 sek. Za każdym razem, kiedy tak się dzieje, ten duch traci 50...25 pkt. żywotności. Ten duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...45 sek.). Za każdym razem, kiedy przeciwnik nie-duch w zasięgu zostanie powalony, będzie powalony przez przynajmniej 3 sek. Koszt powalenia: ten duch traci 50...25 pkt. żywotności.'],
3016=>['Schronienie (PvP)','Tworzysz 1...8 poziomowego ducha. Nie będący duchami sojusznicy w jego zasięgu od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Za każdym razem, kiedy ten duch zapobiega obrażeniom, traci 75...45 pkt. żywotności. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Sojusznicy nie-duchy w zasięgu, od pojedynczego ataku nie mogą stracić więcej niż 10% maksymalnych pkt. żywotności. Koszt ochrony przed obrażeniami: ten duch traci 75...45 pkt. żywotności.'],
3017=>['Antyzaklęcie (PvP)','Tworzysz 1...8 poziomowego ducha. Ten duch zadaje 5...20 pkt. obrażeń, a każdy kto otrzyma od niego obrażenia, traci jedno zaklęcie. Duch ginie po 15...40 sek.','Tworzy ducha na poziomie 1...8 (czas życia 15...40 sek.). Jego ataki zadają 5...20 pkt. obrażeń i usuwają zaklęcie.'],
3018=>['Odnowa (PvP)','Tworzysz 1...10 poziomowego ducha. Gdy ten duch ginie, wszyscy członkowie drużyny w okolicy zostają wskrzeszeni z 5...50% pkt. żywotności i z zerem pkt. energii. Ten duch ginie po 30 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30 sek.). Efekt końcowy: wskrzesza martwych członków drużyny w okolicy (5...50% żywotności, 0 pkt. energii).'],
3019=>['Pieśń Krwi (PvP)','Tworzysz ducha na poziomie 1...8, który ginie po 30...150 sek. Ataki tego ducha wykradają do 5...25 pkt. żywotności.','Tworzy ducha na poziomie 1...8 (czas życia 30...150 sek.). Jego ataki wykradają 5...25 pkt. żywotności.'],
3020=>['Żądza Wędrowania (PvP)','Tworzysz 1...8 poziomowego ducha. Za każdym razem, kiedy ten duch trafia stojącego w miejscu przeciwnika, ten przeciwnik zostaje powalony, a duch traci 70...50 pkt. żywotności. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...8 (czas życia 30...60 sek.). Jego ataki powalają przeciwników stojących w miejscu. Koszt powalenia: ten duch traci 70...50 pkt. żywotności.'],
3021=>['Żar Sawanny (PvP)','W miejscu, gdzie znajduje się wybrany przeciwnik tworzysz Żar Sawanny. Przez 5 sek. wszyscy przeciwnicy w pobliżu otrzymują co sekundę 5...20 pkt. obrażeń od ognia za każdą sekundę działania tego czaru.','W każdej sekundzie od rzucenia czaru zadaje 5...20 pkt. obrażeń od ognia (5 sek.). Trafia przeciwników w pobliżu początkowego miejsca znajdowania się celu.'],
3022=>['Spojrzenie Furii (PvP)','Niszczy wybranego sprzymierzonego ducha, by stworzyć Ducha Furii poziomu 1...10. Ataki tego ducha zadają 5...20 pkt. obrażeń. Duch umiera po 30...60 sek.','Niszczy sprzymierzonego ducha. Tworzy ducha o poziomie 1...10 (długość życia: 30...60 sek.). Jego ataki zadają 5...20 pkt. obrażeń.'],
3023=>['Katusze (PvP)','Tworzysz 1...7 poziomowego ducha. Ataki tego ducha zadają 5...20 pkt. obrażeń, a przeciwnikom pod działaniem klątw zadają podwójne obrażenia. Duch ginie po 15...45 sek.','Tworzy ducha na poziomie 1...7 (czas życia 15...45 sek.). Jego ataki zadają 5...20 pkt. obrażeń. Podwójne obrażenia dla przeciwników pod działaniem klątwy.'],
3024=>['Wzmocnienie (PvP)','Tworzysz 1...10 poziomowego ducha. Wszyscy sojusznicy w jego zasięgu, którzy trzymają przedmiot otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii. Duch ginie po 15...60 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...60 sek.). Sojusznicy w zasięgu, którzy trzymają przedmiot, otrzymują 15...45 pkt. do maksymalnej żywotności i 10 pkt. do maksymalnej energii.'],
3025=>['Ozdrowienie (PvP)','Tworzysz 1...10 poziomowego ducha. Przypadłości, na które cierpią sojusznicy w jego zasięgu kończą się o 20...50% szybciej. Duch ginie po 30...60 sek.','Tworzy ducha na poziomie 1...10 (czas życia 30...60 sek.). Przypadłości, na które cierpią sojusznicy w zasięgu, kończą się o 20...50% szybciej.'],
3026=>['Po Oczach! (PvP)','Przez 10 sek., następny atak wykonany przez każdego sojusznika w zasięgu słuchu ma dodatkowe 30...75% szans na trafienie krytyczne.','(10 sek.) Sojusznicy w zasięgu słuchu mają +30...75% szans na wykonanie trafienia krytycznego w czasie swojego następnego ataku.'],
3027=>['Ustój! (PvP)','Przez 5...15 sek., następnym razem, gdy wybrany sojusznik inny niż ty ma zostać powalony, 1 przeciwnik w pobliżu otrzymuje w zamian 15...90 pkt. obrażeń.','(5...15 sek.) Ochroni przed następnym powaleniem i zadaje 15...90 pkt. obrażeń jednemu przeciwnikowi w pobliżu wybranego sojusznika. Na cel nie można wybrać siebie.'],
3028=>['Ognisty Finał (PvP)','Przez 10...35 sek., za każdym razem, kiedy zaśpiew lub okrzyk przestaną działać na wybranym sojuszniku nie-duchu, wszyscy przeciwnicy bezpośrednio przy tym sojuszniku zaczną płonąć przez 1...5 sek.','(10...35 sek.) U przeciwników w bezpośredniej odległości wywołuje przypadłość płonięcie (1...5 sek.), za każdym razem, kiedy zaśpiew lub okrzyk przestanie działać na wybranym sojuszniku. Na cel nie można wybrać ducha.'],
3029=>['Zaśpiew Odpędzenia Ostrzy (PvP)','Przez 20 sek. wybrany sojusznik nie-duch posiada +10...40 pkt. pancerza przeciwko obrażeniom ciętym. To echo jest ponownie nakładane za każdym razem, kiedy przestanie na tym sojuszniku działać zaśpiew lub okrzyk.','(20 sek.) Wybrany sojusznik posiada +10...40 pkt. pancerza przeciwko obrażeniom ciętym. Odnowienie: za każdym razem, kiedy przestaje na tym sojuszniku działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
3030=>['Sygnet Powrotu (PvP)','Wskrzeszasz wybranego członka drużyny, który zmartwychwstaje z 5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu.','Wskrzesza wybranego członka drużyny (5...20% pkt. żywotności i 1...4% pkt. energii na każdego członka drużyny w zasięgu słuchu).'],
3031=>['Łapy Precz! (PvP)','Przez 20 sek. następne 1...5 umiejętności oparte na dotyku, użyte przeciwko tobie nie zadziałają.','(20 sek.) Następne 1...5 umiejętności oparte na dotyku, użyte przeciwko tobie nie zadziałają.'],
3032=>['Utrzymać Pozycje! (PvP)','Przez 5...20 sek., wszyscy członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeśli się nie poruszają. Efekt przestaje działać na sojuszniku, jeśli ten zaatakuje.','(5...20 sek.) Członkowie drużyny w zasięgu słuchu otrzymują +24 pkt. pancerza, jeżeli się nie poruszają. Przestaje działać, jeśli dany sojusznik zaatakuje.'],
3033=>['Jeszcze Tu Wrócimy! (PvP)','Przez 10 sek., za każdym razem, kiedy członkowie drużyny w zasięgu słuchu użyją umiejętności wskrzeszającej, zmartwychwstający sojusznicy powracają do życia z dodatkowymi 10...75% pkt. żywotności i 5...50% pkt. energii.','(10 sek.) Za każdym razem, kiedy członkowie drużyny w zasięgu słuchu użyją umiejętności wskrzeszającej, zmartwychwstający sojusznicy powracają do życia z dodatkowymi 10...75% pkt. żywotności i 5...50% pkt. energii.'],
3034=>['Odnajdźcie Ich Słabości! (PvP)','Przez 5...20 sek., kiedy następnym razem wybrany sojusznik spowoduje obrażenia krytyczne, to zada też głęboka ranę na 5...20 sek.','(5...20 sek.) Z następnym trafieniem krytycznym wybrany sojusznik wywołuje przypadłość głęboka rana (5...20 sek.).'],
3035=>['Trzymać Się! (PvP)','Wszyscy sojusznicy w zasięgu słuchu i posiadający mniej niż 75% pkt. żywotności otrzymują 1...10 pkt. energii.','Sojusznicy w zasięgu słuchu otrzymują 1...10 pkt. energii. Działa tylko na sojuszników posiadających mniej niż 75% żywotności.'],
3036=>['"Pomocy!" (PvP)','Wskazany sojusznik niebędący duchem zyskuje 5...50 pkt. zdrowia. Przez 1...10 sek. zaklęcia innych sojuszników, których celem jest ten sojusznik, są rzucane o 50% szybciej.','(1...10 sek.) Wskazany sojusznik niebędący duchem zyskuje 5...50 pkt. zdrowia, zaklęcia sojuszników rzucane na niego są rzucane o 50% szybciej.'],
3037=>['Wycofać Się! (PvP)','Przez 4...10 sek. wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość zwiększa się o 33%. "Wycofać Się!" przestanie działać na sojuszniku z jego kolejnym trafionym atakiem.','(4...10 sek.) Wszyscy poruszający się sojusznicy w zasięgu słuchu otrzymują 5...15 pkt. żywotności na sek., a ich szybkość ruchu zwiększa się o 33%. Przestanie działać na sojusznika, jeśli jego atak trafi.'],
3038=>['Agonia (PvP)','Tworzysz 1...8 poziomowego ducha. Obecność ducha powoduje, że każdy przeciwnik w jego zasięgu słuchu co sekundę traci 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego przeciwnika, który w ten sposób ucierpi. Duch ginie po 30...90 sek.','Tworzy ducha na poziomie 1...8 (czas życia 30...90 sek.). Przeciwnicy w zasięgu słuchu co sekundę tracą 3...10 pkt. żywotności. Ten duch traci 3...10 pkt. żywotności na każdego przeciwnika, który traci żywotność.'],
3039=>['Odmłodzenie (PvP)','Tworzysz 1...16 poziomowego ducha. Duch uzdrawia każdego członka drużyny w zasięgu słuchu, w każdej sekundzie dodając mu 3...10 pkt. żywotności. Duch traci 3...10 pkt. żywotności, na każdego członka drużyny uzdrowionego w ten sposób. Duch ginie po 30...90 sek.','Tworzy ducha na poziomie 1...16 (czas życia 30...90 sek.). Członkowie drużyny w zasięgu słuchu otrzymują co sekundę po 3...10 pkt. żywotności. Koszt uleczenia: ten duch traci 3...10 pkt. żywotności.'],
3040=>['Hymn Rozproszenia (PvP)','Przez 1...10 sek. następna umiejętność związana z atakami, używana przez każdego sojusznika w zasięgu słuchu, przerywa także czynność przeciwnika.','(1...10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem przerywają czynność przeciwnika.'],
3045=>['Uzdrowienie Zwierzęcia (PvP)','Leczysz swojego zwierzęcego towarzysza dodając mu 40...120 pkt. żywotności. Jeśli jest martwy, wskrzeszasz go z 10...58% punktami żywotności. Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.','Twój zwierzęcy towarzysz otrzymuje 40...120 pkt. żywotności. Wskrzesza twojego zwierzęcego towarzysza (10...58% żywotności). Jeśli masz na wyposażeniu Uzdrowienie Zwierzęcia, twój towarzysz będzie podróżował wraz z tobą.'],
3047=>['Natarcie Melandru (PvP)','Twój zwierzęcy towarzysz wykonuje Natarcie Melandru, które zadaje +5...20 pkt. obrażeń. Jeśli atak trafi przeciwnika pod działaniem zaklęcia, to przeciwnik ten i wrogowie znajdujący się bezpośrednio przy nim otrzymają +5...35 pkt. dodatkowych obrażeń.','Zadaje +5...20 pkt. obrażeń. Wybranemu przeciwnikowi i przeciwnikom bezpośrednio przy nim zadaje po +5...35 pkt. dodatkowych obrażeń, jeżeli ten przeciwnik jest pod działaniem zaklęcia.'],
3048=>['Całun Boleści (PvP)','Przez 30...60 sek., jeżeli masz mniej niż 50% pkt. żywotności, masz 75% szansy na zablokowanie ataków.','(30...60 sek.) Masz 75% szans na blokowanie. Bez efektu, chyba że twoja żywotność jest poniżej 50%.'],
3049=>['Niewidoczna Furia (PvP)','Przez 15...60 sek., twoich ataków nie mogą zablokować oślepieni przeciwnicy.','(15...60 sek.) Nie możesz zostać zablokowany przez oślepionych przeciwników.'],
3050=>['Drapieżcza Więź (PvP)','Przez 5...20 s, ataki twojego zwierzęcego towarzysza leczą cię, dodając ci 1...31 pkt. żywotnoci.','(5...20 s) Otrzymujesz 1...31 pkt. żywotności, za każdym razem, kiedy twój zwierzęcy towarzysz wykona udany atak.'],
3051=>['Rozszalałe Uderzenie (PvP)','Twój zwierzęcy towarzysz wykonuje Rozszalałe Uderzenie, które zadaje +3...23 pkt. obrażeń (maksymalna premia to 60 pkt.) na każdą odnawiającą się umiejętność Panowania nad Zwierzętami.','Zadaje +3...23 pkt. obrażeń (maksymalnie 60) za każdą odnawiającą się umiejętność Panowania nad Zwierzętami.'],
3053=>['Sygnet Śmiertelnego Zepsucia (PvP)','Musi następować po podwójnym ataku. Zaatakowany wróg otrzymuje 5...35 pkt. obrażeń za każdą posiadaną przypadłość (maksymalnie 130 pkt. obrażeń).','Zadaje 5...35 pkt. obrażeń (maksymalnie 130) za każdą przypadłość na wybranym przeciwniku. Musi nastąpić po ataku podwójnym.'],
3054=>['Masochizm (PvP)','Przez 30 s, za każdym razem, kiedy poświęcisz punkty żywotności, otrzymasz 1...3 pkt. energii.','(30 s) Otrzymasz 1...3 energii za każdym razem, gdy poświęcisz żywotność.'],
3058=>['Bluźniercza Uczta (PvP)','Wykradasz do 10...65 pkt. żywotności od maksymalnie 1...4 przeciwników w okolicy.','Wykrada 10...65 pkt. żywotności od 1...4 przeciwników w twojej okolicy.'],
3059=>['Sygnet Agonii (PvP)','Krwawisz przez 25 sek. Wszyscy przeciwnicy w pobliżu otrzymują 10...70 pkt. obrażeń.','Przeciwnikom w pobliżu ciebie zadaje po 10...70 pkt. obrażeń. Krwawisz (25 sek.).'],
3060=>['Ucieczka (PvP)','Przez 1...8 sek., poruszasz się o 33% szybciej i masz 75% szansy na zablokowanie ataków. Ucieczka przestaje działać po wykonaniu ataku wręcz.','(1...8 sek.) Poruszasz się o 33% szybciej i masz 75% szans na zablokowanie ataków. Przestaje działać po wykonaniu ataku wręcz.'],
3061=>['Zabójczy Kwiat (PvP)','Musi nastąpić po ataku drugą ręką. Zabójczy Kwiat zadaje wybranemu przeciwnikowi +20...45 pkt. obrażeń, wszyscy przeciwnicy bezpośrednio przy nim otrzymują 20...45 pkt. obrażeń.','Zadaje +20...45 pkt. obrażeń. Działa także na przeciwników bezpośrednio przy wybranym przeciwniku. Musi nastąpić po ataku drugą ręką.'],
3062=>['Finał Odnowy (PvP)','Przez 10...35 sek., przez kilka (5) następnych razy, kiedy okrzyk lub zaśpiew przestaną działać na wybranym sojuszniku nie-duchu, odzyskuje on 15...75 pkt. żywotności.','(10...35 sek.) Wybrany sojusznik odzyskuje 15...75 pkt. żywotności przez kilka (5) następnych razy, kiedy przestaje na nim działać zaśpiew lub okrzyk. Na cel nie można wybrać ducha.'],
3063=>['Mantra Zdecydowania (PvP)','Przez 5 sek., twoje czynności nie mogą być przerwane, ale za każdym razem, gdy byłyby przerwane, tracisz 10...4 pkt. energii albo Mantra Zdecydowania przestanie działać.','(5 sek.) Chroni cię przed przerwaniami. Koszt ochrony: utrata 10...4 pkt. energii lub koniec Mantry Zdecydowania.'],
3141=>['Błyskawiczny refleks (PvP)','Przez 5...11 sek., masz 75% szans na zablokowanie atak&oacute;w wręcz i strzeleckich, a dodatkowo atakujesz o 33% szybciej.','(5...11 sek.) Atakujesz o 33% szybciej i masz 75% szans na blokowanie.'],
3143=>['Cios Odnowy (PvP)','Jeśli Cios Odnowy trafi, zadaje +5...20 pkt. obrażeń. Jeśli trafisz powalonego wroga, otrzymujesz 3 pkt. energii, a atak ten natychmiast się odnawia.','Zadaje +5...20 pkt. obrażeń. Otrzymujesz 3 pkt. energii, zaś atak ten natychmiast się odnawia, jeśli wybrany przeciwnik był powalony.'],
3144=>['Jedność w Uzdrowieniu (PvP)','Jeśli żywotność twojego zwierzęcego towarzysza jest poniżej 75%, obaj otrzymujecie po 25...145 pkt. żywotności. Jeśli tw&oacute;j zwierzęcy towarzysz jest martwy, powraca do życia z 50% pkt. żywotności.','Przywraca tobie i twojemu zwierzęcemu towarzyszowi po 25...145 pkt. żywotności. Jeśli zwierzęcy towarzysz nie żyje, zostaje wskrzeszony z 50% żywotności. Bez efektu, chyba że któryś z was ma poniżej 75% żywotności..'],
3145=>['Szklane Strzały (PvP)','Przez 10...35 sek., twoje strzały po trafieniu zadają +6...18 pkt. obrażeń, a jeśli zostaną zablokowane, to powodują, że na 10...20 sek. cel zaczyna krwawić.','(10...35 sek.) Twoje strzały zadają +6...18 pkt. obrażeń. Wywołuje przypadłość krwawienie (10...20 sek.), jeżeli zostanie zablokowana.'],
3147=>['Ostra Strzała (PvP)','Jeśli atak trafi, zadajesz +5...15 pkt. obrażeń. Jeśli jest to trafienie krytyczne, zdajesz dodatkowe +5...30 pkt. obrażeń.','Zadaje +5...15 pkt. obrażeń. Zadaje +5...30 pkt. dodatkowych obrażeń, jeżeli wykonasz trafienie krytyczne.'],
3148=>['Hymn Zazdrości (PvP)','Przez 10 sek., następna umiejętność związana z atakiem, użyta przez każdego sojusznika w zasięgu słuchu zadaje +10...20 pkt. obrażeń przeciwnikom posiadającym więcej niż 50% pkt. żywotności.','(10 sek.) Sojusznicy w zasięgu słuchu, ze swoją następną umiejętnością związaną z atakiem zadają +10...20 pkt. obrażeń. Dodatkowe obrażenia zadawane są tylko przeciwnikom, kt&oacute;rzy mają więcej niż 50% żywotności.'],
3149=>['Zaśpiew Ozdrowienia (PvP)','Przez 15 sek., posiadasz regenerację żywotności + 2...3. To echo jest ponownie nakładane za każdym razem, kiedy przestaje na tobie działać pieśń lub okrzyk.','(15 sek.) Otrzymujesz regenerację żywotności +2...3. Odnowienie: za każdym razem, gdy przestaje na tobie działać pieśń lub okrzyk.'],
3151=>['Empatia (PvP)','Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik atakuje, ten przeciwnik otrzymuje 15...45 pkt. obrażeń.','(5...15 sek.) Wybrany przeciwnik otrzymuje 15...45 pkt. obrażeń, za każdym razem, kiedy atakuje.'],
3152=>['Okulawiające Katusze (PvP)','Przez 5...20 sek., wybrany przeciwnik porusza się 50% wolniej oraz cierpi na -2...6 degeneracji pkt. żywotności.','(5...20 sek.) Wybrany przeciwnik porusza się o 50% wolniej i cierpi na degenerację żywotności -2...6.'],
3156=>['Postawa Żołnierza (PvP)','Przez 4...10 sek., kiedy będziesz pod działaniem okrzyku lub pieśni, atakujesz o 33% szybciej.','(4...10 sek.) Atakujesz o 33% szybciej, jeżeli jesteś pod działaniem okrzyku lub pieśni.'],
3157=>['Niszczycielską Była Glewia (PvP)','Trzymaj prochy Glewii przez maksymalnie 30...60 sek. Kiedy je trzymasz, wszystkie umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Gdy upuścisz jej prochy, wszyscy przeciwnicy w okolicy otrzymają 15...85 pkt. obrażeń od błyskawic.','(30...60 sek.) Twoje umiejętności Rytualisty otrzymują 10% do penetracji pancerza. Efekt upuszczenia: wszyscy przeciwnicy w okolicy otrzymują po 15...85 pkt. obrażeń od błyskawic.'],
3179=>['Mantra Sygnetów (PvP)','Przez 10...40 sek., otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem, gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.','(10...40 sek.) Otrzymujesz +3 do pancerza za każdy sygnet na wyposażeniu. Za każdym razem, gdy użyjesz jakiegoś sygnetu, otrzymujesz 5...60 żywotności.'],
3180=>['Rozbicie Urojeń (PvP)','Zdejmij jedną klątwę mesmera z wybranego przeciwnika. Jeśli klątwa zostanie usunięta, to ten przeciwnik odniesie 15...75 pkt. obrażeń, wszyscy wrogowie w jego bezpośrednim sąsiedztwie odniosą 75% tych obrażeń.','Zdejmuje jedną klątwę mesmera z wyznaczonego przeciwnika. Skutek zdjęcia: 15...75 pkt. obrażeń dla celu i 75% tych obrażeń dla wszystkich sąsiednich przeciwników.'],
3181=>['Iluzoryczna Broń (PvP)','Przez 30 sekund, twoje ataki nie trafiają ani nie chybiają. Zamiast tego Iluzoryczna Broń zadajee 20...60 pkt. obrażeń twoim celom przy każdym ataku wręcz.','(30 sek.) Zadaje 20...60 pkt. obrażeń przeciwnikom zamiast innych obrażeń lub efektów z ataków wręcz. Twoje ataki wręcz nie trafiają ani nie chybiają.'],
3183=>['Migrena (PvP)','Przez 4...16 sek., wybrany przeciwnik cierpi na -1...8 degeneracji pkt. żywotności oraz uaktywnia umiejętności 100% dłużej.','(4...16 sek.) Powoduje degenerację żywotności -1...8 i dwukrotnie wydłuża czas aktywacji umiejętności.'],
3184=>['Nagromadzenie Bólu (PvP)','Wybrany przeciwnik otrzymuje 10...35 pkt. obrażeń. Jeżeli wybrany przeciwnik jest pod wpływem 2 lub więcej klątw, to otrzymuje głęboką ranę na 5...20 sek.','Zadaje 10...35 pkt. obrażeń. Wywołuje głęboką ranę (5...20 sek.), jeżeli wybrany przeciwnik jest pod działaniem 2 lub więcej klątw.'],
3185=>['Psychiczna Niestabilność (PvP)','Przerywa akcję wybranego przeciwnika. Jeśli tą akcją jest umiejętność, przeciwnik i wszyscy wrogowie w bezpośrednim sąsiedztwie zostają powaleni na 2...3 sek. (50% szans na niepowodzenie, jeśli Szybkie Rzucanie Czarów jest na poziomie 4 lub mniejszym.)','Przerywa akcję. Efekt przerwania: jeśli tą akcją jest umiejętność, przeciwnik i wszyscy wrogowie w bezpośrednim sąsiedztwie zostają powaleni na 2...3 sek. 50% szans na niepowodzenie, chyba że Szybkie Rzucanie Czarów jest na poziomie 5 lub wyższym.'],
3186=>['Wspólny Ciężar (PvP)','Przez 5...20 sek. wybrany przeciwnik i wszyscy przeciwnicy na obszarze ataku rzucają zaklęcia i poruszają się o 33% wolniej.','Klątwa działa także na przeciwników w pobliżu twojego celu (5...20 sek.). Ci przeciwnicy atakują, rzucają zaklęcia i poruszają się o 33% wolniej.'],
3187=>['Kradzież Szybkości (PvP)','Przez 1...10 sek., cel i wszyscy przeciwnicy w jego sąsiedztwie rzucają czary 100% dłużej. Twoje czary wycelowane w tych przeciwników rzucane są 50% szybciej.','Klątwa działa także na wrogów w bezpośrednim sąsiedztwie (1...10 sek.). Podwaja czas rzucania czarów. Twoje czary wycelowane w przeciwników pod działaniem klątwy, rzucane są 50% szybciej.'],
3188=>['Nienaturalny Sygnet (PvP)','Wybrany przeciwnik otrzymuje 10...60 pkt. obrażeń. Jeśli jest on pod działaniem klątwy lub zaklęcia, przeciwnicy w bezpośrednim sąsiedztwie celu otrzymują 10...60 pkt. obrażeń. Wszystkie twoje umiejątności nie będące umiejętnościami mesmera zostają wyłączone na 10 sekund.','Zadaje 10...60 pkt. obrażeń. Zadaje 10...60 pkt. obrażeń innym wrogom w sąsiedztwie, jeśli cel jest pod działaniem klątwy lub zaklęcia. Wszystkie twoje umiejątności nie będące umiejętnościami mesmera zostają wyłączone (10 sekund).'],
3189=>['Duchowy Ból (PvP)','Wybrany przeciwnik otrzymuje 5...40 pkt. obrażeń. Wszystkie wrogie przywołane stworzenia na obszarze w pobliżu wroga otrzymują 25...125 pkt. obrażeń.','Zadaje 5...40 pkt. obrażeń. Zadaje 25...125 pkt. obrażeń wrogim przywołanym stworzeniom w rejonie wybranego przeciwnika.'],
3190=>['Frustracja (PvP)','Przez 5...20 sek., wybrany przeciwnik rzuca czary o 50% wolniej i otrzymuje 5...50 pkt. obrażeń za każdym razem, kiedy jego akcja zostanie przerwana.','(5...20 sek.) Powoduje, że rzucanie czarów jest wolniejsze o 50%. Wybrany przeciwnik otrzymuje 5...50 pkt. obrażeń, za każdym razem, kiedy jego akcje zostaną przerwane.'],
3191=>['Nieufność (PvP)','Przez 6 sek. następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...60 pkt. obrażeń, a wszyscy przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.','(6 sek.). Następny czar wybranego przeciwnika wymierzony przeciwko twojemu sojusznikowi zawiedzie, przeciwnik ten odniesie 10...60 pkt. obrażeń, a przeciwnicy w jego pobliżu odniosą 75% tych obrażeń.'],
3192=>['Zagadka Zaklinacza (PvP)','Przez 10 sek. wybrany przeciwnik rzuca zaklęcia 100...200% wolniej. Jeśli w momencie nałożenia klątwy wybrany przeciwnik nie znajduje się pod działaniem żadnego zaklęcia, przeciwnik ten odnosi 10...100 pkt. obrażeń, a wszyscy wrogowie w jego bezpośrednim sąsiedztwie odnoszą 75% tych obrażeń.','Spowalnia o 100...200% rzucanie zaklęć (10 sek.). Początkowy efekt: jeśli wybrany przeciwnik nie jest pod wpływem zaklęcia, zadaje mu 10...100 pkt. obrażeń, a sąsiadującym z nim przeciwnikom zadaje 75% tych obrażeń.'],
3193=>['Sygnet Niezgrabności (PvP)','Jeśli wybrany przeciwnik atakuje, zarówno on, jak i wrogowie w jego sąsiedztwie przerywają wykonywanie akcji i otrzymują 15...60 pkt. obrażeń. Wszyscy przeciwnicy korzystający z umiejętności ataku zostają powaleni.','Przerywa atak wybranego przeciwnika i sąsiadujących z nim wrogów. Efekt przerwania: zadaje 15...60 pkt. obrażeń. Powala wrogów używających umiejętności ataku.'],
3194=>['Zwierciadło Antyzaklęcia (PvP)','Z wybranego przeciwnika zdejmujesz jedno zaklęcie. To samo zaklęcie tracą wszyscy członkowie drużyny tego przeciwnika.','Usuwa jedno zaklęcie z wybranego przeciwnika. To samo zaklęcie tracą także członkowie jego drużyny.'],
3195=>['Błędne Oko (PvP)','Przez 4 sek., następnym razem, gdy wybrany przeciwnik wykona atak, zostanie on przerwany, a wszyscy przeciwnicy w pobliżu otrzymają po 10...92 pkt. obrażeń.','(4 sek.) Przerywa następny atak wybranego przeciwnika. Efekt przerwania: 10...92 pkt. obrażeń dla przeciwników w pobliżu.'],
3196=>['Przewidziane Ryzyko (PvP)','Przez 3...12 sek., ataki wybranego przeciwnika zadają +10 obrażeń, ale istnieje 50% szansy, że obrażenia z każdego ataku otrzyma właśnie ten wróg. (Maksymalnie 15...60.)','Wybrany przeciwnik zadaje +10 pkt. obrażeń podczas ataków (3...12 sek.). Istnieje 50% szansy, że obrażenia z każdego ataku (maksymalnie 15...60) otrzyma właśnie ten wróg.'],
3204=>['Ignorowanie Bólu (PvP)','Przez 20 sek. otrzymujesz dodatkowo 90...300 pkt. żywotności oraz 20 pkt. pancerza.','(20 sek.) Otrzymujesz +90...300 do maksymalnej żywotności i +20 do pancerza.'],
3232=>['Uzdrowienie Drużyny (PvP)','Przywraca 30...75 pkt. żywotności całej drużynie.','Przywraca żywotność (30...75) całej drużyny.'],
3233=>['Łup Zwycięzcy (PvP)','Przez najbliższe 3...15 sek., za każdym razem, gdy wybrany wróg zaatakuje lub rzuci czar na istotę mającą mniej żywotności od niego, straci 15...75 pkt. żywotności.','(3...15 sek.) Powoduje utratę 15...75 pkt. żywotności za każdym razem, gdy wybrany wróg zaatakuje lub rzuci czar na stworzenie mające mniej żywotności od niego.'],
3234=>['Wizje Żalu (PvP)','Przez 10 sek., wybrany wróg i wszyscy wrogowie w jego bezpośrednim sąsiedztwie otrzymują 10...30 pkt. obrażeń za każdym razem, gdy użyją umiejętności, oraz dodatkowe 5...40 pkt. obrażeń, jeśli nie mają na sobie innej klątwy mesmera.','Klątwa działa również na wrogów stojących w bezpośrednim sąsiedztwie celu (10 sek.). Otrzymują oni 10...30 pkt. obrażeń za każdym razem, gdy użyją umiejętności, i kolejne 5...40 pkt. obrażeń, jeśli nie ciąży na nich żadna inna klątwa mesmera.'],
3251=>['Lisie Kły (PvP)','Musi nastąpić po ataku poprzedzającym. Lisich Kłów nie da się zablokować. Po trafieniu zdolność zadaje +10...25 obrażeń.','Zadaje +10...25 pkt. obrażeń. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
3252=>['Dzikie Uderzenie (PvP)','Musi nastąpić po ataku poprzedzającym. W przypadku trafienia atak zadaje +10...35 obrazeń i postawa używana przez cel zostaje zakończona. Nie do zablokowania.','Zadaje +10...35 pkt. obrażeń. Usuwa postawę wroga. Nie do zablokowania. Musi nastąpić po ataku poprzedzającym.'],
3263=>['Wypędzające Uderzenie (PvP)','Jeśli ten atak trafi, zadajesz +10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.','Zadaje 10...60 pkt. świętych obrażeń. Zadaje podwójne obrażenia przywołanym stworzeniom.'],
3264=>['Zamach Podwójnego Księżyca (PvP)','Tracisz 1 zaklęcie derwisza i otrzymujesz 10...20 pkt. żywotności. Jeśli stracisz zaklęcie w ten sposób, nie można cię zablokować, atakujesz dwukrotnie, każdy twój cios zadaje 25% obrażeń mniej i otrzymujesz 10...30 pkt. żywotności.','Tracisz 1 z zaklęć derwisza. Otrzymujesz 10...20 pkt. żywotności. Efekt usunięcia: nieblokowalny, atakuje podwójnie, każdy atak każdy cios zadaje 25% obrażeń mniej i otrzymujesz 10...30 pkt. żywotności.'],
3265=>['Niepowstrzymywalny Zamach (PvP)','Zadaje +3...15 pkt. obrażeń i tracisz 1 zaklęcie derwisza. Jeśli stracisz w ten sposób jakieś zaklęcie Niepowstrzymywalny Zamach nie może zostać zablokowany i usuwa jedną postawę.','Zadaje +3...15 pkt. obrażeń. Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Nie do zablokowania, usuwa postawę.'],
3266=>['Nabożny Szturm (PvP)','Usuwasz 1 zaklęcie derwisza. Jeśli zaklęcie derwisza zostało usunięte, umiejętność ta odnawia się 75% szybciej, zaś wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.','Usuwa jedno z twoich zaklęć derwisza. Efekt usunięcia: Umiejętność ta odnawia się 75% szybciej, a wrogowie w bezpośrednim sąsiedztwie otrzymują 15...40 pkt. obrażeń.'],
3269=>['Wiodące Dłonie (PvP)','Przez 20 sek., twoich kolejnych 0...3 ataków nie można zablokować Kiedy ta umiejętność zostaje uaktywniona, usuwa ślepotę.','(20 sek.) Twoje kolejne ataki (0...3) nie mogą zostać zablokowane. Efekt początkowy: Usuwa ślepotę.'],
3270=>['Awatar Dwayny (PvP)','Przez 10...90 sek. twoje ataki zadają święte obrażenia. Za każdym razem, gdy używasz umiejętności ofensywnej derwisza, tracisz 1 klątwę. Za każdym razem, gdy tracisz zaklęcie derwisza, odzyskujesz 5...50 pkt. żywotności. Ta umiejętność zostanie wyłączona na 45 sek.','(10...90 sek.) Zadajesz święte obrażenia. Za każdym razem, gdy używasz umiejętności ataku derwisza, tracisz 1 klątwę. Przywracasz sobie 5...50 pkt. żywotności, za każdym razem gdy stracisz zaklęcie derwisza. Ta umiejętność zostanie wyłączona na 45 sek.'],
3271=>['Awatar Melandru (PvP)','Przez 10...90 sek., masz +100 do żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Za każdym razem gdy stracisz zaklęcie derwisza, tracisz 2 przypadłości. Umiejętność zostaje zablokowana na 45 sekund.','(10...90 sek.) Otrzymujesz +100 do maksymalnej żywotności, +30 do pancerza przeciwko żywiołom, a twoje ataki zadają obrażenia od ziemi. Leczysz u siebie 2 przypadłości za każdym razem, gdy stracisz zaklęcie derwisza. Umiejętność zostaje zablokowana na 45 sekund.'],
3272=>['Mistyczne Uzdrowienie (PvP)','Odzyskujesz 5...65 pkt. żywotności. Przywracasz także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.','Odzyskujesz 5...65 pkt. żywotności. Przywraca także 5...65 żywotności wszystkim członkom drużyny będącym pod wpływem zaklęcia.'],
3273=>['Sygnet Nabożnej Powściągliwości (PvP)','Tracisz 1 zaklęcie derwisza i powodujesz okulawienie wybranego wroga na 5...15 sek. Jeśli zaklęcie zostanie usunięte, ta umiejętność odnowi się 50% szybciej.','(5...15 sek.) Okulawia wybranego wroga i usuwa 1 z twoich zaklęć derwisza. Efekt usunięcia: Odnawia się 50% szybciej.'],
3289=>['Gorączkowe Sny (PvP)','Przez 5...15 sek., za każdym razem, kiedy wybrany przeciwnik zaczyna cierpieć na nową przypadłość, wszyscy przeciwnicy w okolicy zaczynają cierpieć na tę samą przypadłość.','(5...15 sek.) Przeciwnicy w okolicy otrzymują wszystkie nowe przypadłości, które dostaje wybrany wróg.'],
3346=>['Ciernista Aura (PvP)','Wszyscy wybrani przeciwnicy zaczynają krwawić przez 5...15 sek. Następnie, przez 30 sek. zaklęcie to nic nie robi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną okulawieni na 3...8 sek.','(30 sek.) Efekt początkowy: Powoduje krwawienie (5...15 sek.) u pobliskich wrogów. Efekt końcowy: Powoduje okulawienie (3...8 sek.) u pobliskich wrogów.'],
3347=>['Pyłowe Okrycie (PvP)','Wszyscy przeciwnicy w pobliżu otrzymują 10...40 pkt. obrażeń od ziemi. Przez 30 sek., twoje ataki zadają obrażenia od ziemi. Kiedy to zaklęcie dobiegnie końca, wszyscy pobliscy wrogowie zostaną oślepieni na 1...4 sek.','(30 sek.) Twoje ataki zadają obrażenia od ziemi. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom. Efekt końcowy: Wywołuje oślepienie (1...4 sek.) u pobliskich wrogów.'],
3348=>['Pośpiech Lyssy (PvP)','Przez 3...15 sek., twoje zaklęcia derwisza odnawiają się o 33% szybciej. Kiedy uaktywnisz to zaklęcie, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. Kiedy to zaklęcie dobiegnie końca, przerwane zostają akcje wykonywane przez wszystkich przeciwników w bezpośrednim sąsiedztwie. 50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.','(3...15 sek.) Twoje zaklęcia derwisza odnawiają się 33% szybciej. Efekt początkowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. Efekt końcowy: Przerywa akcje wszystkich wrogów w bezpośrednim sąsiedztwie. (50% szansy na porażkę, chyba że Modlitwy Wiatru są na co najmniej 5 poziomie.)'],
3365=>['Napaść (PvP)','Przez 2...8 sek. atakujesz i zdobywasz adrenalinę 25% szybciej.','(2...8 sek.) Atakujesz i zdobywasz adrenalinę 25% szybciej.'],
3366=>['Serce Furii (PvP)','Przez 2...10 sek. atakujesz o 25% szybciej.','(2...10 sek.) Atakujesz 25% szybciej.'],
3367=>['Raniące Uderzenie (PvP)','Jeśli ten atak dojdzie celu, docelowy wróg zaczyna krwawić przez 5...20 sek. i tracisz 1 zaklęcie derwisza. Jeśli doszło do usunięcia zaklęcia, docelowy wróg otrzymuje także głęboką ranę na 5...20 sek.','Wywołuje przypadłość krwawienie (5...20 sek.). Usuwa jedno zaklęcie derwisza. Efekt usunięcia: Powoduje głęboką ranę (5...20 sek.).'],
3368=>['Nabożna Furia (PvP)','Usuwa jedno zaklęcie derwisza. Przez 1...5 sek. atakujesz o 25% szybciej. Jeśli zostało usunięte jakieś zaklęcie, postawa ta trwa dwa razy dłużej.','(1...5 sek.) Atakujesz 25% szybciej i usuwasz 1 ze swoich zaklęć derwisza. Efekt usunięcia: Postawa ta trwa dwa razy dłużej.'],
3373=>['Iluzja Pośpiechu (PvP)','Przez 5...11 sek. poruszasz się o 33% szybciej. Gdy ta zdolność przestanie działać, ulegniesz okaleczeniu na 3 sek.','(5...11 sek.) Poruszasz się o 33% szybciej. Efekt zakończenia: ulegasz okaleczeniu (3 sek.)'],
3374=>['Iluzja Bólu (PvP)','Przez 8 s wskazany wróg otrzymuje -3...10 do regeneracji żywotności oraz 3...10 pkt. obrażeń na sekundę. Gdy efekt dobiegnie końca lub zostanie nałożony ponownie, wróg ten zostanie uleczony z 36...120 pkt. obrażeń.','(8 sek.) Cel otrzymuje -3...10 do regeneracji żywotności i otrzymuje 3...10 pkt. obrażeń na sekundę. Efekt zakończenia: cel odzyskuje 36...120 pkt. żywotności. Ponowne nałożenie kończy efekt.'],
3375=>['Aura Przywrócenia (PvP)','Przez 60 sekund otrzymujesz 0...1 pkt. energii, a przy każdym rzuceniu czaru odzyskujesz żywotność o wartości 200...400% kosztu energii.','(60 sekund.) Otrzymujesz 0...1 pkt. energii, a przy każdym rzuceniu czaru odzyskujesz żywotność o wartości 200...400% kosztu energii.'],
3386=>['Sieć Zakłócenia (PvP)','Przerywa czynność wykonywaną przez cel. Przez 10 sek. cel będzie pod wpływem Sieci Zakłócenia. Gdy efekt ten dobiegnie końca, czynność wykonywana przez wroga zostanie ponownie przerwana.','(10 sek.) Efekt początkowy: przerywa wykonywanie umiejętności. Efekt końcowy: przerywa wykonywanie umiejętności.'],
3396=>['Młot Błyskawic (PvP)','Wybrany przeciwnik otrzymuje 10...100 pkt. obrażeń od elektryczności. Młot Błyskawic ma 25% penetrację pancerza.','Zadaje 10...100 pkt. obrażeń od elektryczności. 25% penetracji pancerza.'],
3397=>['Żywiołowy Płomień (PvP)','Przez 5...20 sek., za każdym razem, kiedy nałożysz klątwę żywiołu na wybranego przeciwnika, zacznie on płonąć przez 1...2 sek.','(5...20 sek.) Powoduje podpalenie (przez 1...2 sek.) za każdym razem, kiedy rzucisz klątwę żywiołu na cel.'],
3398=>['Śliskie Podłoże (PvP)','Jeśli przeciwnik się porusza lub jest oślepiony, zostaje powalony. (50% szansy na porażkę przy Magii Wody na poziomie 4 lub mniej.)','Powoduje powalenie, jeżeli przeciwnik jest w ruchu lub jest oślepiony. (50% szansy na porażkę jeśli Magia Wody nie jest na poziomie 5 lub wyższym.)'],
3422=>['Totem Czasu','Tworzysz Totem Czasu w miejscu, w którym się znajdujesz. Przez 6...20 sek, wszyscy nieduchowi sojusznicy rzucający czary w tym obszarze robią to 15...20% szybciej a ich umiejętności odnawiają się 15...20% szybciej. Umiejętność PvE','(6...20 sek.) Sojusznicy w zasięgu totemu rzucają czary o 15...20% szybciej i ich zdolności odnawiają się o 15...20% szybciej. Przyjazne duchy nie są objęte tym efektem. Umiejętność PvE'],
3423=>['Złodziej Dusz','Przez 3...30 sek, twoje ataki kosztują cię 15...20 punktów życia i zadają 15...20 więcej obrażeń. Umiejętność PvE','(3...30 sek.) Ataki zadają +15...20 obrażeń i kosztują cię 15...20 punktów życia. Umiejętność PvE'],
3424=>['Ponad Limit','Podczas utrzymywania tego zaklęcia, rzucasz czary 20...50% szybciej i odnawiasz je o 40...80% szybciej ale stale otrzymujesz efekt Przemęczenia. Umiejętność PvE','Czary są rzucane o 20...50% szybciej i odnawiają się o 40...80% szybciej. Podczas działania stale otrzymujesz efekt Przemęczenia. Umiejętność PvE'],
3425=>['Wyrok','Atakujesz cel oraz pobliskich przeciwników. Każdy atak, który trafi zadaje +13...30 Świętych obrażeń i powala atakujących przeciwników. Umiejętność PvE','Zadaje celowi oraz pobliskim przeciwnikom +13...30 Świętych obrażeń. Powoduje powalenie atakujących przeciwników. Umiejętność PvE'],
3426=>['Postawa Siedmiu Broni','Przez 3...20 sek, atrybuty twojej broni są zwiększone o 1...15 i atakujesz o 33 % szybciej. Umiejętność PvE','(3...20 sek.) Atrybuty broni są zwiększone o 1...15. Atakujesz o 33 % szybciej. Umiejętność PvE'],
3427=>['„Razem jako jedność!"','Przez 3...15 sek, wszyscy członkowie drużyny w twoim pobliżu lub w pobliżu twojego chowańca zadają +5...15 obrażeń swoimi atakami i otrzymują +1...7 regeneracji zdrowia. Umiejętność PvE','(3...15 sek.) Wszyscy członkowie drużyny w twoim pobliżu lub w pobliżu twojego chowańca zadają +5...15 obrażeń i otrzymują +1...7 regeneracji zdrowia. Umiejętność PvE'],
3428=>['Cienista Kradzież','Używasz Cienistego Kroku do wybranego przeciwnika. Przez 5...20 sek, atrybuty tego przeciwnika są zmniejszane o 1...5 a twoje zwiększane o 1...5. Ta umiejętność jest zaliczana do Głównego ataku. Umiejętność PvE','Używasz Cienistego Kroku do wybranego przeciwnika. Przez 5...20 sek, atrybuty tego przeciwnika są zmniejszane o 1...5 a twoje zwiększane o 1...5. Umiejętność jest zaliczana do Głównego ataku. Umiejętność PvE'],
3429=>['Bronie Trzech Kuźni','Przez 3...20 sek, każdy nieduchowy sojusznik w zasięgu słuchu otrzymuje efekt losowego Zaklęcia broni. Umiejętność PvE','(3...20 sek.) Sojusznicy w zasięgu słuchu otrzymują efekt losowego Zaklęcia broni. Przyjazne duchy nie są objęte tym efektem. Umiejętność PvE'],
3430=>['Przysięga Zmian','Przez 3...10 sek, otrzymujesz +1...6 regeneracji energii. Ta umiejętność jest automatycznie używana za każdym razem, gdy użyjesz umiejętności innej niż derwisza. Umiejętność PvE','(3...10 sek.) Otrzymujesz +1...6 regeneracji energii. Odnowienie: za każdym razem, gdy użyjesz umiejętności innej niż derwisza. Umiejętność PvE'],
3431=>['Heroiczny Śpiew','Przez 3...15 sek, wybrani nieduchowi sojusznicy otrzymują +1...3 do wszystkich atrybutów. To echo jest automatycznie używane za każdym razem, gdy na sojuszniku kończy się efekt okrzyku lub śpiewu. Umiejętność PvE','(3...15 sek.) Cel otrzymuje +1...3 do wszystkich atrybutów. Odnowienie: za każdym razem, gdy na sojuszniku kończy się efekt okrzyku lub śpiewu. Nie można użyć na duchach. Umiejętność PvE'],
3437=>['Kosa Farmera (PvP)','Jeśli atak trafi, zadaje +5...35 pkt. obrażeń. Jeżeli trafisz więcej niż jednego przeciwnika, atak natychmiast się odnawia.','Zadaje +5...35 pkt. obrażeń. Natychmiast się odnawia, jeżeli trafisz więcej niż jednego przeciwnika.'],
3442=>['Potężny Rzut (PvP)','Twoja włócznia leci trzy razy szybciej. Jeśli trafi, zadajesz +10...40 pkt. obrażeń.','Zadaje +10...40 pkt. obrażeń. Ta włócznia leci trzy razy szybciej.'],
3443=>['Furia','Przez 8 sek. atakujesz o 33% szybciej, ale odnosisz 200...150% obrażeń.','(8 sek.) Atakujesz o 33% szybciej. Odnosisz 200...150% obrażeń.'],
3444=>['Sto Ostrzy','Przez 15 sek., za każdym razem, kiedy zaatakujesz mieczem, wszyscy przeciwnicy bezpośrednio przy tobie otrzymają po 10...30 pkt. obrażeń ciętych.','(15 sek.) Przeciwnikom bezpośrednio przy tobie zadaje po 10...30 pkt. obrażeń ciętych, jeśli atakujesz mieczem.'],
3445=>['Odnowienie Natury','Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Zmartwienie Marnotrawcy','Po 3 sek. wybrany przeciwnik odniesie 20...100 pkt. obrażeń, a wszyscy sąsiadujący z nim wrogowie odniosą 75% tych obrażeń. Jeśli wybrany przeciwnik zdoła użyć umiejętności, Zmartwienie Marnotrawcy przestanie działać i nie zadaje obrażeń.','(3 sek.). Efekt końcowy: zadaje 20...100 pkt. obrażeń przeciwnikowi i 75% tych obrażeń sąsiadującym z nim wrogom. Nie ma efektu i kończy się wcześniej, jeżeli wybrany przeciwnik używa umiejętności.'],
3448=>['Pokój i Harmonia','Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...4. Przez 1...3 sek. przypadłości i klątwy na tym sojuszniku trwają o 90% krócej. Wszystkie twoje umiejętności związane z Modlitwami Ofensywnymi zostają zablokowane na 20 sek.','Wybrany sojusznik traci klątwy i przypadłości w liczbie 0...4. Przypadłości i klątwy na tym sojuszniku trwają o 90% krócej (1...3 sek.). Wyłącza twoje umiejętności Modlitw Ofensywnych (20 sek.).'],
3449=>['Uderzenie Obrońcy','Jeśli atak trafi przeciwnika w ruchu, zadajesz 10...40 pkt. dodatkowych obrażeń.','Zadaje +10...40 pkt. obrażeń, jeżeli cel się porusza.'],
3450=>['Okulawiający Strzał','Jeśli Okulawiający Strzał trafi, twój cel zostanie okulawiony na 4...14 sek. Tego ataku nie można zablokować.','Nie do zablokowania. Powoduje okulawienie (4...14 sek.).'],
3451=>['Ryk Otyugha','Przez 5...15 sek., twój zwierzęcy towarzysz posiada +24 pkt. pancerza, dodatkowo jego ataków nie można zablokować.','(5...15 sek.) Twój zwierzęcy towarzysz ma +24 pkt. pancerza, a jego ataków nie można blokować.'],
3452=>['Całun Cienia','Przez 2...7 sek. wybrany przeciwnik nie może być celem zaklęć.','(2...7 sek.) Wybrany przeciwnik nie może być celem zaklęć.'],
3453=>['Pęd','Przez 3 sek. biegasz o 50% szybciej. Każde 2 pkt. przydzielone do Sztuki Cienia skracają odnawianie o 1 sek. (maks. 6 sek.).','(3 sek.) Poruszasz się o 50% szybciej. Każde 2 pkt. przydzielone do Sztuki Cienia skracają odnawianie o 1 sek. (maks. 6 sek.).'],
3454=>['Uzdrawiający Strażnik','Przez 1...4 sek., wszyscy członkowie drużyny w zasięgu słuchu mają 75% szans na blokowanie ataków. Jeśli atak zostanie zablokowany, wszyscy sojusznicy w zasięgu słuchu odzyskują 10...35 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.','(1...4 sek.) Członkowie drużyny w zasięgu słuchu mają 75% szans na zablokowanie ataków. Efekt zablokowania: Sojusznicy w zasięgu słuchu odzyskują 10...35 pkt. żywotności, a Uzdrawiający Strażnik przestaje działać.'],
3455=>['Skuteczne Uderzenie','Jeśli Skuteczne Uderzenie trafi, zadajesz +5...20 pkt. obrażeń i otrzymujesz 2...4 pkt. energii. Jeśli przeciwnik był osłabiony, ataku tego nie można zablokować.','Zadaje +5...20 pkt. obrażeń, a ty otrzymujesz 2...4 pkt. energii. Nie do zablokowania, jeżeli wybrany przeciwnik jest osłabiony.'],
3456=>['"Tchórz!"','Jeśli przeciwnik się porusza, zostaje powalony.','Powoduje powalenie, jeżeli wybrany przeciwnik jest w ruchu.'],
3457=>['Zastawa Obrońcy','Przez 4...8 sek., sojusznicy bezpośrednio przy tobie mają 75% szans na blokowanie ataków. Zastawa Obrońcy skończy się, jeśli się poruszysz.','(4...8 sek.) Sojusznicy w bezpośredniej odległości mają 75% szans na blokowanie. Przestanie działać, jeśli się ruszysz.'],
3458=>['Pierwotny Szał','Przez 1...9 sek. atakujesz 33% szybciej i poruszasz się 33% szybciej, ale odnosisz 200...150% obrażeń.','(1...9 sek.) Atakujesz 33% szybciej i poruszasz się 33% szybciej. Odnosisz 200...150% obrażeń.'],
3459=>['Strzał Melandru','Jeśli Strzał Melandru trafi, przeciwnik zaczyna krwawić przez 5...25 sek. Jeśli trafiony zostanie powalony lub poruszający się przeciwnik , to otrzyma +10...25 pkt. obrażeń i będzie okulawiony przez 5...15 sek.','Wywołuje krwawienie (5...25 sek.). Zadaje +10...25 pkt. obrażeń oraz powoduje okulawienie (5...15 sek.), jeżeli twój cel się porusza lub jest powalony.'],
3460=>['Spokój','Tworzysz 1...10 poziomowego ducha. Zaklęcia rzucane przez stworzenia nie-duchy w jego zasięgu kończą się o 10...30% szybciej. Ten duch ginie po 15...120 sek.','Tworzy ducha na poziomie 1...10 (czas życia 15...120 sek.). Zaklęcia na stworzeniach w zasięgu przestają działać o 10...30% szybciej. Nie działa na duchy.'],
3461=>['Skręcenie Duszy','Przez 5...45 sek. twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się o 25...50% szybciej. Skręcenie Duszy kończy się po przeprowadzeniu określonej liczby rytuałów spętania (1...3).','(5...45 sek.) Twoje rytuały spętania kosztują 15 pkt. energii mniej (minimalnie 5) i odnawiają się o 25...50% szybciej. Kończy się po przeprowadzeniu określonej liczby rytuałów spętania (1...3).'],
3462=>['Prowadzony Oręż','Przez 4...10 sek., ciosy tego sojusznika nie mogą być blokowane.','(4...10 sek.) Ataków nie można blokować.'],
3463=>['Dokuczliwość','Jeżeli wybrany przeciwnik używa umiejętności, aktualnie wykonywana czynność tego przeciwnika i czynność każdego przeciwnika w okolicy zostają przerwane. Dodatkowo wykradasz 0...5 energii od wszystkich wrogów w okolicy.','Przerywa umiejętność. Efekt przerwania: przerywasz także czynności innych wrogów w okolicy i wykradasz 0...5 energii od wszystkich wrogów w okolicy.'],
3464=>['Atak na Oślep','Przez 1...15 sek. atakujesz o 33% szybciej, ale poruszasz się o 33% wolniej. Kończy się, gdy użyjesz umiejętności ataku dystansowego.','(1...15 sek.) Atakujesz o 33% szybciej. Kończy się, gdy użyjesz umiejętności ataku dystansowego. Poruszasz się o 33% wolniej.'],
3465=>['Uderzenie w Szarży','Przez 1...10 sek. biegasz o 33% szybciej. Twoje kolejne trafienie wręcz zadaje +10...80 pkt. obrażeń, a ta postawa przestaje działać. Postawa przestanie działać, kiedy użyjesz umiejętności.','(1...10 sek.) Poruszasz się o 33% szybciej i w następnym celnym ataku wręcz zadajesz +10...80 pkt. obrażeń. Przestanie działać, kiedy trafisz lub jeśli użyjesz umiejętności.'],
3466=>['Rozwścieczający Żar','Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Mistyczne Zepsucie','Wszyscy wrogowie w bezpośrednim sąsiedztwie cierpią przez 2...6 sek. z powodu choroby. Przez 20 sek. nic się nie dzieje. Czas trwania choroby zostaje podwojony, jeśli w momencie aktywacji tej umiejętności znajdujesz się pod wpływem zaklęcia. Kiedy zaklęcie to dobiegnie końca, wszyscy członkowie drużyny w zasięgu słuchu zostają wyleczeni z chorób.','(20 sek.) Efekt początkowy: Wszyscy wrogowie w bezpośrednim sąsiedztwie zaczynają chorować (2...6 sek). Podwojony czas trwania, jeśli już znajdujesz się pod wpływem zaklęcia. Efekt końcowy: Członkowie drużyny w zasięgu słuchu przestają chorować.'],
3468=>['Uścisk Grabieżcy','Przez 5...20 sek. ataki wręcz przeciwko poruszającym się wrogom dodatkowo okulawiają ich na 2...9 sek. Kiedy rzucisz to zaklęcie, przestaje działać na ciebie okulawienie i 1 inna przypadłość. Zaklęcie to kończy się, kiedy okulawisz przeciwnika 1...3 razy.','(5...20 sek.) Atakowanie wręcz poruszających się przeciwników dodatkowo ich okulawia. Początkowy efekt: przestaje na ciebie działać okulawienie i 1 inna przypadłość. Kończy się, gdy okulawisz przeciwników 1...3 razy.'],
3469=>['Okrycie Mirażem','Przez 1...7 sek., otrzymujesz dodatkowe 30...60% szans na zablokowanie ataków. Gdy rzucisz to zaklęcie, wszyscy pobliscy wrogowie zostaną trafieni za 10...40 pkt. obrażeń od ziemi.','(1...7 sek.) Masz 30...60% szans na blok. Efekt początkowy: Zadaje 10...40 obrażeń od ziemi pobliskim wrogom.'],
3470=>['Ulotna Stabilność','Przez 2...8 sek., nie możesz zostać powalony i poruszasz się 25% szybciej. Zaklęcie to kończy się przed czasem, jeśli zapobiegnie powaleniu.','(2...8 sek.) Nie możesz zostać powalony i poruszasz się 25% szybciej. Kończy się, jeśli zapobiegnie powaleniu.'],
3471=>['Nabożne Przywrócenie','Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Jeśli usunięto w ten sposób zaklęcie, tracisz także klątwy w liczbie 1.','Otrzymujesz 80...150 żywotności i usuwasz 1 zaklęcie derwisza. Efekt usunięcia: Tracisz klątwy w liczbie 1.'],
3472=>['Wirująca Szarża','Przez 1...6 sek., poruszasz się o 33% szybciej niż normalnie. Kiedy następnym razem trafisz wroga, wszyscy pozostali przeciwnicy w pobliżu otrzymują 10...50 pkt. obrażeń od zimna, a zaklęcie dobiega końca.','(1...6 sek.) Poruszasz się 33% szybciej. Zadaje 10...50 obrażeń od zimna wszystkim wrogom w pobliżu, kiedy następnym razem trafisz jakiegoś przeciwnika, a to zaklęcie się skończy.'],
3473=>['Rozcinacz Aur','Jeśli atak trafi, powoduje krwawienie przez 5...15 sek. Jeśli znajdujesz się pod wpływem zaklęcia, atak powoduje także pęknięcie zbroi przez 1...10 sek.','(5...15 sek.) Wywołuje krwawienie. Powoduje także pęknięcie zbroi (1...10 sek.), jeśli znajdujesz się pod wpływem zaklęcia.'],
];}
